window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":34000,"as":"","scd":null,"kp":[]},{"i":34001,"as":"","scd":null,"kp":[]},{"i":34002,"as":"","scd":null,"kp":[]},{"i":34003,"as":"","scd":null,"kp":[]},{"i":34004,"as":"","scd":null,"kp":[]},{"i":34005,"as":"","scd":null,"kp":[]},{"i":34006,"as":"","scd":null,"kp":[]},{"i":34007,"as":"研究引入了一种冠醚功能化的Spiro衍生物作为多功能界面层。合理的分子设计实现了钙钛矿表面的p型修饰以优化能级对齐，并通过π-π堆积增强了分子堆积。同时，该界面层具备Li+和Pb2+双重螯合作用，有效抑制了离子迁移和缺陷复合。这种协同策略使冠军器件的效率达到26.06%，并具备卓越的运行稳定性。","scd":null,"kp":["转换效率[冠醚功能化Spiro-AC界面层修饰的钙钛矿太阳能电池]: 26.06%","[钙钛矿光伏界面稳定策略]: 采用冠醚功能化Spiro衍生物实现表面p型修饰、优化能级排列并双重螯合Li+/Pb2+以抑制离子迁移"]},{"i":34008,"as":"研究描述了一种双层分层多孔纳米纤维复合薄膜。该薄膜展现出优异的扭转振荡、弯曲振荡和多刺激响应性，并具备可编程变形和能量转换能力。具体应用包括热风车、自主扭转自振荡做功、自主发电以及智能花朵和纺织品等。这项工作推动了基于纳米纤维的扭转振荡器的发展，拓宽了自主器件在更多领域的应用。","scd":null,"kp":["[人工肌肉材料结构]: 双层分级多孔纳米纤维复合膜","[扭转振荡器应用]: 具备出色的扭转/弯曲振荡、多刺激响应、可编程变形以及热机做功与自动发电等多功能能量转换特性"]},{"i":34009,"as":"研究通过可扩展的常压干燥技术，制备出一种受钢筋混凝土启发的气凝胶。该气凝胶采用海藻酸盐-明胶-聚(3,4-乙烯二氧噻吩)柔性“基体”嵌入碳纳米管“钢筋”，实现了网络增强和多级电磁吸收。这种坚固、轻质且阻燃的架构为高效、多功能电磁干扰屏蔽材料的设计提供了新策略，具备全向超低反射特性。","scd":null,"kp":["[气凝胶电磁屏蔽材料]: 受钢筋混凝土启发的柔性海藻酸盐-明胶-PEDOT基质包裹碳纳米管“钢筋”，实现多级电磁吸收与全向超低反射","[气凝胶制备工艺]: 可放大的常压干燥技术"]},{"i":34010,"as":"","scd":null,"kp":[]},{"i":34011,"as":"","scd":null,"kp":[]},{"i":34012,"as":"","scd":null,"kp":[]},{"i":34013,"as":"","scd":null,"kp":[]},{"i":34014,"as":"","scd":null,"kp":[]},{"i":34015,"as":"","scd":null,"kp":[]},{"i":34016,"as":"","scd":null,"kp":[]},{"i":34017,"as":"","scd":null,"kp":[]},{"i":34018,"as":"原子层沉积技术可精确将硼单原子掺杂至铂纳米颗粒的次表面，引发不对称应变与电子泵效应。该机制在不损失电化学活性表面积的前提下，由内而外有效抑制了不饱和铂位点的电化学腐蚀，从而赋予铂基电催化剂长效的燃料电池耐久性。","scd":null,"kp":["[燃料电池Pt催化剂抗降解]: 利用原子层沉积技术将硼单原子精确间隙掺杂至Pt纳米颗粒次表面，通过非对称应变和电子泵效应由内而外抑制不饱和Pt位点的电化学腐蚀"]},{"i":34019,"as":"研究通过非化学计量比策略，在Na0.96xCa0.04Nb0.96Zr0.04O3-δ导体中实现了Na+和O2-离子协同传导调控。所有样品均具有Pbma正交结构。随着Na含量增加，缺陷特征由空位转为间隙，NbO6八面体发生压缩至倾斜扁平的转变，进而导致Na-O-Na和Na-O-Nb网络中间隙扩大。","scd":null,"kp":["[固态电解质离子传导调控]: 通过A位非化学计量比策略实现Na+和O2-离子的协同传导调控","[Na0.96xCa0.04Nb0.96Zr0.04O3-δ导体结构]: 所有样品均具有Pbma正交结构"]},{"i":34020,"as":"","scd":null,"kp":[]},{"i":34021,"as":"","scd":null,"kp":[]},{"i":34022,"as":"","scd":null,"kp":[]},{"i":34023,"as":"","scd":null,"kp":[]},{"i":34024,"as":"","scd":null,"kp":[]},{"i":34025,"as":"","scd":null,"kp":[]},{"i":34026,"as":"","scd":null,"kp":[]},{"i":34027,"as":"","scd":null,"kp":[]},{"i":34028,"as":"","scd":null,"kp":[]},{"i":34029,"as":"","scd":null,"kp":[]},{"i":34030,"as":"","scd":null,"kp":[]},{"i":34031,"as":"","scd":null,"kp":[]},{"i":34032,"as":"","scd":null,"kp":[]},{"i":34033,"as":"","scd":null,"kp":[]},{"i":34034,"as":"","scd":null,"kp":[]},{"i":34035,"as":"","scd":null,"kp":[]},{"i":34036,"as":"","scd":null,"kp":[]},{"i":34037,"as":"在超排斥材料表面，粘性液滴的下落表现出两种模式：常规快速滚动和速度提升30至60倍的超级快速运动模式。这种超快运动模式依赖于液滴与基底的微弱接触，通过动态插入空气气垫可以“擦除”接触摩擦，从而大幅加快粘性液滴在排斥性斜坡上的移动速度。","scd":null,"kp":["[黏性液滴在超排斥倾斜表面上的运动模式]: 具有双峰动力学特征（根据沉积方式分为两种下降模式）","[超排斥材料]: 具有低接触线钉扎与微小动态摩擦的特性，使黏性液滴形成高流动性的珍珠状"]},{"i":34038,"as":"","scd":null,"kp":[]},{"i":34039,"as":"苜蓿等豆科植物在根瘤发育过程中表达约600种富含半胱氨酸（NCR）的肽，促使根瘤菌终末分化。中华根瘤菌具有共生必需的BacA(SbmA)蛋白，负责将特定的NCR肽输入其细胞质。这种输入机制允许NCR肽发生蛋白水解降解，从而保护内吞细菌免受这些肽的抗菌毒性影响。","scd":null,"kp":["NCR多肽表达量[苜蓿根瘤发育阶段]: 约600种"]},{"i":34040,"as":"氢水合物（HH）填充冰立方C2相具有极短的H2-H2O距离和1:1的化学计量比，形成由水分子和氢分子构成的两个相互渗透的相同金刚石亚晶格。高压条件下，氢分子和水网格的核量子效应占据主导，形成双晶格量子系统。研究探索了压力和温度驱动的相变过程及双量子锁定机制。","scd":null,"kp":["化学计量比[氢水合物立方C2相]: 1:1","[氢水合物立方C2相]: 具有超短H2-H2O距离和极强的主客体相互作用，形成两个互穿的相同类金刚石子晶格"]},{"i":34041,"as":"研究基于氧化石墨烯纳米片构建了耦合光系统I和细胞色素c氧化酶的原电池生物杂化纳米系统。通过拴在碳基底面上的Ni配位位点实现酶的定向固定，具有极小的寄生O2消耗。瞬态吸收和电化学测量证实了该嵌合体实现了光合作用与呼吸作用电子传输链的串联功能。","scd":null,"kp":["[嵌合体光合一呼吸电子传递链]: 基于氧化石墨烯纳米片表面耦合光系统I和细胞色素c氧化酶的自组装原电池生物杂化纳米系统"]},{"i":34042,"as":"碱性水电解（AWE）面临动态活性位点枯竭和局部离子浓度耗散的瓶颈。磁场增强AWE（ME-AWE）策略通过在阳极附近原位定向富集局部活性铁离子，打破了浓度极限，提升了动态铁活性位点的覆盖率，且未提高体相杂质水平。实验证实该策略通过优化铁嵌入动力学改善了析氧反应（OER）动力学。","scd":null,"kp":["[磁场增强碱性电解水(ME-AWE)策略]: 通过原位定向富集阳极附近的局部活性铁离子，打破浓度限制并提升水氧化性能"]},{"i":34043,"as":"结合静态大规模电子断层扫描重建和动态偏振光显微镜，研究在人类组织细胞中验证了有丝分裂纺锤体的活性液晶连续介质理论。在微米尺度上，局部相互作用（聚合、排列、扩散和极性运输）主导了微管的集体行为；而在亚微米尺度上，电子断层扫描揭示了染色体附着微管的具体离散特征。","scd":null,"kp":["[人类有丝分裂纺锤体]: 表现出活性液晶的集体行为特征，符合连续介质理论"]},{"i":34044,"as":"通过分子级结构控制编程材料的宏观特性是重大科学挑战。研究以嵌段共聚物为模型，提出一种基于自洽场理论（SCFT）的计算算法。该算法学习逆向转化，通过改变分子序列来实现目标自组装结构。这为定向设计特定分子以达成预期自组装结构的逆向设计提供了计算工具。","scd":null,"kp":["[嵌段共聚物逆向设计]: 利用自洽场理论(SCFT)算法通过分子级结构控制编程实现宏观材料的自组装"]},{"i":34045,"as":"研究提出一种甲硫氨酸选择性、不可逆的生物偶联策略，在温和含水反应条件下使用活化的烯丙基溴化物，兼容多种肽和蛋白质。与传统烯丙基溴化物相比，该方法提高了偶联物稳定性并抑制了非特异性反应。该技术实现了肽和蛋白质的优先标记，并在共价抑制剂设计和蛋白质功能化中得到概念验证应用。","scd":null,"kp":["[蛋氨酸特异性非逆转生物偶联技术]: 采用活化的烯丙基溴化物在温和水相条件下实现多肽和蛋白质的精准修饰，提高了偶联稳定性并抑制了非特异性反应"]},{"i":34046,"as":"结合组织病理学、空间转录组和单核RNA测序技术，研究绘制了人类小脑Bergmann神经胶质（BG）发育图谱。BG在受孕后约11周出现，最初作为普尔基涅细胞（PC）迁移的支架。在PC形成多层排列后，BG形成由分隔层（LD）隔开的独立平行层，两层在妊娠晚期融合。该发育时间线挑战了以往的认知。","scd":null,"kp":[]},{"i":34047,"as":"","scd":null,"kp":[]},{"i":34048,"as":"","scd":null,"kp":[]},{"i":34049,"as":"斑马鱼幼虫侧线系统对流体运动敏感。通过向神经丘提供方向性刺激并进行高分辨率钙成像，研究绘制了后脑响应图谱。研究结果揭示了基于以自我为中心的空间框架原则：大脑能够全脑集中处理侧线输入信号，编码相对于身体重心的水流方向，这打破了中枢侧线处理缺乏空间拓扑结构的传统观念。","scd":null,"kp":[]},{"i":34050,"as":"TMEM16A通道传导Ca2+激活的Cl-电流。利用门控分子动力学模拟和结构导向电生理学，研究表明PIP2和Ca2+通过变构偶联 Cooperative gating 协同控制TMEM16A通道。这种双重调节的分子机制具体依赖于两者的结合位点间的变构偶联作用，从而共同开启离子通道。","scd":null,"kp":[]},{"i":34051,"as":"菊科植物在中始新世经历了古老的全基因组三倍化（古六倍体化）。通过对23个桔梗目基因组进行共线性系统发育分析，鉴定出可追溯至菊科共同二倍体祖先的16个基因组群。每个群经历了三倍化，产生共计48个基因组块（16x3），代表了菊科祖先基因组，揭示了古六倍体衍生的基因组块在菊科中的分布。","scd":null,"kp":["[菊科植物演化]: 中始新世时期发生了古老的全基因组三倍化（古六倍化）事件"]},{"i":34052,"as":"","scd":null,"kp":[]},{"i":34053,"as":"","scd":null,"kp":[]},{"i":34054,"as":"对370个人类室管膜瘤样本的转录组分析揭示了两个不同的分子亚组：EPN-E1和EPN-E2。其中EPN-E1集群富含携带ZFTA-RELA融合的幕上肿瘤，预后较差。通过系统方法验证，研究确定MERTK为ZFTA-RELA驱动的室管膜瘤的治疗弱点，为这种侵袭性亚型的靶向治疗提供了新方向。","scd":null,"kp":["室管膜瘤流行病学[儿童颅内肿瘤]: 约占10%","分子亚型分类[370个人类室管膜瘤样本转录组分析]: 鉴定为EPN-E1和EPN-E2两个不同的分子亚组"]},{"i":34055,"as":"","scd":null,"kp":[]},{"i":34056,"as":"","scd":null,"kp":[]},{"i":34057,"as":"","scd":null,"kp":[]},{"i":34058,"as":"","scd":null,"kp":[]},{"i":34059,"as":"","scd":null,"kp":[]},{"i":34060,"as":"","scd":null,"kp":[]},{"i":34061,"as":"研究提出一种用于表征自旋量子比特的可扩展架构，采用平面锗材料实现量子点交叉阵列。该测试工程平台包含紧密间距的自旋量子比特图块，具备容纳1,058个单空穴自旋量子比特的潜力。在毫开尔文温度下对其中40个图块进行测量，成功展示了关键的设备功能，包括图块可寻址性。","scd":null,"kp":["量子器件表征测试环境[自旋量子比特]: 毫开尔文温度及磁场环境","表征架构[自旋量子比特]: 量子点十字阵列"]},{"i":34062,"as":"","scd":null,"kp":[]},{"i":34063,"as":"","scd":null,"kp":[]},{"i":34064,"as":"","scd":null,"kp":[]},{"i":34065,"as":"","scd":null,"kp":[]},{"i":34066,"as":"","scd":null,"kp":[]},{"i":34067,"as":"","scd":null,"kp":[]},{"i":34068,"as":"","scd":null,"kp":[]},{"i":34069,"as":"为应对气候变化引发的作物光合作用受损和氧化应激增加，研究人员开发了一种可贴附在叶片上的微针贴片。该贴片在近红外光激活下释放营养物质和抗氧化剂。这种直接的生物界面技术改善了棉花等植物的生长和抗逆性，且无化学残留，为气候变暖下的可持续农业提供了有效保护手段。","scd":null,"kp":["释放触发条件[微针纳米酶贴片]: 近红外光激活","应用部位[农作植物]: 直接附着于叶片","技术优势[农用化学品递送]: 无化学残留并提高植物生长和抗逆性"]},{"i":34070,"as":"","scd":null,"kp":[]},{"i":34071,"as":"","scd":null,"kp":[]},{"i":34072,"as":"","scd":null,"kp":[]},{"i":34073,"as":"","scd":null,"kp":[]},{"i":34074,"as":"","scd":null,"kp":[]},{"i":34075,"as":"","scd":null,"kp":[]},{"i":34076,"as":"","scd":null,"kp":[]},{"i":34077,"as":"","scd":null,"kp":[]},{"i":34078,"as":"","scd":null,"kp":[]},{"i":34079,"as":"","scd":null,"kp":[]},{"i":34080,"as":"研究提出一种将天然木材转化为结构一体化、可定制设计的吸湿冷却木基水凝胶的技术。该结构解决了现有装置热质动力学不佳的难题，能够在白天实现稳定的混合冷却驱动发电，为全球能源危机提供了一种可持续的解决方案。","scd":null,"kp":["材料结构[天然木材转化]: 吸湿性水气凝胶(HCW)","系统功能[ HCW一体化结构]: 日间稳定混合冷却驱动发电","技术突破[新型水气凝胶设计]: 解决现有装置热质动力学不良的挑战"]},{"i":34081,"as":"","scd":null,"kp":[]},{"i":34082,"as":"","scd":null,"kp":[]},{"i":34083,"as":"","scd":null,"kp":[]},{"i":34084,"as":"","scd":null,"kp":[]},{"i":34085,"as":"","scd":null,"kp":[]},{"i":34086,"as":"","scd":null,"kp":[]},{"i":34087,"as":"","scd":null,"kp":[]},{"i":34088,"as":"","scd":null,"kp":[]},{"i":34089,"as":"","scd":null,"kp":[]},{"i":34090,"as":"","scd":null,"kp":[]},{"i":34091,"as":"","scd":null,"kp":[]},{"i":34092,"as":"","scd":null,"kp":[]},{"i":34093,"as":"","scd":null,"kp":[]},{"i":34094,"as":"锂硫电池因多电子氧化还原反应、高理论能量密度（2500 Wh/kg）和成本效益成为大规模储能的重要技术。针对可溶性液相中间体和固体硫沉淀导致循环稳定性差的问题，本综述探讨了使用可溶性硫物种作为正极活性材料的半液态锂硫电池，以解决不可逆的固-液-固相变问题。","scd":null,"kp":["理论能量密度[锂硫电池]: 2500 Wh/kg","储能机制[锂硫电池]: 多电子氧化还原反应","应用定位[半液态锂硫电池]: 规模化储能"]},{"i":34095,"as":"研究开发了一种无溶剂、可扩展的二氧化碳激光烧蚀技术，用于制造超可拉伸的超疏液表面。通过引入机器学习框架，直接确定最佳的激光烧蚀条件，避免了繁冗的试错实验。最终制得的表面在承受400%应变和超过5000次拉伸-释放循环等多种形变模式下，均能保持超疏液特性。","scd":null,"kp":["制备工艺[超疏液表面制备]: 无溶剂CO2激光烧蚀技术","极限拉伸应变[超全疏液表面]: 400%","耐久性[超全疏液表面]: 5000次以上拉伸-释放循环","技术优势[激光烧蚀条件优化]: 利用机器学习框架识别最优激光烧蚀条件以避免大量试错"]},{"i":34096,"as":"","scd":null,"kp":[]},{"i":34097,"as":"","scd":null,"kp":[]},{"i":34098,"as":"","scd":null,"kp":[]},{"i":34099,"as":"","scd":null,"kp":[]},{"i":34100,"as":"","scd":null,"kp":[]},{"i":34101,"as":"","scd":null,"kp":[]},{"i":34102,"as":"","scd":null,"kp":[]},{"i":34103,"as":"","scd":null,"kp":[]},{"i":34104,"as":"","scd":null,"kp":[]},{"i":34105,"as":"","scd":null,"kp":[]},{"i":34106,"as":"","scd":null,"kp":[]},{"i":34107,"as":"本研究将智能材料应用于软体机器人领域，解决了形状记忆合金训练及场景适应性受限的问题。利用机器学习构建了NiTi合金训练参数的智能预测模型。通过对NiTi合金丝进行编程训练并结合仿生原型，成功创造出完全由NiTi合金驱动、具备一维到三维形态转换能力的软体机器人。","scd":null,"kp":["预测模型构建材料[软体机器人智能训练]: 镍钛形状记忆合金","驱动机制[软体机器人]: 纯镍钛合金丝驱动","形态转换能力[软体机器人]: 从一维到三维的形态转变"]},{"i":34108,"as":"","scd":null,"kp":[]},{"i":34109,"as":"","scd":null,"kp":[]},{"i":34110,"as":"","scd":null,"kp":[]},{"i":34111,"as":"","scd":null,"kp":[]},{"i":34112,"as":"","scd":null,"kp":[]},{"i":34113,"as":"","scd":null,"kp":[]},{"i":34114,"as":"碲化锗是一种极具潜力的热电材料，但受限于高空穴浓度导致的低塞贝克系数和高热导率。研究发现，在其中加入碘化亚铜能够同步调节空穴浓度和热导率，在维持良好电气性能的同时有效阻挡热流，显著提升了热电转换效率。该策略为先进能源回收和制冷应用中的材料优化提供了通用方法。","scd":null,"kp":["不平衡抑制策略[碲化锗热电材料]: 添加碘化铜盐","改性机理[碲化锗]: 同步调控空穴浓度和热导率","改性效果[碲化锗]: 在维持良好电学性能的同时更有效地阻挡热流"]},{"i":34115,"as":"","scd":null,"kp":[]},{"i":34116,"as":"研究开发了用于光催化苄胺偶联反应的多层二维氧化钛膜。通过调控层间距、光强度和膜厚度，该反应在室温下7秒内实现了99.2%的转化率和99.3%的选择性。机理表明，该膜增强了电荷分离与转移效率，且空间限域效应和金属空位极大促进了反应物吸附并降低了反应能垒。","scd":null,"kp":["目标产物转化率[光催化苯甲胺偶联反应]: 99.2%","目标产物选择性[光催化苯甲胺偶联反应]: 99.3%","反应条件[二维氧化钛膜限域光催化]: 室温下7秒内完成","性能强化机理[多层氧化钛膜]: 增强电荷分离和转移效率，结合空间限域和金属空位效应"]},{"i":34117,"as":"研究提出了一种全水相自由基转移接枝策略，在保留天然纳米结构的前提下，从硫醇化纤维中生长短链聚丙烯酸低聚物，使纤维素纤维的电荷密度达到6.7 mmol/g。所得超荷电纤维展现出优异的吸附性能并支持水解回收，为高性能生物基材料提供了可扩展且可调的化学平台。","scd":null,"kp":["电荷密度[纤维素纤维]: 6.7 mmol/g","改性工艺[纤维素纤维超荷电化]: 全水相自由基转移接枝策略","技术优势[超荷电纤维]: 在达到高电荷密度的同时保留原生天然结构且可水解回收"]},{"i":34118,"as":"研究利用构象生物传感器揭示了G蛋白偶联受体（GPCR）在内涵体中对G蛋白的调控机制。三种Gs偶联的GPCR能够引发Gαs从细胞膜向内涵体的净重分布，且无需受体内在化。而内涵体上活性态Gαs的产生则依赖于GPCR内在化。此外，研究还发现了GPCR在内涵体与细胞膜之间偶联选择性的位置偏差。","scd":null,"kp":[]},{"i":34119,"as":"针对地球同位素不平衡问题，第一性原理结构和熔点计算表明，高压下的铅硫相能够在地幔深处稳定储存非放射成因铅。PbS早期结晶并在核幔边界保持固态，形成与铀、钍隔离的长期储库。在富硫条件下，PbS可反应形成多硫化物相（PbS2和PbS3），其截然不同的熔融行为促进了铅的储存和有限的向上运移。","scd":null,"kp":["研究方法[地幔铅储层预测]: 第一性原理结构预测和熔点计算","稳定主岩结构[地球深部地幔非放射性成因铅]: 高压Pb-S相","地球化学意义[未放射成因铅隐藏储层]: 解释硅酸盐地球与球粒陨石之间的同位素不平衡"]},{"i":34120,"as":"研究开发了具有高薄膜厚度耐受性的半透明有机太阳能电池，适用于建筑集成光伏。活性层厚度为119纳米和301纳米的器件，其光利用率分别达到4.04%和3.02%。面积100平方厘米的组件组件失配比（CTM）约为85%，光利用率为3.32%。通过600平方厘米的发电窗户模型，验证了其在发电、储能和温度控制方面的可行性。","scd":null,"kp":["活性层厚度[供体稀释半透明有机太阳能电池]: 119 nm 和 301 nm","光利用率[供体稀释半透明有机太阳能电池]: 4.04% 和 3.02%","组件面积[半透明有机太阳能电池模块]: 100 cm2","组件-电池效率比(CTM)[大面积半透明模块]: ~85%","光利用率[大面积半透明模块]: 3.32%"]},{"i":34121,"as":"淀粉样蛋白在已有纤维表面形成新纤维和寡聚体的二次成核过程是引发阿尔茨海默病等疾病的重要驱动因素。利用特定抑制剂Brichos证实，由Aβ40和Aβ42肽组成的纤维上的二次成核位点数量十分稀少。研究指出，这些二次成核位点主要位于原纤维组装过程中引入的罕见生长缺陷处，即纤维核心结构的不规则处。","scd":null,"kp":[]},{"i":34122,"as":"转录因子Twist1驱动的内皮-间质转化与晚期动脉粥样硬化斑块的发展密切相关。在高胆固醇小鼠模型中诱导内皮细胞敲除Twist1，结合单细胞RNA测序证实，内皮Twist1能够促进晚期斑块内的内皮-间质转化。组织学分析表明，Twist1不仅促进斑块生长，还增加了胶原蛋白等斑块稳定性特征，并减少了坏死等不稳定特征。","scd":null,"kp":[]},{"i":34123,"as":"","scd":null,"kp":[]},{"i":34124,"as":"","scd":null,"kp":[]},{"i":34125,"as":"","scd":null,"kp":[]},{"i":34126,"as":"","scd":null,"kp":[]},{"i":34127,"as":"","scd":null,"kp":[]},{"i":34128,"as":"","scd":null,"kp":[]},{"i":34129,"as":"通过在聚合物受体中引入线性排列的小分子受体，有效抑制了分子的自缠结并增强了聚合物太阳能电池的结构有序性。该方法打破了效率与稳定性之间的权衡，使器件的功率转换效率超过19%，并在空气中获得了超过2000小时的T97运行寿命，实现了超稳定运行。","scd":null,"kp":["能量转换效率[聚合物太阳能电池]: 超过19%","T97运行寿命[空气中运行的聚合物太阳能电池]: 超过2000小时"]},{"i":34130,"as":"","scd":null,"kp":[]},{"i":34131,"as":"","scd":null,"kp":[]},{"i":34132,"as":"","scd":null,"kp":[]},{"i":34133,"as":"","scd":null,"kp":[]},{"i":34134,"as":"","scd":null,"kp":[]},{"i":34135,"as":"III族氮化物高电子迁移率晶体管在高温电子领域具有应用潜力。研究分析了该晶体管的高温运行情况，探讨了高温对材料属性、器件结构和电路级行为的影响。通过优化势垒层与沟道工程、选择合适基底以及采用钝化策略，有效缓解了高温引起的负面效应，并评估了其在逻辑和射频电路中的热稳定性。","scd":null,"kp":["[III族氮化物高电子迁移率晶体管]: 具备在高温电子应用（如电力电子、通信、航空航天等）中运行的潜力"]},{"i":34136,"as":"","scd":null,"kp":[]},{"i":34137,"as":"","scd":null,"kp":[]},{"i":34138,"as":"","scd":null,"kp":[]},{"i":34139,"as":"研究开发了一种用于增强碱性介质中乙醇氧化反应的模块化多界面纳米晶体催化剂。该催化剂集成了Co2P/Pd核壳与PdAu异质结构界面，其中Co2P/Pd界面加速了乙酸盐的生成，而PdAu界面则促进了CO的脱附清除。这种多界面协同作用赋予了催化剂卓越的催化活性。","scd":null,"kp":["[碱性电解液乙醇氧化反应]: 开发了一种集成Co2P/Pd核壳和PdAu异质结构界面的模块化多界面纳米晶催化剂","催化机制[Co2P/Pd界面]: 加速醋酸盐形成","催化机制[PdAu异质结构]: 促进CO脱附去除"]},{"i":34140,"as":"研究构建了由垂直1T'/2H-MoTe2/ITO器件组成的范德华集成交叉阵列，用于可见光和近红外区域的超低功耗成像。不对称电极实现了自供电光电探测。该交叉阵列中的垂直器件具备可调节的原子级通道和较大的光照面积，有效增强了光电响应，为二维材料光电探测器的性能优化与集成提供了新策略。","scd":null,"kp":["[范德华集成交叉阵列]: 由垂直1T'/2H-MoTe2/ITO器件组成，用于可见光和近红外区域的超低功耗成像","[垂直交叉阵列光电探测器]: 不对称电极实现自供电光电探测，具有可调原子级通道和大照明面积"]},{"i":34141,"as":"该研究引入了一种暗场电子断层扫描技术，能够以亚纳米级分辨率重建三维晶粒形态和取向，实现对晶界平面和曲率的定量分析。研究结果揭示了由热驱动的晶界向Schwarz晶体演化的过程，为纳米晶金属的结构稳定性提供了全新见解。","scd":null,"kp":["分辨率[暗场电子断层扫描重建三维晶粒形态和取向]: 亚纳米级","[热驱动晶界演化]: 向Schwarz晶体方向演化，提供纳米晶金属结构稳定性新见解"]},{"i":34142,"as":"为解决半月板修复难题，研究开发了一种具有仿生力学的3D打印连续蚕丝增强支架。通过原位浸渍和3D打印技术，将蚕丝整合到聚己内酯基长丝中，使支架具备类似半月板的各向异性、粘弹性及抗疲劳和缝合能力。该支架促进了细胞增殖、分化与组织重塑，转录组学揭示了动态机械刺激下多条机械转导通路的激活。","scd":null,"kp":[]},{"i":34143,"as":"","scd":null,"kp":[]},{"i":34144,"as":"","scd":null,"kp":[]},{"i":34145,"as":"","scd":null,"kp":[]},{"i":34146,"as":"","scd":null,"kp":[]},{"i":34147,"as":"","scd":null,"kp":[]},{"i":34148,"as":"","scd":null,"kp":[]},{"i":34149,"as":"","scd":null,"kp":[]},{"i":34150,"as":"","scd":null,"kp":[]},{"i":34151,"as":"","scd":null,"kp":[]},{"i":34152,"as":"受豆腐皮成型过程启发，研究提出了一种界面老化策略，精确控制碳纳米管薄膜的致密化过程。该简便方法制造出具有高度可编程裂纹结构的可拉伸复合材料，进而研发出光电协同表皮传感器。这些传感器提供了灵敏可调的电应变传感和光学信息加密功能，推动了可靠的多功能可穿戴传感技术发展。","scd":null,"kp":["[碳纳米管薄膜]: 受豆腐皮形成启发，采用界面老化策略精确控制其致密化","[表皮传感器]: 制造出具有高度可编程裂纹结构的可拉伸复合材料，提供可调谐的敏感电应变传感和光学信息加密"]},{"i":34153,"as":"","scd":null,"kp":[]},{"i":34154,"as":"针对气泡在液面聚集降低系统性能的问题，实验表明，将高透气亲气膜置于液-气界面可在几毫秒内消除气泡。当透气性超过临界阈值时，流动会脱离微孔中的经典达西动力学，呈现出超快除泡机制。研究考察了单个气泡接近膜时的局部相互作用，确定了三种渐近的排气状态，并用标度定律解释了其物理机制。","scd":null,"kp":["[气液界面除泡]: 在液-气界面放置高透气性亲气膜可在毫秒级内消灭气泡","[气泡消灭超快机制]: 仅在高于临界渗透率阈值时出现，微孔内流动脱离经典达西驱动动力学"]},{"i":34155,"as":"","scd":null,"kp":[]},{"i":34156,"as":"","scd":null,"kp":[]},{"i":34157,"as":"研究人员设计出一种具有超排列和致密结构的仿竹Ti3C2Tx膜，展现出优异的质子选择性传输特性。在常规废水处理过程（酸碱中和）中，该膜实现了水和能源的同步回收。该技术为解决水资源和能源危机提供了有效途径。","scd":null,"kp":["[仿竹纳米流体Ti3C2Tx膜]: 具有超顺排和致密化结构，表现出优异的质子选择性传输行为","[废水酸碱中和过程]: 利用该仿生膜实现了水和能源的同步回收"]},{"i":34158,"as":"","scd":null,"kp":[]},{"i":34159,"as":"","scd":null,"kp":[]},{"i":34160,"as":"","scd":null,"kp":[]},{"i":34161,"as":"","scd":null,"kp":[]},{"i":34162,"as":"","scd":null,"kp":[]},{"i":34163,"as":"","scd":null,"kp":[]},{"i":34164,"as":"","scd":null,"kp":[]},{"i":34165,"as":"","scd":null,"kp":[]},{"i":34166,"as":"","scd":null,"kp":[]},{"i":34167,"as":"","scd":null,"kp":[]},{"i":34168,"as":"","scd":null,"kp":[]},{"i":34169,"as":"研究利用第一性原理计算揭示了多种金属在粘土矿物表面的竞争吸附微观机制。结果表明，金属离子尺寸主导了其在粘土矿物表面的络合，多金属竞争吸附在吸附过程中起关键调节作用。结合理论与实验数据，该框架为准确预测水土环境中有毒金属的分布提供了模型。","scd":null,"kp":["[多重金属在黏土矿物上的竞争吸附]: 揭示了多金属在异质黏土矿物表面竞争吸附的微观机制，为预测土壤-水环境中有毒金属分布提供框架"]},{"i":34170,"as":"对5114种期刊和520万篇论文的分析显示，尽管70%的期刊出台了AI使用政策（主要要求披露），研究人员在各学科中对AI写作工具的使用仍急剧增加，有无政策并无显著差异。非英语国家、物理科学和开放获取期刊的增长率最高。对16.4万篇出版物的全文分析揭示了严重的透明度差距，绝大多数受政策约束的论文并未按规定披露AI使用情况。","scd":null,"kp":["AI政策采用率[学术期刊]: 70%","分析样本量[学术期刊]: 5,114本","分析样本量[相关论文]: 超过520万篇"]},{"i":34171,"as":"美国可再生能源供电的低成本特性导致空间供需不匹配和电网输电网络紧张。研究指出，消除跨区域输电限制将使美国本土48州2022年和2023年的发电成本分别降低58至71亿美元和34至50亿美元。然而，市场整合在降低系统总成本的同时会改变发电公司的利益分配，部分地区的生产商有动机阻碍电网整合。","scd":null,"kp":["发电成本降低[消除区域间电网输电约束-2022年]: 58亿至71亿美元","发电成本降低[消除区域间电网输电约束-2023年]: 34亿至50亿美元"]},{"i":34172,"as":"","scd":null,"kp":[]},{"i":34173,"as":"神经元中线粒体结构蛋白Mic19的缺失会破坏线粒体完整性，激活Z-mtDNA-ZBP1-RIPK3-MLKL轴，导致线粒体膜孔形成和mtDNA泄漏。泄漏的mtDNA被小胶质细胞摄取，触发cGAS-STING依赖性炎症信号传导和丝氨酸代谢重编程。这一“线粒体-免疫-代谢”轴驱动了自发性的慢性癫痫发生。","scd":null,"kp":[]},{"i":34174,"as":"","scd":null,"kp":[]},{"i":34175,"as":"研究使用深度神经网络和强化学习（RL）智能体执行奖励引导学习任务，以计算模拟人类的错误监控和元控制机制。只有当深度RL智能体被设计为能显式预测内侧前额叶皮层中触发的动作预测误差时，才能展现出与人类高度相似的元控制特征。此外，当智能体被训练为高估或低估控制能力时，它们能够模拟出人类元控制的病理特征。","scd":null,"kp":["任务解决能力[深度强化学习智能体]: 仅在适应动作可控性变化的设计下才能完成任务"]},{"i":34176,"as":"大环超分子发光系统通过非共价相互作用精确控制发射特性，为传统发光系统提供了有效替代方案。大环主体利用主客体相互作用提高发光效率、产生新发光特性并促进刺激响应行为。本文综述了新型大环超分子发光系统在构建和应用方面的最新进展，展示了其在超分子化学和材料科学领域的重要地位。","scd":null,"kp":["发光系统调控机制[大环超分子体系]: 通过非共价相互作用精确控制发射特性","发光增强机制[大环主体-客体相互作用]: 增强发光效率并产生新发光特性"]},{"i":34177,"as":"","scd":null,"kp":[]},{"i":34178,"as":"","scd":null,"kp":[]},{"i":34179,"as":"","scd":null,"kp":[]},{"i":34180,"as":"","scd":null,"kp":[]},{"i":34181,"as":"","scd":null,"kp":[]},{"i":34182,"as":"","scd":null,"kp":[]},{"i":34183,"as":"","scd":null,"kp":[]},{"i":34184,"as":"压缩空气储能（CAES）可作为可再生能源电网的长时储能方案，其利用电能驱动压缩机压缩空气，并在需要时释放驱动涡轮机发电。大型CAES设施可存储超过300兆瓦的电力，往返效率为50%至70%。为适应不可调度的可再生能源，需改进压缩机和膨胀机以提高可变负载下的运行压力和效率。压缩空气可存储于地质构造或人工容器中。","scd":null,"kp":["储能规模[大型压缩空气储能设施]: >300 MW","往返效率[压缩空气储能系统]: 50-70%"]},{"i":34185,"as":"研究提出一种高熵工程方法来开发兼具热传感器和热障双重功能的陶瓷材料。高熵工程赋予了陶瓷优异的热障性能。通过Tb3+到Eu3+的交叉弛豫介导能量转移过程，打破了超高温度下的理论测温灵敏度极限，展示了该材料在航空航天工业中进行3D动态高温成像的应用潜力。","scd":null,"kp":["材料功能[高熵工程石榴石陶瓷]: 兼具热传感器与热障双功能","能量转移机制[Tb3+到Eu3+]: 交叉弛豫介导","应用前景[高灵敏度温度测量]: 突破超高温度下的理论测温灵敏度极限"]},{"i":34186,"as":"本研究提出了一种名为GrainBot的人工智能分析框架，利用深度学习和可解释性分析将多晶材料的复杂显微镜图像转化为机器可读的定量数据。该工具包实现了精确的晶粒级表征，揭示了结构特征之间的隐藏关联，为材料科学领域的数据驱动研究、闭环发现以及自驱动实验室奠定了基础。","scd":null,"kp":["分析框架[GrainBot多晶材料显微图像]: 结合深度学习与可解释分析的AI驱动定量化框架","表征能力[晶粒级别]: 精确的晶粒级表征并揭示结构特征间的隐藏关系"]},{"i":34187,"as":"动态聚合物注释库（DPAL）是一个汇集同行评议研究的注释库。它通过将医学领域常用的系统性文献检索方法进行重新设计，使其更广泛地适用于材料设计问题，从而填补了材料科学领域的知识空白。","scd":null,"kp":["动态聚合物标注库[材料科学文献自动化策展]: 将医学领域的系统文献检索方法重新设计并应用于材料设计"]},{"i":34188,"as":"受沙漠甲虫和仙人掌刺的启发，研究人员设计出一种仿生楔形结构电极，有效克服了海水电解中阴极气泡脱离缓慢和Mg2+/Ca2+沉淀造成的活性位点堵塞问题。该电极能够排斥盐分并引导气体定向传输，实现了高效耐用的制氢过程。其制氢成本约为每公斤1.7美元，低于美国能源部设定的2030年每公斤2美元的目标。","scd":null,"kp":["制氢成本[仿生楔形结构电极海水产氢]: ~1.7美元/kg H2","电极设计[克服盐分沉淀挑战]: 受沙漠甲虫和仙人掌刺启发的仿生楔形结构","性能表现[仿生流导向电极]: 促进排盐和定向气体传输的高效稳定产氢"]},{"i":34189,"as":"","scd":null,"kp":[]},{"i":34190,"as":"","scd":null,"kp":[]},{"i":34191,"as":"","scd":null,"kp":[]},{"i":34192,"as":"","scd":null,"kp":[]},{"i":34193,"as":"","scd":null,"kp":[]},{"i":34194,"as":"","scd":null,"kp":[]},{"i":34195,"as":"","scd":null,"kp":[]},{"i":34196,"as":"研究报道了一种基于转移二维材料构建大规模电路的代工厂导向策略。该方法涵盖电路设计、材料生长、转移和器件制造等六个方面的测试与迭代优化。通过制备约130批次样品提高各层级的良率，最终成功制造出单晶体管良率近100%、开关比大于10^7的完整微处理器，解决了二维材料芯片低产率和实验室制造的限制。","scd":null,"kp":["芯片良率问题[大规模2D材料数百晶体管芯片]: 低良率且依赖实验室制备","晶圆代工适配策略[2D材料大规模电路制备]: 包含电路设计、版图设计、材料生长、材料转移、器件制造等六个方面测试与迭代优化"]},{"i":34197,"as":"","scd":null,"kp":[]},{"i":34198,"as":"","scd":null,"kp":[]},{"i":34199,"as":"","scd":null,"kp":[]},{"i":34200,"as":"","scd":null,"kp":[]},{"i":34201,"as":"","scd":null,"kp":[]},{"i":34202,"as":"","scd":null,"kp":[]},{"i":34203,"as":"","scd":null,"kp":[]},{"i":34204,"as":"","scd":null,"kp":[]},{"i":34205,"as":"","scd":null,"kp":[]},{"i":34206,"as":"","scd":null,"kp":[]},{"i":34207,"as":"","scd":null,"kp":[]},{"i":34208,"as":"","scd":null,"kp":[]},{"i":34209,"as":"","scd":null,"kp":[]},{"i":34210,"as":"","scd":null,"kp":[]},{"i":34211,"as":"","scd":null,"kp":[]},{"i":34212,"as":"","scd":null,"kp":[]},{"i":34213,"as":"","scd":null,"kp":[]},{"i":34214,"as":"","scd":null,"kp":[]},{"i":34215,"as":"","scd":null,"kp":[]},{"i":34216,"as":"","scd":null,"kp":[]},{"i":34217,"as":"","scd":null,"kp":[]},{"i":34218,"as":"","scd":null,"kp":[]},{"i":34219,"as":"","scd":null,"kp":[]},{"i":34220,"as":"","scd":null,"kp":[]},{"i":34221,"as":"","scd":null,"kp":[]},{"i":34222,"as":"","scd":null,"kp":[]},{"i":34223,"as":"","scd":null,"kp":[]},{"i":34224,"as":"一种由氧化石墨烯支撑的环唑-偶氮苯共价网络被用作光可再生吸附剂，用于选择性提取锂。在可见光下，该吸附剂对锂离子的捕获量达15.27 mmol/g，Li+/Mg2+选择性为11.44。在紫外光照射下，偶氮苯异构化为顺式状态，扩大环唑空腔并在6分钟内触发离子释放。该技术为节能可持续的离子提取开辟了新途径。","scd":null,"kp":["吸附容量[可见光下选择性提锂]: 15.27 mmol g−1","离子选择性[Li+/Mg2+]: 11.44","释放时间[紫外光诱导顺式异构化释锂]: 6 min","吸附剂材料[光再生提锂]: 氧化石墨烯支撑的环胺-偶氮苯共价网络"]},{"i":34225,"as":"研究提出一种以客体为中心的策略，将热活化延迟荧光发射体掺入压电主体材料中，构建高性能的有机主客体机械发光（ML）系统。这些系统在可见光谱范围内展现出高效、可重现且热增强的机械发光特性。该材料在抗热猝灭应力映射、可重复使用可穿戴设备和实时结构健康监测方面具有广阔的应用潜力。","scd":null,"kp":["发光系统[有机主客体机械发光]: 热活化延迟荧光发射体结合压电主体材料","[热增强机械发光]: 具有抗热淬灭、高度可重复及高效率特性"]},{"i":34226,"as":"","scd":null,"kp":[]},{"i":34227,"as":"","scd":null,"kp":[]},{"i":34228,"as":"","scd":null,"kp":[]},{"i":34229,"as":"","scd":null,"kp":[]},{"i":34230,"as":"","scd":null,"kp":[]},{"i":34231,"as":"","scd":null,"kp":[]},{"i":34232,"as":"","scd":null,"kp":[]},{"i":34233,"as":"非晶态电致变色三氧化物在电荷插入过程中的原位光吸收演变可分为三个阶段：第一阶段吸收主要发生在低能区；第二阶段吸收逐渐向高能区转移；第三阶段吸收在较高能区稳定。该研究明确揭示了MOx在电荷插入期间光吸收特性的阶段性演变规律。","scd":null,"kp":["光学吸收演变[非晶电致变色三氧化物电荷嵌入阶段-I]: 主要发生在低能区","光学吸收演变[非晶电致变色三氧化物电荷插入阶段-II]: 逐渐向高能区转移","光学吸收演变[非晶电致变色三氧化物电荷插入阶段-III]: 在高能区达到稳定"]},{"i":34234,"as":"","scd":null,"kp":[]},{"i":34235,"as":"利用植物来源且无细胞因子的生物墨水，可生成具有免疫指导性的骨类器官，能够内在募集巨噬细胞并将其重编程为长效的M2表型。芦荟-纳米粘土-GelMA系统将免疫调节与增强的成骨、细胞外基质成熟及结构可印刷性相结合，实现了稳健的颅骨缺陷修复，为免疫响应性骨类器官工程建立了可扩展的转化平台。","scd":null,"kp":["生物墨水[构建免疫 instructive 骨类器官]: 植物衍生且无细胞因子的生物墨水","系统组成[芦荟-纳米粘土-GelMA]: 整合免疫调节、增强成骨作用、ECM成熟与结构可印刷性"]},{"i":34236,"as":"高熵合金化使钙钛矿纳米晶体在室温下实现稳健的单光子发射。通过引入多种金属阳离子，晶格无序化将激子局域化，减弱了电子-声子耦合，并抑制了陷阱辅助的复合。这些机制使得材料产生几乎不闪烁的深蓝色发射，在室温下单光子纯度高达96%，确立了面向实用量子光源的内在材料设计路径。","scd":null,"kp":["单光子纯度[室温下高熵合金钙钛矿纳米晶]: 96%","发光特征[深蓝光发射]: 几乎不闪烁","[材料设计机制]: 引入多种金属阳离子引发晶格无序，从而局域激子、减弱电声子耦合并抑制陷阱辅助复合"]},{"i":34237,"as":"X射线可在钙钛矿纳米晶体超晶格中触发超荧光，激活相干集体发射而非非相干复合。由此产生的闪烁具有超快、相干且高效的特点，并具有大斯托克斯位移，有效抑制了高密度纳米晶体组件中普遍存在的重吸收问题，确立了量子闪烁这一在电离辐射下获取相干光学观测量的全新体系。","scd":null,"kp":["闪烁发光机制[X射线激发钙钛矿纳米晶超晶格]: 触发超荧光实现集体发射而非非相干复合","[闪烁特性]: 具有超快、相干、高效特点，且大斯托克斯位移抑制了密集组装纳米晶中的重吸收问题"]},{"i":34238,"as":"研究人员利用液-液相分离技术，引入了一种微滴辅助折叠策略，专门用于处理原子级薄且机械脆弱的二维材料。通过进一步控制折叠方向，能够实现可调的层间堆叠角度，为工程化摩尔超晶格提供了新机遇。","scd":null,"kp":["折叠策略[液液相分离辅助二维材料]: 液滴辅助折叠策略","[工艺特点]: 能够控制折叠方向以实现可调的层间堆叠角，为工程化莫尔超晶格提供机会"]},{"i":34239,"as":"该研究提出了一种限域微流体掺杂（CMD）方法，类似于漏印版工艺，能够直接在有机半导体薄膜上“打印”功能区域。该技术无需使用金属电极，仅靠单一柔性聚合物材料即可构建复杂电路，有效简化了高性能柔性电子器件的制造流程，实现了类似硅芯片离子注入般的精确区域掺杂。","scd":null,"kp":["掺杂方法[有机半导体精密掺杂与器件工程]: 限制微流体掺杂(CMD)法","[工艺特点]: 无需金属电极，允许将功能区域直接“印刷”到有机半导体薄膜上以构建复杂电路"]},{"i":34240,"as":"研究开发出一种充当“液体焊料”的可变形电极，能够在刚性热电材料与柔性基底之间建立坚固稳定的连接。采用该技术制造的可穿戴器件兼具出色的拉伸性和高发电效率，仅依靠体温即可驱动计步器，且无需散热器即可提供主动皮肤冷却功能。","scd":null,"kp":["电极材料[可拉伸热电器件连接]: 类似“液态焊料”的两亲性可变形互连材料","[器件应用特性]: 结合优异拉伸性与高发电效率，能仅靠体热驱动计步器并提供无散热器的主动皮肤冷却"]},{"i":34241,"as":"该工作通过重力翻转退火策略制备出兼具应变不变电导率和Janus粘附性的软体导电有机凝胶，构建了稳健的皮肤界面。结合基于Transformer的神经网络，该有机凝胶电极可提供抗振动的高精度记录，并对生理信号进行智能解码，推进了新一代生物电子传感与刺激技术的发展。","scd":null,"kp":["有机凝胶特性[AI辅助生物电子学]: 应变不变的电导率与Janus粘附性","[电极系统功能]: 结合基于Transformer的神经网络，提供抗振动记录并智能解码生理信号"]},{"i":34242,"as":"以多晶铝硅酸盐微纤维为反应模板，在双催化剂体系中通过协同刻蚀-催化机制，制备出由单晶莫来石纳米线组成的轻质整体气凝胶。这种自支撑且无晶界的纳米线网络，使材料在高达1700°C的极端温度下依然保持优异的隔热性能和结构稳定性，确立了极端环境热防护材料的新范式。","scd":null,"kp":["耐温性能[单晶莫来石纳米线气凝胶]: 1700°C","微观结构[单晶莫来石纳米线气凝胶]: 无晶界自支撑纳米线网络","合成机制[双催化剂体系]: 协同刻蚀-催化机制"]},{"i":34243,"as":"","scd":null,"kp":[]},{"i":34244,"as":"电荷密度波在低维系统中经历连续的熔化过程，依次形成部分有序的向列相和六角相。热激发引发的电子无序化最初通过改变局部波长的平滑弹性变形出现，随后通过位错成核产生。低维电子熔化具有三个显著特征：方位角超晶格峰展宽、波矢收缩以及积分强度衰减。","scd":null,"kp":["[低维电荷密度波熔解]: 连续经过部分有序的向列相和六角相状态并逐步产生位错","电子熔化特征[低维材料系统]: 方位角超晶格峰展宽、波矢收缩、积分强度衰减"]},{"i":34245,"as":"","scd":null,"kp":[]},{"i":34246,"as":"","scd":null,"kp":[]},{"i":34247,"as":"","scd":null,"kp":[]},{"i":34248,"as":"","scd":null,"kp":[]},{"i":34249,"as":"","scd":null,"kp":[]},{"i":34250,"as":"","scd":null,"kp":[]},{"i":34251,"as":"","scd":null,"kp":[]},{"i":34252,"as":"","scd":null,"kp":[]},{"i":34253,"as":"","scd":null,"kp":[]},{"i":34254,"as":"该研究引入了一种氟辅助闪速加热策略，能够在数秒内将废弃玻璃等富硅废料快速转化为形貌可控的碳化硅。该工艺能够实现纳米线的选择性生长，在大幅降低能耗和环境影响的同时提供卓越的复合材料增强效果，且方法具备通用性和可扩展性，可延伸至其他先进碳化物纳米材料。","scd":null,"kp":["合成时间[氟辅助闪速焦耳加热法]: 数秒内","原料来源[碳化硅合成]: 废玻璃及其他富硅废弃物","工艺特点[形貌可控碳化物合成]: 可实现选择性纳米线生长"]},{"i":34255,"as":"通过设计具有规则DPP-Se主链和随机极性侧链的无规共聚物（PDPPgx-Se），实现了聚合物热电性能的优化。通过调节极性侧链比例控制掺杂浓度，规则的骨架序列确保了高迁移率。载流子浓度和迁移率的协同优化在不牺牲塞贝克系数的情况下提高了电导率，最终获得了361 μW m−1 K−2的功率因子和0.46的ZT值。","scd":null,"kp":["功率因子[吡咯并吡咯二酮基热电共聚物]: 361 μW m−1 K−2","分子设计[PDPPgx-Se共聚物]: 规则的DPP-Se主链与随机的极性/烷基侧链"]},{"i":34256,"as":"","scd":null,"kp":[]},{"i":34257,"as":"","scd":null,"kp":[]},{"i":34258,"as":"","scd":null,"kp":[]},{"i":34259,"as":"","scd":null,"kp":[]},{"i":34260,"as":"","scd":null,"kp":[]},{"i":34261,"as":"","scd":null,"kp":[]},{"i":34262,"as":"","scd":null,"kp":[]},{"i":34263,"as":"","scd":null,"kp":[]},{"i":34264,"as":"","scd":null,"kp":[]},{"i":34265,"as":"","scd":null,"kp":[]},{"i":34266,"as":"","scd":null,"kp":[]},{"i":34267,"as":"","scd":null,"kp":[]},{"i":34268,"as":"","scd":null,"kp":[]},{"i":34269,"as":"","scd":null,"kp":[]},{"i":34270,"as":"","scd":null,"kp":[]},{"i":34271,"as":"","scd":null,"kp":[]},{"i":34272,"as":"","scd":null,"kp":[]},{"i":34273,"as":"","scd":null,"kp":[]},{"i":34274,"as":"","scd":null,"kp":[]},{"i":34275,"as":"","scd":null,"kp":[]},{"i":34276,"as":"","scd":null,"kp":[]},{"i":34277,"as":"","scd":null,"kp":[]},{"i":34278,"as":"","scd":null,"kp":[]},{"i":34279,"as":"","scd":null,"kp":[]},{"i":34280,"as":"","scd":null,"kp":[]},{"i":34281,"as":"","scd":null,"kp":[]},{"i":34282,"as":"利用两种部分相容的硼酸酯交联聚合物发生自发相分离，制备出具有网格状微相结构的水凝胶。将富水柔性微区包裹在疏水性刚性微区内，赋予了该水凝胶卓越的水下稳定性、机械稳健性以及自润滑特性，适用于复杂环境下的柔性电子器件。","scd":null,"kp":["微观相结构[硼酸酯交联聚合物水凝胶]: 网格状微相分离结构","材料特性[水下柔性电子水凝胶]: 具备优异的水下稳定性、机械鲁棒性和自润滑性"]},{"i":34283,"as":"","scd":null,"kp":[]},{"i":34284,"as":"针对小型化可拉伸晶体管和电容器缺乏可按比例变薄的弹性体介电层问题，研究提出交联辅助陷阱产生法。通过定制多臂交联剂减小弹性体网络自由体积（阻止电荷载流子加速），同时引入异质性（形成紧密结合载流子的深度化学陷阱），有效提升了常见弹性体介电层的击穿强度，满足了高度集成本征可拉伸电子器件的需求。","scd":null,"kp":["增强机制[弹性体电介质]: 交联辅助陷阱产生方法","性能突破[超薄弹性体电介质]: 随占地面积等比例变薄且具有高击穿强度"]},{"i":34285,"as":"","scd":null,"kp":[]},{"i":34286,"as":"","scd":null,"kp":[]},{"i":34287,"as":"","scd":null,"kp":[]},{"i":34288,"as":"基于HMB的能量再激发（ERE）机制创建了用于高效电荷分离的离域激子库，同时通过分子界面工程增强了π-π堆叠效应，两者共同作用成功制备出光电转换效率高达创纪录20.5%的高性能有机太阳能电池。","scd":null,"kp":["光电转换效率[有机太阳能电池]: 20.5%","机制[HMB介导的能量再激发]: 形成离域激子库以实现高效电荷分离"]},{"i":34289,"as":"","scd":null,"kp":[]},{"i":34290,"as":"","scd":null,"kp":[]},{"i":34291,"as":"","scd":null,"kp":[]},{"i":34292,"as":"为解决超导量子计算机布线冗余带来的扩展性挑战，该研究通过倒装芯片键合技术，将量子比特与单磁通量子（SFQ）控制电子器件集成到单一多芯片模块中，在毫开尔文温度下实现了低温超导数字控制。系统利用数字解复用技术将控制脉冲分配给多个量子比特，打破了控制线与量子比特数量的线性比例关系。","scd":null,"kp":["运行环境[超导数字电子学控制的量子计算机]: 毫开尔文温度","集成方案[超导量子计算平台]: 低温超导数字控制电子器件与量子比特共存"]},{"i":34293,"as":"","scd":null,"kp":[]},{"i":34294,"as":"","scd":null,"kp":[]},{"i":34295,"as":"","scd":null,"kp":[]},{"i":34296,"as":"","scd":null,"kp":[]},{"i":34297,"as":"可充电镁电池（RMBs）凭借3833 mAh cm−3的高体积容量以及镁元素的高自然丰度与安全性，成为极具潜力的替代电池体系。然而，由于传统锂离子电池电解液配方无法支持可逆的镁沉积，电解质的匮乏严重制约了RMBs的发展。该综述回顾了从早期格氏试剂络合物到新兴单盐电解质的演变历程，并系统探讨了RMB电解质的基础设计原则。","scd":null,"kp":["体积容量[可充电镁电池]: 3833 mAh cm−3","发展瓶颈[可充电镁电池]: 缺乏可行的电解液"]},{"i":34298,"as":"","scd":null,"kp":[]},{"i":34299,"as":"","scd":null,"kp":[]},{"i":34300,"as":"通过受限水动力学与柔性侧链相互作用的机制，固态多孔肽材料能够根据温度和湿度变化在软硬状态间进行可逆切换。材料的水分含量决定了其分子堆积与力学性能：含水量越高材料越硬，含水量越低则变软。该策略可用于制备具有相依赖性功能的软多孔及肽基材料，在催化、分离和过滤领域展现出新机遇。","scd":null,"kp":["力学状态调控[多孔肽材料]: 基于水分含量在软硬状态间可逆切换","机制[多孔肽材料固态分子重组]: 受限水动力学与柔性侧链相互作用的共同驱动"]},{"i":34301,"as":"针对分子电子器件因不稳定和重现性差而受限的问题，该研究表明强电场可在大面积分子结中驱动原位化学修饰，从而制造出更稳健的器件，实现高效的电流整流。该策略为可靠的分子电子学开辟了新路径，并对电化学、表面化学和合成化学具有广泛的指导意义。","scd":null,"kp":[]},{"i":34302,"as":"","scd":null,"kp":[]},{"i":34303,"as":"","scd":null,"kp":[]},{"i":34304,"as":"","scd":null,"kp":[]},{"i":34305,"as":"","scd":null,"kp":[]},{"i":34306,"as":"","scd":null,"kp":[]},{"i":34307,"as":"","scd":null,"kp":[]},{"i":34308,"as":"","scd":null,"kp":[]},{"i":34309,"as":"","scd":null,"kp":[]},{"i":34310,"as":"","scd":null,"kp":[]},{"i":34311,"as":"","scd":null,"kp":[]},{"i":34312,"as":"","scd":null,"kp":[]},{"i":34313,"as":"","scd":null,"kp":[]},{"i":34314,"as":"","scd":null,"kp":[]},{"i":34315,"as":"","scd":null,"kp":[]},{"i":34316,"as":"","scd":null,"kp":[]},{"i":34317,"as":"","scd":null,"kp":[]},{"i":34318,"as":"","scd":null,"kp":[]},{"i":34319,"as":"","scd":null,"kp":[]},{"i":34320,"as":"","scd":null,"kp":[]},{"i":34321,"as":"","scd":null,"kp":[]},{"i":34322,"as":"","scd":null,"kp":[]},{"i":34323,"as":"","scd":null,"kp":[]},{"i":34324,"as":"","scd":null,"kp":[]},{"i":34325,"as":"","scd":null,"kp":[]},{"i":34326,"as":"研究展示了一种电化学控制的液态金属系统，表现出依赖于合金成分的运动、变形和极性反转行为。这些现象是由电毛细管力、氧化物弹性和界面氧化之间的相互作用引起的，能够产生类似弹簧的形变和动态运动。通过集成导电边界，该系统实现了受控铺展、碎裂以及固体运输功能。","scd":null,"kp":["运动及形变特征[液态金属电化学系统]: 合金依赖性运动、形变及极性反转","驱动力[液态金属动态行为]: 电毛细管力、氧化物弹性与界面氧化的相互作用","可控形变[导电边界]: 类弹簧形变、铺展、碎裂与固体传输"]},{"i":34327,"as":"本研究聚焦真实材料中的自旋劈裂与自旋极化物理，将显性与隐性自旋效应统一归纳为四个类别，分类依据涵盖使能对称性、物理相互作用和磁性构型。研究为每个类别确认了代表性材料系统，并探讨了反铁磁体中显隐自旋效应的可调性。","scd":null,"kp":[]},{"i":34328,"as":"现有大气取水（AWH）技术以高温热驱动解吸为主，存在周期长（20-100分钟）和能耗高（大于3 kWh/kg）的问题。本综述探讨了替代技术以降低能耗并提高产水率。指出利用振动驱动替代热蒸发可使吸附剂再生能耗降至0.09 kWh/kg，并将解吸周期缩短至2分钟以内，同时刺激响应相变吸附剂材料也能有效降低热能耗。","scd":null,"kp":["脱附周期[高温热驱动的单级大气取水(AWH)原型]: 20-100分钟","系统能耗[最佳单级AWH系统]: 大于~3 kWh kg−1"]},{"i":34329,"as":"","scd":null,"kp":[]},{"i":34330,"as":"","scd":null,"kp":[]},{"i":34331,"as":"","scd":null,"kp":[]},{"i":34332,"as":"","scd":null,"kp":[]},{"i":34333,"as":"","scd":null,"kp":[]},{"i":34334,"as":"","scd":null,"kp":[]},{"i":34335,"as":"","scd":null,"kp":[]},{"i":34336,"as":"","scd":null,"kp":[]},{"i":34337,"as":"","scd":null,"kp":[]},{"i":34338,"as":"","scd":null,"kp":[]},{"i":34339,"as":"","scd":null,"kp":[]},{"i":34340,"as":"可穿戴电子纺织品正从单一功能材料向集成电子系统演变。本文综述了传感、能源、反馈、通信和计算等领域的可扩展电子织物平台，重点介绍了系统级集成的最新进展，并指出了在可靠性、可制造性和互操作性方面的关键瓶颈，为智能纺织品和人机接口等应用提供了工业化导向的框架。","scd":null,"kp":[]},{"i":34341,"as":"本研究利用三聚氰酸互变异构（三酮/三醇构型）实现了共价有机框架的精确结构异构化。通过调节溶剂介电常数，选择性合成了两种结构不同的均相三嗪基COFs（Ton-COF和Tol-COF），二者表现出差异化的超级电容器性能。这为先进电化学储能材料的分子设计与性能调控提供了新见解。","scd":null,"kp":["互变异构机制[共价有机框架(COFs)精准结构异构化]: 氰尿酸互变异构(三酮/三醇构型)","合成调控条件[选择性合成同源三嗪基COFs(Ton-COF与Tol-COF)]: 改变溶剂介电常数"]},{"i":34342,"as":"为克服复合聚合物电解质的局限，研究人员开发了一种AI筛选的溶胶-凝胶策略来合成二维LALZO纳米片。这种高长径比的填料构建了类似砖泥结构的骨架，增强了聚合物基体并建立了连续的离子传输网络。该电解质有效抑制了锂枝晶，实现了具有高机械韧性和电化学稳定性的长寿命全固态锂金属电池。","scd":null,"kp":["合成策略[AI筛选的二维LALZO纳米片]: 溶胶-凝胶法","物理结构[二维LALZO高长径比填料]: 砖混式骨架","抑制效果[复合聚合物电解质]: 有效抑制锂枝晶生长"]},{"i":34343,"as":"单层二硒化钨（WSe2）p型晶体管的低接触电阻实现面临挑战。传统高功函金属接触需要高温沉积，易在界面产生缺陷或应变。本研究采用具有原子级平整表面且可低温沉积的金属层状二维材料Nb0.3W0.7Se2，成功为单层和双层WSe2场效应晶体管创建了接触。","scd":null,"kp":["接触材料成分[p型单层二硒化钨(WSe2)晶体管]: 金属层状Nb0.3W0.7Se2","界面特征[低接触电阻金属二维材料接触]: 原子级平整表面且可低温沉积"]},{"i":34344,"as":"","scd":null,"kp":[]},{"i":34345,"as":"","scd":null,"kp":[]},{"i":34346,"as":"","scd":null,"kp":[]},{"i":34347,"as":"","scd":null,"kp":[]},{"i":34348,"as":"高性能有机闪烁体的设计策略主要侧重于通过调整分子结构、调谐激发态动力学、引入重原子效应以及抑制非辐射跃迁途径，来同步提升材料的光学效率、成像分辨率和稳定性。这些进展推动了下一代辐射探测技术的发展。","scd":null,"kp":["分子设计策略[高性能有机闪烁体]: 定制分子结构、调节激发态动力学、引入重原子效应及抑制非辐射途径"]},{"i":34349,"as":"","scd":null,"kp":[]},{"i":34350,"as":"台阶极性作为几何开关，调控了镍表面的氧化物生长模式。内在配位驱动的向下扩散产生了整流原子通量，在正台阶处通量补给氧化物边缘驱动横向生长，在负台阶处则流失材料迫使向内氧化。该机制将原子尺度的能量学与宏观氧化形貌联系了起来。","scd":null,"kp":["几何开关[调控镍表面氧化物生长模式]: 阶梯极性","生长机制[正阶梯处]: 配位驱动的向下扩散产生整流吸附原子流，供应氧化物周界，驱动横向生长","生长机制[负阶梯处]: 吸附原子流向外流失，迫使向内氧化"]},{"i":34351,"as":"","scd":null,"kp":[]},{"i":34352,"as":"","scd":null,"kp":[]},{"i":34353,"as":"","scd":null,"kp":[]},{"i":34354,"as":"","scd":null,"kp":[]},{"i":34355,"as":"","scd":null,"kp":[]},{"i":34356,"as":"","scd":null,"kp":[]},{"i":34357,"as":"","scd":null,"kp":[]},{"i":34358,"as":"","scd":null,"kp":[]},{"i":34359,"as":"","scd":null,"kp":[]},{"i":34360,"as":"通过在埋底界面构筑1D/3D钙钛矿异质结，实现了对离子迁移的有效抑制并提供高效的载流子提取。基于此构建的X射线探测器达到了9.5 nGy/s的低检测限，并在超过100 Gy的辐射剂量下保持稳定运行，性能优于大多数已报道的浆料刮涂法制备的MAPbI3厚膜探测器。","scd":null,"kp":["检测限[钙钛矿X射线探测器]: 9.5 nGyairs-1","稳定运行辐射剂量[钙钛矿X射线探测器]: > 100 Gyair","界面异质结[埋底界面]: 1D/3D钙钛矿异质结"]},{"i":34361,"as":"","scd":null,"kp":[]},{"i":34362,"as":"","scd":null,"kp":[]},{"i":34363,"as":"","scd":null,"kp":[]},{"i":34364,"as":"","scd":null,"kp":[]},{"i":34365,"as":"","scd":null,"kp":[]},{"i":34366,"as":"手性钙钛矿的光学性能难以控制。本研究利用统计分析和机器学习解码了控制其手性光学响应的复杂合成要素。研究确定溶剂选择、温度和薄膜厚度为关键因素，提供了一种数据驱动的材料优化策略，为高性能手性材料的理性设计指明了方向。","scd":null,"kp":["关键合成因素[手性二维钙钛矿]: 溶剂选择、温度、薄膜厚度"]},{"i":34367,"as":"通过能带结构工程方法，研究人员在硅衬底上垂直生长p-GaN/n-AlGaN/n-GaN纳米线，构建了集感光、存储和处理功能于一体的p-n结二极管。n型AlGaN段的较大带隙在GaN p-n结中创建了电子库，这种嵌入式电子库配置实现了对电荷捕获的精确控制，可用于神经形态图像传感器。","scd":null,"kp":["器件集成功能[p-n二极管]: 光电传感、存储和处理一体化","技术路径[多功能二极管]: 能带结构工程"]},{"i":34368,"as":"","scd":null,"kp":[]},{"i":34369,"as":"","scd":null,"kp":[]},{"i":34370,"as":"","scd":null,"kp":[]},{"i":34371,"as":"","scd":null,"kp":[]},{"i":34372,"as":"","scd":null,"kp":[]},{"i":34373,"as":"","scd":null,"kp":[]},{"i":34374,"as":"","scd":null,"kp":[]},{"i":34375,"as":"","scd":null,"kp":[]},{"i":34376,"as":"","scd":null,"kp":[]},{"i":34377,"as":"","scd":null,"kp":[]},{"i":34378,"as":"","scd":null,"kp":[]},{"i":34379,"as":"","scd":null,"kp":[]},{"i":34380,"as":"","scd":null,"kp":[]},{"i":34381,"as":"","scd":null,"kp":[]},{"i":34382,"as":"","scd":null,"kp":[]},{"i":34383,"as":"","scd":null,"kp":[]},{"i":34384,"as":"","scd":null,"kp":[]},{"i":34385,"as":"","scd":null,"kp":[]},{"i":34386,"as":"通过双重热退火工程制备的核壳结构复合材料，在柔性织物上实现了创纪录的99.9 dB（100 kHz下）超宽频电磁干扰屏蔽效能。体外神经保护实验验证了该织物的有效性，为临床医生提供了新一代的可穿戴电磁防护装备。","scd":null,"kp":["电磁屏蔽效能[柔性织物核壳复合材料]: 99.9 dB","测试频率[柔性织物核壳复合材料]: 100 kHz","制备工艺[核壳复合材料]: 双热退火法"]},{"i":34387,"as":"","scd":null,"kp":[]},{"i":34388,"as":"研究人员在集成576-Kb的忆阻器芯片上实现了原位计算光谱仪。通过开发忆阻器正则化和滤波器嵌入策略，克服了光谱重建的极度敏感性，达到了与软件等效的精度。系统级基准测试表明，该硬件重建单次光谱仅需125.0纳秒，能耗仅为6.7纳焦，展现出极高的能效。","scd":null,"kp":["芯片容量[集成忆阻器计算光谱仪]: 576 Kb"]},{"i":34389,"as":"在氮化镓（GaN）和氮化铝界面处极化诱导的二维空穴气中观察到了高空穴迁移率，并首次观测到量子振荡。轻空穴和重空穴在2K温度下的迁移率分别达到2000和400 cm2 V-1 s-1。利用Shubnikov-de Haas振荡提取了它们的面密度、量子散射时间及有效质量。","scd":null,"kp":["高迁移率空穴[氮化镓/氮化铝界面]: 极化诱导二维空穴气"]},{"i":34390,"as":"通过一步界面聚合策略制备了自漂浮的COF-[NH2-GO] Janus膜，用于高效的光催化合成过氧化氢（H2O2）。引入的石墨烯促进了光生载流子的分离和转移，同时自漂浮膜光催化剂稳定了气-液-固三相界面，显著增强了氧气的传质效率。","scd":null,"kp":["制备工艺[自漂浮Janus薄膜]: 一步界面聚合法","材料组成[COF基Janus薄膜]: COF-[NH2-GO]（引入石墨烯）","催化机制[H2O2光合作用]: 稳定气-液-固三相界面增强O2传质"]},{"i":34391,"as":"二维层状材料可调的表面化学为金属电池中人工界面层的开发提供了新机遇。研究以具有不同表面官能团的MXene为模型系统，阐明了表面化学调节锌金属沉积行为的内在机制，助力高稳定锌金属电池的研发。","scd":null,"kp":["界面层材料[锌金属电池]: 具有多种表面端基的MXene二维材料"]},{"i":34392,"as":"","scd":null,"kp":[]},{"i":34393,"as":"在功能陶瓷中工程化可逆相变，能够产生克服传统能量损耗限制的巨大热释电响应。这种“自恢复”材料通过太阳能收集实现了高效的水净化，为开发长期、可持续的环境技术提供了一种变革性策略。","scd":null,"kp":["材料特性[热释电材料]: 可逆相变与“自恢复”功能"]},{"i":34394,"as":"现有蛋白质设计多聚焦于静态结构。本研究介绍了一个通过设定振动动力学来设计蛋白质的生成框架VibeGen。该研究将动力学作为首要设计目标，揭示了多种不同的折叠结构可以实现相似的功能运动，为工程化酶、生物材料开辟了超越静态结构的新途径。","scd":null,"kp":["设计靶标[蛋白质从头设计]: 振动动力学","核心算法[蛋白质设计]: 语言扩散模型"]},{"i":34395,"as":"研究人员开发了一种柔性晶体管，利用锚定在超薄二维片层上的孤立重原子，实现了在传输和阻挡电磁波之间的电学切换。该器件具有高精度和低功耗特点，使下一代可穿戴和集成电路中的动态可编程信号管理成为可能，突破了传统静态屏蔽的局限。","scd":null,"kp":["[动态电磁波控制]: 采用锚定在超薄片上的孤立重原子柔性晶体管，实现低功耗、高精度的电磁波发射与阻断电控切换","[应用场景]: 可穿戴设备与下一代集成电路中的动态可编程信号管理"]},{"i":34396,"as":"霍夫迈斯特效应是编程下一代水凝胶的强大离子特异性工具。通过合理选择离子，可在不依赖静态化学交联的情况下，动态调节水凝胶的机械、电气和环境耐受性能。这些智能适应性水凝胶在离子电子学、生物医学和可持续工程等领域展现出广泛应用前景。","scd":null,"kp":["[水凝胶属性调控]: 通过霍夫迈斯特效应（离子特异性）在不依赖静态化学交联的情况下动态调控力学、电学及耐环境性能","[应用场景]: 离子电子学、生物医学和可持续工程领域的智能自适应水凝胶"]},{"i":34397,"as":"","scd":null,"kp":[]},{"i":34398,"as":"","scd":null,"kp":[]},{"i":34399,"as":"","scd":null,"kp":[]},{"i":34400,"as":"","scd":null,"kp":[]},{"i":34401,"as":"","scd":null,"kp":[]},{"i":34402,"as":"","scd":null,"kp":[]},{"i":34403,"as":"实现公正的清洁能源转型需要技术的公平获取与利益共享。然而，高昂的初期成本、信贷受限和住房约束等结构性障碍严重阻碍了低收入家庭和租房者采用清洁能源技术。这些障碍削弱了相关政策在弱势群体中的实施效果。现有的推广工具在资格排除、同等技术有效成本更高以及政策 regressive（累退）效应等方面存在系统性失效，无法有效惠及面临多重结构性限制的弱势家庭。","scd":null,"kp":["[清洁能源技术部署障碍]: 存在初始成本高、信贷获取受限及住房条件等结构性障碍，阻碍低收入家庭和租户的采用","[公正能源转型要求]: 需在技术部署中实现公平获取、参与和利益共享"]},{"i":34404,"as":"","scd":null,"kp":[]},{"i":34405,"as":"","scd":null,"kp":[]},{"i":34406,"as":"针对数据伪造削弱信任的问题，研究团队开发了一种新型录影设备技术，通过单片集成加密传感器在物理录制过程与不可篡改的数字实体（如公共区块链条目）之间建立加密链接。该传感器集成了数据记录设备、哈希单元（持续对录制数据进行哈希处理）和加密签名单元（使用公钥加密方案对哈希值签名）。系统随后将带有签名的哈希值上传，确保数据真实性与物理数字链接。","scd":null,"kp":["[防数据伪造机制]: 通过传感器内加密签名技术，在物理过程（录制动作）与不可变数字实体（公共区块链条目）之间建立加密链接"]},{"i":34407,"as":"","scd":null,"kp":[]},{"i":34408,"as":"","scd":null,"kp":[]},{"i":34409,"as":"","scd":null,"kp":[]},{"i":34410,"as":"","scd":null,"kp":[]},{"i":34411,"as":"","scd":null,"kp":[]},{"i":34412,"as":"","scd":null,"kp":[]},{"i":34413,"as":"现有手部追踪技术在视角、手部位置和连续动作识别上存在局限。研究团队开发了一款完全集成、无线且可穿戴的超声波成像腕带，结合人工智能算法，能够在日常活动中实时、连续地追踪五根手指和手掌的任意手部构型。该技术突破了传统基于相机、应变传感器、惯性传感器或肌电图传感器的技术瓶颈，为空间计算、虚拟/增强现实、机器人和假肢等领域的自然手部交互提供了有效解决方案。","scd":null,"kp":["[手部追踪技术限制]: 现有基于摄像头、应变/惯性传感器及肌电图传感器的技术存在视角受限、手部位置和活动受限等缺陷","[新型追踪方案]: 使用可穿戴式腕部成像技术以克服现有局限并适应日常活动"]},{"i":34414,"as":"","scd":null,"kp":[]},{"i":34415,"as":"","scd":null,"kp":[]},{"i":34416,"as":"研究团队利用具有氧化还原活性的Cu2+离子作为电荷载流子，开发出一种采用支柱状石墨烯-硒正极的异价离子Cu-Se电池。该设计利用Cu2+的变价特性实现可逆的Se⇄CuSe⇄Cu₂Se转化反应，使电子转移数量翻倍，突破了传统的容量耗尽策略限制。测试表明，该电池具备出色的倍率性能和优异的循环稳定性，为高容量“摇椅式”电池提供了新的设计范式。","scd":null,"kp":["氧化还原载体[跨价态离子电池]: 氧化还原活性的Cu2+离子","正极材料[跨价态Cu-Se电池]: 支撑状石墨烯-硒复合材料","[电池反应机制]: 利用Cu2+的可变价态实现Se ⇄ CuSe ⇄ Cu₂Se的可逆转化，电子转移数翻倍","[技术优势]: 具有优异的倍率性能和循环稳定性，突破传统容量耗尽策略"]},{"i":34417,"as":"为满足片上系统异构设计和高能源利用率的趋势，该研究首次提出并实现了兼容CMOS工艺的晶圆级锂离子电池。该电池具有高体积能量密度和高容量利用率，支持分布式片上电源架构。通过用单片集成的储能器件替代传统的离散电池，该架构为构建更高效、紧凑且多功能的集成电子系统提供了可扩展的制造路径。","scd":null,"kp":["器件特性[CMOS兼容锂电池]: 晶圆级、高体积能量密度及高容量利用率","[芯片电源架构]: 首次通过单片集成储能器件取代分立电池，实现分布式片上电源供应"]},{"i":34418,"as":"","scd":null,"kp":[]},{"i":34419,"as":"","scd":null,"kp":[]},{"i":34420,"as":"","scd":null,"kp":[]},{"i":34421,"as":"","scd":null,"kp":[]},{"i":34422,"as":"","scd":null,"kp":[]},{"i":34423,"as":"研究团队开发了一种自供电有机光电化学突触（SOPECS），在生物相容性电解液中运行，用于模拟生物视觉系统。该器件由光致还原反应驱动，展现出多波长响应能力、神经形态可塑性，并在活细胞条件下具备视觉自我恢复功能。该成果为开发自主的、兼容电解质的神经形态视觉系统铺平了道路。","scd":null,"kp":["器件类型[仿生视觉系统]: 自供电有机光电化学突触（SOPECS）","[运行环境]: 生物相容性电解质及活细胞条件","[核心特征]: 由光诱导还原反应驱动，具备多波长响应性、神经形态可塑性及视觉自我恢复能力"]},{"i":34424,"as":"","scd":null,"kp":[]},{"i":34425,"as":"","scd":null,"kp":[]},{"i":34426,"as":"","scd":null,"kp":[]},{"i":34427,"as":"","scd":null,"kp":[]},{"i":34428,"as":"","scd":null,"kp":[]},{"i":34429,"as":"研究通过配体工程实现了CsPbBr3钙钛矿纳米片的自组装，成功制备出取向可调（从边缘向上到平面向下）的超晶格，从而实现了对各向异性光学性质的控制。边缘向上的纳米片薄膜能产生更强的线偏振光，而平面向下的薄膜则表现出更高的光耦合输出效率，显著提升了LED器件性能。这种取向控制是通过调节配体的有机骨架来实现的。","scd":null,"kp":["[超晶格取向调控]: 通过配体工程实现CsPbBr3纳米片从“边朝上”到“面朝下”的自组装可调","[光学性能特征]: 边朝上薄膜产生更强线偏振光，面朝下薄膜展现出更高光耦合输出","[器件性能影响]: 面朝下薄膜的高光耦合特性可提升LED器件性能"]},{"i":34430,"as":"针对离网和应急场景下的免能耗水净化挑战，研究报道了一种具有智能柔性纳米针的海胆状共价有机框架（COF）。该材料结合了对细菌、病毒和藻类的机械灭活与对广谱毒素的吸附功能。其柔性纳米针通过“捕获-反弹-拉扯”机制工作，多孔框架则负责去除微生物毒素和化学污染物。基于此研发的轻量级设备能够一步高效净化真实水源且具备可回收性。","scd":null,"kp":["[材料构型]: 具有智能柔性纳米棘突的海胆状共价有机框架（COF）","[净水机制]: 纳米棘突通过“捕获-反弹-拉扯”机制使细菌/病毒/藻类等机械失活，多孔框架同步吸附广谱毒素和化学污染物","[应用特点]: 免动力、便携、轻量化的一步式实地水体净化"]},{"i":34431,"as":"该研究提出了一种利用光聚集剂选择性操控聚合物半导体局部导电域的光触发策略。通过将孤立的导电域整合为连续网络，实现了实时可调的相工程，构建了具有高霍尔迁移率的高效电荷传输路径。作为通用空穴注入层，该材料显著提升了全色OLED器件的性能。","scd":null,"kp":["载流子迁移率[光调控聚合物半导体相工程]: 高霍尔迁移率","相工程机制[光聚集剂调控]: 实时调控且将孤立导电域整合为连续网络","应用效果[全色OLED空穴注入层]: 增强器件性能"]},{"i":34432,"as":"研究展示了一款基于NiTe2/WSe2纳米条带的光电探测器，通过门控编程构建了仿生多维卷积核。该器件结合了巨大的各向异性、动态可调的门控光电流极性，并在偏振、波长和电学域上实现了三重可编程性。这些特性使其能够进行实时各向异性滤波，实现了高分辨率无透镜偏振成像，并在无需冯·诺依曼架构的情况下完成多维图像预处理。","scd":null,"kp":["光电特性[NiTe2/WSe2纳米带光电探测器]: 巨大各向异性与动态栅极可调光电流极性","可编程维度[仿生多维卷积核]: 极化、波长和电子域的三方可编程性","系统优势[高分辨率无透镜偏振成像]: 突破冯·诺依曼瓶颈实现多维图像实时预处理"]},{"i":34433,"as":"研究团队在氰基桥联金属框架中组装了具有周期性和可调性的五核金属催化剂，用于光催化还原CO2。该催化剂在光催化生成CO的反应中展现出优异的催化活性和选择性。研究揭示了五核金属在催化过程中的协同作用机制，为设计用于光催化CO2还原反应的先进多核金属催化剂提供了新策略。","scd":null,"kp":["催化剂结构[氰基桥联金属框架]: 周期性且可裁剪的五核金属催化剂","催化机制[五核金属位点]: 多金属位点间的协同催化作用","催化性能[CO2光还原反应]: 具有优异的CO生成光催化活性与选择性"]},{"i":34434,"as":"该研究针对磷酸铁锂（LiFePO4）在充放电循环中因分离成富锂和贫锂区而导致内部应变的失效机制。研究证明，通过设计表面涂层来控制颗粒界面的锂离子运动，可以防止这种内在的不均匀性。基于此发现，团队开发出一种混合陶瓷-碳涂层材料，实现了优异的相均匀性并赋予电池快速充电能力。","scd":null,"kp":["界面修饰策略[LiFePO4充放电过程]: 陶瓷碳混合表面涂层控制锂离子在界面的运动","改性效果[防止活性材料颗粒相分离]: 提供优异的相均匀性","电化学性能[混合涂层锂离子电池]: 赋予电池快速充电能力"]},{"i":34435,"as":"","scd":null,"kp":[]},{"i":34436,"as":"该研究提出了一种简便且可扩展的超快烧结策略，用于直接升级商用橄榄石型正极材料。利用受限的热生长动力学，该方法在不导致颗粒粗化的同时，同步优化了表面和体相微观结构，显著提升了电子电导率和Li+扩散能力，大幅改善了电池的倍率和循环性能。该工艺已在公斤级水平上得到验证，适用于从LiFePO4到Li(FexMn1-x)PO4等多种正极材料。","scd":null,"kp":["烧结工艺[橄榄石型阴极材料升级]: 快速且可扩展的超快烧结策略","微观结构调控[受约束热生长动力学]: 同步优化表面和体相微观结构且无颗粒粗化","电化学提升[LiFePO4至Li(FexMn1-x)PO4体系]: 显著增强电子导电率和锂离子扩散能力","验证规模[商业橄榄石阴极]: 千克级验证"]},{"i":34437,"as":"","scd":null,"kp":[]},{"i":34438,"as":"","scd":null,"kp":[]},{"i":34439,"as":"","scd":null,"kp":[]},{"i":34440,"as":"","scd":null,"kp":[]},{"i":34441,"as":"","scd":null,"kp":[]},{"i":34442,"as":"","scd":null,"kp":[]},{"i":34443,"as":"","scd":null,"kp":[]},{"i":34444,"as":"","scd":null,"kp":[]},{"i":34445,"as":"碲（Te）作为与硒（Se）密切相关的硫族元素，具有与硒高度相似的物理化学性质。该综述以硒为基准，系统阐述了碲在生物功能、合理设计及生物医学应用方面的独特优势。文章指出了碲的应用前景，明确了新出现的机遇，并为未来相关生物医学研究提供了深入的方向指引。","scd":null,"kp":["基础属性[碲元素]: 与硒具有高度相似的理化性质","应用潜力[生物医用碲纳米药物]: 具有独特的生物应用前景与合理的生物医学设计空间"]},{"i":34446,"as":"水凝胶超材料的折叠过程会改变结构单元之间的接触点，从而改变化学信号在这些结构中传播的轨迹。这一现象适用于多种超材料几何形状、化学信号类型和水凝胶成分。对超材料结构的反复折叠能够实时调控化学信号，并允许化学信号跨越较远的物理距离进行跳跃传输。","scd":null,"kp":["信号传导机制[水凝胶超材料折叠]: 通过改变单元间接触点改变化学信号轨迹","调控特性[多几何形状与化学信号]: 实时调制并允许跨越远距离跃迁"]},{"i":34447,"as":"传统软材料打印技术致力于阻止材料流动，而该研究反其道而行之，精确设计超软硅胶的流动、铺展和随时间冷凝冻结的过程。该技术将原本被视为打印失败的塌陷现象转化为可控的成型机制，能够利用超软材料制造出图案化的平整薄膜和多层结构，为柔性与软体器件制造开辟了全新路径。","scd":null,"kp":["成型机制[润湿驱动的热冷冻打印]: 精确设计超软硅胶的流动、铺展和冷冻时间","工艺特点[超软材料打印]: 将材料塌陷缺陷转化为可控的成型机制","结构制造[超软硅胶薄膜]: 能够制造图案化平整薄膜和多层结构"]},{"i":34448,"as":"超薄HfO2器件中电阻开关与铁电开关的耦合作用，复杂化了铁电特性的表征并限制了器件的耐久性。该研究通过定制脉冲工程将这两种现象解耦，明确指出氧空位迁移是导致极化值虚高和器件失效的主要原因。研究提出了抑制电阻开关伪影的有效策略，为准确评估下一代铁电存储器的本征铁电性能和提高可靠性铺平了道路。","scd":null,"kp":["阻变与铁电耦合[超薄Hf0.5Zr0.5O2薄膜]: 通过定制脉冲工程解耦阻变对铁电极化翻转的影响","失效机理[阻变行为]: 氧空位迁移是导致夸大极化值和器件失效的主要原因","改善策略[铁电HfO2器件]: 有效抑制阻变伪影以准确评估本征铁电性能"]},{"i":34449,"as":"点缺陷决定了半导体和量子材料的性能，但难以实现无损量化。研究提出的DefectNet模型利用振动光谱和物理信息机器学习框架，直接从声子态密度中识别缺陷种类和浓度。该模型在模拟数据和中子散射数据上均得到验证，能够解析共存的多种掺杂剂，有效消除了模拟与实验之间的差距，推动了振动光谱技术向自动化缺陷检测发展。","scd":null,"kp":["底层模型[无损缺陷识别]: 基于物理信息机器学习框架的DefectNet基础模型","输入与特征[振动光谱分析]: 直接利用声子态密度识别缺陷种类和浓度","验证效果[半导体与量子材料模拟及中子散射数据]: 能够解析多种共存的掺杂剂并弥合仿真与实验差距"]},{"i":34450,"as":"该文论述了生成式人工智能（包括扩散模型和基于语言的人工智能代理）如何将金属有机框架（MOF）的发现过程从缓慢的筛选转变为靶向设计。文章强调了计算与自动化实验相耦合对加速探索传统能源和环境应用中难以合成的材料的重要影响。","scd":null,"kp":["[金属有机框架设计与合成]: 生成式AI正推动其从缓慢筛选向靶向设计转变"]},{"i":34451,"as":"含贵金属的MAX相（层状碳化物/氮化物）及其衍生物MXene结合了M-X骨架结构与贵金属的催化和电子特性。该综述涵盖了拓扑A位修饰策略以及MXene贵金属的键合路径，重点介绍了这些材料在增强电荷转移、提高稳定性等方面的优势及其应用，并展望了未来用于先进催化剂和器件的可扩展化设计方向。","scd":null,"kp":["[含贵金属MAX相及其衍生物]: 结合M-X骨架与贵金属的催化/电子特性，提升电荷转移与稳定性"]},{"i":34452,"as":"该研究提出一种基于液态金属冷冻保护剂的介入式强化传热方法，用于快速均匀地复温生物样品。该方法利用高导热性的液态金属，大幅降低了界面和接触热阻，实现了表面和体积的协同强化传热。这一技术显著提高了组织存活率，并成功完成了首例玻璃化冷冻兔肾的移植，为大规模器官储存奠定了基础。","scd":null,"kp":["传热增强方法[液金属冷冻保护剂]: 介入式增强热传递","[规模化生物样本冷冻保存]: 显著改善组织存活率并首次实现玻璃化冷冻样本移植"]},{"i":34453,"as":"该研究利用超分辨显微镜解析了聚合物-纳米颗粒（PNP）水凝胶的微观结构。结合空间统计分析和流变学表征，发现在α-环糊精存在下，超分子添加剂使纳米颗粒由均匀分布转变为聚集态，从而提升了水凝胶的流变学性能。时间分析进一步揭示了这种结构变化与材料老化及聚集动力学之间的联系。","scd":null,"kp":["微结构转变[超分子水凝胶添加α-环糊精]: 纳米粒子由均匀分布转变为聚集体","流变学性能[α-环糊精诱导微结构聚集]: 提升"]},{"i":34454,"as":"为解决硅自旋量子比特读取架构复杂和保真度受限的问题，该研究提出一种射频电子级联读取方法。该方法通过交流电子共隧穿效应增强色散信号，使信噪比提升超过35分贝，最小积分时间缩短至7.6±0.2微秒。该技术成功实现了天然硅基双电子自旋的单态-三态读取，为可扩展量子处理提供了紧凑高效的方案。","scd":null,"kp":["读出技术[硅自旋量子比特]: 射频电子级联读出方法（无需近邻电荷传感器，缓解架构复杂度）"]},{"i":34455,"as":"该技术成功研发新型耐高温碳化硅复合材料，突破传统材料在极端环境下的应用瓶颈。通过优化基体与界面相组成，材料在1600摄氏度高温下抗拉强度保持在500兆帕以上，且具备优异的抗热震性能。该成果可直接应用于下一代航空航天飞行器热防护系统及高性能燃气轮机核心部件，具有重大工程应用价值。","scd":null,"kp":[]},{"i":34456,"as":"针对电催化固氮中界面气体传输受限和析氢副反应（HER）的难题，该研究构建了一种超润湿微腔电极。该电极通过调节润湿状态，有效抑制了HER并建立起有利的固液气三相界面微环境，从而显著提升了电催化合成氨的性能。研究结论突出了界面工程在高效电极设计中的关键作用。","scd":null,"kp":["[电催化合成氨]: 构建超润湿微腔电极调控三相界面微环境，克服界面气态传输限制并抑制析氢反应"]},{"i":34457,"as":"该研究探讨了“高福祉低需求”（HwL）住房模式，旨在降低建筑运行和建材中的能源与材料消耗，同时维持或提升个人与社区的福祉。除了依靠技术提升建筑性能，该研究还结合了服务供给、评估模型与最佳实践数据。通过在热舒适度、照明和家用电器等方面的技术应用，可有效减少运营能耗，并通过缩小房屋面积等措施降低隐含能耗。","scd":null,"kp":["[住房建设与运营]: 高福祉与低需求（HwL）策略，在维持或提升个体福祉的同时减少能源和材料消耗"]},{"i":34458,"as":"该研究开发了一种具有电荷离域铟中心的结晶型氰胺铟框架，并将其用作锂硫电池的高效隔膜修饰剂。该设计能够同时增强对多硫化物的吸附能力，并降低硫氧化还原反应的能垒，从而显著提升了电池的倍率性能和长期循环稳定性。","scd":null,"kp":["[锂硫电池隔膜修饰物]: 电荷离域的氰胺铟框架","[锂硫电池性能]: 同时增强多硫化物吸附并降低硫氧化还原反应能垒，实现高倍率容量和延长循环稳定性"]},{"i":34459,"as":"国产新一代人工智能大模型正式开源，参数规模达到千亿级别，全面超越前代产品的逻辑推理与多模态处理能力。模型采用创新的稀疏注意力机制，训练效率提升40%，推理成本降低一半。在多项国际权威评测中，该模型在自然语言理解、代码生成和图像识别等任务上均取得顶尖成绩，为学术研究和商业落地提供强大算力支持。","scd":null,"kp":[]},{"i":34460,"as":"","scd":null,"kp":[]},{"i":34461,"as":"该综述系统总结了二维光子晶体微激光器的研究进展，将其波长、模式、光束形状、功率和时间等发射特性整合至统一的设计空间内。文章将六种物理调控机制映射到五类输出类别，涵盖了BIC纳米激光器、拓扑/涡旋微激光器及瓦特级PCSELs等。此外，还指出了在超快时间控制、电泵浦可见光平台及稳健可制造集成方面的未来机遇。","scd":null,"kp":["[二维光子晶体微纳激光器]: 实现对波长、模式、光束形状、功率和时间的全发射控制"]},{"i":34462,"as":"","scd":null,"kp":[]},{"i":34463,"as":"","scd":null,"kp":[]},{"i":34464,"as":"","scd":null,"kp":[]},{"i":34465,"as":"","scd":null,"kp":[]},{"i":34466,"as":"","scd":null,"kp":[]},{"i":34467,"as":"","scd":null,"kp":[]},{"i":34468,"as":"","scd":null,"kp":[]},{"i":34469,"as":"","scd":null,"kp":[]},{"i":34470,"as":"","scd":null,"kp":[]},{"i":34471,"as":"","scd":null,"kp":[]},{"i":34472,"as":"该研究开发了一种适用于软体和混合电子设备的三维可拉伸核壳电缆。该电缆具备可图案化、可回收和抗噪特性，其制造工艺兼容多尺度生产，回收率高达95%。它的杨氏模量约为0.9兆帕，最大拉伸率约为800%，且在拉伸状态下电阻几乎不发生变化，能够与各种导电焊盘形成可靠的接口连接。","scd":null,"kp":["[三维可拉伸电缆]: 具备可图案化、可回收和抗噪声特性的核壳结构线缆"]},{"i":34473,"as":"为满足集成电路后端工艺（BEOL）互连线微型化的需求，该研究在350摄氏度的兼容温度下，通过无等离子热原子层沉积技术晶圆级生长了超薄二硫化钨（WS2）。这种WS2层兼具互连阻挡层和衬层功能，能防止铜扩散并改善金属附着力。单层WS2不仅能阻止铜向二氧化硅扩散，还能将10纳米厚铜膜的电阻率降低六个数量级以上。","scd":null,"kp":["薄膜厚度[二硫化钨层]: 超薄(2层)","生长温度[无等离子体热原子层沉积]: 350 ℃(兼容BEOL工艺)","[晶圆级生长]: 无等离子体热原子层沉积"]},{"i":34474,"as":"全球首个深海移动科考站完成万米海试，标志着深海装备工程技术取得历史性突破。科考站采用钛合金耐压壳体设计，可容纳六名科研人员，配备先进的声学通信和自主导航系统。配备的多个机械臂和深海探测模块，可在马里亚纳海沟极端环境下连续作业三十天。此次成功将为深海生物基因测序和矿产资源勘探提供核心装备支持。","scd":null,"kp":[]},{"i":34475,"as":"在工业级绒面硅上沉积钙钛矿以制造高效叠层太阳能电池时，粗糙表面常导致薄膜不均。该研究开发了一种“闪蒸提取”策略，通过快速去除溶剂，使钙钛矿在绒面硅上均匀高质量生长。这种全溶液工艺实现了近30%的光电转换效率，为下一代太阳能电池板的低成本、大规模制造提供了有效路径。","scd":null,"kp":["转换效率[绒面硅钙钛矿叠层电池]: 约30%","[钙钛矿薄膜沉积]: 闪蒸提取全溶液工艺(形成均匀高质量层)"]},{"i":34476,"as":"该综述探讨了手性钙钛矿材料在光伏领域的应用，分析了其手性机制、当前面临的挑战及未来研究方向。由于钙钛矿组成和结构的高度可调性，其在展现卓越光伏效率的同时，也能轻易引入手性。相关研究旨在加速手性钙钛矿光伏技术的发展，并促进手性、材料与能源等多学科交叉融合。","scd":null,"kp":["[手性钙钛矿]: 具备高可调成分与结构，易于引入手性"]},{"i":34477,"as":"自动驾驶实验室（SDL）结合了机器人、人工智能和自动化实验，有望加速科学发现，但该领域目前仍较为分散。ThinkFactory 2025社区研讨会提出了多项优先发展事项，包括建立基准测试、互操作性标准、提升易用性以及构建结构化的人机协作机制。这些举措有助于推动SDL从孤立的概念演示转化为广泛应用的研究基础设施。","scd":null,"kp":["[自驱动实验室(SDL)]: 亟待基准测试、互操作性标准与人机协作结构化以实现广泛应用"]},{"i":34478,"as":"柔性自供电电子器件集成了导体、半导体和介电材料，能够通过太阳能电池、摩擦纳米发电机（TENG）、压电纳米发电机（PENG）等多种能量收集器获取环境与生物机械能。借助仿生和人工结构工程，这些器件实现了自愈合、自清洁、防火和自粘附等多功能集成，并能与皮肤共形接触，在下一代可穿戴设备、个性化医疗和人机交互领域展现出广阔前景。","scd":null,"kp":["[柔性自供能电子器件]: 实现自愈合、自清洁、防火、自粘等多功能集成及皮肤共形接触"]},{"i":34479,"as":"量子计算云平台迎来重大升级，全面接入全新一代超导量子芯片。芯片采用高品质因数三维封装技术，单比特门保真度突破99.9%，相干时间提升至两百微秒以上。云平台同步优化了混合经典-量子算法运行环境，新增量子纠缠态实时监控和误差自动校正功能。此次升级让普通用户也能免费体验百量子比特级别的算力服务，极大降低了前沿科研门槛。","scd":null,"kp":[]},{"i":34480,"as":"该研究提出一种π轨道耦合策略，成功制备出具有面面π-π堆叠结构的高性能双极性有机共晶。这种Cu-PcC共晶打破了传统体系中电荷转移诱导的传输限制，实现了高效的双极性电荷传输。基于此材料构建的X射线探测器展现出3.02×10^6 μC Gy⁻¹ cm⁻²的超高灵敏度，并具有明显的偏压对称响应，推动了下一代多功能光电探测器的发展。","scd":null,"kp":["X射线探测灵敏度[面对面π-π堆叠Cu-PcC有机共晶]: 3.02 × 10^6 μC Gy−1 cm−2","[双极性传输]: π轨道耦合策略打破电荷转移诱导限制"]},{"i":34481,"as":"","scd":null,"kp":[]},{"i":34482,"as":"","scd":null,"kp":[]},{"i":34483,"as":"为解决4d和5d贵金属极难稳定为单原子态的难题，该研究受氢脆现象启发，开发了一种热激活合成策略。在高温合成中，氢气渗透削弱了金属簇内的金属内聚力，促使其解离为单个原子，随后被碳载体中的氮掺杂剂稳定，形成M-N4单原子位点。以钌为模型，显微和光谱技术证实了该机制，制备出的催化剂在酸性氧还原反应中表现出优异性能。","scd":null,"kp":["[单原子催化剂合成]: 氢脆辅助热激活策略(利用H2渗透解离4d/5d金属簇为单原子)"]},{"i":34484,"as":"最新临床研究表明，新型靶向药物在治疗晚期非小细胞肺癌的三期试验中取得突破性成果。药物通过特异性抑制肿瘤血管生成通路，显著延长患者无进展生存期达十五个月，客观缓解率提升至百分之七十五。相比传统放化疗，该药物副作用大幅降低，患者耐受性良好。此项突破已获国家药监局优先审评资格，预计将于下季度获批上市。","scd":null,"kp":[]},{"i":34485,"as":"中国深海载人潜水器完成西太平洋海底多金属结核勘探任务。本次下潜深度突破七千米，采集了大量珍贵深海生物样本和沉积物岩心。潜水器配备的新型声学成像系统和机械抓取臂，实现了对复杂海底地形的高精度测绘和无损采样。此次勘探数据为深海矿产资源评估及海洋生态系统保护提供了详实的科学依据，进一步巩固了我国在深海装备领域的领先地位。","scd":null,"kp":[]},{"i":34486,"as":"","scd":null,"kp":[]},{"i":34487,"as":"","scd":null,"kp":[]},{"i":34488,"as":"","scd":null,"kp":[]},{"i":34489,"as":"该研究提出缺陷-界面共功能化策略，通过引入硒空位和金属异质结激活了层状BiCuSeO超晶格。这种修饰实现了高效的层间电荷释放，并在光热加热下显著增强了热电转换。增强的光热电场协同放大了类酶催化和活性氧的产生，实现了对肿瘤的有效抑制。该研究为热电材料与催化纳米药物的耦合提供了通用框架。","scd":null,"kp":["[BiCuSeO超晶格]: 缺陷-界面共功能化(引入硒空位与金属异质结)激活层间电荷释放并增强热电转换"]},{"i":34490,"as":"混合电解槽系统集成了质子、阴离子和双极性膜系统的优势，能够实现酸碱耦合及多功能电合成。该综述指出，为推进该系统在可扩展、高效脱碳过程中的应用，未来需要依靠先进材料、创新架构设计以及智能控制系统，以克服离子传输和系统稳定性方面的挑战。","scd":null,"kp":["[混合电解槽]: 整合质子、阴离子和双极膜系统优势，实现酸碱耦合与多功能电合成"]},{"i":34491,"as":"","scd":null,"kp":[]},{"i":34492,"as":"柱芳烃通过限制空间内的阳离子中间体稳定化，实现了催化反马尔科夫尼科夫卤化反应。大环共价有机主体通过边缘功能化设计成催化剂，其具备明确且可调的空腔，利用尺寸和形状互补性结合底物。这种机制将反应位点拉近至催化基团，有效加速化学反应，并在受限微环境中稳定阳离子中间体，从而实现非常规的反应选择性。","scd":null,"kp":["[Pillar[5]arene大环主体催化]: 限域空间内稳定阳离子中间体实现反马尔科夫尼科夫卤化"]},{"i":34493,"as":"","scd":null,"kp":[]},{"i":34494,"as":"","scd":null,"kp":[]},{"i":34495,"as":"","scd":null,"kp":[]},{"i":34496,"as":"","scd":null,"kp":[]},{"i":34497,"as":"","scd":null,"kp":[]},{"i":34498,"as":"","scd":null,"kp":[]},{"i":34499,"as":"","scd":null,"kp":[]},{"i":34500,"as":"","scd":null,"kp":[]},{"i":34501,"as":"","scd":null,"kp":[]},{"i":34502,"as":"","scd":null,"kp":[]},{"i":34503,"as":"","scd":null,"kp":[]},{"i":34504,"as":"","scd":null,"kp":[]},{"i":34505,"as":"","scd":null,"kp":[]},{"i":34506,"as":"","scd":null,"kp":[]},{"i":34507,"as":"","scd":null,"kp":[]},{"i":34508,"as":"","scd":null,"kp":[]},{"i":34509,"as":"","scd":null,"kp":[]},{"i":34510,"as":"","scd":null,"kp":[]},{"i":34511,"as":"","scd":null,"kp":[]},{"i":34512,"as":"","scd":null,"kp":[]},{"i":34513,"as":"","scd":null,"kp":[]},{"i":34514,"as":"","scd":null,"kp":[]},{"i":34515,"as":"","scd":null,"kp":[]},{"i":34516,"as":"","scd":null,"kp":[]},{"i":34517,"as":"","scd":null,"kp":[]},{"i":34518,"as":"","scd":null,"kp":[]},{"i":34519,"as":"","scd":null,"kp":[]},{"i":34520,"as":"","scd":null,"kp":[]},{"i":34521,"as":"","scd":null,"kp":[]},{"i":34522,"as":"","scd":null,"kp":[]},{"i":34523,"as":"","scd":null,"kp":[]},{"i":34524,"as":"","scd":null,"kp":[]},{"i":34525,"as":"","scd":null,"kp":[]},{"i":34526,"as":"","scd":null,"kp":[]},{"i":34527,"as":"","scd":null,"kp":[]},{"i":34528,"as":"","scd":null,"kp":[]},{"i":34529,"as":"","scd":null,"kp":[]},{"i":34530,"as":"","scd":null,"kp":[]},{"i":34531,"as":"","scd":null,"kp":[]},{"i":34532,"as":"","scd":null,"kp":[]},{"i":34533,"as":"","scd":null,"kp":[]},{"i":34534,"as":"","scd":null,"kp":[]},{"i":34535,"as":"","scd":null,"kp":[]},{"i":34536,"as":"","scd":null,"kp":[]},{"i":34537,"as":"","scd":null,"kp":[]},{"i":34538,"as":"","scd":null,"kp":[]},{"i":34539,"as":"","scd":null,"kp":[]},{"i":34540,"as":"研究提出一种集成了微机电系统(MEMS)执行器的芯片级图像传感器。针对数字图像传感器像素缩小受限于信噪比且空间带宽积不足的问题，该传感器利用MEMS执行器精确调制数字图像传感器位置，从而克服传统限制，有效提升了传感器的空间带宽积，满足了光场和光谱等多维信息的传感需求。","scd":null,"kp":["像素微型化与高密度[数字图像传感器]: 受限于信噪比问题"]},{"i":34541,"as":"","scd":null,"kp":[]},{"i":34542,"as":"","scd":null,"kp":[]},{"i":34543,"as":"","scd":null,"kp":[]},{"i":34544,"as":"针对铁电流体室温“结冰”状态图案化的难题，研究提出利用飞秒激光直写技术结合热电与流动协同效应，精确构筑极性畴。该方法将以往难以图案化的材料转化为复杂非线性光学器件的多功能平台，为可编程非线性光子超材料的构建提供了稳健可靠的策略。","scd":null,"kp":["[室温冰冻态铁电流体材料]: 飞秒激光直写技术利用热电与流动协同效应实现极化域的精确图案化加工"]},{"i":34545,"as":"","scd":null,"kp":[]},{"i":34546,"as":"","scd":null,"kp":[]},{"i":34547,"as":"","scd":null,"kp":[]},{"i":34548,"as":"","scd":null,"kp":[]},{"i":34549,"as":"","scd":null,"kp":[]},{"i":34550,"as":"","scd":null,"kp":[]},{"i":34551,"as":"","scd":null,"kp":[]},{"i":34552,"as":"","scd":null,"kp":[]},{"i":34553,"as":"","scd":null,"kp":[]},{"i":34554,"as":"","scd":null,"kp":[]},{"i":34555,"as":"研究提出一种具备具身智能的液态金属形状记忆机器人。该机器人能够实现可编程变形以及自动可逆的形状恢复，具有出色的变形能力、可靠的形状记忆功能及优异的耐高温性能。在管道导航、地球物理勘探、核废料修复及灾难响应等多个场景中展现出巨大的应用潜力。","scd":null,"kp":["[液金属形状记忆机器人]: 具备可编程变形、自动可逆形状恢复、可靠形状记忆功能及优异耐高温性能"]},{"i":34556,"as":"","scd":null,"kp":[]},{"i":34557,"as":"","scd":null,"kp":[]},{"i":34558,"as":"","scd":null,"kp":[]},{"i":34559,"as":"","scd":null,"kp":[]},{"i":34560,"as":"","scd":null,"kp":[]},{"i":34561,"as":"","scd":null,"kp":[]},{"i":34562,"as":"","scd":null,"kp":[]},{"i":34563,"as":"","scd":null,"kp":[]},{"i":34564,"as":"","scd":null,"kp":[]},{"i":34565,"as":"","scd":null,"kp":[]},{"i":34566,"as":"","scd":null,"kp":[]},{"i":34567,"as":"","scd":null,"kp":[]},{"i":34568,"as":"","scd":null,"kp":[]},{"i":34569,"as":"","scd":null,"kp":[]},{"i":34570,"as":"","scd":null,"kp":[]},{"i":34571,"as":"","scd":null,"kp":[]},{"i":34572,"as":"针对固态电池中堆压效应机制尚不明确的问题，研究发现在硫化物电解质中，依赖于时间的机械弛豫过程比仅施加压力大小更能增强循环稳定性。通过在循环中引入受控的零电流保持时间，可有效减少界面空隙并抑制枝晶驱动的断裂，为提升硫化物固态电池性能提供了新的力学指导策略。","scd":null,"kp":["[硫化物固态电解质电池]: 时间依赖的机械弛豫（而非单纯压力大小）可增强循环稳定性","[零电流保持策略]: 减少界面空位并抑制枝晶驱动的断裂"]},{"i":34573,"as":"","scd":null,"kp":[]},{"i":34574,"as":"针对表皮传感器受限于电池和数据传输的问题，研究开发了一种无电池表皮传感器网络。该网络通过可穿戴超材料实现无线互联，利用双模超材料纺织品将功率传输(13.56 MHz)和数据通信(2.4 GHz)信道分离。该系统以智能手机为枢纽，为多个表皮传感器提供高效的无线供电和低延迟生物信号采集，实现连续高保真监测。","scd":null,"kp":["[表皮传感器无线供电]: 13.56 MHz"]},{"i":34575,"as":"","scd":null,"kp":[]},{"i":34576,"as":"","scd":null,"kp":[]},{"i":34577,"as":"","scd":null,"kp":[]},{"i":34578,"as":"","scd":null,"kp":[]},{"i":34579,"as":"","scd":null,"kp":[]},{"i":34580,"as":"","scd":null,"kp":[]},{"i":34581,"as":"","scd":null,"kp":[]},{"i":34582,"as":"","scd":null,"kp":[]},{"i":34583,"as":"","scd":null,"kp":[]},{"i":34584,"as":"","scd":null,"kp":[]},{"i":34585,"as":"","scd":null,"kp":[]},{"i":34586,"as":"","scd":null,"kp":[]},{"i":34587,"as":"","scd":null,"kp":[]},{"i":34588,"as":"","scd":null,"kp":[]},{"i":34589,"as":"针对感光细胞退化导致的失明问题，研究开发了一种可贴附于视网膜表面的超薄人工视网膜。该器件由近红外光敏光电晶体管阵列和三维液态金属微柱电极组成，能将近红外光转化为电刺激。液态金属电极增强了与视网膜神经节细胞的贴合度，在提供有效电荷注入的同时将组织损伤降至最低。","scd":null,"kp":["[薄人造视网膜设备]: 能够将近红外光(NIR)转换为电刺激以激发视网膜神经元"]},{"i":34590,"as":"研究阐明了分子添加剂提升钙钛矿发光二极管效率的根本机制。研究发现，添加剂分子内部细微的电子极化能够有效控制钙钛ite薄膜的结晶过程，使其形成更均匀、缺陷受抑制的薄膜结构。该工作显著提升了器件效率，并为下一代钙钛矿光电材料中的添加剂设计提供了清晰的原则。","scd":null,"kp":["[钙钛矿发光二极管]: 添加剂分子内的微妙电子极化可控制钙钛矿晶体形成，诱导均匀且抑制缺陷的薄膜，从而显著提高器件效率"]},{"i":34591,"as":"","scd":null,"kp":[]},{"i":34592,"as":"","scd":null,"kp":[]},{"i":34593,"as":"","scd":null,"kp":[]},{"i":34594,"as":"","scd":null,"kp":[]},{"i":34595,"as":"","scd":null,"kp":[]},{"i":34596,"as":"","scd":null,"kp":[]},{"i":34597,"as":"","scd":null,"kp":[]},{"i":34598,"as":"","scd":null,"kp":[]},{"i":34599,"as":"","scd":null,"kp":[]},{"i":34600,"as":"针对水中全氟和多氟烷基物质(PFAS)的敏感监测需求，研究开发了一种可规模化合成的二维氟化纳米材料。该材料兼具强荧光与富含氟的多孔表面，能够与PFAS发生强烈相互作用并引发快速荧光猝灭，从而实现对亚皮摩尔浓度PFAS的快速、选择性检测，为高灵敏环境传感提供了可扩展的方案。","scd":null,"kp":["PFAS检测限[二维氟化纳米材料]: 亚皮摩尔浓度","[二维氟化纳米材料]: 结合强荧光与富氟多孔表面，与PFAS强相互作用引起快速荧光猝灭"]},{"i":34601,"as":"研究开发了一种基于直接光图案化聚合物半导体、通过溶液工艺制备的本征可拉伸有机互补电路。通过将高性能n型聚合物半导体共价嵌入弹性体基质，制备出在100%应变下电子迁移率为0.28 cm² V⁻¹ s⁻¹的完全可拉伸晶体管。结合p型聚合物半导体层的共价功能化策略，实现了高度可扩展的柔性电路制造。","scd":null,"kp":["[本征可拉伸互补电路]: 采用溶液加工工艺，基于可直接光图案化的聚合物半导体"]},{"i":34602,"as":"","scd":null,"kp":[]},{"i":34603,"as":"研究首次报道了具有高热电性能的弹性三维结构化Bi2Te3基复合材料。得益于Ecoflex-Bi2Te3的双网络结构，该复合材料兼具相对较高的电导率、优异的弹性以及低热导率，其性能超越了以往多数柔性三维热电材料，在通过收集人体热量为自供电可穿戴设备供电方面展现出巨大潜力。","scd":null,"kp":["热电复合材料[本征弹性三维架构]: Ecoflex-Bi2Te3双网络结构，具有较高电导率、优异弹性和低热导率"]},{"i":34604,"as":"","scd":null,"kp":[]},{"i":34605,"as":"研究开发了一种名为HIDE的透明涂层系统，通过将工程化淀粉样蛋白与合成DNA结合，实现跨宏观二维码到分子DNA序列等四个空间尺度的数据加密。该系统将可见的表面特征与嵌入的分子数据解耦，需要物理与生化双重正交密钥才能完全解密，从而构建了高度安全的下一代产品认证平台。","scd":null,"kp":["防伪涂层系统[信息加密尺度]: 四个空间尺度（从宏观QR码到分子DNA序列）","解密机制[防伪涂层系统]: 需要正交的物理和生化密钥进行完整解密"]},{"i":34606,"as":"研究提出一种由骨架锚定钾引导的介孔选择性烧结策略。在极低含量的钾引导下，二氧化硅致密化过程精准定向至纳米球的介孔壁，从而在显著降低的温度下实现了对脆弱纳米晶体的致密封装。该技术合成了高分散、超稳定的溶液可加工荧光纳米球，适用于Micro-LED颜色转换和生物成像等要求严苛的应用场景。","scd":null,"kp":["介孔选择性烧结[致密化封装]: 超低且骨架锚定的钾引导二氧化硅致密化至介孔壁","纳米晶封装[高性能荧光纳米球]: 在显著降低的温度下实现且不牺牲分散性"]},{"i":34607,"as":"","scd":null,"kp":[]},{"i":34608,"as":"","scd":null,"kp":[]},{"i":34609,"as":"","scd":null,"kp":[]},{"i":34610,"as":"","scd":null,"kp":[]},{"i":34611,"as":"","scd":null,"kp":[]},{"i":34612,"as":"","scd":null,"kp":[]},{"i":34613,"as":"受跳蚤节肢弹性蛋白取向分层结构的启发，研究提出一种结合共价桥接和纤维流剪切策略，协同增强摩擦电气凝胶在极端应变下的弹性和抗疲劳性。基于该策略制备的摩擦电裂纹传感器展现出超快响应和稳定的信号输出，为新一代高性能气凝胶传感器材料的设计与制备提供了新思路。","scd":null,"kp":["摩擦电气凝胶[极端应变下的弹性和抗疲劳性增强]: 共价桥接与纤维流剪切协同策略（仿生跳虫节肢弹性蛋白垫）","摩擦电裂纹传感器[性能表现]: 超快响应和稳定的信号输出"]},{"i":34614,"as":"","scd":null,"kp":[]},{"i":34615,"as":"","scd":null,"kp":[]},{"i":34616,"as":"","scd":null,"kp":[]},{"i":34617,"as":"","scd":null,"kp":[]},{"i":34618,"as":"","scd":null,"kp":[]},{"i":34619,"as":"","scd":null,"kp":[]},{"i":34620,"as":"","scd":null,"kp":[]},{"i":34621,"as":"","scd":null,"kp":[]},{"i":34622,"as":"","scd":null,"kp":[]},{"i":34623,"as":"","scd":null,"kp":[]},{"i":34624,"as":"","scd":null,"kp":[]},{"i":34625,"as":"","scd":null,"kp":[]},{"i":34626,"as":"","scd":null,"kp":[]},{"i":34627,"as":"","scd":null,"kp":[]},{"i":34628,"as":"","scd":null,"kp":[]},{"i":34629,"as":"","scd":null,"kp":[]},{"i":34630,"as":"","scd":null,"kp":[]},{"i":34631,"as":"","scd":null,"kp":[]},{"i":34632,"as":"","scd":null,"kp":[]},{"i":34633,"as":"","scd":null,"kp":[]},{"i":34634,"as":"","scd":null,"kp":[]},{"i":34635,"as":"","scd":null,"kp":[]},{"i":34636,"as":"","scd":null,"kp":[]},{"i":34637,"as":"","scd":null,"kp":[]},{"i":34638,"as":"","scd":null,"kp":[]},{"i":34639,"as":"","scd":null,"kp":[]},{"i":34640,"as":"研究利用热塑性聚合物（聚碳酸酯）内部超快激光诱导的微涡流产生复杂的光色散信号，实现微型光谱仪的制造。这种基于光弹性效应的方法无需外部刺激即可提供丰富且多样的光谱响应。该色散结构工作带宽达400-1550纳米，占用面积仅为10×10平方微米，且不依赖外部偏振控制。","scd":null,"kp":["微型光谱仪[光色散组件]: 超快激光诱导聚碳酸酯基板内的微型涡流产生复杂的色散（无需外部刺激）"]},{"i":34641,"as":"","scd":null,"kp":[]},{"i":34642,"as":"","scd":null,"kp":[]},{"i":34643,"as":"","scd":null,"kp":[]},{"i":34644,"as":"","scd":null,"kp":[]},{"i":34645,"as":"研究基于全球分布的温度敏感代用网络，重建了过去九个世纪(1100-2006年)的跨年大气二氧化碳增长率(CGR)。该重建结果已通过动态全球植被模型模拟和厄尔尼诺-南方涛动现象的对比验证。数据揭示了陆地生物圈碳吸收波动导致的CGR变异性，及其与陆地生态系统和气候驱动因素的密切联系。","scd":null,"kp":["大气CO2增长率[过去九百年]: 实现年际大气CO2增长率（CGR）的重构以揭示其自然变率"]},{"i":34646,"as":"","scd":null,"kp":[]},{"i":34647,"as":"","scd":null,"kp":[]},{"i":34648,"as":"研究开发了一种具备双立体中心的手性生物基聚合物，无需添加手性选择剂即可自组装形成紧密堆积的膜，实现手性选择性纳米过滤。通过量化渗透液和截留液，揭示了压力调节对映选择性和对映体截留率的机制，确立了立体规整自组装作为实现可持续手性分离的新设计路线。","scd":null,"kp":["生物基聚合物膜[手性纳米过滤]: 具有双立体中心的本征手性聚合物自组装成致密膜（无需添加手性选择剂）","对映选择性[手性纳米过滤膜]: 压力可调节对映选择性和对映体截留率"]},{"i":34649,"as":"","scd":null,"kp":[]},{"i":34650,"as":"","scd":null,"kp":[]},{"i":34651,"as":"","scd":null,"kp":[]},{"i":34652,"as":"","scd":null,"kp":[]},{"i":34653,"as":"","scd":null,"kp":[]},{"i":34654,"as":"","scd":null,"kp":[]},{"i":34655,"as":"","scd":null,"kp":[]},{"i":34656,"as":"","scd":null,"kp":[]},{"i":34657,"as":"","scd":null,"kp":[]},{"i":34658,"as":"","scd":null,"kp":[]},{"i":34659,"as":"","scd":null,"kp":[]},{"i":34660,"as":"研究探讨了可再生氢气在工业脱碳中的作用及其对全球价值链的地缘经济影响，分析了工业集群与潜在大规模制氢地区之间的空间错位问题。文章提出了基于可再生氢气生产的三个未来情景：在“燃料替代”情景中，可再生氢气替代化石燃料，且依赖于长距离氢气运输基础设施的建设，工业价值链不会发生重大重塑。","scd":null,"kp":["可再生氢[地缘经济影响]: 解决工业集群与潜在大规模可再生氢生产地之间的地理错配问题"]},{"i":34661,"as":"","scd":null,"kp":[]},{"i":34662,"as":"关于2022年发表于《Matter》期刊上的一篇关于二维多孔石墨炔文章的撤稿通知。","scd":null,"kp":["二维多孔石墨炔[环状π伸展构建]: 撤稿声明（Retraction Notice）"]},{"i":34663,"as":"","scd":null,"kp":[]},{"i":34664,"as":"","scd":null,"kp":[]},{"i":34665,"as":"","scd":null,"kp":[]},{"i":34666,"as":"","scd":null,"kp":[]},{"i":34667,"as":"","scd":null,"kp":[]},{"i":34668,"as":"研究设计了一种生物相容性全水凝胶电极阵列，突破了水凝胶纤维直径的制造极限，将其降至亚微米级(0.94微米)。这一创新极大降低了免疫反应，实现了对单个神经元动作电位的高分辨率追踪。同时，克服了水凝胶材料固有的电学和稳定性缺陷，实现了长达6个月以上且具有高质量信噪比(16.9 dB)的神经元信号记录。","scd":null,"kp":["水凝胶电极阵列[水凝胶纤维直径]: 0.94 μm（突破制造极限至亚微米级）","神经元信号记录[信噪比]: 16.9 dB","神经元信号记录[长期稳定性]: 超过6个月","脑机接口[功能特性]: 实现免疫反应显著降低和单神经元动作电位高分辨率追踪"]},{"i":34669,"as":"","scd":null,"kp":[]},{"i":34670,"as":"","scd":null,"kp":[]},{"i":34671,"as":"","scd":null,"kp":[]},{"i":34672,"as":"研究提出一种受水启发的“类机械组装”柔性策略，通过氧化石墨烯二维分子保形界面实现强且可逆的组装。这种机制允许材料构建成特定结构，并能够可逆地拆卸和重新组装成其他结构。该组装方法为构建生命集成材料开辟了新途径。","scd":null,"kp":["类机械组装[组装机制]: 氧化石墨烯二维分子共形界面实现强且可逆的组装、分解与重组装","材料构建[生命集成材料]: 能够可逆拆卸并重组成其他结构的柔性策略"]},{"i":34673,"as":"","scd":null,"kp":[]},{"i":34674,"as":"本文报道了一种三维微仪器化神经网络设备。该设备将三维柔性电子传感器和刺激器阵列与三维培养的神经网络集成在一起。它能够跨越多个平面记录动作电位，且持续期可达6个月。这一技术实现了对不断演变的神经元连接图谱的定量监测，并支持进行药理刺激实验，为类脑计算、人工智能以及神经疾病进展研究提供了稳定的设备-神经网络接口。","scd":null,"kp":["[设备-神经网络接口]: 三维微仪器化神经网络器件提供了稳定的3D类脑计算与结构模拟接口"]},{"i":34675,"as":"","scd":null,"kp":[]},{"i":34676,"as":"","scd":null,"kp":[]},{"i":34677,"as":"","scd":null,"kp":[]},{"i":34678,"as":"","scd":null,"kp":[]},{"i":34679,"as":"本文提出了一种基于高介电常数氧化铝（Al2O3）中间层的晶圆级干转移策略。该策略成功将4英寸单晶二硫化钼（MoS2）薄膜集成到柔性基底上。与传统湿转移不同，该方法无需接触聚合物或溶剂，避免了表面污染，保留了MoS2的内在电子特性，为高性能柔性电子器件制造提供了理想方案。","scd":null,"kp":["[转移工艺]: 基于氧化物的干法转移策略(替代传统湿法转移以避免表面污染)","材料[柔性电子半导体]: 蓝宝石衬底上化学气相沉积生长的单晶二硫化钼"]},{"i":34680,"as":"研究介绍了名为Synthegy的框架，该框架将大语言模型与传统搜索算法结合作为化学推理引擎。化学家可使用自然语言指定合成策略要求，该系统能从大候选池中识别可行路线，其评估结果有71%与专家判断一致。此外，该范式还可通过评估基元反应步骤指导反应机制阐明，证明了大语言模型与计算工具结合在化学发现中的有效性。","scd":null,"kp":["专家评估一致率[合成路线规划]: 71%","大模型应用[化学合成]: 结合大语言模型与传统搜索算法作为化学推理引擎(Synthegy框架)"]},{"i":34681,"as":"","scd":null,"kp":[]},{"i":34682,"as":"","scd":null,"kp":[]},{"i":34683,"as":"","scd":null,"kp":[]},{"i":34684,"as":"","scd":null,"kp":[]},{"i":34685,"as":"","scd":null,"kp":[]},{"i":34686,"as":"","scd":null,"kp":[]},{"i":34687,"as":"","scd":null,"kp":[]},{"i":34688,"as":"","scd":null,"kp":[]},{"i":34689,"as":"","scd":null,"kp":[]},{"i":34690,"as":"","scd":null,"kp":[]},{"i":34691,"as":"","scd":null,"kp":[]},{"i":34692,"as":"","scd":null,"kp":[]},{"i":34693,"as":"","scd":null,"kp":[]},{"i":34694,"as":"","scd":null,"kp":[]},{"i":34695,"as":"","scd":null,"kp":[]},{"i":34696,"as":"","scd":null,"kp":[]},{"i":34697,"as":"","scd":null,"kp":[]},{"i":34698,"as":"","scd":null,"kp":[]},{"i":34699,"as":"针对二维材料（如二硫化钼）构建神经形态存内计算硬件时存在的权重精度与能效之间的权衡问题，本文报道了一种硬件内的信号折叠方案。不同于提升操作电压或使用校准补偿方案的高能耗方法，该方案能够同时实现高权重精度和高能效，从而推动此类硬件在边缘人工智能平台中的扩展应用。","scd":null,"kp":["[神经形态硬件瓶颈]: 权重精度与能效之间存在相互制约的权衡关系","核心材料[存内计算硬件]: 二维二硫化钼(MoS2)"]},{"i":34700,"as":"","scd":null,"kp":[]},{"i":34701,"as":"","scd":null,"kp":[]},{"i":34702,"as":"","scd":null,"kp":[]},{"i":34703,"as":"","scd":null,"kp":[]},{"i":34704,"as":"","scd":null,"kp":[]},{"i":34705,"as":"","scd":null,"kp":[]},{"i":34706,"as":"","scd":null,"kp":[]},{"i":34707,"as":"","scd":null,"kp":[]},{"i":34708,"as":"本研究展示了一种基于3D打印与输注沉淀反应的单锅自由形式制造方法，用于构建微尺度磁响应材料。该方法能够打印任意3D几何形状，并实现空间可编程的磁响应特性。这为制造机械和磁性均可调的材料提供了途径，适用于可重构器件、医疗机器人及微型软驱动系统等广泛应用。","scd":null,"kp":["[制造工艺]: 基于3D打印与随后的输液沉淀反应的自由形式制造法","特性[微型磁性材料]: 空间可编程的任意三维几何形状及可调纳米颗粒负载"]},{"i":34709,"as":"本文研发出一种极性可切换的离子二极管。该器件利用电编程的混合电荷聚电解质水凝胶产生内置电场，通过逆转离子迁移方向，能在两个整流状态之间进行切换。在全波整流器的应用展示中，四个二极管通过集体重编程实现了直流输出的反转，而无需像传统电路那样进行物理重新布线。","scd":null,"kp":["[整流电路重构]: 无需物理重新布线即可通过集体重编程四个二极管反转直流输出","核心机制[极性可切换离子二极管]: 混合电荷聚电解质水凝胶经电编程产生内置电场，通过反转离子迁移方向在两种整流状态间切换"]},{"i":34710,"as":"","scd":null,"kp":[]},{"i":34711,"as":"针对氨因危险性在储运上的限制，本文探讨了固体吸附技术在氨-热联合存储中的应用。将氨与热存储结合，吸附材料可实现约10 MJ/l的总能量密度。理想的氨吸附材料需具备高能量密度、长期稳定性和优越的传热传质特性。卤化物、氢键有机框架和石墨烯气凝胶等材料，特别是金属有机框架，被认为是合适的候选材料。","scd":null,"kp":["能量密度[氨-热联合存储]: ~10 MJ l−1"]},{"i":34712,"as":"","scd":null,"kp":[]},{"i":34713,"as":"","scd":null,"kp":[]},{"i":34714,"as":"本文综述了利用先进原位电子显微技术实时观察陶瓷材料在应力下变形与断裂过程的研究。这些高分辨率原子尺度实验揭示了陶瓷硬度与脆性源于其独特的原子级应力响应机制。这些微观机制的揭示，为设计兼具高强度与高韧性且能适应极端环境的新一代陶瓷材料提供了关键科学依据。","scd":null,"kp":["[变形与断裂机制]: 硬度与脆性源于独特的原子尺度应力响应机制"]},{"i":34715,"as":"本文通过对咔唑-卟啉共价有机框架进行维度调控，实现了对光生载流子动力学的高效控制。一维COF展现出增强的电荷分离能力和延长的载流子寿命。基于一维COF/石墨烯的光电突触器件具备高响应度、强突触可塑性以及宽带多色感知能力，在自适应神经形态视觉领域展现出巨大潜力。","scd":null,"kp":["[光电突触性能]: 具备高光电导率、鲁棒的突触可塑性以及宽带多色感知能力","载流子动力学[一维共价有机框架]: 增强的电荷分离与延长的载流子寿命"]},{"i":34716,"as":"","scd":null,"kp":[]},{"i":34717,"as":"本文报道了一个可对等离子体斯格明子进行编码的可编程平台。该平台能合成包括Néel型斯格明子和子在内的多种拓扑结构，并利用超快编码在时间维度上产生谐波斯格明子。这些可编程的拓扑斯格明子被应用于通信和传感，实现了稳健的多通道无线通信，能够在湍流噪声信道和极端条件下提供可靠的通信能力。","scd":null,"kp":["[编码平台特性]: 能够编码包括尼尔型斯格明子、 merons(半子)及谐波斯格明子在内的多种拓扑结构的可编程平台"]},{"i":34718,"as":"本文研究了固态氖作为单电子量子比特宿主的抗噪特性。在约10mK时，固态氖电子电荷量子比特具有长相干时间和高操作保真度。研究表明，当操作温度高于100mK且偏离电荷不敏感的甜点位置时，固态氖依然展现出抵御电荷和热噪声的韧性。其低频和高频电荷噪声密度特征为可扩展量子信息架构的发展提供了支持。","scd":null,"kp":["[电子量子比特]: 100 mK以上温度固态氖可作为抗噪宿主","[电荷量子比特]: 10 mK左右温度下具有长相干时间和高操作保真度"]},{"i":34719,"as":"","scd":null,"kp":[]},{"i":34720,"as":"本文评估了美国《通胀削减法案》（IRA）及2025年预算法案（OBBBA）对能源系统的影响。IRA预计将放大现有的脱碳趋势，到2035年使温室气体排放量较无IRA基线减少约一倍，并显著改善近期空气质量与人类健康。IRA还预计在未来十年使包括可再生能源、储能、核能及碳捕获在内的清洁电力投资增加约一倍。","scd":null,"kp":["[美国能源系统]: IRA法案有望放大现有脱碳趋势，大致使排放（减排幅度）翻倍"]},{"i":34721,"as":"","scd":null,"kp":[]},{"i":34722,"as":"本文报道了一种用于传感与计算的对称性可重构光电二极管。该器件基于硫化银铋，在两个高功函数电极间构建对称背靠背肖特基结。通过电压编程诱导银离子的局部电化学还原，器件可发生对称到不对称的可逆转变，降低一侧肖特基势垒。该技术实现了传感器层面的直接光电流计算，满足微型机器人等边缘智能应用的低功耗需求。","scd":null,"kp":["[传感器级直接光电流计算]: 可解决微型机器人和可穿戴设备等智能边缘应用的严苛功率限制","光电器件[对称可重构光电二极管]: 基于硫化银铋（AgBiS2）构建"]},{"i":34723,"as":"针对传统水凝胶在强度和韧性之间的权衡，本文受肌肉纤维取向和蜘蛛丝分级结构的启发，开发了一种双重仿生耦合策略。该策略通过耦合取向与结晶作用，使水凝胶同时实现了高强度、高韧性和抗疲劳性。这种新型水凝胶在人工肌腱和韧带等承受负荷的生物医学应用中具有广阔前景。","scd":null,"kp":["[水凝胶机械性能]: 受肌肉纤维和蜘蛛丝启发的双仿生策略可同时实现高强度、韧性和抗疲劳性"]},{"i":34724,"as":"","scd":null,"kp":[]},{"i":34725,"as":"","scd":null,"kp":[]},{"i":34726,"as":"","scd":null,"kp":[]},{"i":34727,"as":"","scd":null,"kp":[]},{"i":34728,"as":"","scd":null,"kp":[]},{"i":34729,"as":"","scd":null,"kp":[]},{"i":34730,"as":"","scd":null,"kp":[]},{"i":34731,"as":"","scd":null,"kp":[]},{"i":34732,"as":"","scd":null,"kp":[]},{"i":34733,"as":"","scd":null,"kp":[]},{"i":34734,"as":"","scd":null,"kp":[]},{"i":34735,"as":"","scd":null,"kp":[]},{"i":34736,"as":"","scd":null,"kp":[]},{"i":34737,"as":"","scd":null,"kp":[]},{"i":34738,"as":"","scd":null,"kp":[]},{"i":34739,"as":"本文结合离子-分子交叉束三维速度成像实验与39维精确势能面动力学模拟，深入研究了Cl− + (CH3)3CI反应的原子级动力学。研究发现，直接的E2消除反应生成了大部分高激发的中性产物和缓慢的离子产物分布。此外，研究还揭示了SN2反应中一种直接的“翻转”保留机制，即取代反应通过叔丁基的直接翻转而发生。","scd":null,"kp":[]},{"i":34740,"as":"","scd":null,"kp":[]},{"i":34741,"as":"本文以16p12.1缺失为模型，利用诱导多能干细胞和CRISPR编辑细胞系，研究了遗传背景对神经发育障碍表型差异的影响。研究发现，基因缺失与遗传背景中的罕见变异共同影响染色质可及性和神经发育基因表达。细胞分析确定了抑制性神经元产生改变和神经祖细胞增殖异常等家族特异性表型，这些表型与头部大小变化相关。","scd":null,"kp":[]},{"i":34742,"as":"","scd":null,"kp":[]},{"i":34743,"as":"","scd":null,"kp":[]},{"i":34744,"as":"","scd":null,"kp":[]},{"i":34745,"as":"","scd":null,"kp":[]},{"i":34746,"as":"","scd":null,"kp":[]},{"i":34747,"as":"","scd":null,"kp":[]},{"i":34748,"as":"为了解决动态身体运动引起的生物电子器件界面失效问题，本文报道了一种基于三维拓扑互穿结构和共价化学锚定的抗磨损生物电子技术（TopoLock）。该技术适用于多种生物电子材料和制造工艺。在多个临床前动物模型中证明，该系统能够实现长期电生理记录、电刺激和化学传感，有效提升了生物电子器件的长期可靠性和耐用性。","scd":null,"kp":["[耐磨生物电子器件]: 基于三维拓扑互穿架构和共价化学锚定构建"]},{"i":34749,"as":"本文探讨了宇称-时间（PT）对称性及奇异点在电子电路中的发展与应用。PT对称性源于量子力学，现已扩展至电子系统，其非厄米系统特征表现为两个或多个特征值及特征向量汇合的奇异点。文章综述了PT对称性在电子电路中的基本原理和实现方式，并重点强调了这些系统在传感器和信号调制等领域的应用潜力。","scd":null,"kp":["[电子电路]: 宇称-时间(PT)对称和非厄米系统存在多个特征值及特征向量合并的奇异点"]},{"i":34750,"as":"本文开发了一种可持续的功能性生物复合材料合成新策略。该方法在室温条件下，利用微生物在二维功能材料存在时进行生物合成，成功制备出内部结构可精确控制且具有卓越导热性能的分级生物复合材料。这种结合可编程微生物合成与纳米材料的技术为高性能可持续材料的制造开辟了新途径。","scd":null,"kp":["[生物复合材料合成]: 室温环境下利用微生物在功能二维材料存在下进行合成"]},{"i":34751,"as":"","scd":null,"kp":[]},{"i":34752,"as":"","scd":null,"kp":[]},{"i":34753,"as":"","scd":null,"kp":[]},{"i":34754,"as":"","scd":null,"kp":[]},{"i":34755,"as":"研究发现北极熊的毛发在零下80摄氏度的极端低温下依然保持极高的韧性。这种低温韧性源于其独特的分级纤维结构，该结构在低温下仍能保持多尺度变形和能量耗散能力。这表明出色的低温力学性能可以通过结构设计实现，为开发在极端寒冷环境中仍保持机械可靠性的仿生合成材料提供了重要启示。","scd":null,"kp":["[北极熊毛发展材料]: −80°C下通过分级纤维结构保持极高韧性"]},{"i":34756,"as":"研究提出一种三层范德华异质结构以实现非对称热传输。这种厚度小于5纳米的“热Janus晶体”由二硫化钼、硫化硒化钼和二硒化钨构成。通过精确调节异质结构各界面的扭曲角，能够在面外方向实现非对称的声子传输特性，从而高效散发集成电路的热量并阻断反向热流，保护热敏组件。","scd":null,"kp":["[范德华异质结]: 三层结构可实现面外方向的非对称热传输"]},{"i":34757,"as":"针对机械界面微观表面粗糙度限制实际接触面积并阻碍电子或声子传输的问题，研究提出受传统木工榫卯接头启发的机械元界面。该界面利用几何驱动的接触力增强，将界面应力从压缩转换为剪切，消除介电势垒，显著提升界面的电子和热传输性能，解决电路中的焦耳热和散热问题。","scd":null,"kp":["[电子与热传输]: 受传统木工榫卯和指接启发的机械元界面可增强材料间界面输运性能"]},{"i":34758,"as":"","scd":null,"kp":[]},{"i":34759,"as":"","scd":null,"kp":[]},{"i":34760,"as":"","scd":null,"kp":[]},{"i":34761,"as":"","scd":null,"kp":[]},{"i":34762,"as":"","scd":null,"kp":[]},{"i":34763,"as":"","scd":null,"kp":[]},{"i":34764,"as":"","scd":null,"kp":[]},{"i":34765,"as":"","scd":null,"kp":[]},{"i":34766,"as":"自助实验室（SDLs）能够快速、智能地开展材料研究并生成高质量元数据。研究指出，将SDL转化为社区资源面临三大关键障碍：开放科学实践受限、基础设施不完善以及缺乏自动化兼容的化学体系。文章总结了相关发现，并提出了具体行动建议以克服这些障碍，推动SDL发挥广泛的社会影响力。","scd":null,"kp":["[自驱动实验室(SDLs)社区化]: 核心障碍在于开放科学实践受限、基础设施发展不足以及缺乏自动化兼容的化学体系"]},{"i":34767,"as":"","scd":null,"kp":[]},{"i":34768,"as":"","scd":null,"kp":[]},{"i":34769,"as":"","scd":null,"kp":[]},{"i":34770,"as":"","scd":null,"kp":[]},{"i":34771,"as":"为解决水凝胶电解质在锌离子电池中机械强度与离子传导率难以兼顾的问题，研究提出一种耦合补偿策略。通过构建ZnXP凝胶，该策略在破坏电解质内部原有氢键的同时，协同增强了机械耗散能力和锌离子传输，从而实现了锌离子电池的长效可逆运行，提升了电池的综合性能。","scd":null,"kp":["[锌离子电池水凝胶电解质]: 提出ZnXP凝胶耦合补偿策略，通过打破固有氢键实现机械耗散与Zn2+传输的协同增强，解决机械强度与离子电导率的权衡限制"]},{"i":34772,"as":"","scd":null,"kp":[]},{"i":34773,"as":"","scd":null,"kp":[]},{"i":34774,"as":"","scd":null,"kp":[]},{"i":34775,"as":"","scd":null,"kp":[]},{"i":34776,"as":"","scd":null,"kp":[]},{"i":34777,"as":"","scd":null,"kp":[]},{"i":34778,"as":"","scd":null,"kp":[]},{"i":34779,"as":"","scd":null,"kp":[]},{"i":34780,"as":"","scd":null,"kp":[]},{"i":34781,"as":"","scd":null,"kp":[]},{"i":34782,"as":"","scd":null,"kp":[]},{"i":34783,"as":"","scd":null,"kp":[]},{"i":34784,"as":"","scd":null,"kp":[]},{"i":34785,"as":"","scd":null,"kp":[]},{"i":34786,"as":"","scd":null,"kp":[]},{"i":34787,"as":"","scd":null,"kp":[]},{"i":34788,"as":"","scd":null,"kp":[]},{"i":34789,"as":"","scd":null,"kp":[]},{"i":34790,"as":"","scd":null,"kp":[]},{"i":34791,"as":"","scd":null,"kp":[]},{"i":34792,"as":"","scd":null,"kp":[]},{"i":34793,"as":"","scd":null,"kp":[]},{"i":34794,"as":"研究通过对锆基金属有机框架进行选择性配体裁剪，同时加速电子转移和离子传输，实现了电化学和浓差极化的操作中原位解耦与双重抑制。这一方法突破了极化对工作电压的限制，成功实现了超快电化学氟离子捕获，超越了传统单一过程的优化效果。","scd":null,"kp":["[电化学氟离子捕获]: 通过锆基金属有机框架的配体裁剪同步加速电子转移和离子传输，实现电化学和浓差极化的解耦与双重抑制"]},{"i":34795,"as":"","scd":null,"kp":[]},{"i":34796,"as":"","scd":null,"kp":[]},{"i":34797,"as":"","scd":null,"kp":[]},{"i":34798,"as":"","scd":null,"kp":[]},{"i":34799,"as":"研究开发出一种基于柔性基板排列碳纳米管阵列的射频晶体管，满足第六代无线通信对100 GHz以上工作频率的需求。通过电热协同设计改善器件散热与射频性能，该晶体管的电流增益和功率增益截止频率均超过100 GHz，且通态电流达到0.9毫安/微米，克服了柔性基板导热性差的问题。","scd":null,"kp":["工作频率[柔性射频碳纳米管晶体管]: 高于100 GHz"]},{"i":34800,"as":"研究提出一种基于物理不可克隆功能的安全系统，利用混沌垂直腔面发射激光器作为密钥生成的熵源。该系统的响应速率超过500 Gbps，每个激光发射器的能耗低于1皮焦耳/比特。结合卷积神经网络模型，系统实现了近零误报率的动态密钥实时匹配，并采用生成对抗框架进一步增强安全性、降低通信开销。","scd":null,"kp":["响应速率[混沌垂直腔面发射激光器物理不可克隆函数]: 高于500 Gbps","能耗[混沌垂直腔面发射激光器物理不可克隆函数]: 低于1 pJ/bit"]},{"i":34801,"as":"研究展示了一种可用于仄焦耳量级量热法的金属超导体-正常导体-超导体（SNS）传感器。与以往从稳态噪声和响应度测量中进行数学估计不同，该研究直接使用了金属SNS传感器进行实际的仄焦耳级能量测量。这一热学能量探测器通过吸收能量转化为热量并读取温度变化，在量子技术和计算领域具有基础性应用价值。","scd":null,"kp":["[量热法能量探测]: 预测超导体-正常导体-超导体(SNS)辐射传感器结合金属和石墨烯吸收体可实现极高灵敏度的Z焦耳级能量测量"]},{"i":34802,"as":"","scd":null,"kp":[]},{"i":34803,"as":"","scd":null,"kp":[]},{"i":34804,"as":"","scd":null,"kp":[]},{"i":34805,"as":"研究提出一种改进的气体淬火策略，将不稳定的溶剂去除过程转化为均匀且受控的蒸发环境。该方法增强了成核同步性，缓解了柔性基底的内在不稳定性。由此制备的柔性钙钛矿太阳能电池实现了24.72%的最高光电转换效率，在1个太阳光照下运行1500小时后效率保留率为91.5%，并在经历10000次弯折循环后仍保持91.2%的初始效率。","scd":null,"kp":["冠军效率[柔性钙钛矿太阳能电池(气淬策略)]: 24.72%","效率保持率[柔性钙钛矿太阳能电池(1个太阳光照度运行1500小时)]: 91.5%","初始PCE保持率[柔性钙钛矿太阳能电池(弯折10000次)]: 91.2%"]},{"i":34806,"as":"","scd":null,"kp":[]},{"i":34807,"as":"","scd":null,"kp":[]},{"i":34808,"as":"","scd":null,"kp":[]},{"i":34809,"as":"","scd":null,"kp":[]},{"i":34810,"as":"","scd":null,"kp":[]},{"i":34811,"as":"","scd":null,"kp":[]},{"i":34812,"as":"","scd":null,"kp":[]},{"i":34813,"as":"","scd":null,"kp":[]},{"i":34814,"as":"","scd":null,"kp":[]},{"i":34815,"as":"","scd":null,"kp":[]},{"i":34816,"as":"","scd":null,"kp":[]},{"i":34817,"as":"","scd":null,"kp":[]},{"i":34818,"as":"","scd":null,"kp":[]},{"i":34819,"as":"","scd":null,"kp":[]},{"i":34820,"as":"","scd":null,"kp":[]},{"i":34821,"as":"","scd":null,"kp":[]},{"i":34822,"as":"","scd":null,"kp":[]},{"i":34823,"as":"","scd":null,"kp":[]},{"i":34824,"as":"","scd":null,"kp":[]},{"i":34825,"as":"","scd":null,"kp":[]},{"i":34826,"as":"","scd":null,"kp":[]},{"i":34827,"as":"","scd":null,"kp":[]},{"i":34828,"as":"","scd":null,"kp":[]},{"i":34829,"as":"","scd":null,"kp":[]},{"i":34830,"as":"","scd":null,"kp":[]},{"i":34831,"as":"","scd":null,"kp":[]},{"i":34832,"as":"","scd":null,"kp":[]},{"i":34833,"as":"","scd":null,"kp":[]},{"i":34834,"as":"","scd":null,"kp":[]},{"i":34835,"as":"","scd":null,"kp":[]},{"i":34836,"as":"","scd":null,"kp":[]},{"i":34837,"as":"为克服二硫化钼等二维半导体与三维接触界面质量差的问题，研究结合金属有机化学气相沉积和硫化技术，在晶圆级规模制备出二硫化铌和二硫化钼的图案化金属-半导体异质结构。这种异质结构可作为活性沟道材料，兼具高质量生长、可扩展性和广泛适用性，显著提升了晶体管的器件性能。","scd":null,"kp":["[二维半导体存储器件]: 开发二硫化铌与二硫化钼的图案化金属-半导体异质结构，以解决二维材料与3D接触的界面质量问题并提升非易失性存储性能"]},{"i":34838,"as":"","scd":null,"kp":[]},{"i":34839,"as":"","scd":null,"kp":[]},{"i":34840,"as":"研究报道了高性能的单层二硒化钨p型晶体管。采用工业兼容的氧掺杂技术修复缺陷态后，器件在室温下的空穴迁移率达到137 cm²/V·s，接触电阻约560 Ω·μm。通道长度缩减至45纳米的器件表现出1245 μA/μm的高通态电流和约10⁹的开关比，克服了p型晶体管性能落后于n型器件的瓶颈。","scd":null,"kp":["空穴迁移率[p型单层二硒化钨晶体管(室温)]: 137 cm2 V−1 s−1","接触电阻[p型单层二硒化钨晶体管(室温)]: 约560 Ω µm"]},{"i":34841,"as":"","scd":null,"kp":[]},{"i":34842,"as":"","scd":null,"kp":[]},{"i":34843,"as":"研究实现了大规模本征可拉伸有机电化学晶体管阵列的制造，解决了神经形态边缘计算的规模化瓶颈。该晶体管密度高达每平方厘米10000个，具备良好的突触性能，包括线性、精确的电导编程和良好的保持力，器件性能均匀。这为处理大量多模态感知数据的可穿戴近传感器计算提供了有效解决方案。","scd":null,"kp":[]},{"i":34844,"as":"","scd":null,"kp":[]},{"i":34845,"as":"","scd":null,"kp":[]},{"i":34846,"as":"","scd":null,"kp":[]},{"i":34847,"as":"","scd":null,"kp":[]},{"i":34848,"as":"","scd":null,"kp":[]},{"i":34849,"as":"","scd":null,"kp":[]},{"i":34850,"as":"","scd":null,"kp":[]},{"i":34851,"as":"","scd":null,"kp":[]},{"i":34852,"as":"针对钙钛矿/硅叠层太阳能电池在金字塔纹理硅上覆盖不良和漏电的问题，研究引入了峰值选择性钝化技术。通过在金字塔顶部局部沉积氧化铝（Al₂O₃），实现了无针孔的钙钛矿薄膜并有效抑制了漏电流。该设计使电池效率突破33%并增强了稳定性，为叠层光伏技术的发展提供了实用途径。","scd":null,"kp":["能量转换效率[钙钛矿/硅叠层太阳能电池]: >33%","钝化技术[金字塔纹理硅表面尖峰]: Al2O3局部沉积选择性钝化","[钙钛矿/硅叠层太阳能电池]: 实现无针孔钙钛矿薄膜并抑制漏电"]},{"i":34853,"as":"","scd":null,"kp":[]},{"i":34854,"as":"","scd":null,"kp":[]},{"i":34855,"as":"","scd":null,"kp":[]},{"i":34856,"as":"","scd":null,"kp":[]},{"i":34857,"as":"","scd":null,"kp":[]},{"i":34858,"as":"","scd":null,"kp":[]},{"i":34859,"as":"","scd":null,"kp":[]},{"i":34860,"as":"","scd":null,"kp":[]},{"i":34861,"as":"","scd":null,"kp":[]},{"i":34862,"as":"研究使用具有受控无序序列的单晶体，通过多种实验探针对比了三种自旋组织。长程有序具有单一波矢不稳定性，与具有多重不稳定性的短程有序相竞争。这两者与自旋玻璃完全不同，自旋玻璃由单一且不相关的自旋组成。该研究明确区分了自旋玻璃与短程有序在时间和空间上的分离特征。","scd":null,"kp":["自旋构型[自旋玻璃]: 单个、无关联的自旋","自旋构型[长程有序态]: 单一波矢不稳定性","自旋构型[短程有序态]: 多重不稳定性"]},{"i":34863,"as":"","scd":null,"kp":[]},{"i":34864,"as":"","scd":null,"kp":[]},{"i":34865,"as":"","scd":null,"kp":[]},{"i":34866,"as":"","scd":null,"kp":[]},{"i":34867,"as":"研究通过在铝硅酸盐玻璃中进行温和的阶梯式结晶，制备出晶圆级的Ce³⁺掺杂石榴石型准透明陶瓷。作为高功率光子引擎，该材料支持超过1.2公里距离的室外白光通信，其-3 dB带宽高达71.8 MHz。该成果在白光通信及未来低空经济应用中展现出非凡的潜力。","scd":null,"kp":["材料体系[光子引擎准透明陶瓷]: Ce3+掺杂石榴石型Lu(Ca2-xMgx)Al3Si2O12:Ce3+","制备工艺[铝硅酸盐玻璃]: 温和的阶梯式结晶法","传输距离[室外白光通信(VLC)]: 1.2公里","-3 dB带宽[室外白光通信(VLC)]: 71.8 MHz"]},{"i":34868,"as":"","scd":null,"kp":[]},{"i":34869,"as":"","scd":null,"kp":[]},{"i":34870,"as":"","scd":null,"kp":[]},{"i":34871,"as":"","scd":null,"kp":[]},{"i":34872,"as":"","scd":null,"kp":[]},{"i":34873,"as":"","scd":null,"kp":[]},{"i":34874,"as":"","scd":null,"kp":[]},{"i":34875,"as":"","scd":null,"kp":[]},{"i":34876,"as":"","scd":null,"kp":[]},{"i":34877,"as":"研究结合0.5微米工业制造工艺与后端集成实验室工艺，构建了一台二硫化钼计算机。该计算机包含由四层金属互连的1433个晶体管，集成密度约为每平方厘米9336个晶体管。此项多级协同优化技术克服了原子级缺陷和器件变异等大规模集成难题，为开发高能效的人工智能计算技术提供了可行路径。","scd":null,"kp":["[二硫化钼(MoS2)计算机]: 构建了位并行(bit-parallel)计算架构","技术瓶颈[2D半导体超大规模集成]: 难以控制原子级缺陷、介观器件变化，且缺乏宏观变化感知设计方法"]},{"i":34878,"as":"钙钛矿光伏技术在效率上快速提升，但其商业化部署仍受限于规模化、可靠性和系统级的不确定性。文章指出，该领域目前的主要制约因素已从材料发现转向商业化进程。作者将钙钛矿及钙钛矿-硅叠层光伏的商业化重新定义为一个涵盖材料、制造、标准、政策和市场设计的多维产品中心演变，强调需打破单靠实验室效率提升带来的效益平台期。","scd":null,"kp":["发展限制[钙钛矿光伏商业化]: 主要受限于规模化、可靠性及系统级不确定性，而非材料发现"]},{"i":34879,"as":"","scd":null,"kp":[]},{"i":34880,"as":"研究将染色质免疫沉淀（ChIP）与无标记定量质谱技术相结合（qChIP-MS），用于探究局部染色质组成。该方法突破了传统ChIP-seq技术一次仅能分析一种蛋白质的局限性。研究在端粒、转录因子、组织样本以及通过dCas9介导的特定位点富集中验证了该方法的广泛适用性。","scd":null,"kp":["检测方法[局部染色质组成分析]: qChIP-MS (结合无标记定量质谱的染色质免疫共沉淀)"]},{"i":34881,"as":"","scd":null,"kp":[]},{"i":34882,"as":"","scd":null,"kp":[]},{"i":34883,"as":"","scd":null,"kp":[]},{"i":34884,"as":"","scd":null,"kp":[]},{"i":34885,"as":"研究利用层析特异性血氧水平依赖（BOLD）成像测量人类对级联奇异范式的听觉预测反应。通过建立模型并排除引流效应，发现预测违背呈现潜在的层级组织，与平面极（planum polare）浅层和外侧颞叶皮质中层的反应相关。研究结果将预测更新的神经动力学与人类中尺度皮质结构联系起来。","scd":null,"kp":["检测方法[人类皮层层级听觉预测过程]: 层级特异性血氧水平依赖(BOLD)成像"]},{"i":34886,"as":"","scd":null,"kp":[]},{"i":34887,"as":"","scd":null,"kp":[]},{"i":34888,"as":"","scd":null,"kp":[]},{"i":34889,"as":"","scd":null,"kp":[]},{"i":34890,"as":"研究开发了基于单平面照明显微镜的空间荧光交叉相关光谱技术（SPIM-sFCCS），以直接测量早期斑马鱼胚胎中形态发生素Squint的扩散系数。发现Squint的扩散系数是其分子大小、组织间隙内粘度及空间拥挤程度的函数。该技术能够在多空间尺度上根据地形学直接观察并测量形态发生素的运输。","scd":null,"kp":["测量技术[活体斑马鱼胚胎形态发生素多尺度运输追踪]: 基于单平面照明显微镜的空间荧光交叉相关光谱(SPIM-based spatial FCCS)","[稳定浓度梯度建立]: 需将形态发生素扩散减少至少一个数量级"]},{"i":34891,"as":"研究利用飞秒激光脉冲观察嵌入玻璃中的CsPbI3钙钛矿纳米晶体中激子-极化子的相干动力学。在2K温度下，通过双脉冲光子回波技术观测到激子-极化子态之间的量子拍频，表现出长达约300皮秒（T2）的光学相干时间。衰变由5-15皮秒的光学声子寿命决定。在四能级模型中，通过黄-里斯因子直接量化了激子-声子耦合强度。","scd":null,"kp":["光学相干时间[玻璃嵌入式CsPbI3钙钛矿纳米晶激子-极化子]: T2 ≈ 300 ps","测试条件[量子拍频观测]: 2K温度下使用瞬态双脉冲光子回波"]},{"i":34892,"as":"研究开发了一种用于高分辨率可视化压力映射的软性机-电致发光电子皮肤。该电子皮肤采用超薄、全软微结构设计，利用应变局部化变形和内在的力-电-光耦合机制。它能够在弯曲和柔性基底上实现定量压力传感，解决了传统可视化压力映射系统由于密集阵列或半刚性结构导致体积大、信号串扰及无法顺应动态变化曲面的问题。","scd":null,"kp":["核心材料[具有高分辨率压力映射的应变定位发光电子皮肤]: 软机械-电致发光材料"]},{"i":34893,"as":"针对B,N掺杂纳米石墨烯作为深蓝色OLED掺杂剂反向 intersystem 穿越效率低的问题，研究合成了三种具有异构骨架的四硼化纳米石墨烯。理论和实验表明，增加分子的平面度能促进共振效应、电荷转移离域和结构刚性。因此，最平面化的发射体实现了超窄发射，证明分子拓扑结构在加速反向 intersystem 穿越和提升颜色纯度方面起到决定性作用。","scd":null,"kp":["OLED掺杂剂[B,N掺杂纳米石墨烯]: 窄带发射且具备三线态激子捕获能力","应用瓶颈[B,N掺杂纳米石墨烯]: 反向系间窜跃(RISC)效率低下","分子拓扑结构[π拓展策略]: 可用于加速RISC并提升色纯度"]},{"i":34894,"as":"研究表明，流体铁电材料中的约束不对称性可以定制和多样化电极化拓扑孤子，为设计大规模复杂畴结构提供了关键途径。研究发现了非经典电单极子和混合拓扑态（包括手性半子和反半子变体，及其与嵌套斯格明子核心的复合杂化）。这些结构具有本征自电荷，通过向列弹性相互作用，形成多体拓扑构型。","scd":null,"kp":["极性拓扑结构[流体铁电体]: 可通过空间限制不对称性进行剪裁和多样化","拓扑态[流体铁电体]: 发现非经典电单极子和混合拓扑态","复杂畴结构[流体铁电体]: 为大规模设计提供关键途径"]},{"i":34895,"as":"在D03-Fe3Ga中发现了由手性反常主导的异常稳健传输现象。实验观察到正负向磁阻的理想组合、理想的平面纵向磁阻（PLMR）和平面霍尔效应。超低温下电阻率表现出显著的非费米液体行为，并伴随巨大的反常霍尔电导率（AHC）。DFT计算证实这些特性源于近平坦三维能带交叉产生的倾斜外尔点。","scd":null,"kp":["材料体系[手性反常主导的拓扑传输]: D03-Fe3Ga","磁电阻效应[D03-Fe3Ga]: 正/负磁电阻、理想面内纵向磁电阻(PLMR)和面内霍尔效应(PHE)的完美结合","电阻特性[D03-Fe3Ga]: 表现出极低温下极其稳健的电阻行为"]},{"i":34896,"as":"为了克服对称相对论零知识证明（ZKP）高轮次复杂度导致不可实际应用的缺陷，研究开发了一种高效的基于相对论比特承诺的非对称相对论零知识证明协议。该协议通过将其与非局部CHSH博弈相关联，证明了其量子完备性。这一新协议在无需计算假设的前提下实现了无条件安全性，成功降低了运行时间和总体随机性成本。","scd":null,"kp":["安全性[经典零知识证明]: 依赖计算假设，易受量子攻击","证明机制[量子可靠对称相对论零知识证明]: 无需计算假设即可解决图三着色问题","技术缺陷[对称相对论零知识证明]: 高轮次复杂度导致运行时间和总体随机性消耗不可行","研究突破[零知识证明]: 提出非对称相对论零知识证明以解决高复杂度问题"]},{"i":34897,"as":"研究展示了一类具有坚固且柔性六角形波纹微结构的纳米层压膜，可用作激光驱动的反射光帆。原型采用氧化铝和二硫化钼通过可扩展的半导体工艺制成，具备极低的面密度。实验测量结果表明，该微结构光帆实现了超过50%的宽带反射率和极低的宽带吸收率，满足了光帆苛刻的光学、机械和质量限制。","scd":null,"kp":["光帆结构[激光驱动]: 具有强韧且柔性六边形波纹微结构的纳米层压薄膜","制备材料[实验原型]: 氧化铝和二硫化钼","制备工艺[纳米层压光帆]: 可扩展的半导体加工技术"]},{"i":34898,"as":"研究提出一种氧化还原解耦电解策略用于电化学直接空气捕获（eDAC）二氧化碳，将二氧化碳释放和吸附剂再生进行空间分离。通过调节氧化还原介质并合成特定阳离子交换膜，克服了传统系统中质子和氢氧根复合导致的电流效率降低问题。该解耦架构能够高效产生高浓度碱性吸收液，实现了高电流效率和能量效率。","scd":null,"kp":["能量效率条件[电化学直接空气捕获(eDAC)]: 仅在产生稀氢氧化物流体时达到高能效","捕获液pH值[稀氢氧化物流体]: pH ≈ 13","兼容性[稀氢氧化物流体]: 与当前空气接触器不兼容","根本限制[生成高浓度捕获液]: 质子和氢氧根复合导致电流效率降低"]},{"i":34899,"as":"随着技术经济评估在工艺研究中成为标准做法，其研究范围和具体应用方法应当根据所评估技术的成熟度进行精确校准，以确保分析结果的准确性和适用性。","scd":null,"kp":[]},{"i":34900,"as":"电化学直接空气捕获技术提供了一种替代传统热化学方法的新途径。最新研发的氧化还原解耦架构，成功解决了系统高效产生高浓度强碱性吸收液的难题，使高效的二氧化碳捕获成为可能。","scd":null,"kp":["系统架构[电化学直接空气捕获]: 氧化还原解耦架构","解决能力[氧化还原解耦架构]: 高效生成高碱性吸附剂溶液"]},{"i":34901,"as":"Albert Liu探索了水伏技术如何从植物的蒸腾作用中汲取灵感，通过特定材料和结构设计，有效收集自然界中水分子蒸发时产生的动能，将其转化为可利用的电能。","scd":null,"kp":["水伏技术[能量收集]: 收集蒸发水分子的动能","技术灵感[水伏技术]: 植物蒸腾作用"]},{"i":34902,"as":"","scd":null,"kp":[]},{"i":34903,"as":"","scd":null,"kp":[]},{"i":34904,"as":"","scd":null,"kp":[]},{"i":34905,"as":"","scd":null,"kp":[]},{"i":34906,"as":"","scd":null,"kp":[]},{"i":34907,"as":"新兴的可充电金属-CO2电池因具有将电网级储能与利用丰富CO2气体相结合的潜力而备受关注。该研究通过对现有报告的深入分析，提供了一套包含系统性指标的跨领域部署清单，为该技术实际应用的研究与开发确立了规范框架。","scd":null,"kp":["应用前景[可充电金属-CO2电池]: 具有将电网级储能与利用丰富CO2气体相耦合的潜力"]},{"i":34908,"as":"钾离子电池内部界面层的不稳定会加速性能衰减。研究在电池内部通过聚合反应原位形成一层化学锚定的弹性保护膜。该膜能有效缓冲电极的剧烈膨胀，并提供快速离子传输通道，解决了结构稳定性和传输效率之间的冲突。测试表明该电池寿命显著延长，甚至在-40°C极端低温下也能稳定运行。","scd":null,"kp":["保护膜[钾离子电池]: 原位生成化学锚定的弹性保护膜","制备工艺[弹性保护膜]: 电池内部的原位聚合","功能特性[弹性保护膜]: 缓冲剧烈的电极膨胀并同时提供快速离子传输路径","技术结论[原位聚合物接枝界面层]: 有效解决了结构稳定性和传输效率之间的冲突"]},{"i":34909,"as":"漂浮光伏（FPV）系统自2015年发展迅速，至2024年装机容量超9.6 GWp。评估显示，利用10%的内陆和专属经济区海域可分别产生22 TWp和718 TWp以上的发电潜力。目前FPV资本支出降至1.25美元/Wp，尽管平准化电力成本高于陆地光伏，但具有节水、协同水电及减少土地冲突等附加效益。","scd":null,"kp":["装机容量[漂浮式光伏系统]: 9.6 GWp以上(截至2024年)","发电潜力[内陆水域(覆盖10%)]: 22 TWp以上","发电潜力[专属经济区离岸海域(覆盖10%)]: 718 TWp以上"]},{"i":34910,"as":"","scd":null,"kp":[]},{"i":34911,"as":"","scd":null,"kp":[]},{"i":34912,"as":"","scd":null,"kp":[]},{"i":34913,"as":"","scd":null,"kp":[]},{"i":34914,"as":"","scd":null,"kp":[]},{"i":34915,"as":"","scd":null,"kp":[]},{"i":34916,"as":"综述提出了一种用于定制多功能离子凝胶电解质的“结构-性质-功能”统一框架。该电解质结合离子液体与聚合物网络，具有高导电性和机械适应性。该框架明确了解决离子传输和界面限制的设计策略，为开发适用于可穿戴电子设备的坚固且可自愈的离子凝胶电解质提供指导。","scd":null,"kp":["电解质特性[离子凝胶电解质]: 结合离子液体与聚合物网络提供高电导率和机械适应性","电解质特性[自愈性和稳健性离子凝胶]: 克服离子传输和界面限制"]},{"i":34917,"as":"","scd":null,"kp":[]},{"i":34918,"as":"研发出一种干燥的多电极阵列技术，能够对具有高曲率组织的植物内部传导的电信号进行有效的可视化观察。","scd":null,"kp":["电极阵列[植物高曲率组织电信号可视化]: 干式多电极阵列"]},{"i":34919,"as":"研发出一种低漂移电极阵列，用于可视化植物中受环境刺激的电信号。该阵列由MXene和压敏粘合剂制成的干燥导电复合材料构成，放置于金/铬/聚二甲基硅氧烷薄膜上。结合生物电子模型优化电极配置，克服了传统植物生物电子接口空间分辨率低和信号漂移的限制，实现了对植物电活动的时空可视化监测。","scd":null,"kp":["电极阵列[环境刺激下植物电信号高时空可视化]: 低漂移、高密度电极阵列"]},{"i":34920,"as":"提出一种结合机器学习与混合生物打印的策略，以实现毛细管尺度的分层血管网络制造。该策略整合了牺牲材料的高分辨率气溶胶喷射打印和组织基质的高通量挤出打印，达到低于10微米的分辨率，并能实时按需调节血管直径。利用约束贝叶斯优化快速确定最佳打印参数，支持从一维导管到复杂结构的可靠制造。","scd":null,"kp":["打印分辨率[混合生物打印毛细血管网络]: 10 µm以下(亚10微米)","打印策略[毛细血管级生物打印]: 结合气溶胶喷射打印牺牲材料与挤出打印组织基质，并辅以机器学习"]},{"i":34921,"as":"提出一种半机械蜂群合作与博弈架构，通过基于情感的脑机接口（BMI）实现闭环控制。该系统利用小鼠的内在情感状态（恐惧）作为触发器来调节机器人群策略。通过轻量级实时无线BMI记录小鼠基底外侧杏仁核的局部场电位（LFP），采用双阈值解码算法，在自由移动状态下实现稳健的情感解码与机械协同。","scd":null,"kp":["控制系统[赛博群体协作]: 利用动物内在情绪状态（恐惧）作为高级触发器的闭环架构"]},{"i":34922,"as":"将编织技术重新定义为一种设计具有可编程力学特性的三维缠结固体的通用策略。研究利用对线圈结构的精确几何描述和多材料3D打印技术，构建了平面和体积针织结构。这些结构的线圈参数能够直接控制其刚度和强度，利用拓扑结构中的密集互锁和滑动接触，实现了超越传统材料成分的非凡物理性能。","scd":null,"kp":["结构力学[3D打印针织物]: 利用拓扑缠结和滑动接触实现超常的物理行为"]},{"i":34923,"as":"","scd":null,"kp":[]},{"i":34924,"as":"基于长期实验数据，揭示了多植物 farming 中土壤处理与天气变化对生物量生产的影响可以解耦。土壤处理的选择不仅改变多植物系统的平均产量（回报），还改变其对天气变化的敏感性（风险）。研究结果证实了多物种种植系统在应对农业风险与收益平衡方面的潜力，为替代脆弱的单一种植模式提供了科学依据。","scd":null,"kp":["农业生态[多植物混作系统]: 相较于单作模式，可通过风险-收益平衡来响应土壤处理和天气变化"]},{"i":34925,"as":"","scd":null,"kp":[]},{"i":34926,"as":"开发了一个基于限制的尺度框架，统一描述多孔材料中对流热传输的物理机制。该框架通过尺度比视角，将多孔介质中的经典对流与侧向受限的瑞利-贝纳德系统定量联系起来。针对随机多孔和裂隙介质，模型恢复了有效限制机制，成功描述了从粘性基质主导的对流过渡到受惯性影响及最终类似 bulk fluid 的羽流对流状态。","scd":null,"kp":["流动状态转变[多孔材料内部对流]: 通过动态限制控制的统一尺度框架，实现从孔隙对流到自由对流的转变"]},{"i":34927,"as":"","scd":null,"kp":[]},{"i":34928,"as":"","scd":null,"kp":[]},{"i":34929,"as":"评估了大语言模型（如ChatGPT）在定量社会科学研究可重复性评估中的协作效果。288名研究人员被分配至纯人工、AI辅助和AI主导团队中执行复现任务。结果显示，AI辅助团队的表现优于AI主导团队，但仍未能超越纯人类团队，表明AI在辅助科研验证时仍具有一定的局限性，完全依赖AI并不能达到最高准确率。","scd":null,"kp":["AI团队表现[定量社会科学可重复性评估]: AI辅助团队优于AI主导团队，但未超越纯人工团队"]},{"i":34930,"as":"开发了名为FIELD的框架，构建了涵盖美国本土的牲畜、野鸟和人类生态系统的高分辨率时空网格数字模型。该框架利用统计和优化技术融合多源多尺度数据，包含农场级别的牲畜生产、人口和野鸟分布。该数字模型为解决高致病性禽流感等“同一健康”问题提供了强有力的工具，支持对多宿主流行病传播的复杂交互进行深度建模分析。","scd":null,"kp":["[高致病性禽流感等One Health问题建模]: 开发构建包含牲畜生产加工、人类等实体交互的逼真时空网格化数字孪生方法"]},{"i":34931,"as":"","scd":null,"kp":[]},{"i":34932,"as":"通过控制大气暴露实验证实，碳质小行星“龙宫”样本颗粒在抵达地球后数周至数月内即发生明显的地球风化。磁黄铁矿因氧化和失硫形成富铁氧非晶边缘，相邻层状硅酸盐非晶化，碳质物质形成纳米气泡。根据磁黄铁矿蚀变边缘的厚度，估算出了早期风化速率，强调了地外物质样本需防范早期地球环境改变的必要性。","scd":null,"kp":["[地球风化与氧化作用]: 磁黄铁矿形成富铁氧非晶边缘并伴随失硫，相邻层状硅酸盐非晶化","地球风化时间[Ryugu颗粒暴露于大气环境]: 几周至几个月内发生可测量的陆地风化"]},{"i":34933,"as":"利用多模式集合模型评估了全球洪水时间的变化。研究表明，人为气候变化导致全球洪水时间提前，每升温0.5°C提前0.43±0.25天，且存在区域差异。在1.5°C升温下，50.73%的陆地面临超过7天的洪峰时间偏移，2.0°C时增至52.85%。中国、印度和美国等国家将受到显著影响，极大地打乱了灾害准备机制。","scd":null,"kp":[]},{"i":34934,"as":"","scd":null,"kp":[]},{"i":34935,"as":"","scd":null,"kp":[]},{"i":34936,"as":"整合了2003至2021年间北极和南大洋超6000次箱室法空气-冰层CO2通量测量数据。数据表明，海冰在冬季释放CO2，在夏季吸收CO2。年均通量显示，北极和南大洋海冰分别是+4 Tg C/年和+2 Tg C/年的微小净碳源。这挑战了以往认为海冰是巨大碳汇的观点，证实海冰在极寒冷的冬季也能进行气体交换。","scd":null,"kp":[]},{"i":34937,"as":"基于17个河流三角洲的1600多个土壤样本，编制了北极三角洲碳和氮储量清单。估算显示，面积近10万平方公里的北极三角洲沉积物储存了57.5 Pg碳和3.8 Pg氮。在气候变化引起海平面上升、冻土融化等背景下，这些土壤碳和氮的生物利用度正在增加，代表了具有极高潜在脆弱性的大型生物地球化学储库。","scd":null,"kp":[]},{"i":34938,"as":"在异常点运行的电子电路可用于制造强大的传感器，但相关挑战（特别是与噪声相关的挑战）仍有待解决。","scd":null,"kp":["[异常点运行的电子电路]: 具备开发强力传感器的潜力，但存在噪声等相关挑战待解决"]},{"i":34939,"as":"研究调查了2010至2020年间全球4116个城市的可持续发展目标（SDG）相互作用，并模拟了孤立与协作等五种交互场景。结果表明，其他城市在颗粒物、气态污染物和温室气体等指标上改善10%，能够有效提升相关城市的可持续发展表现。","scd":null,"kp":[]},{"i":34940,"as":"国际海事组织（IMO）净零框架通过定价机制和燃料标准推广低气候影响的海运燃料。政策制定必须考虑全生命周期视角，以避免环境影响向燃料供应链转移，并解决包括土地利用和矿产资源枯竭在内的广泛环境问题。","scd":null,"kp":["[IMO净零框架]: 结合定价机制与燃料标准，促进低气候影响船用燃料的采用","[全球航运气候政策]: 必须考虑生命周期视角，避免影响转移至燃料供应链并解决土地和矿产资源枯竭等环境问题"]},{"i":34941,"as":"有机光敏剂因其可调的分子结构和多变的激发态动力学，在光化学和光生物学过程中发挥核心作用。其机制分为依赖氧的II型、低依赖氧的I型和不依赖氧的新兴路径。为提升光敏效率，已开发出多种分子设计策略，并通过引入机器学习作为数据驱动的预测框架，以弥补对结构与性质关系理解的不足，加速候选材料的筛选。","scd":null,"kp":["[有机光敏剂分子设计]: 基于可调分子结构和激发态动力学，分为依赖氧气的II型、较少依赖氧气的I型及不依赖氧气的新兴路径"]},{"i":34942,"as":"研究开发了一种原子级精确的Cu4Pt2(C≡CCyOH)8团簇作为电催化剂用于甲苯氧化，实现了大于99%的法拉第效率和生成苯甲醛的绝对选择性。该催化剂整合了三个协同功能模块：簇的羟基配体捕获水并释放至Cu位点，水在Cu位点被激活形成OH自由基；Pt位点负责抽取甲苯甲基上的氢原子；随后OH自由基进行后续反应。","scd":null,"kp":["苯甲醛选择性[Cu4Pt2(C≡CCyOH)8原子级精确团簇电催化甲苯氧化]: 100%","法拉第效率[Cu4Pt2(C≡CCyOH)8原子级精确团簇电催化甲苯氧化]: >99%","[多模块协同催化]: 单一团簇催化剂集成三个功能模块协同断裂和重组C(sp3)-H键"]},{"i":34943,"as":"光学共振腔结构产生高度非均匀的光场分布，利用不对称的电子和空穴扩散率驱动微纳尺度的光生电荷高效分离。飞秒到秒级的时空成像显示，超快热电子扩散（约3皮秒）和长寿命的陷阱限制传输（约5毫秒）共同促成了电荷分离。利用该机制可有效提升光电和光催化转换效率。","scd":null,"kp":["[光生电荷分离机制]: 光学共振腔结构产生高度非均匀光场分布驱动微纳尺度的高效电荷分离"]},{"i":34944,"as":"全球变暖背景下，地球表面入射太阳辐射（DSSR）呈现显著的经向对比：极地变暗和北半球中纬度变亮。在高排放情景下，北极和南极高纬度地区DSSR季节周期分别减弱14.6%和7.0%，而北半球中纬度地区则略微增强2.1%。云层减少是导致北半球中纬度变亮的重要因素。","scd":null,"kp":["[全球变暖下地表太阳辐射(DSSR)变化]: 呈现明显的未来经向对比特征，即极地变暗与北半球中纬度变亮","[DSSR季节周期特征]: 变亮与变暗对比在夏季达到峰值，削弱了高纬度地区DSSR的季节周期"]},{"i":34945,"as":"","scd":null,"kp":[]},{"i":34946,"as":"研究提出了一种温和、高效的协议，通过双功能硅烷试剂将脂肪族酮转化为酮类自由基。该方法利用独特的自由基转移策略，避开了传统的强还原条件，成功将酮类自由基生成与过渡金属催化结合，实现了羰基碳上高价值碳碳键的形成。","scd":null,"kp":["[温和条件下的酮转化]: 避开强还原条件/试剂，将常见脂肪族酮转化为酮类自由基，实现与过渡金属催化氧化还原中性酮-烯烃偶联"]},{"i":34947,"as":"研究设计了配对的镍原子中心和Ni2-Fe双中心催化剂，以调控析氧反应（OER）路径。两种催化剂均具有Ni2(N/O)6部分，通过在Fe-O4配位中引入相邻的铁原子，产生空间位阻和电子效应，成功在Ni位点激活了氧化物路径机制（OPM），实现了高效的析氧反应。","scd":null,"kp":["[析氧反应机制(OER)]: 通过Fe单原子赋能的Ni双位点激活氧化物路径机制(OPM)以满足*O─*O自由基偶联的几何和电子要求"]},{"i":34948,"as":"研究提出一种由B-N-B键桥接的扭曲混合四硼化多共振热活化延迟荧光（MR-TADF）发射体。B-N-B基团的对称吸电子特性增强了原子级轨道分离，使材料实现了低于10纳米的超窄半峰宽（FWHM）发射，同时结合了快速的反向系间窜越（RISC）特性，显著提升了OLED性能。","scd":null,"kp":["半峰宽(FWHM)[MR-TADF发射器]: <10 nm","发射器分子结构[MR-TADF发射器]: B─N─B键桥连的扭曲混合四硼酸化结构","逆向系间窜越(RISC)[MR-TADF发射器]: 快速"]},{"i":34949,"as":"研究人员开发出一种完全不含金属元素的卤化物水系电池。该电池由还原氧化石墨烯正极、基于紫精的有机负极以及双卤化物水凝胶电解质组成。通过将具有不同季铵阳离子的溴化物和氯化物结合在黄原胶基质中，构建了限制性离子环境，有效稳定了活性多卤化物中间体，推进了可持续储能技术的发展。","scd":null,"kp":["电池组成[卤素离子水系电池]: 完全无金属元素（含还原氧化石墨烯等）","电解质[卤素离子水系电池]: 双卤素调控水凝胶电解质"]},{"i":34950,"as":"为解决热电设备中接触面积效应引起的信号模糊问题，研究开发了一种双模态双层电子皮肤。底层基于单壁碳纳米管的热电层作为快速响应伤害感受器，将温度梯度转化为电压编码的“疼痛”信号；顶层基于聚集诱导发光发光体的光致发光层提供独立于接触面积的光学映射，实现同时进行疼痛感知和损伤映射。","scd":null,"kp":["感知解耦机制[双模态热电/AIE电子皮肤]: 解耦接触面积模糊性（同时实现痛觉感知与损伤映射）","材料组成[双模态电子皮肤]: 集成单壁碳纳米管的双层结构"]},{"i":34951,"as":"研究开发了一种软体导电表皮电极，通过定制T形和U形指状结构并调节粘性，解决了稳定贴附与无损撕除的矛盾。从U形剥至T形时，电极与皮肤发生协同形变，增强粘附力以获取高保真信号；反向剥离时，U形指失效，实现电极的轻松、无创脱离。","scd":null,"kp":["粘附特性[表皮电极]: 结合稳定粘附（高保真信号采集）与可切换弱粘附（无损伤移除）"]},{"i":34952,"as":"针对钙钛矿太阳能电池由于低表面能（100）晶面过度生长导致难以控制晶体取向的问题，研究提出一种干扰结晶策略。通过在碘化铅前驱体中加入磺酸盐添加剂，对FA+插入产生依赖晶面的动力学扰动。该添加剂优先吸附在（100）表面限制A位点生长，从而重塑晶面竞争，显著提升器件的效率和稳定性。","scd":null,"kp":["结晶控制策略[钙钛矿太阳能电池]: 干扰结晶（通过调节A位插层动力学重塑晶面竞争）","添加剂类型[钙钛矿太阳能电池]: 磺酸盐基添加剂"]},{"i":34953,"as":"研究通过分子工程策略，合理设计含有磷/氮和具有π-π相互作用的联苯作为硬段，开发出高强度、坚韧、阻燃且可自愈的聚氨酯弹性体。分子间较强的π-π堆叠作用使弹性体具备卓越的机械性能和自愈能力，同时解决了阻燃性等性能难以兼顾的挑战。","scd":null,"kp":["材料性能[聚氨酯弹性体]: 高强度、高韧性、阻燃且自修复","分子设计策略[聚氨酯弹性体]: 引入含磷/氮和联苯链段"]},{"i":34954,"as":"研究提出一种时空控制策略，利用界面刻蚀驱动的反应扩散，在三维纳米多孔金属化合物上制备出多尺度图灵图案合金。这些合金具有小于2纳米的条纹宽度，涵盖二元到高熵成分，克服了传统合金在条纹宽度和成分上的限制。其可调的跨尺度结构有效促进了可持续能量转换系统中的催化反应。","scd":null,"kp":["合成策略[高熵合金]: 时空控制（界面刻蚀驱动的反应扩散）","材料微观形貌[高熵合金]: 多尺度图灵图案全亚纳米合金"]},{"i":34955,"as":"研究开发了一种名为RMDR的膜定位荧光探针，可通过依赖极性的荧光寿命变化来报告细胞膜水合作用。RMDR在0%至1%的局部含水量范围内表现出明显的荧光寿命下降。利用该探针，成功可视化了低渗刺激下细胞膜水合作用的增加，并识别出从细胞外围到中心的时空梯度变化。","scd":null,"kp":["荧光探针[细胞膜水合作用检测]: RMDR（罗丹明衍生物膜深红探针，基于极性变化实现对微量水敏感检测）"]},{"i":34956,"as":"为解决断层体积3D打印（TVP）在窄光剂量窗口下固化不足的问题，研究提出一种肽自组装介导的聚合策略。将乙烯化自组装肽接枝到四臂聚乙二醇大分子单体上，其自组装诱导了乙烯基的纳米级空间限域效应，大幅缩小固化阈值，成功制造出具有高保真度且机械增强的水凝胶器件。","scd":null,"kp":["固化机制[光交联水凝胶]: 肽自组装介导聚合实现凝胶化后陡峭阈值固化","材料性能[体积3D打印水凝胶]: 机械增强且提升打印保真度与稳定性"]},{"i":34957,"as":"为实现宽温自供电X射线探测，研究制备了一种高熵无铅弛豫铁电陶瓷（BNBT-CHTT）。该材料通过高熵设计有效稳定了极性纳米微区，展现出优异的弛豫铁电特性。其在宽温域内表现出高灵敏度和高稳定性的X射线探测能力，满足了低剂量医疗诊断的需求。","scd":null,"kp":["工作温度范围[无铅弛豫铁电陶瓷]: 宽温域","探测器功能[X射线探测器]: 自供电探测","材料体系[X射线探测器]: 高熵无铅弛豫铁电陶瓷(0.85Bi0.47Na0.47Ba0.06TiO3基)"]},{"i":34958,"as":"研究使用可调节刚度的合成水凝胶作为限制空间，证明了在弹性材料中生长会以刚度依赖的方式降低铜绿假单胞菌（Pseudomonas aeruginosa）对抗生素的敏感性。这表明细菌在受到机械限制和局部高压应力时，会通过生理适应显著提高其对抗生素的耐受性。","scd":null,"kp":[]},{"i":34959,"as":"本研究提出一种基于复数空间的动物导航路径积分模型。研究指出，头部方向（HD）细胞提供方位参考系旋转，双侧脑干神经元控制运动幅度，内嗅-海马图中的左右交替theta波扫掠持续对这些双侧激活状态进行采样。方向改变时的参考系旋转映射为乘以单位复数，从而将自我中心的运动信息转换为导航向量，揭示了路径积分背后的神经生物学机制。","scd":null,"kp":[]},{"i":34960,"as":"本研究基于五项草地生物多样性实验的长期数据，量化了物种共存潜力（即生态位差异超过适合度差异的程度），并分析了其与生态系统生产力和稳定性之间的关系。结果表明，在共存、生产力与稳定性三者之间呈现出整体的正相关性。这统一了物种共存机制与生物多样性对生态系统功能影响的研究框架。","scd":null,"kp":[]},{"i":34961,"as":"巨型单细胞纤毛虫（Spirostomum）能在不到5毫秒内收缩至原体长的四分之一。研究量化了收缩过程中的皮层微管、膜皱褶和网状肌丝的变化，并开发了多尺度模型连接局部缩短与细胞变形。免疫荧光和电子显微镜证实，钙调蛋白和Sfi1同源物定位于肌丝中，粗粒度网格模拟成功重现了观察到的变形，揭示了这种超快钙触发收缩的生化机制。","scd":null,"kp":[]},{"i":34962,"as":"研究结合综合诱变、高内涵活细胞成像和自动定量分析，构建了人类α-微管蛋白TUBA1A所有2683个单核苷酸编码变异的完整功能图谱。微管组装的系统分析揭示了不同类别的突变会破坏蛋白质折叠、分子伴侣结合和原丝几何结构，界定了微管蛋白功能的结构约束。分子动力学模拟进一步揭示了局部结构动态，为重新解释疾病相关变异提供了功能依据。","scd":null,"kp":[]},{"i":34963,"as":"","scd":null,"kp":[]},{"i":34964,"as":"","scd":null,"kp":[]},{"i":34965,"as":"","scd":null,"kp":[]},{"i":34966,"as":"针对肝纤维化，本研究开发了一种结合CD163抗体和脂质纳米颗粒（LNP）的靶向治疗策略，递送编码针对成纤维细胞激活蛋白（FAP）的嵌合抗原受体巨噬细胞（CAR-M）mRNA。该原位CAR-M策略能够有效抑制激活的肝星状细胞（HSCs）的异常活性并调节肝脏免疫微环境，从而减轻细胞外基质异常积累，为肝纤维化的管理提供了新型治疗方法。","scd":null,"kp":["靶点[肝纤维化发病机制]: 活化肝星状细胞(HSCs)高表达的成纤维细胞激活蛋白(FAP)","递送策略[原位CAR-巨噬细胞]: mRNA负载的脂质纳米颗粒(LNP)"]},{"i":34967,"as":"在具有子空间测量的量子系统中，复现时间受Anandan-Aharonov相位支配并呈现分数化量子现象。本研究确立了相互作用多体自旋系统中复现时间的通用上限和下限，并探讨了接近这些极限的物理情景，揭示了在监测条件下量子过程的速度极限。研究结果表明，在特定情况下，复杂的多体系统可以被有效地映射以理解其动力学行为。","scd":null,"kp":["主导机制[带子空间测量的量子系统]: 回归时间受Anandan-Aharonov相支配并产生分数化量子回归时间","[相互作用量子系统中的分数化量子现象]: 建立了普适的上下界"]},{"i":34968,"as":"玻色峰是玻璃和非晶材料中相对于德拜模型多出的过剩振动状态，导致异常的热性质和力学特征。尽管等静态性和临界稳定性概念在解释堆积型玻璃的玻色峰方面得到了大量数据支持，但本研究指出，这些概念尚未在共价网络玻璃中得到证实。文章强调了理解共价网络玻璃中玻色峰机制的重要性和当前研究的局限性。","scd":null,"kp":["非晶态特征[共价网络玻璃]: 相对于德拜模型存在过剩振动状态(玻色峰)","[等静定性与临界稳定性]: 理解共价网络玻璃玻色峰的最具前景概念"]},{"i":34969,"as":"豆娘通过两种策略克服了光子玻璃中固有的无序性和颗粒尺寸多分散性导致的色彩饱和度低的问题，从而产生鲜艳且与角度无关的结构色。首先，透明蝶啶纳米球掺杂黄色色素增强了蓝绿光的反射；其次，通过调节折射率。这一生物学光操纵机制为设计可持续、高性能的非虹彩结构色光子材料提供了新思路。","scd":null,"kp":["光子结构色生成策略[豆娘克服光子玻璃颜色饱和障碍]: 色素负载与折射率调制"]},{"i":34970,"as":"","scd":null,"kp":[]},{"i":34971,"as":"","scd":null,"kp":[]},{"i":34972,"as":"通过分析四大出版商在2020至2025年间发表的730万篇学术期刊全文，研究发现大语言模型（LLM）在学术文章中的普及率迅速上升。具有LLM特征的高频词汇语料库分析显示，受LLM影响的文章比例从2023年的12%激增至2025年的57%。这些受影响文章在文本特征上存在显著异异性，揭示了不同社会和机构背景下的LLM应用现状。","scd":null,"kp":["分析样本量[大语言模型在学术文章中的扩散追踪]: 730万篇期刊文章","文献时间跨度[2020-2025年四大学术出版商发表的大语言模型关联语言分析]: 2020–2025","特征词集[LLM高频突变词汇语料库]: 228个焦点词"]},{"i":34973,"as":"","scd":null,"kp":[]},{"i":34974,"as":"研究表明，甲磺酸（MSA）在主导全球主要海洋的对流层上层新粒子形成（NPF）中发挥关键作用。量子化学和团簇动力学模拟揭示，MSA能将硫酸-氨的成核速率提高1到3个数量级。这一发现挑战了MSA仅作为边界层关键前体的传统认知，阐明了海洋对流层上层维持巨大气溶胶库的机制，大幅降低了气候预测中的不确定性。","scd":null,"kp":["主导前体物质[海洋对流层上部新粒子形成(NPF)]: 甲磺酸(MSA)"]},{"i":34975,"as":"在连续波激光激发下，铁磁流体展现出振荡和双稳态旋转的动态行为。马兰戈尼不稳定性引起的局部激光加热使单个尖峰消失或像钟摆一样振荡。存在两个或多个尖峰时，图案会根据激光位置进行稳定的顺时针或逆时针自发旋转，气流吹拂或轻微拖动可反转旋转方向。这些现象源于热磁动力学中的对称性破缺。","scd":null,"kp":["触发因素[连续波激光激发下的铁流体]: 马兰戈尼不稳定性引起的局部激光加热","动力学特征[激光照射下的热磁动力学]: 振荡、自发旋转和流动双稳态"]},{"i":34976,"as":"","scd":null,"kp":[]},{"i":34977,"as":"糖尿病动脉粥样硬化与内皮-间质转化密切相关。研究发现，糖尿病患者颈动脉斑块和糖尿病小鼠主动脉内皮中由EZH2介导的H3K27三甲基化水平升高。使用GSK-126进行药理学抑制EZH2，可有效减轻EndMT并降低糖尿病小鼠的动脉粥样硬化负荷。该研究揭示了表观遗传调控在血管病变中的作用，并为治疗提供了新的靶向策略。","scd":null,"kp":["表观遗传机制[糖尿病颈动脉斑块中的内皮-间质转化(EndMT)]: EZH2介导的H3K27三甲基化水平升高","药理干预[GSK-126缓解EndMT与动脉粥样硬化]: EZH2抑制剂GSK-126"]},{"i":34978,"as":"本研究通过在钼-锰双原子位点上调控一氧化氮（NO）中间体的行为，实现了高选择性的电化学尿素合成。高NO表面覆盖率和强结合能促进了NO二聚化路径形成N-N键，随后高效插入一氧化碳（CO）形成尿素。该方法成功抑制了竞争性氨生成，实现了93.3%的尿素氮选择性，产率高达每毫克催化剂35.16毫摩尔。","scd":null,"kp":["电催化合成[CO2与NO3-电化学合成尿素]: 调控一氧化氮(NO)中间体行为以促进直接C-N偶联","催化剂材料[高选择性电化学合成尿素]: 钼-锰(Mo-Mn)催化剂"]},{"i":34979,"as":"为解决全球分布式医疗和研究公平性问题，本研究团队在北美、南美和亚洲推广了一种基于无细胞蛋白合成和开源硬件的低门槛分布式生物制造模式。该模式赋能资源匮乏地区的弱势群体就地、按时生产所需的分子诊断试剂和生物治疗药物，摆脱了对集中式制造和冷链物流的依赖，极大促进了全球生物经济的公平性和韧性。","scd":null,"kp":["技术范式[分布式无细胞蛋白质生物制造]: 摆脱集中式生物制造和冷链物流依赖的分布式模式"]},{"i":34980,"as":"本研究搭建了一个研究应变软化晶格中纯稀疏孤子的实验平台，深入揭示了孤子的碰撞特征。实验结果表明，对称和非对称碰撞均表现出弹性相互作用和依赖于振幅的相移。这些实验观察到的动力学行为加深了对机械超材料中非线性波动现象的理解，并为波导和能量收集应用的设计提供了关键依据。","scd":null,"kp":["[机械超材料]: 孤立波相互作用受能量耗散和高精度测量需求限制尚未完全明了","[稀疏孤立波]: 用于揭示应变软化介质中的非线性波动力学特性","[应用场景]: 波导和能量收集"]},{"i":34981,"as":"研究开发了一种利用肾脏可清除的谷胱甘肽-金纳米团簇（GSH-Au NCs）进行对比剂节省的CT成像方法，用于早期肾脏功能障碍的空间映射。GSH-Au NCs凭借2.8纳米的超小流体动力学尺寸和高X射线衰减能力，实现了快速肾脏清除和稳健的肾内CT对比。在三种机制不同的小鼠急性肾损伤模型中，低剂量GSH-Au NCs在生物标志物变化之前即可产生特定机制的成像特征。","scd":null,"kp":["流体力学尺寸[肾可清除谷胱甘肽-金纳米簇]: 2.8纳米","[CT造影方法]: 利用肾可清除金纳米簇在腔室水平空间映射肾功能以减少造影剂用量"]},{"i":34982,"as":"","scd":null,"kp":[]},{"i":34983,"as":"研究团队在一项为期一年的实验中，追踪了20个堆肥衍生的微生物群落中的病毒动态。研究发现这些群落形成了由不同纤维素降解菌主导的两种稳定类型。在其中一种群落中，观察到一种名为Theomophage的未被表征病毒发生了大规模的爆发，其占比最高达到宏基因组测序片段的74%，创下了目前最大的噬菌体爆发记录。在爆发期间及随时间推移，该病毒展现出显著的遗传稳定性，而病毒群落的迁移则产生了相反的作用。","scd":null,"kp":["[堆肥衍生微生物群落]: 分为由不同纤维素降解菌主导的两种替代稳定类型","[噬菌体动态]: 观察到Theomphage大规模并行爆发"]},{"i":34984,"as":"研究设计了一种针对淋巴结递送的亲水性修饰DNA佐剂（AMP-DNA）。该佐剂能够增强对TANK结合激酶1（TBK1）危险信号通路的刺激，从而激发强烈的适应性免疫和长期记忆。在实验中，AMP-DNA佐剂在小鼠和非人灵长类动物的淋巴结内引发了由I型干扰素（IFN-I）主导的炎症环境，促使多功能细胞显著增加细胞因子分泌，诱导出强效且持久的体液和细胞免疫反应。","scd":null,"kp":["[佐剂类型]: 亲水性修饰的免疫刺激性DNA佐剂","[作用靶点]: 靶向淋巴结递送并增强TANK结合激酶1(TBK1)介导的危险感知通路"]},{"i":34985,"as":"本研究结合实验与分子动力学模拟，揭示了水对基于双三氟甲磺酰亚胺([TFSI]-)的钠盐离子液体电解质的纳米结构和电化学性能的影响。干燥的钠盐离子液体表现出偏离经典静电学的长程排斥力。加入水后，会减小离子簇尺寸并降低其有序性，使力学分布更接近纯离子液体。原子力显微镜显示，水引起了带负电表面附近的离子簇重组。含水体系表现出电容增加，且电容曲线由驼峰状转变为钟形。","scd":null,"kp":["电解液体系[钠电池]: 盐在离子液体中且含双三氟甲磺酰亚胺([TFSI]−)","[干燥钠-盐在离子液体]: 表现出偏离经典静电学的长程排斥力，受纳米级离子聚集体的表面诱导聚集影响"]},{"i":34986,"as":"针对丙型肝炎病毒（HCV）缺乏有效体内模型的难题，研究利用移植了原代人肝细胞的Fah-/-/Rag2-/-/Il2rg-/- (FRG)和uPA-SCID人源化肝脏嵌合体小鼠模型，研究了HCV的感染动态。该嵌合小鼠模型支持来自多种HCV源的高水平病毒血症，可用于抗病毒药物测试和疫苗开发。研究进一步利用该模型评估了脂质纳米颗粒（LNP）介导的递送系统在HCV研究中的效果。","scd":null,"kp":["人源化肝脏嵌合体小鼠模型[丙肝病毒研究]: Fah−/−/Rag2−/−/Il2rg−/−基因型","[模型特征]: 支持多种HCV来源的高水平病毒血症且适用于抗病毒测试，但缺乏免疫系统"]},{"i":34987,"as":"钻辉无球粒陨石是太阳系中已知最干燥的行星物质。研究测量了八块该陨石的高精度质量无关铬同位素（ε54Cr）数据。来自母体深部的样本ε54Cr值一致，代表了地幔成分；而淬火陨石基质的ε54Cr值出现异常，反映了撞击体污染。结合铬氧同位素数据，研究得出结论：一个类似Ivuna的富含挥发物的撞击体撞击了钻辉陨石母体（APB），这一“湿撞干”事件导致了母体内部挥发分的丢失。","scd":null,"kp":["[无球粒陨石母体]: 已知太阳系中最干燥的行星物质","同位素分析[铬同位素(ε54Cr)]: 高精度质量无关数据用于鉴定深度不同的APB区域样本及撞击体身份"]},{"i":34988,"as":"研究展示了一种双功能声光换能器的实验成果，实现了同时进行水下加密通信和距离测量。该换能器能将水下声信号高效转化为单光子，通过光纤传输距离可达50公里。在实现长距离通信的同时，该设备还成功完成了亚波长级别的距离测量。这一技术有效解决了水下环境中跨越不同信息载体的转换问题，为下一代空海地一体化网络中的水下设备集成提供了新途径。","scd":null,"kp":["[水下双功能声光换能器]: 统一了水下环境中传感和加密通信功能并实现亚波长测距"]},{"i":34989,"as":"研究提出了一种极紫外（XUV）时空光谱相位调制器。该装置基于强XUV激光束穿透光学厚度共振靶产生，通过在垂直和平行于激光传播方向上引起共振附近的色散分布变化进行调制。实验表明，产生的偶极辐射在远场中经历了光谱重塑，且发散度高于原始光束。通过强XUV诱导，在远场光谱中成功获得了双峰离轴结构，实现了对极紫外辐射方向的重定向和光谱重塑。","scd":null,"kp":["[极紫外(XUV)空间光谱相位调制器]: 基于强XUV激光束穿透光学厚共振靶，在共振附近引入垂直和平行于共振的色散分布变化"]},{"i":34990,"as":"研究结合成年斑马鱼的钙成像和闭环虚拟现实技术，揭示了小脑在回避学习中的作用机制。实验表明，斑马鱼以依赖小脑的方式学会将视觉线索与安全或危险关联。背部小脑的输出神经元和浦肯野细胞产生了线索选择性反应。输出神经元编码了效价状态，且以偏好危险的细胞居多；浦肯野细胞也表现出更强烈的危险偏好。线索逆转实验表明，小脑通过结构化的效价表征来支持适应性行为控制。","scd":null,"kp":["[小脑]: 形成代表安全和危险的内部结构化效价表征以支持适应性行为控制","研究方法[斑马鱼避障学习]: 结合钙成像和闭环虚拟现实"]},{"i":34991,"as":"本研究开发出高性能的Ω型栅极单晶In2O3场效应晶体管（Ω-SC In2O3 FETs）。该器件的平均场效应迁移率高达321.7 cm²/V·s，开关比超过10的9次方。为展示其在高端领域的应用潜力，研究基于该晶体管构建了无电容的两晶体管（2T0C）动态随机存取存储器（DRAM）单元。该研究成果大幅突破了氧化物的性能极限，为先进DRAM架构提供了高性能器件支撑。","scd":null,"kp":["[2T0C动态随机存取存储器]: 采用Ω形栅单晶In2O3场效应管(Ω-SC In2O3 FETs)实现无电容结构并突破氧化物电子器件性能极限"]},{"i":34992,"as":"研究通过高分辨率多世纪全球气候模拟发现，黑潮延伸区中尺度涡旋驱动的大气异常对太平洋年代际振荡（PDO）演变至关重要。在PDO冷相位期间，黑潮向北偏移产生的中尺度海表温度异常加强了侧向非绝热加热梯度，引起深层上升气流，冷却中层对流层并削弱北部斜压性。这一过程抑制了瞬态涡旋动量通量，证实了海洋中尺度涡旋在增强PDO可预测性中的关键作用。","scd":null,"kp":["[太平洋年代际振荡(PDO)机制]: 海洋中尺度涡流驱动的黑潮延伸区大气异常对PDO演变起关键反馈作用并增强其可预测性"]},{"i":34993,"as":"研究通过重新分析环状肉芽肿（GA）和皮肤类肉瘤病（cSAR）的单细胞RNA测序数据并进行体外验证，揭示了IFN-γ介导的巨噬细胞异常激活是疾病核心。氧化磷酸化（OXPHOS）是这些巨噬细胞的主要代谢途径。研究在细胞内鉴定了一个受电子传递链（ETC）抑制剂影响的IFN-γ诱导网络，其中鸟苷酸结合蛋白1（GBP1）在控制巨噬细胞激活中处于核心地位。抑制STAT1、ETC或GBP1成为潜在疗法。","scd":null,"kp":[]},{"i":34994,"as":"RNA解旋酶DHX36在抗病毒免疫反应中发挥调节开关的作用。在稳态条件下，DHX36抑制免疫激活；而在暴露于双链RNA时，DHX36活性降低，从而允许免疫激活。缺乏DHX36的细胞会进入持续激活的免疫状态，表现为RNA G-四联体结构积累、依赖蛋白激酶R（PKR）的应激颗粒形成，以及干扰素刺激基因表达水平升高。这些细胞对病毒RNA传感器表现出更强的响应能力。","scd":null,"kp":[]},{"i":34995,"as":"研究在锰基卤化物凝胶中设计了一个由压力触发的Förster共振能量转移（FRET）网络。该网络通过外部能量注入实现了异常的红光发射增强，其红光发光强度达到了环境绿光强度的355%。在压缩过程中，压力引起的基质刚性化隔离了锰-溴四面体，抑制了由d-d耦合引起的非辐射跃迁。凝胶基质产生的应变放大了FRET效率，从而在克服压力淬灭效应的同时实现了红光发射的增强。","scd":null,"kp":["[锰基金属卤化物凝胶]: 通过压力触发的FRET网络在克服压力淬灭效应下实现反常的红光发射增强"]},{"i":34996,"as":"研究测试了17,129个随机合成DNA序列和91,866个大肠杆菌基因组序列的启动子活性，评估了它们启动转录的倾向。结果显示，基因组DNA编码的启动子数量比随机DNA多约1.3倍，这一规律同样适用于基因内部区域。在进一步对非启动子序列进行超过50万个突变测试后，发现启动子从随机DNA序列中涌现的概率比从基因组DNA序列中高出约3倍。研究表明基因内部启动子具有被低估的作用。","scd":null,"kp":[]},{"i":34997,"as":"研究发现，血小板来源的细胞外囊泡（PEVs）能够有效修复子宫内膜损伤并改善小鼠的妊娠结局。宫内灌注后，PEVs凭借纳米级尺寸富集在受损子宫内膜的炎症部位。机制研究表明，PEVs激活巨噬细胞中的AMPK-ULK1通路，通过增强线粒体自噬来调节巨噬细胞表型，减少促炎因子的分泌。这一过程成功调节了子宫内膜的免疫微环境，展现出在治疗子宫内膜损伤导致的不孕症方面的临床应用潜力。","scd":null,"kp":[]},{"i":34998,"as":"研究通过分析425份血液样本的RNA测序数据，鉴定出一种女性特有的嵌合RNA：UBA1-CDK16，并在超过1200份血液样本中得到了验证。该嵌合RNA是通过两个相邻的X染色体连锁母基因UBA1和CDK16之间的顺式剪接形成的。尽管这两个基因在两性中均有表达，但女性特有的染色质环结构促成了连接位点处的剪接。这一进化过程中出现的嵌合RNA参与了特异性免疫调节过程。","scd":null,"kp":[]},{"i":34999,"as":"研究提出了一种具有全息激光输出的发光超表面系统。该系统由二元结构超表面与增益介质集成，能够在单个设备内实现相干光的产生和输出激光光束的精确整形。该系统克服了自发辐射低相干性限制和被动全息依赖外部光源的问题，不仅实现了光波生成，还完成了对远场辐射模式的定制，为高级光子学应用提供了一种紧凑、高度集成的光源控制解决方案。","scd":null,"kp":[]},{"i":35000,"as":"研究发现，敲除磷酸乙醇酸磷酸酶（PGP）可通过重塑代谢途径来抑制由脂质过氧化引起的铁死亡。同位素标记和代谢组学显示，PGP缺失触发了磷酸戊糖途径以及细胞能量和脂质代谢的改变，从而引发多因素抗氧化反应。然而，药理学尝试得出相反结论：最近报道的PGP抑制剂CP1实际上会产生强烈的铁死亡增敏作用。该研究利用基因和生物物理学方法揭示了靶向PGP在调节铁死亡中的复杂机制。","scd":null,"kp":[]},{"i":35001,"as":"研究确定RNA剪接因子SRSF3在调节调节性T细胞（Treg）命运和功能中起决定性作用。人类FOXP3基因存在两种异构体，其外显子2对Treg功能至关重要。机制上，SRSF3促进FOXP3外显子2的包含和蛋白质表达，从而保护Treg细胞。在Treg细胞中特异性敲除Srsf3基因会导致FOXP3表达失衡。这一发现明确了SRSF3在自身免疫和抗肿瘤免疫中维持Treg细胞稳态的关键机制。","scd":null,"kp":[]},{"i":35002,"as":"研究提出了一种基于纯度约束下测量不确定性的半设备无关量子随机数发生器（QRNG）协议，用于估计条件最小熵。该协议无需对二维源和可数维度测量设备进行详细建模，即可抵御针对测量设备的量子攻击。研究揭示了由纯度条件隐含产生的不确定性关系，通过测试状态定义了随机性参数C，并利用状态的幺正旋转对称性建立了该参数与可提取随机性分析界限之间的联系，保障了量子随机性的安全性。","scd":null,"kp":["[半设备无关量子随机数发生器]: 基于纯度约束下的测量不确定性进行条件最小熵估计，无需对2D源和可数维测量进行详细建模即可抵御量子侧信道攻击"]},{"i":35003,"as":"胆碱是维持细胞稳态的必需营养素。人类神经元中由高亲和性钠依赖性转运蛋白CHT1介导胆碱摄取以合成乙酰胆碱。研究鉴定并表征了一种与人类CHT1具有高序列相似性的细菌钠依赖性胆碱转运蛋白sfCHT。通过冷冻电镜解析其结合钠离子和胆碱的结构，揭示了sfCHT具有LeuT折叠架构及相关的钠离子配位机制。","scd":null,"kp":[]},{"i":35004,"as":"光热释电效应可通过重构和非易失性特征提升光电设备性能。研究调控了一种类陶瓷双轴分子铁电材料(N-甲基环己基铵)2PbCl4的光热释电特性。该材料表现出双轴铁电性（Aizu符号：4/mmmFmm2），克服了分子系统热释电性易衰退和抗疲劳性差的挑战，实现了可重构和非易失性的光热释电效应。","scd":null,"kp":["[类陶瓷双轴分子铁电体]: 通过极化工程成功实现具有重构性和非易失性的光热电效应"]},{"i":35005,"as":"针对创伤性脑损伤导致的脑缺损，研究设计了一种抗溶胀、可生物降解的黏附性水凝胶。该水凝胶通过硫辛酸和二甲双胍两种药物基于多氢键的超分子自组装形成，具有与原生脑组织匹配的机械和电学特性。在降解过程中，释放的硫辛酸重塑促再生微环境，二甲双胍促进内源性神经干细胞的自发募集，从而驱动内源性神经再生。","scd":null,"kp":["[可生物降解粘附水凝胶]: 通过硫辛酸和二甲双胍的多氢键超分子自组装实现抗溶胀特性，并重塑微环境以驱动内源性神经再生"]},{"i":35006,"as":"植物中S-亚硝基谷胱甘肽还原酶1（GSNOR1）突变会导致一氧化氮（NO）大量积累并削弱免疫。研究发现过量的NO会破坏细胞pH稳态，导致质外体酸化和细胞质碱化，干扰水杨酸（SA）在维管组织中的运输，致使植物无法响应叶面SA并丧失系统获得性抗性（SAR）。通过根部供应SA则可绕过这一限制。","scd":null,"kp":[]},{"i":35007,"as":"深地碳的运输取决于含碳相的稳定性。理论预测表明高压下可形成同时容纳硅和碳的矿物，但此前缺乏实验证据。研究证明，在40(2)吉帕斯卡和约1800(200)开尔文的极端条件下，二氧化碳能够与硅酸或方石英发生反应，形成无水硅酸盐Si[CO3]2。该化合物的结构由特定的[SiO6]和[CO3]单元构成。","scd":null,"kp":[]},{"i":35008,"as":"电催化硝酸根还原产氨的选择性偏低，限制了其实际应用。研究通过控制前驱体还原动力学，在二维银纳米三角片边缘选择性生长三维铜，精准合成出具有异相堆叠层错界面特征的银-铜维度结型Janus纳米晶体。该结构可串联电催化硝酸根还原为氨，组分与界面长度表现出明确的定量相关性。","scd":null,"kp":["[Ag-Cu维度结型Janus纳米晶体]: 具有异质堆垛层错界面，实现硝酸盐到氨的串联电催化还原"]},{"i":35009,"as":"受腹足类动物利用足部波输送界面流体的启发，研究开发了一种基于磁驱动预屈曲波动片的近边界泵送机制。理论模型验证了设计参数对流体输送性能的影响，并表明多个驱动单元间的时空相位优化可显著提升输运效果。基于此机制构建了用于平面和管道运输的微型器件，以及具备蜗牛样黏附爬行能力的微型软体机器人。","scd":null,"kp":[]},{"i":35010,"as":"为解决可拉伸生理电极因水和离子侵入界面而迅速失效的问题，研究开发了一种离子屏蔽超薄封装技术。该技术利用热压键合界面，通过单步热压排出截留空气并促使聚合物链相互扩散，消除界面缺陷。该封装厚度约10微米，在溶液中抵抗水和离子渗透的时间超过12个月，比未处理界面长10倍以上，实现了长期稳定的高保真电生理信号监测。","scd":null,"kp":["[可拉伸生物电子封装工艺]: 采用热压键合界面实现聚合物链互扩散，形成离子屏蔽超薄封装层以排空截留空气并消除界面缺陷"]},{"i":35011,"as":"受天然竹子径向梯度结构的启发，研究开发了具有径向梯度的BiO(Cl, Br)纳米片。该结构打破了BiOCl的 centro对称性，产生强压电效应，同时通过内置机械异质性放大了柔性电效应。在内置场、压电场和柔性电场三场协同作用下，BiO(Cl, Br)纳米片成功实现了高效的过氧化氢（H2O2）协同生产。","scd":null,"kp":["[压电催化材料]: 受竹子启发开发径向梯度的BiO(Cl, Br)纳米材料，通过柔性电效应打破非中心对称限制实现三场协同生产H2O2"]},{"i":35012,"as":"针对肿瘤细胞凋亡抵抗限制光动力和光热治疗疗效的问题，研究构建了一种铋基光热敏感纳米异质结。该纳米材料通过光热效应触发铁死亡和泛凋亡（PANoptosis），绕过传统的细胞凋亡耐药途径，引发强烈的抗肿瘤免疫反应。这解决了传统免疫原性细胞死亡诱导剂药代动力学不佳和剂量依赖性毒性的缺陷，有效改善了肿瘤免疫治疗。","scd":null,"kp":[]},{"i":35013,"as":"为了在机器人中实现类人触觉感知，研究受鱼鳞启发开发了一种巨型压电容传感器（GPCS）。该传感器的仿电场门控薄膜由镶嵌在弹性体基质中的高介电常数刚性鳞片和空气间隙组成，具有极高的体介电常数。这些空气间隙充当电场门，能够调节电极对之间的边缘电场，将微小的机械形变转化为显著的电容变化，兼具低检测限、快速响应和高可靠性。","scd":null,"kp":["[巨型压电容传感器]: 基于受鱼鳞启发的电场门控薄膜，具备高度机械顺应性，实现媲美人类触觉感知级别的感知能力"]},{"i":35014,"as":"二维多金属氧酸盐基金属有机框架在催化领域潜力巨大，但其定向合成与剥离极具挑战。研究采用极性导向策略，合理组装并合成出一种可剥离的2D POMOF材料（包含Co、特定有机配体及P2W15Ta3O等多金属氧酸盐簇）。该材料可作为无贵金属催化剂，有效催化炔烃的转移半氢化反应。","scd":null,"kp":["[炔烃转移半加氢反应]: 使用非贵金属催化剂","[二维多金属氧酸盐基金属有机框架]: 极性导向合成且可剥离"]},{"i":35015,"as":"为了提升有机非富勒烯太阳能电池（ONSCs）的光电转换效率，研究引入钙钛矿量子点作为掺杂剂。在平面异质结器件中，将FAPbI3量子点分别引入给体聚合物和受体分子层，实现了垂直掺杂的精确调控。该方法有效解决了高激子结合能和电荷传输受限的问题，成功制备出效率超过20.5%的ONSCs器件。","scd":null,"kp":["光电转换效率[有机非富勒烯太阳能电池]: >20.5%","[给体/受体掺杂调控]: 钙钛矿量子点","[器件结构]: 顺序沉积平面异质结"]},{"i":35016,"as":"","scd":null,"kp":[]},{"i":35017,"as":"为解决钾离子电池中传统酯类电解质导致石墨剥离和倍率性能差的问题，研究设计了一种偶极工程电解质。该电解质在钾离子脱溶剂化过程中形成瞬态极化空腔，产生局部负静电势以吸引钾离子，从而降低离子传输势垒。该机制显著提升了钾离子动力学，促进了稳定石墨负界的形成，实现了超快且稳定的钾离子电池储钾循环。","scd":null,"kp":["[钾离子电池石墨负极电解液]: 偶极工程化电解液形成瞬态极化空腔","[传统酯类电解液局限性]: 碳酸丙烯酯引起溶剂共插层导致石墨剥离"]},{"i":35018,"as":"电催化二氧化碳还原产甲烷受限于迟缓的加氢动力学。研究通过分子融合策略合成了富含半离子型碳氟键的富氟碳量子点，其氟含量高达28.8 at.%。半离子型碳氟键能够有效调控活性氢物种的动态行为，优化加氢过程。在流动池中，该催化剂的甲烷法拉第效率达到63.2%，分电流密度达到210.8 mA cm⁻²，展现出高选择性和高催化活性。","scd":null,"kp":["氟含量[F1-CQDs碳量子点]: 高达 unprecedented F content","[CO2电还原产物]: CH4","[合成策略]: 分子融合策略","[催化机制]: 半离子型C-F键调节氢动力学管理活性氢物种"]},{"i":35019,"as":"光学活性稠合氮杂环的高效合成具有重要药学价值。研究开发了一种不对称还原三组分环化反应，利用简单的手性磷酸/PhSiH3催化体系，将多种异喹啉盐与甲醛及N-烷基苯胺反应。该反应通过弱反应性氮杂芳环的加氢脱芳构化，成功构建了含有连续季碳和叔碳立体中心的稠合氮杂环，产物分离收率和对映选择性良好。","scd":null,"kp":["[稠合氮杂环构建]: 不对称还原性三组分环化反应","[产物立体化学特征]: 连续的季碳和叔碳立体中心","[反应底物特性]: 弱反应性氮杂芳烃的加氢脱芳化"]},{"i":35020,"as":"关于铋基电催化二氧化碳还原产甲酸的机制存在争议。研究结合恒电势从头算分子动力学（AIMD）模拟和光谱学证据，证实该反应由*COOH路径分叉决定，倾向于形成甲酸而不是一氧化碳。此外，还识别出一种替代性的*H介导路径。这推翻了传统认为仅由*OCHO中间体主导反应机制的认识。","scd":null,"kp":["[铋催化剂CO2电还原机理]: *COOH途径分叉决定HCOOH的形成","[反应中间体]: 碳结合的*COOH物种和氧结合的*OCHO物种"]},{"i":35021,"as":"","scd":null,"kp":[]},{"i":35022,"as":"[FeFe]-氢酶的成熟依赖于含有[4Fe-4S]簇的HydF成熟酶支架蛋白来组装和递送[2Fe]亚基。利用57Fe核共振振动光谱结合选择性同位素标记及蛋白质结构预测，研究证实[2Fe]亚基结合在[4Fe-4S]簇附近，两者之间并未形成共价氰化物桥连，但依然保持电子耦合状态。这阐明了HydF在催化成熟过程中的具体分子作用机制。","scd":null,"kp":["[[FeFe]-氢化酶成熟机制]: HydF引导的非共价[4Fe-4S]/[2Fe]界面","[HydF成熟酶功能]: 组装并递送H-簇的有机金属[2Fe]亚基"]},{"i":35023,"as":"一种光流体策略实现了游离醇的δ-C(sp3)-H羰基化内酯化。该转化过程通过光化学产生烷氧基自由基，发生选择性1,5-氢原子转移，捕获一氧化碳形成δ-酰基自由基，最终发生自由基-极性交叉实现分子内环化生成δ-内酯。使用强氧化性吖啶光催化剂是促进酰基自由基氧化的关键，从而区别于常规的质子耦合电子转移（PCET）机制。","scd":null,"kp":["[游离醇直接合成δ-内酯]: 光致δ-C(sp3)-H羰基化反应","[反应模式]: 连续流光化学策略","[反应机理]: 光化学产生烷氧自由基与1,5-氢原子转移"]},{"i":35024,"as":"受肌肉纤维排列启发，通过程序化冰晶生长技术开发出一种超可拉伸的芳纶摩擦电气凝胶。该气凝胶的取向拟合度达98%，比传统冷冻铸造方法高2.6倍。这种有序结构能在拉伸时分散应力，使气凝胶可承受高达539%的极限应变。基于该气凝胶的摩擦电传感阵列具备振动反馈功能，被应用于智能汽车座椅领域。","scd":null,"kp":["取向拟合度[摩擦纳米发电气凝胶]: 98%","[超可拉伸聚芳族酰胺摩擦电气凝胶]: 仿生肌肉纤维取向与程序化冰晶生长策略","[应用场景]: 智能汽车座椅柔性传感器"]},{"i":35025,"as":"一种水诱导增韧的水下黏合剂成功将水分子从黏合障碍转化为增强因素。该黏合剂包含亲水和疏水单元，使其在初始柔软状态下能够自适应贴合粗糙表面。此外，聚合物链之间的强相互作用通过水分子被原位激活，引发相分离并显著增强其力学性能，从而解决了传统水下黏合剂在界面黏合力与内聚力之间的权衡难题。","scd":null,"kp":["[水下粘附剂]: 水分子诱导的增韧型水下粘合材料","[技术突破]: 将水分子从界面粘附屏障转化为增强材料内聚强度的强化因素"]},{"i":35026,"as":"一种基于单一三明治式压电结构的高简化多模态应变传感器问世。其基于微裂纹的压阻层同时充当压电电极，通过阻抗域分离在共享电通道内实现解耦传感。压电输出直接反映应变速率，与压阻读取的应变幅值形成互补，从而实现动态与静态应变的集成测量。该架构有效解决了传统多模态设备结构复杂且易受串扰干扰的问题。","scd":null,"kp":["[多模态应变传感器]: 基于单一三明治型压电架构和微裂纹压阻层的极高简化设计"]},{"i":35027,"as":"受菖蒲叶脉结构启发，研究人员开发出一种具有极强抗疲劳性和环境稳定性的“共晶皮肤”。该材料由定向聚氨酯纤维网络嵌入疏水性共晶凝胶基质组成。其固有的疏水性有效抑制了水合作用，在100天内溶胀率低于1.1%，表现出极佳的尺寸稳定性。这种层级纤维强化的结构有效解决了传统水凝胶易吸水溶胀和界面失效的限制，适用于水陆两栖表皮电子设备。","scd":null,"kp":["仿生共晶皮肤材料[受力与潮湿环境]: 具有极端抗疲劳性和稳健的湿态粘附性"]},{"i":35028,"as":"","scd":null,"kp":[]},{"i":35029,"as":"","scd":null,"kp":[]},{"i":35030,"as":"金晶表面的六边形图案构成了一个不利于化学反应发生的环境。表面化学的这种特性解释了黄金能够长期保持光泽、不易发生反应的原因。","scd":null,"kp":["[金晶体表面化学反应]: 六方图案构型是不利于反应发生的环境"]},{"i":35031,"as":"","scd":null,"kp":[]},{"i":35032,"as":"","scd":null,"kp":[]},{"i":35033,"as":"","scd":null,"kp":[]},{"i":35034,"as":"","scd":null,"kp":[]},{"i":35035,"as":"","scd":null,"kp":[]},{"i":35036,"as":"","scd":null,"kp":[]},{"i":35037,"as":"","scd":null,"kp":[]},{"i":35038,"as":"","scd":null,"kp":[]},{"i":35039,"as":"","scd":null,"kp":[]},{"i":35040,"as":"蓝色起源公司的火箭发生爆炸事故，这一失败将直接推迟美国宇航局（NASA）的载人登月计划，从而影响美国与中国在月球表面探索的竞争进度。","scd":null,"kp":["[蓝色起源火箭爆炸]: 导致NASA载人登月任务可能面临延期"]},{"i":35041,"as":"","scd":null,"kp":[]},{"i":35042,"as":"研究人员利用聚合物接枝纳米晶体超晶格内的受限物理缠结，构建出可编程聚合物介孔膜。液-气界面自组装的二维超晶格作为结构模板，热处理激活聚合物缠结以稳定框架。去除纳米晶体核后，得到具有长程有序结构、自立且比模量极高的介孔膜，解决了结构有序性与机械稳定性难以兼顾的制造难题。","scd":null,"kp":["[聚合物介孔膜制造策略]: 利用纳米晶体超晶格内的受限物理纠缠实现结构有序与机械稳定"]},{"i":35043,"as":"","scd":null,"kp":[]},{"i":35044,"as":"","scd":null,"kp":[]},{"i":35045,"as":"","scd":null,"kp":[]},{"i":35046,"as":"","scd":null,"kp":[]},{"i":35047,"as":"","scd":null,"kp":[]},{"i":35048,"as":"","scd":null,"kp":[]},{"i":35049,"as":"","scd":null,"kp":[]},{"i":35050,"as":"一种自上而下的层叠冲压方法实现了微电池的高通量生产。结合无阳极初始设计与互穿的正极|电解质融合层，该工艺构建了坚固的界面以承受高速冲压产生的机械应力。生产速率高达每小时1800个，且产出的微电池在均匀性和电化学性能上表现优异，克服了传统自下而上组装法效率低和一致性差的缺陷。","scd":null,"kp":["[微电池制造工艺]: 采用自上而下的叠层冲压方法实现高通量生产"]},{"i":35051,"as":"RbAg4I5超离子导体展现出极佳的隔热性能。与传统缺乏此类晶体特征的SiO2隔热材料不同，单晶RbAg4I5在室温下的热导率极低，仅为130 mW m−1 K−1。此外，3.6%密度的多孔RbAg4I5表现出更卓越的隔热能力，确立了超离子导体作为高性能隔热材料的新范式。","scd":null,"kp":["[RbAg4I5超离子导体]: 具有高流动性带电离子和松散键合等晶体学特征从而实现优异的隔热性能"]},{"i":35052,"as":"","scd":null,"kp":[]},{"i":35053,"as":"","scd":null,"kp":[]},{"i":35054,"as":"在交织电荷密度波的超导体中观察到了超流效应。施加的面内磁场产生的迈斯纳电流能够调控前体电荷密度波（CDW）矢量处的Bogoliubov准粒子激发。扫描隧道光谱图像显示，磁场驱动了CDW调制的对称性破缺，具体表现为从C3v到Cs的相变。","scd":null,"kp":["[与电荷密度波交织的超导体]: 迈斯纳电流产生的超流效应可实现对准粒子色散的操控"]},{"i":35055,"as":"阿留申岛弧俯冲启动时间的地质年代学和地球化学数据分析表明，其俯冲始于至少5600万年前。早期前弧熔岩成分与西太平洋俯冲初期的前弧玄武岩相似。阿留申俯冲的启动及太平洋板块绝对运动的改变，是由Olyutorsky岛弧与堪察加-科里亚克边缘碰撞以及伊泽纳崎-太平洋海脊俯冲触发的。","scd":null,"kp":["阿留申岛弧俯冲起始时间[地质与地球化学数据约束]: ≥56百万年前"]},{"i":35056,"as":"低温电子显微镜制样过程存在瓶颈，cryoWriter作为一种无吸渍的微流控机器人，通过在受控环境中将纳升级样品以螺旋或直线图案书写到电镜网格上，解决了此问题。该技术仅需极少的样品体积即可制备高质量网格，已成功获得TMV、去铁铁蛋白和TRPM4的近原子分辨率三维重构，并支持通过二次点样增加颗粒密度或双线点样实现时间分辨的蛋白质-配体混合。","scd":null,"kp":["[CryoWriter冷冻电镜载网制备技术]: 无吸迹微流控机器人写入纳升级体积以实现高质量样品制备"]},{"i":35057,"as":"钙钛矿量子点具有优异的色纯度、可调带隙和高光致发光量子产率，是下一代发光二极管的理想发光材料。本综述重点关注材料合成、表面化学与器件工程之间的内在联系，系统总结了“合成-表面-器件”优化框架。核心要点包括抑制缺陷和增强稳定性的组分与表面工程，以及改善电荷平衡、辐射复合和光提取的器件级优化策略。","scd":null,"kp":["发光二极管[发射体]: 钙钛矿量子点(PQDs)"]},{"i":35058,"as":"为克服纳米纤维气凝胶的物理脆性，研究人员通过聚乙烯基倍半硅氧烷（PVSQ）在交联细菌纤维素（BC）网络上的原位气相聚合，开发出一种具有核壳结构并由硅氧烷键共价融合的混合气凝胶（BC-PVSQ）。该独特结构赋予气凝胶出色的机械韧性和适应性，包括超过99%的可压缩性和优异的抗弯曲能力，使其成为轻量化航空航天可展开系统中理想的热绝缘材料。","scd":null,"kp":["纳米纤维气凝胶[空间系统热绝缘]: 共价熔合的核壳结构纤维连接","气凝胶[纤维间结点]: 通过硅氧烷键融合","气凝胶[制备工艺]: 原位气相聚合"]},{"i":35059,"as":"硫化物电解质因具有高室温离子电导率在全固态锂电池中至关重要，但其界面不稳定性限制了高倍率性能。该研究提出一种分子级界面构建策略，利用高压二氧化碳对硫化锂磷锂（LPSC）表面进行原位工程化调控。通过浓二氧化碳的精确控制，有效改善了固态电池的界面不稳定性，从而提升了电池的整体高倍率储能性能。","scd":null,"kp":["硫化物固态电解质[室温离子电导率]: 高","界面工程[硫化物基全固态锂电池]: 高压CO2驱动的分子级界面工程"]},{"i":35060,"as":"钠金属负极具有1166 mAh/g的高理论容量和低氧化还原电位，但沉积不均导致的枝晶和界面不稳定性限制了其应用。研究通过在柔性铜集流体上原位电化学转化CuInS2，构建了一种坚固的三维胶状夹层。该夹层生成的Na2S/Na5InS4结构有效缓解了钠金属电池循环过程中的界面不稳定性和枝晶问题，实现了高容量柔性电池的稳定运行。","scd":null,"kp":["理论比容量[钠金属负极]: 1166 mAh g⁻¹","氧化还原电位[钠金属负极]: -2.71 V (vs. SHE)","钠金属电池[界面层]: 铟介导的胶状中间层"]},{"i":35061,"as":"针对传统塑料回收效率低和能耗高的问题，该研究提出了一种利用超声波振动冷加工技术将废塑料升级回收的新策略。该技术成功将废旧聚对苯二甲酸乙二醇酯（PET）转化为碳材料。这种环保高性能的冷制造方法不仅避免了传统工艺的过度能源需求，还将转化后的碳材料应用于高效海水蒸馏领域。","scd":null,"kp":["废塑料回收[处理工艺]: 超声波振动驱动的冷态升级回收"]},{"i":35062,"as":"水系锌电池受限于低能量密度和锌负极界面的电化学不稳定性。该研究开发了一种由氧化石墨烯纳米带（GONRs）组成的轨道杂化纳米种子（OHNS）界面，采用可扩展的狭缝涂布工艺沉积在铜集流体上，实现了无负极水系锌电池。纳米带丰富的碳边缘与锌发生轨道杂化，增强了锌成核动力学并抑制了表面扩散，使电池具备一分钟快充和高能量密度特性。","scd":null,"kp":["水系锌电池[充电时间]: 一分钟","锌电池[负极类型]: 无负极","中间相[锌电池界面]: 轨道杂化纳米种子(OHNS)","沉积层[OHNS组成]: 氧化石墨烯纳米带(GONRs)","镀层工艺[铜集流体]: 可扩展的狭缝涂布"]},{"i":35063,"as":"自组装共轭聚合物纳米纤维能够形成细长的渗透网络以促进电荷传输。该研究提出一个由分子相互作用主导的反溶剂诱导纳米纤维自组装框架，结合汉森溶解度参数和链段特异性亲和力描述符来预测溶剂-反溶剂组合。具有低烷基侧链亲和力的反溶剂促进了刚性细长纤维预聚物的形成，为共轭聚合物纳米纤维的绿色制造提供了通用策略。","scd":null,"kp":["自组装框架[共轭聚合物纳米纤维]: 反溶剂诱导的自组装","分子设计[纳米纤维生长]: 结合Hansen溶度参数"]},{"i":35064,"as":"弱溶剂化电解质是稳定锂金属负极的有效策略，但其分子设计缺乏统一标准。该研究建立了一个定量设计框架，将大量有机分子的结构基序和物理化学性质转化为控制锂离子溶剂化作用的描述符。通过多级化学信息筛选工作流，在庞大的化学空间中精准识别出数百种具有氧化还原稳定性的候选分子，为弱溶剂化电解质的高通量设计提供了数据驱动洞见。","scd":null,"kp":["弱溶剂化电解质[数据驱动设计]: 236875个有机分子结构 motifs 编码为6个可转移描述符"]},{"i":35065,"as":"原子级金属簇催化剂的反应活性高度依赖于载体。该研究利用机器学习势加速的多尺度模拟表明，二维载体二硫化钼的晶相决定了负载型Co8团簇的结构和电化学固氮性能。在金属性的1T-MoS2上，强金属-载体相互作用作为结构收敛器，将Co8团簇锁定为单一的优势结构，从而展现出区别于半导体相2H-MoS2的卓越电催化氮还原性能。","scd":null,"kp":["催化剂[电化学固氮]: 负载在MoS2上的Co8团簇","载体[催化性能调控]: 金属相1T与半导体相2H MoS2的晶相控制"]},{"i":35066,"as":"针对视觉惯性里程计系统中组件数据时空不一致导致性能下降的问题，该研究开发了一种基于FAPbI3钙钛矿量子点敏化二硫化钼异质结构的多模态传感器。该传感器集成了可重构的光电探测器和光突触功能，在单一器件内成功实现了视觉惯性系统的信息融合，为无人驾驶车辆和移动机器人提供连续且精确的高速运动追踪与定位监测。","scd":null,"kp":["多模态传感器[异质结构]: Pb-S强耦合异质结构","光吸收材料[视觉惯性传感器]: FAPbI3"]},{"i":35067,"as":"无负极钠金属电池去除了多余的金属钠负极，显著提升了能量密度并简化了制造工艺。本综述将理论可逆性作为统一标准，对钠损失途径进行分类，系统解析了在有限钠库存和固有不稳定界面化学双重限制下，活性钠不可逆损耗导致的容量衰减机制，为无负极钠金属电池的界面化学调控和实际应用提供了热力学与动力学理论支撑。","scd":null,"kp":["无负极钠金属电池[衰减机制]: 活性钠不可逆损耗","负极设计[制造简化]: 去除过量金属钠负极"]},{"i":35068,"as":"结构电池在承受机械载荷的同时储存能量，但面临界面阻抗高和循环稳定性差等挑战。该研究通过真空辅助树脂传递成型技术开发了一种刚性结构电池电解质。该设计利用多孔树脂骨架吸附液态电解液，在电极和隔膜中形成均匀的互连多孔通道，在保持高结构刚性和稳定固体电解质界面（SEI）的同时，极大促进了锂离子的高效传输。","scd":null,"kp":["结构电池电解质[骨架特征]: 多孔树脂骨架吸附液态电解质","结构电池电解质[性能提升]: 具有高离子传输效率的刚性特征","制备工艺[结构电池]: 真空辅助浸渍/成型工艺"]},{"i":35069,"as":"电池老化和突发故障引发的热失控是全球关注的安全焦点。本综述从多物理场耦合和多尺度失效机制解析了热失控的演化过程，强调了下一代电池系统化学特性的异质性。文章系统评估了本征安全材料与结构设计的成熟度，并重点论述了基于云端的电池管理系统在数据治理、云边协同监控以及系统级主动保护中的作用，将机器智能应用于电池安全管理。","scd":null,"kp":["失效机制[热失控诱因]: 电池老化与突发故障","安全机制[下一代电池]: 采用本质安全材料及多物理场/多尺度监测"]},{"i":35070,"as":"过渡金属氧化物的氧还原反应活性受限于低效的界面电荷转移。该研究报告了在共价有机聚合物（COP）与四氧化三铁（Fe3O4）纳米晶体杂化物中，由吡啶异构体驱动的界面自旋工程。使用二氨基吡啶异构体作为结构单元，构建了富含吡啶的COP来锚定Fe3O4，精确定制的分子吡啶环境有效编程了Fe3O4的电子和自旋结构，显著提升了催化性能。","scd":null,"kp":["催化剂[ORR界面调控]: 吡啶异构体驱动的界面自旋工程(COP-Fe3O4杂化物)","催化机制[电荷与表面调控]: 分子级吡啶环境调控电子结构以优化电荷转移与表面吸附"]},{"i":35071,"as":"亚单位疫苗免疫原性较弱，该研究开发了一种基于生物矿化技术的焦磷酸锰矿化DNA双佐剂亚单位疫苗平台。Mn/CpG双佐剂有效调节了Th1和Th2免疫反应的平衡。通过CpG激活TLR9信号通路以及锰离子介导cGAS-STING信号通路的协同作用，该疫苗引发了强大的抗原特异性细胞免疫，在体外和体内实验中均表现出远超商业铝佐剂的免疫增强效果。","scd":null,"kp":["纳米疫苗[佐剂平台]: 焦磷酸锰矿化DNA双佐剂平台","免疫响应[亚基疫苗]: 调节Th1与Th2免疫平衡并激发强效抗原特异性细胞免疫"]},{"i":35072,"as":"高熵氧化物因多组分“鸡尾酒效应”成为极具潜力的锂电池负极材料，但多组分系统的复杂性导致开发成本高。该研究提出一种以形成能和嵌锂体积变化为核心评价指标的分步元素筛选策略。基于文献数据统计和材料计算，成功开发出一种新型的零应变、高容量高熵氧化物负极材料，显著提升了锂离子电池的比容量、倍率性能和循环稳定性。","scd":null,"kp":["负极材料[LIBs]: 零应变、高容量高熵氧化物","筛选策略[高熵氧化物探索]: 逐步元素筛选法"]},{"i":35073,"as":"多硫化锂的穿梭效应、缓慢的反应动力学以及锂枝晶的生长限制了锂硫电池的性能。该研究报道了锚定在三维交联氮掺杂类石墨烯多孔碳纳米片上的单原子分散Fe-N4基团（Fe-N4-GCs）。作为硫宿主，Fe-N4-GCs提供丰富的吸附位点并高效催化多硫化锂转化；作为隔膜涂层，它们形成了均匀的锂离子传输通道，从而实现了低负正极容量比的稳定锂硫电池。","scd":null,"kp":["锂硫电池[低N/P比稳定运行]: 使用三维交联Fe-N4-GCs材料","催化与调控[多硫化锂]: 原子级分散的Fe-N4位点提供多硫化锂催化转化","负极保护[抑制锂枝晶]: Fe-N4-GCs作为锂调节剂抵抗枝晶生长"]},{"i":35074,"as":"利用纤维素的内在手性和簇发光特性构建圆偏振发光（CPL）材料具有独特优势。该研究首次展示了纤维素衍生物的本征CPL，利用了簇发光与手性向列液晶相超分子手性的协同效应。胆甾型纤维素衍生物能够将其固有的手性和激发能同时转移给掺杂的非手性荧光染料，通过能量转移实现了放大的多色CPL发射。","scd":null,"kp":["发光材料[圆偏振发光]: 具有簇发光特性的胆甾相纤维素衍生物","发光机制[放大CPL效应]: 协同手性传递与能量转移"]},{"i":35075,"as":"本研究提出了一种镍/光氧化还原双催化迁移交叉偶联技术。该技术首次利用氯硅烷实现了远程C(sp2)–H的甲硅烷基化，成功进行位点选择性的ipso/ortho双官能化反应。此方法通过1,n-金属迁移机制，解决了远程C–H键难以直接功能化的问题，为通过迁移交叉偶联构建C–Si键提供了新途径。","scd":null,"kp":["催化体系[迁移交叉偶联]: 镍/光氧化还原双催化体系","成键反应[远程官能团化]: 实现1,n-金属迁移的C(sp2)-H/Si-Cl交叉偶联构建C-Si键"]},{"i":35076,"as":"针对海上可再生能源耦合水电解制氢过程中的功率波动问题，研究团队开发了一种基于电化学阻抗谱的动态等效电路模型。该模型能够有效解析波动态负载下的瞬态行为，定量分离由气泡屏蔽和孔隙阻塞引起的动力学因素与传质损失，从而精确识别催化剂退化及膜性能机制。","scd":null,"kp":["水合法电解[动态工况]: 解决功率间歇性带来的电极界面微观快速变化挑战","建模分析[瞬态动力学研究]: 基于电化学阻抗谱建立的动态等效电路模型"]},{"i":35077,"as":"为解决钙钛矿薄膜结晶度低及晶界缺陷多的问题，研究人员合成了富含电子的共价有机框架（COF），并通过一步后处理在其孔隙中引入N-阳离子自由基。这种自由基的引入显著降低了材料的带隙，能够同时控制结晶动力学、缺陷钝化及能级对齐，从而提升钙钛矿太阳能电池的效率和稳定性。","scd":null,"kp":["调控材料[钙钛矿结晶]: 富电子共价有机框架自由基","关键技术瓶颈[钙钛矿太阳能电池]: 同时控制结晶动力学、缺陷钝化和能级排列面临重大挑战"]},{"i":35078,"as":"针对高色纯度显示器对深蓝色发光体的需求，研究提出一种骨架刚性策略。通过将五元含氧杂环融合到经典MR-TADF骨架（ν-DABNA）中，利用芳香族融合与构象锁定引入刚性，提高了光学带隙并形成分子内C–H···O次级相互作用。这使得概念验证分子v-DABNA-O在甲苯中表现出系统性蓝移和窄带发射光谱，有效降低了对眼睛的光生物学风险。","scd":null,"kp":["分子设计策略[深蓝光有机电致发光]: 骨架刚性化与分子构象锁定（融合五元含氧杂环）"]},{"i":35079,"as":"针对19F磁共振成像（MRI）灵敏度低及常规探针尺寸较大导致肝脏清除缓慢和肿瘤积累有限的问题，研究开发了尺寸小于50纳米的核壳二氧化硅纳米颗粒（s-FLAME）。该颗粒装载了全氟-15-冠-5-醚（PFCE），结合了高氟密度与高19F MR灵敏度，实现了受控的体内行为，有效改善了探针的药代动力学特性。","scd":null,"kp":["粒径[核壳二氧化硅纳米颗粒]: <50 nm","成像探针[19F磁共振成像]: 包封全氟化碳的纳米颗粒"]},{"i":35080,"as":"研究报道了Au(III)半醌配合物的合成、分离、表征及其在光催化中的首次应用。该配合物通过Au(III)邻苯二酚前驱体的单电子氧化获得，氧化发生在O^O配体上，而金中心保持+3氧化态。由于具有四方平面几何构型和富电子特性，该类配合物能与有机底物形成电子供体-受体（EDA）相互作用，在可见光照射下实现催化功能。","scd":null,"kp":["催化剂[光催化应用]: 金(III)半醌配合物","合成工艺[金(III)半醌配合物]: Au(III)邻苯二酚盐前驱体的单电子氧化"]},{"i":35081,"as":"研究开发了一种由TiO2纳米管和均匀修饰的卤化物钙钛矿Cs3Bi2Br9（CBB）纳米点（<2 nm）组成的复合光催化剂。该催化剂在温和条件（100–120°C，1–4 bar，蓝光照射）下，通过甲基芳烃的氨氧化反应可持续合成芳腈。该方法产率高达353 µmol g⁻¹ h⁻¹，克服了传统方法需要极高温（≥350°C）或高压氧气的严苛条件。","scd":null,"kp":["反应温度[传统芳香腈合成(氨氧化)]: ≥350°C","反应压力[传统芳香腈合成(氨氧化)]: ≥15 bar O2","光催化剂[芳香腈光催化合成]: TiO2纳米管负载Cs3Bi2Br9 (CBB) 纳米点","纳米点尺寸[Cs3Bi2Br9]: <2 nm"]},{"i":35082,"as":"研究通过全电子DFT计算，量化了高价铋化学中的标量相对论效应，揭示了高价位铋促进弱配位阴离子（如三氟甲磺酸根和四氟硼酸根）偶联的驱动力来源。计算表明，相对论效应使Bi 6s轨道显著稳定，极大地影响了Bi(V)/Bi(III)过程的结构和前沿轨道能量，进而对还原消除反应产生显著影响。","scd":null,"kp":["理论机制[高价铋耦合弱配位阴离子]: 标量相对论效应引起Bi 6s轨道的显著稳定化"]},{"i":35083,"as":"研究报道了一种由CdS纳米棒上配位三个外来磷原子的原子级分散Au物种（AuP3-CdS）驱动的光催化碳-氮偶联协同氧化还原路径。该系统集成了无氧醇脱氢和亚胺加氢反应，实现了生物质衍生醇与无机氮源向高价值胺的转化。原位光谱和理论计算表明，Au-P3位点促进了电荷分离，并优化了C-H活化及氮转化动力学。","scd":null,"kp":["催化体系[光驱动碳-氮偶联合成高价值胺]: 原子级分散的Au物种（与三个外来配位原子配位）","反应路径[光催化碳-氮偶联]: 厌氧醇脱氢与亚胺氢化的协同氧化还原路径"]},{"i":35084,"as":"为克服紫外/可见光在组织中穿透力弱的问题，研究开发了一种基于偶氮苯衍生物和大环主体（环糊精和葫芦脲）的γ-射线调控主客体识别系统。在2 Gy的临床剂量下，γ射线能触发偶氮苯的顺反异构化，实现与大环分子的高效识别。γ射线展现出优于蓝光的深层组织穿透力，为体内主客体超分子系统的应用提供了途径。","scd":null,"kp":["调控手段[主客体分子识别系统]: γ射线辐照","优势特征[γ射线调节系统]: 具有优异的深层组织穿透能力"]},{"i":35085,"as":"研究通过反溶剂策略将二维金属有机框架Cu-TCPP和Zn-TCPP精确渗入有机太阳能电池活性层上部。这利用了MOF层内连续的π-d共轭显著增强了电荷传输，且MOF与受体L8-BO之间的金属中心配位等分子间相互作用优化了器件性能，成功制备了效率高达20.70%的二元有机太阳能电池。","scd":null,"kp":["转换效率[二元有机太阳能电池]: 20.70%","电荷提取材料[有机太阳能电池活性层]: 二维金属有机框架（Cu-TCPP和Zn-TCPP）"]},{"i":35086,"as":"针对酸性析氧反应（OER）中铱基催化剂易过度氧化和腐蚀的问题，研究合成了一种负载在氮掺杂石墨烯上的W单原子修饰IrOx纳米团簇（W-IrOx/NG）。W单原子通过W-N3O1配位结构形成钨电子缓冲，对铱活性位点进行调控与屏蔽，有效解决了催化剂的活性-稳定性权衡问题，显著提升了PEMWE的催化效率与耐久性。","scd":null,"kp":["催化剂[酸性析氧反应(OER)]: 负载于氮掺杂石墨烯并装饰有W单原子的IrOx纳米簇（W-IrOx）","催化机制[铱活性位点调节]: 通过钨电子缓冲调节和屏蔽铱活性位点"]},{"i":35087,"as":"铁蛋白催化Fe²⁺氧化的亚铁氧化酶中心向内腔转移Fe³⁺的具体路径此前未知。通过时间分辨X射线晶体学，研究确定了厌氧结合Fe²⁺的人胞质H链铁蛋白在暴露于氧气后的铁结合位点。研究追踪了Fe³⁺从亚铁氧化酶中心转移至蛋白质内表面/中心腔以沉积矿物的过程，揭示了铁核成核和矿化的关键机制。","scd":null,"kp":["催化位点[铁蛋白催化Fe2+氧化]: 亚铁氧化中心","[Fe3+转移路径]: 从亚铁氧化中心转移至蛋白质内表面/中央空腔进行矿化"]},{"i":35088,"as":"研究开发了一种镍催化的交叉亲电体偶联（XEC）策略，可从易得的卤代炔烃和烯丙基醋酸酯高效合成多种间隔烯炔。该方法底物适用范围广，兼容脂肪族、芳香族及复杂的天然产物和药物衍生基团。机理和DFT研究证实其遵循双氧化加成路径，Ni⁰优先与卤代炔烃发生氧化加成，是首例过渡金属催化的此类还原交叉偶联反应。","scd":null,"kp":["催化体系[交叉亲电偶联合成间隔烯炔]: 镍催化","底物适用性[交叉亲电偶联]: 具有广谱的底物适用性，兼容脂肪族、芳香族亲电试剂以及复杂天然产物和药物衍生结构"]},{"i":35089,"as":"为满足重型车辆质子交换膜燃料电池对寿命和效率的严苛要求，研究通过双金属配合物高温热解，合成了一种高度有序的L10-PtCo金属间纳米催化剂。该催化剂由均匀分散的纳米颗粒组成，有序度约80%，平均尺寸适中。该设计克服了低铂用量下性能与耐久性难以兼顾的挑战，有效提升了燃料电池性能。","scd":null,"kp":["催化剂设计[低铂重型燃料电池]: 中等尺寸金属间化合物PtCo催化剂","[重型车辆燃料电池要求]: 需平衡性能与耐久性以满足苛刻工况，当前通常需提升铂负载量"]},{"i":35090,"as":"研究通过原子层沉积在氧化铁纳米棒上引入高分散的CoOx团簇，构建了CoOx/Fe2O3催化剂，用于无溶剂条件下环己烷的选择性好氧氧化。该催化剂在界面形成了Co-O-Fe活性位点，显著增强了自旋极化和晶格氧迁移，有效促进了自由基的选择性生成并避免了过度氧化等副反应，显著提升了催化选择性。","scd":null,"kp":["催化作用机制[环己烷氧化]: 增强的自旋极化和晶格氧迁移","[烷基选择性氧化挑战]: 促进自由基选择性生成同时避免副反应（如过度氧化）"]},{"i":35091,"as":"针对中性条件下电催化析氯反应中阳极易溶解及析氧副反应严重的问题，研究开发了表面氟化的氢氧化钴纳米片（Co(OH)xFy）作为无贵金属电催化剂。结合太阳能驱动策略，该催化剂在中性条件下实现了高选择性的活性氯电合成。氟化钴位点有效调控了催化性能，实现了高效的原位海水净化。","scd":null,"kp":["催化位点[中性活性氯电合成]: 氟化钴位点","[电催化析氯反应限制因素]: 中性条件下析氧反应的激烈竞争及严重的阳极溶解问题，需贵金属电极实现高选择性"]},{"i":35092,"as":"本文是Andrey Lvov的个人简介。他提到如果能够回到过去做实验，会选择在Aleksei E. Chichibabin实验室研究具有潜在光致变色特性的吡啶基硫代靛酮。此外，他认为工作中最具挑战性的部分是在团队中维持友好且富有创造力的氛围。","scd":null,"kp":[]},{"i":35093,"as":"研究开发了一种基于氮掺杂多孔碳负载的单原子铁催化剂（Fe-SAC，具有明确的Fe-N4活性位点）的可持续非均相催化方法。该催化剂利用水中的分子氧，实现了甲基（杂）芳烃的氧化酯化及烷基芳烃的C-C键断裂，合成芳香族甲酯。催化剂表现出卓越的活性与选择性，成功克服了C(sp³)–H和C-C键的惰性，应用于聚苯乙烯和木质素衍生原料的升级回收。","scd":null,"kp":["催化剂[水中有氧条件下的氧化酯化与C-C键断裂]: 原子级分散的铁催化剂","[催化氧化策略]: 将甲基（杂）芳烃和烷基芳烃转化为高附加值芳香族甲酯"]},{"i":35094,"as":"为解决强相分离与动态相互作用之间的结构权衡限制，研究采用动态超支化拓扑策略，构建了金纳米粒子交联的聚氨酯弹性体。该材料具有包含动态拓扑网络、强氢键硬结构域以及无定形基质相分离纳米组装的分层结构。通过可逆解离与组合，实现了超灵敏的应变诱导结晶（SIC），赋予材料坚韧、可自修复的形状记忆功能，适用于人工肌肉和软驱动器。","scd":null,"kp":["材料设计策略[兼具韧性与自愈合的形状记忆聚氨酯弹性体]: 动态超支化拓扑网络工程","[材料结构特征]: 金纳米颗粒交联"]},{"i":35095,"as":"短波红外（SWIR）超窄带材料因其卓越的光谱纯度在高分辨率成像中具有极大潜力。研究人员通过控制空间位阻、磺酸盐介导的静电相互作用及π共轭设计，合理工程化了SWIR花菁染料，使其能够形成高度有序的J-聚集。优化后的染料IRJ1089可组装成高度稳定且无需封装的J-聚集体，并应用于多光谱光声断层成像。","scd":null,"kp":["材料特性[短波红外超窄带吸收]: J-聚集体材料","[超窄带长波吸收内在矛盾]: 长波长吸收、振动展宽与无序聚集产生的结构无序之间存在权衡"]},{"i":35096,"as":"受大脑皮层高效信号处理能力启发，研究人员构建了具有沟回结构的分级碳球（HCSs-sg）作为仿生界面。该结构模拟了皮层中密集的神经元分布，显著增加了伪电容活性位点，从而有效解决了水系锌离子电池在极低温下由于扩散层中Zn²⁺传输缓慢和亥姆霍兹层脱溶剂化势垒导致的性能瓶颈。","scd":null,"kp":["界面工程策略[低温水系锌离子电池快反应动力学]: 仿大脑皮层生物界面工程","[低温运行阻碍因素]: 扩散层内迟缓的Zn2+传输及亥姆霍兹层的脱溶剂化势垒"]},{"i":35097,"as":"针对微晶玻璃（GCs）结晶度与光学透明度之间的固有矛盾，研究人员开发了一种Li⁺掺杂介导的拓扑网络调控策略。实验与分子动力学模拟证实，Li⁺作为网络修饰体，能够松弛MgO-Al₂O₃-SiO₂透明微晶玻璃中刚性的四面体骨架结构，成功实现近乎完全的结晶度，以满足多功能光电应用的需求。","scd":null,"kp":["玻璃陶瓷结晶度[近全结晶多功能光电应用]: 超高","光学透明度[Li+介导拓扑网络调控铝硅酸盐玻璃陶瓷]: 优异"]},{"i":35098,"as":"","scd":null,"kp":[]},{"i":35099,"as":"","scd":null,"kp":[]},{"i":35100,"as":"","scd":null,"kp":[]},{"i":35101,"as":"","scd":null,"kp":[]},{"i":35102,"as":"","scd":null,"kp":[]},{"i":35103,"as":"","scd":null,"kp":[]},{"i":35104,"as":"为解决锌电池中锌枝晶生长、寄生副反应和界面Zn²⁺传输缓慢的问题，受磷脂双分子层启发，研究人员引入了仿生两性离子水凝胶电解质（PAMC）。该电解质将甲基丙烯酰氧基磷酰胆碱、聚丙烯酰胺和微量丙烯酸整合至坚固的网络中。两性离子基团通过部分替换水分子来调节Zn²⁺的初级溶剂化结构，从而实现高度可逆的锌负极。","scd":null,"kp":["电解质结构[仿生磷脂膜设计]: 两性离子水凝胶(PAMC)","解决问题[仿生两性离子水凝胶电解质锌负极]: 抑制锌枝晶生长、寄生副反应及改善界面Zn2+传输迟缓问题"]},{"i":35105,"as":"为克服传统金属氧化物电子传输层（ETL）在电荷传输性能上的局限，研究提出使用表面修饰的InAs量子点作为新型ETL。具体方法为利用单分子层ZnSe薄壳钝化InAs量子点的表面缺陷，并用金属硫族元素络合物配体替换原有的长链配体。这一策略有效促进了电子的平滑流动，显著提升了光电器件的性能。","scd":null,"kp":["电子传输层材料[InAs/ZnSe量子点]: 金属硫族络合物配体修饰"]},{"i":35106,"as":"本文介绍了研究人员Shoupeng Cao的学术背景与科研动机。他在构思分子设计和自组装的新想法及机制时极其专注。其最大的动力不仅在于追求卓越的科学研究，还在于通过有意义的指导与相互的学术成长来培养和启发年轻一代科研人员。","scd":null,"kp":[]},{"i":35107,"as":"针对生物质分子5-羟甲基糠醛（HMF）在低温下高活性、高选择性加氢脱氧（HDO）的挑战，研究人员利用改进的硬模板法制备了富含边缘硫空位的MoS₂催化剂（MoS₂-T）。在70°C的反应条件下，该催化剂在HMF转化生成C6燃料掺混物（DMF与BMFE混合物）的HDO反应中表现出97.2%的高产率。若延长反应时间，HMF的转化率可达100%。","scd":null,"kp":["反应温度[MoS2边缘硫空位催化5-羟甲基糠醛(HMF)加氢脱氧]: 室温","催化选择性[MoS2-T催化剂HMF加氢脱氧]: 高活性与高选择性","催化剂活性位点[MoS2-T]: 富边缘硫空位"]},{"i":35108,"as":"单分子光谱技术被用于研究恶嗪荧光团ATTO655与两种大环主体（CB8和sCX4）之间的相互作用。该技术克服了宏观实验在分析配合物异质性、化学计量比、动力学速率等方面的局限，成功区分了由配合物形成或碰撞过程引起的光物理效应，揭示了恶嗪-大环配合物在单分子分辨率下的变构调节、光物理变化及结合机制。","scd":null,"kp":["[恶嗪-大环复合物单分子行为]: 结合形成与光物理变化的别构调控机制表征"]},{"i":35109,"as":"聚原酸酯是一类具有生物降解性和化学可回收性的高分子，但长期以来面临合成挑战。研究开发了一种通过螺环原酸酯的阳离子开环聚合合成聚（原酸酯）弹性体的新方法。该聚合反应通过卤键供体催化实现精确的分子量控制，成功制备出化学循环型的聚（原酸酯）弹性体，拓展了新型聚合物材料的探索空间。","scd":null,"kp":["[聚(原酸酯)弹性体]: 卤键供体催化阳离子开环聚合合成且具备化学循环特性"]},{"i":35110,"as":"针对甲烷干重整（DRM）过程中严重的硫中毒问题，研究发现在Pt/CeO₂催化剂的Pt-O-Ce界面上，CO₂可诱导反向晶格氧溢流（RLOS）。这一过程将氧从CeO₂转移至Pt，将沉积的硫氧化为SO₂从而有效去除。Pt-O-Ce界面极低的氧迁移势垒与Pt对硫的高氧化活性，使得Pt/CeO₂催化剂在H₂S存在后能够实现独特的自我恢复。","scd":null,"kp":["抗硫中毒机制[Pt/CeO2催化甲烷干重整]: CO2诱导逆向晶格氧溢流(RLOS)氧化并脱除S"]},{"i":35111,"as":"为解决海水高浓度氯离子在电解制氢中引发的竞争吸附和电极腐蚀问题，研究人员开发了由惰性碳化聚合物点（CPDs）屏蔽的Co₃O₄电催化剂。该催化剂在500 mA cm⁻²电流密度下过电位仅为270 mV，并在600和800 mA cm⁻²的安培级大电流下分别展现出4200小时和3200小时的卓越抗氯耐久性。","scd":null,"kp":["耐氯腐蚀性能[Co3O4@碳化聚合物点电催化剂]: 实现安培级耐氯析氧反应","催化剂结构[海水电解析氧]: 惰性碳化聚合物点(CPDs)包覆Co3O4"]},{"i":35112,"as":"基于扭曲分子内电荷穿梭（TICS）机制，研究开发了一种超快、高灵敏度的亚硝酸盐（NO₂⁻）比率荧光检测与成像新策略。通过将邻苯二胺（OPD）片段策略性安装在焦宁荧光团的meso位，TICS过程被特定触发并与NO₂⁻发生反应。该方法成功实现了对亚硝酸盐的强抗干扰比率计量传感。","scd":null,"kp":["响应速度[扭曲分子内电荷穿梭(TICS)亚硝酸盐传感]: 超快","检测机制[亚硝酸根比率型荧光传感成像]: 基于扭曲分子内电荷穿梭(TICS)过程的比率型检测"]},{"i":35113,"as":"研究利用电子显微镜的高能电子束照射三种通过固态拓扑光二聚获得的胸腺嘧啶二聚体（TDs）晶体，探索由自由基离子引发的固-固裂分反应。实验对象包括顺-顺式-胸腺嘧啶二聚体、顺-顺式-N,N-二甲基-胸腺嘧啶二聚体等，展示了在电子束电离启动并由电子转移介导放大的单晶到单晶裂分过程。","scd":null,"kp":["[自由基离子诱导固-固分裂反应]: 暴露于电子显微镜高能电子束引发","[胸腺嘧啶二聚体]: 固态拓扑化学光二聚化合成"]},{"i":35114,"as":"针对高压锂金属电池中电极-电解质界面（EEI）不稳定的问题，研究提出在弱溶剂化电解液中利用DFOB⁻与2-噻吩甲腈（2-TC）添加剂之间的弱相互作用，协同调节溶剂化结构和双电层（EDL）。2-TC与DFOB⁻之间的离子-偶极相互作用促进了富含DFOB⁻的接触离子对形成，成功构建了机械坚固且具柔性的EEI。","scd":null,"kp":["[电极-电解质界面(EEI)构建]: 通过DFOB⁻阴离子添加剂弱相互作用协同调控溶剂化结构和双电层","[EEI特性]: 机械坚固且具柔韧性"]},{"i":35115,"as":"针对铂基核壳催化剂在酸性高电位下的结构失稳问题，研究以Pd@Pt核壳纳米晶为模型，结合原位溶解分析、电子显微镜和DFT计算，证实了针孔介导的溶解机制：Pd在针孔缺陷处的溶解破坏了局部界面结构，进而导致Pt壳层不稳定。研究通过间隙C/N掺杂实现了原子级界面锚定，有效抑制了金属溶解，稳定了Pd@Pt电催化剂。","scd":null,"kp":["[Pd@Pt核壳纳米晶电催化剂稳定化]: 间隙C/N掺杂实现原子级界面锚定并抑制金属溶解","[催化体系模型]: Pd@Pt核壳结构"]},{"i":35116,"as":"为解决半导体中光生载流子随机重组和激子结合能强的问题，研究在共价有机框架（COFs）中引入了“同时打破几何和电子对称性”的分子设计策略。利用不对称噻吩环替换对称苯环单元，诱导点群畸变和不对称电子密度重排，产生内置极化场，使激子结合能大幅降低，载流子寿命延长超300%，显著提升了H₂O₂的光合作用效率。","scd":null,"kp":["[光催化过氧化氢合成]: 在共价有机框架中引入同时打破几何与电子对称性的分子设计策略","[对称性打破作用]: 本征编程定向电荷流向，抑制光生电荷快速随机复合"]},{"i":35117,"as":"借鉴酶催化机制，研究人员设计了一种带有羧基功能化的大环钌基催化剂Ru(bda)，用于光驱动水氧化。该催化剂利用位于相对两侧的羧酸盐和Ru(V)=O单元形成O-O键，实现了“氧化物继电器”机制。同位素标记实验和单晶分析证实了这一基于外配位层功能基团导向的人工光催化水氧化路径。","scd":null,"kp":["[光驱动水氧化催化剂]: 羧基功能化Ru(bda)基大环化合物","[O-O键形成机制]: 氧化物继电器路径"]},{"i":35118,"as":"为解决室温氟离子电池（FIBs）输出电压低的问题，研究构建了一种基于NH₄F的甲醇/水混合电解液的高压水系FIB系统。该系统将锌/羟基氟化锌（Zn↔ZnOHF）固态负极与发生I⁻↔I₂F⁻可逆卤间化合物转化的碘正极耦合，实现了约1.3V的高输出电压。负极处NH₄⁺的强络合作用有效稳固了界面反应。","scd":null,"kp":["输出电压[室温下水系氟离子电池]: ~1.3 V","[固-固锌负极]: 锌/羟基氟化锌(Zn↔ZnOHF)氧化还原体系","[卤素间碘正极]: 发生可逆I⁻↔I转换反应"]},{"i":35119,"as":"针对水系全有机电池正极材料容量和电位受限的瓶颈，研究提出一种交叉共轭双活性中心设计策略。通过将醌类单元引入聚合物骨架形成供体-受体（D-A）结构，有效调节了2D氧化还原聚合物（2DRPs）的电子分布和前沿轨道。该设计克服了单纯增加吡嗪单元带来的活性降低问题，大幅提升了电池的能量密度。","scd":null,"kp":["[高能量密度水系全聚合物电池设计]: 采用交叉共轭双活性中心策略调控2D氧化还原聚合物电子分布与前沿轨道","[正极材料受限问题]: 缺乏大容量和高电位的正极材料"]},{"i":35120,"as":"人工离子通道中的跨膜离子流对生物混合电子器件至关重要。研究将DNA折纸贴片（直径0.8纳米）锚定在活体神经元细胞膜上，实现了约2 nS的稳定离子传输和通道样随机性，在不破坏神经元生理功能的前提下进行细胞内药物递送。借助膜片钳等技术，成功通过DNA贴片获得了可重复的细胞内和准细胞内电压测量结果。","scd":null,"kp":["DNA折纸砖直径[人工离子通道]: 0.8 nm","净离子电导[DNA折纸砖离子通道]: ~2 nS","[细胞内神经元记录]: 利用锚定在活体神经元膜上的DNA折纸砖实现高度稳定的离子传输和细胞内记录"]},{"i":35121,"as":"","scd":null,"kp":[]},{"i":35122,"as":"","scd":null,"kp":[]},{"i":35123,"as":"","scd":null,"kp":[]},{"i":35124,"as":"","scd":null,"kp":[]},{"i":35125,"as":"","scd":null,"kp":[]},{"i":35126,"as":"正交晶系范德华磁体具备低对称性晶体场和各向异性晶格，能驱动特殊的电子、磁性和激子行为。与蜂窝和六方系统相比，该材料为实现多样化的二维磁性、增强的自旋-电荷-晶格耦合以及更强的光与物质相互作用提供了新途径，可应用于构建具有可调功能的自旋电子学、光磁学、磁光子和光子技术。","scd":null,"kp":["[正交二维范德华磁体]: 提供低对称性晶体场和各向异性晶格","[技术赋能方向]: 增强自旋-电荷-晶格耦合及更强的光物质相互作用，可用于未来自旋电子学及光磁技术"]},{"i":35127,"as":"针对传统固定孔径膜难以精确分离相似离子的问题，研究人员在MXene膜中引入电压诱导的亚纳米通道塑性概念。施加电压会使膜通道收缩，形成自适应通路，允许锂离子通过并阻挡镁离子。这种电可编程通道塑性机制为构建更智能的分离膜提供了新方法，可应用于锂回收、水处理及离子选择性分离技术。","scd":null,"kp":["[MXene膜离子分离机制]: 电压诱导亚纳米通道收缩产生自适应塑性，允许锂离子透过并阻挡镁离子","[智能分离膜应用]: 锂回收、水处理及离子选择性技术"]},{"i":35128,"as":"为探究DNA甲基化与焦虑症的关联，研究团队在14,443名参与者的血液样本中开展了大规模全甲基化组关联分析，并利用表观基因组反卷积分析了12种不同的血液细胞类型。结果在全血中检测到4个显著相关的CpG位点，在各细胞类型中检测到15至124个相关位点。发现的特异性基因包括与应激反应相关的FAM171A2和VIPAS39，以及与焦虑症相关的NCOR1。","scd":null,"kp":[]},{"i":35129,"as":"利用冷冻电子显微镜技术，研究人员分析了多西环素在伯氏考克斯氏体和大肠杆菌核糖体上的结合机制。传统认知中该药物通过结合小亚基A位点阻断tRNA，但结构数据显示，多西环素结合在核糖体大亚基的退出通道。在伯氏考克斯氏体中，三个多西环素分子堆叠直接阻断通道；而在大肠杆菌中，单个药物分子结合引发了核糖体构象的剧烈变化。","scd":null,"kp":["最低抑菌浓度[多西环素针对伯氏考克斯氏体]: 极低","作用机制[多西环素靶向细菌核糖体]: 阻断tRNA与小亚基解码中心(A位点)的结合"]},{"i":35130,"as":"基于全球蝴蝶和植物分布数据集，研究揭示了蝴蝶幼虫食谱宽度的变化模式与驱动因素。幼虫食谱宽度与植物科丰富度呈负相关，但温度的直接影响抵消了部分作用。岛屿环境中的物种通常食谱更广，但特有性较高的岛屿物种食谱较窄。该结果有助于深入理解全球植食性昆虫的饮食生态演化机制。","scd":null,"kp":[]},{"i":35131,"as":"研究发现矿物光催化这一非生物过程是海洋透光层中二价铁（Fe(II)）产生的关键激活途径。实验室使用合成氧化铁和锐钛矿（TiO2）在人工海水中进行实验，结果表明锐钛矿驱动的Fe(III)到Fe(II)循环速率比现有模型假设高出四倍。这一光化学生产与生物摄取耦合的高通量稳态机制，解释了阳光照射水域中持续存在Fe(II)的现象。","scd":null,"kp":["光催化驱动的Fe(III)还原为Fe(II)速率[人工海水中锐钛矿(TiO2)介导的矿物光催化]: 高达（未给出具体数值，具有极速特征）","激活途径[海洋颗粒铁库中的Fe(II)生产]: 矿物光催化（非生物过程）"]},{"i":35132,"as":"针对射血分数保留的心力衰竭（HFpEF），该研究开发了一种基于闭环控制系统的体外仿生左心房心室模拟器。该模拟器采用高度可控的人工肌肉纤维，通过目标导向控制系统在舒张期调节人工心肌的顺应性。该设备能够模拟HFpEF的疾病进展，作为概念验证，它比现有模型具备更强的多维高阶模拟能力，为相关医疗器械的测试提供了平台。","scd":null,"kp":["测试模型[体外仿生左心房室模拟器针对射血分数保留的心力衰竭(HFpEF)]: 具有闭环控制系统以模拟疾病进展","技术成熟度[HFpEF疾病进展模拟器]: 处于概念验证阶段"]},{"i":35133,"as":"结合冷冻电子显微镜技术，研究原位监测了家蚕丝腺内丝蛋白的大分子组装和结构转变过程。在纳米到微米尺度上揭示了丝蛋白的存储与转化机制：在存储期间，丝蛋白形成微米级的球形“区室”以确保蛋白质的稳定性。这一发现阐释了液态原液转化为分层结构固态纤维过程中的关键步骤，补充了体外研究的局限。","scd":null,"kp":["结构演变特征[丝蛋白沿丝腺的阶段式大分子组装]: 逐步发生大分子组装与结构转变，实现液体原液储存向分级结构的转化"]},{"i":35134,"as":"为解决触觉传感器中机械压力与环境湿度信号产生交叉干扰的难题，研究提出了一种基于离子-电子电荷传输差异的解耦机制。通过设计双相双导电弹性体（BiDCE），利用离子和电子导电域之间的相分离，实现了多模态传感能力。结合阻抗谱解耦策略，该传感器能够在同时承受湿度和机械刺激的条件下，准确分离压力和湿度信号。","scd":null,"kp":["传感机制[无交叉干扰的机械与湿度刺激解耦]: 基于离子-电子电荷传输动力学差异的独立电荷传输"]},{"i":35135,"as":"研究在超导量子处理器中展示了具有低延迟反馈的实时量子纠错能力。通过将可扩展的FPGA解码器集成到控制系统，团队执行了多达25轮解码的8量子比特稳定性实验，每轮平均解码时间低于1微秒。实验结果证明，当解码器在超导硬件上以严格速度要求作为流式解码器运行时，能够有效避免计算积压问题，维持较快的逻辑时钟速率。","scd":null,"kp":["解码延迟与可扩展性[超导量子处理器量子纠错]: 具备低延迟反馈和可扩展的FPGA解码器集成控制系统"]},{"i":35136,"as":"利用高分辨率共振非弹性X射线散射技术，研究团队在铜氧化物超导体La2−xSrxCuO4中检验了动力学电荷-电荷关联，揭示了量子临界标度行为。观测到不同掺杂浓度和温度下的逆关联长度坍缩在同一条通用标度曲线上，得出临界指数ν为0.74 ± 0.08。该指数的非负性证实了隐藏在超导穹顶下量子临界点（QCP）的存在。","scd":null,"kp":["探测方法[铜酸盐超导体量子临界点(QCP)电荷-电荷关联]: 高分辨共振非弹性X射线散射","关键发现[La2−xSrxCuO4的量子临界标度]: 揭示了隐藏在超导穹顶下的量子临界标度行为"]},{"i":35137,"as":"针对柔性钙钛矿太阳能电池埋底界面不均匀和自组装单分子层易团聚的问题，研究引入基于聚(4-(3-苯基-9H-咔唑-9-基)丁基磷酸酯)的不对称聚合物自组装层。该聚合物结构富含刚性苯基-咔唑单元和多个锚定位点，构建了致密、高浸润且电学均匀的空穴选择性接触层。这种设计增强了界面偶极子和钙钛矿结合力，实现了均匀结晶并降低了非辐射损耗。","scd":null,"kp":["界面均质化材料[柔形钙钛矿光伏电池埋底界面]: 基于聚(4-(3-苯基-9H-咔唑-9-基)丁基磷酸盐)(Poly-3Ph-4PACz)的不对称聚合物自组装层"]},{"i":35138,"as":"在笼目磁体CsCr3Sb5中，研究证实了可以通过磁场控制交变磁性自旋密度波与电荷密度波序。利用50 mK深低温扫描隧道显微镜，观察到了两种此前未报道的电荷密度波序。密度泛函理论证实其中一种为4a0×结构的电荷密度波。该结果为微观尺度解析和控制几何阻挫晶格中的自旋与电荷序提供了实验依据。","scd":null,"kp":["调控手段[Kagome磁体CsCr3Sb5中的交变磁性自旋密度波]: 磁场控制"]},{"i":35139,"as":"研究开发了一种可打印的3D消色差超透镜，用于全色有机发光二极管近眼显示系统。通过使用灰度电子束光刻和基于干法刻蚀的高度编码纳米模板，结合无软模具的纳米压印技术（NIL），实现了超透镜的高保真度和高产出率。压印的3D超原子提供了可控的高度多样性，在低折射率树脂平台上实现了消色差相位匹配。","scd":null,"kp":["加工成型技术[全色OLED近眼显示器3D消色差超构透镜]: 灰度电子束光刻(EBL)结合干法刻蚀的高度编码纳米模板，以及无软模纳米压印光刻(NIL)"]},{"i":35140,"as":"通过结合纳米限域和Z向裂纹增韧机制，多尺度结构的MXene/聚乙烯（PE）纳米复合材料表现出优异的力学性能。在仅添加2.25 vol%低浓度MXene的情况下，该结构实现了以吸收为主的电磁干扰（EMI）屏蔽效能，高达40.40 dB。此外，该材料具有强烈的电热各向异性，且聚乙烯基体保证了材料在强酸强碱环境下的出色化学稳定性。","scd":null,"kp":["电磁干扰屏蔽效能[2.25 vol% MXene添加量]: 40.40 dB","屏蔽机制[低含量MXene纳米复合材料]: 高吸收 dominated","化学稳定性[基体材料]: 在强酸强碱条件下具有突出的化学稳定性","机械性能[协同结构设计]: 通过纳米限制和Z向裂纹增韧的协同作用显著提升","电热各向异性[多尺度结构]: 具有强的电热各向异性"]},{"i":35141,"as":"","scd":null,"kp":[]},{"i":35142,"as":"为解决有机电化学晶体管（OECT）操作中离子动态调控的难题，研究提出了一种阴离子-阳离子双掺杂机制。通过设计具有强侧链-阳离子相互作用的p型有机混合离子-电子导体Pu2gT，实现了阳离子排出与阴离子注入同步发生的延迟阳离子动态过程。该双掺杂机制显著提升了OECT的电流灵敏度，增强了生物化学信号的转导与放大能力。","scd":null,"kp":["主导操作机制[大多数报道的OECTs]: 通常由单一离子（如p型累积器件中的阴离子）主导","技术挑战[电化学掺杂过程]: 难以调节离子动力学以使两种离子在掺杂过程中同时发挥作用"]},{"i":35143,"as":"","scd":null,"kp":[]},{"i":35144,"as":"","scd":null,"kp":[]},{"i":35145,"as":"","scd":null,"kp":[]},{"i":35146,"as":"研究开发了一种金属定向β折叠片组装策略，成功制备出具备平行和反平行β折叠结构的自支撑二维肽晶体。反平行排列促进了层内机械互锁，显著增强了二维晶格的稳定性。该策略允许对氨基酸序列、手性和侧链化学进行可编程控制，克服了难以建立长程有序分子内氢键网络的挑战，成功实现了原子级厚度的二维仿生材料构建。","scd":null,"kp":["合成策略[2D肽晶体构建]: 金属导向的β折叠片状组装策略","技术挑战[构建超薄单晶2D肽材料]: 长程有序的层内氢键网络难以建立和维持","材料功能[2D肽结构]: 能够通过原子级薄层结构模拟生物分子的对映选择性识别"]},{"i":35147,"as":"研究人员提出了一种通用的界面能驱动乳液组装策略，用于便捷合成具有不同对称性、介晶相和孔径的大孔介孔共价有机框架。通过精确调整水/油比例，可以系统地调控乳液相、胶束结构和组装行为。该技术有效解决了在优化储能离子传输过程中精确控制介孔-微孔结构的难题，从而加速水系电池中锌离子的脱溶剂化过程。","scd":null,"kp":[]},{"i":35148,"as":"现有塑料回收面临经济、后勤及技术规模化等挑战，且现有研究多关注理想化的单一聚合物，忽略了现实中成分复杂且受污染的真实塑料废弃物流。为实现塑料循环经济，开发针对复杂废物的选择性回收技术至关重要。本文综述了复杂塑料废物的概念，并评估了溶剂型回收等具备潜力的选择性塑料废物回收策略。","scd":null,"kp":["技术瓶颈[塑料回收工艺]: 将实验室创新扩大到工业可行工艺存在技术障碍","现有研究局限[单聚合物废物流]: 忽略了真实世界塑料废物流通常具有的异质性和受污染特征"]},{"i":35149,"as":"","scd":null,"kp":[]},{"i":35150,"as":"","scd":null,"kp":[]},{"i":35151,"as":"","scd":null,"kp":[]},{"i":35152,"as":"","scd":null,"kp":[]},{"i":35153,"as":"研究人员开发了一种机器学习系统，能够利用智能手机前置摄像头在日常使用时被动捕捉的面部视频来监测用户心率。该系统符合业界心率测量的精度标准，其测量日常静息心率的准确度可与可穿戴设备相媲美，且能够跨不同肤色光谱估算智能手机用户的心率和静息心率。","scd":null,"kp":["监测精度[心率测量系统]: 符合行业标准，与可穿戴设备测量日常静息心率的精度相当","系统适用性[肤色]: 能够跨越不同肤色光谱估算心率"]},{"i":35154,"as":"亚马逊地区的森林砍伐正在改变大气中的水分传输。研究表明，由此产生的连锁反应导致即使在全球气温仅有小幅上升（低水平变暖）的情况下，也可能引发亚马逊地区大部分现存雨林的枯死和消退。","scd":null,"kp":[]},{"i":35155,"as":"","scd":null,"kp":[]},{"i":35156,"as":"","scd":null,"kp":[]},{"i":35157,"as":"环丁烷氨基腈作为空间位阻较大的α,α-二取代非天然氨基酸衍生物，在药物研究中备受关注。研究人员利用市售酮或醛，通过三重态氮宾介导的关键反应，实现了高非对映选择性的模块化精确合成。该转化利用双自由基介导的亚烷基环丙烷扩环反应，成功构建了具有更大位阻的邻位四取代衍生物，有效提升了分子的药效、代谢稳定性和选择性。","scd":null,"kp":["非共价催化剂组装[合成应用]: 实现阻位环丁烷氨基氰化合物的模块化非对映选择性合成","技术挑战[立体位阻更高的邻位四取代衍生物]: 通用合成策略严重阻碍了其化学空间的发展和探索"]},{"i":35158,"as":"","scd":null,"kp":[]},{"i":35159,"as":"研究团队开发了名为PHRM的深度学习被动心率监测系统。该系统利用基于面部视频的光电容积脉搏波描记法，在日常使用智能手机时被动测量心率（HR）和静息心率（RHR）。该系统在包含21.1万名视频的庞大验证集中表现出色，其准确性优于现有最先进的方法，平均绝对百分比误差极低，其性能可媲美参考心电图设备。","scd":null,"kp":["系统开发规模[深度学习模型训练]: 使用485名参与者的192,353个视频进行开发","技术指标[静息心率(RHR)]: 作为心血管健康和死亡率的关键生物标志物"]},{"i":35160,"as":"由于传统的手性氢原子转移（HAT）催化剂难以对短寿命的开壳中间体实现充分的对映选择性控制，研究团队提出了一种全新方法。该方法通过手性磷酸与市售2-巯基吡啶的非共价自组装，原位生成手性HAT催化剂。这种非共价催化剂组装策略成功实现了对映选择性的氢原子中继，为引入或编辑叔碳立体中心提供了高效的合成途径。","scd":null,"kp":["技术挑战[手性氢原子转移催化剂设计]: 对短寿命开壳中间体缺乏足够的手性控制"]},{"i":35161,"as":"针对倒钙钛矿太阳能电池中自组装单分子层空穴选择性接触易受紫外线损伤和热不稳定影响的问题，研究人员对MeO-2PACz分子进行了间隔基工程改造。研究揭示了非共价连接发生光降解、共价结构发生热降解的两种途径。在此基础上设计出新型MP3分子，结合了共价与非共价间隔基序及吸电子基团，有效抑制了紫外线诱导的降解，大幅提升了器件的紫外与热稳定性。","scd":null,"kp":["降解路径[基准分子MeO-2PACz]: 光降解和热不稳定性为两条不同路径","技术挑战[倒置钙钛矿太阳能电池耐久性]: 传统咔唑分子的紫外脆弱性和膦酸锚定基团的热不稳定性阻碍了器件耐久性","解决策略[空穴选择性接触]: 间隔基团工程"]},{"i":35162,"as":"癌症相关成纤维细胞通过生成纤维连接蛋白基质构建肿瘤基质。研究表明，该基质会逐渐获得与细胞层相同的向列序，并反向反馈使细胞和拓扑缺陷固定化。这种互惠耦合引发了一种老化过程，导致细胞流和缺陷运动显著减缓并最终冻结。尽管运动停滞，单层细胞仍保持活性，通过基质重塑调节其活性向列动力学，从而机械性地限制肿瘤扩张。","scd":null,"kp":["基质重组装[癌症相关成纤维细胞]: 纤连蛋白基质逐渐获得与细胞层相同的向列序","结构功能[成纤维细胞形态]: 对齐、细长的形态形成机械限制肿瘤扩张的包膜"]},{"i":35163,"as":"研究表明，农业劳动力短缺是导致耕地被废弃的主要因素之一。在现有环境约束的基础上，劳动力将成为未来耕地可用性及其变化的主导制约因素。模型预测显示，引入劳动力约束将额外抵消部分未来的耕地可用性。尽管全球自然区域无需进一步开垦即可满足全球耕地总需求，但在劳动力受限的情况下，各区域间的耕地可用性差异仍将持续存在。","scd":null,"kp":["耕地可用性未来变化[主导制约因素]: 农业劳动力","[核心条件]: 耕地撂荒现象持续存在，劳动力短缺是主要促成因素之一"]},{"i":35164,"as":"金属有机框架作为具有高度通用性和可调结构的材料，能够对催化剂结构进行精确控制。文章探讨了要实现其在催化领域的可持续和经济可行应用，必须通过改进评估指标和合理的材料设计，在催化活性、化学稳定性以及生产规模之间取得有效平衡。","scd":null,"kp":["催化剂设计[金属有机框架]: 平衡催化活性、稳定性和规模化应用","[可持续经济可行性]: 依赖于改进的评估指标和基于信息的材料设计"]},{"i":35165,"as":"模型研究表明，气候变化虽可能改变农作物的适宜种植区域，但务农人员的数量才是决定土地实际耕作情况的关键。不断萎缩的农业劳动力可能导致那些气候条件适宜的广阔地区实际上无法用于农业耕作。","scd":null,"kp":["[农业劳动力萎缩影响]: 可能导致气候适宜的广大地区实际上无法用于耕种"]},{"i":35166,"as":"在线预测市场正在针对从气候变化到量子计算等众多科学议题开设投注。然而，科研人员对这些预测市场的准确性持怀疑态度，并对其炒作现象提出了质疑。","scd":null,"kp":[]},{"i":35167,"as":"σ-p超共轭被证实是调控共价有机框架（COFs）激发态行为和供体特性的有效分子杠杆。激活σ-p超共轭可使COFs的荧光量子产率最高放大167倍，并引发激发态电荷密度的显著重排。这种原子级电子调控实现了对COF-OMe/Eu@UiO-66-(COOH)2异质结界面电荷转移方向和幅度的可编程控制，进而产生级联激发-发射耦合及依赖于激发波长的多色光输出。此外，激素结合过程会对这种由超共轭增强的界面产生扰动。","scd":null,"kp":["荧光量子产量放大倍数[σ-p超共轭激活的共价有机框架COFs]: 高达167倍","[激发态电荷密度]: 发生显著重分布","[光学调制]: 实现对级联光学调制方向和幅值的可编程控制"]},{"i":35168,"as":"针对传统离子凝胶聚合条件苛刻、生物相容性差且难以兼顾高机械强度与强黏附力的问题，研究人员提出一种由生物离子液体诱导、液态金属介导的自引发快速原位聚合策略。基于苹果酸/L-(-)-肉碱的离子液体能够破坏液态金属表面的氧化层，从而加速原位聚合过程，同时通过与聚合物发生强烈的可逆相互作用，构建出动态拓扑网络。该方法成功制备出具有良好生物相容性及稳固界面黏附力的韧性离子凝胶。","scd":null,"kp":["离子凝胶合成策略[液态金属介导的生物离子液体诱导自引发]: 快速原位聚合","[材料性能特点]: 兼具高机械强度、强附着强度与良好的生物相容性"]},{"i":35169,"as":"研究人员开发出完全基于DNA的水凝胶微粒（HMPs），其材料特性可通过自组装DNA纳米结构的序列可编程设计进行精确调控。该微粒通过在水包油液滴中微流控包封两种正交DNA纳米星和序列互补的DNA连接子形成。通过改变DNA纳米星设计的价态，实现了跨越三个数量级杨氏模量的可调机械性能以及独特的粘弹性行为，能够对尺寸、刚度、粘弹性和配体呈递进行精准控制，广泛应用于三维细胞培养系统。","scd":null,"kp":["水凝胶微粒特性调控[基于序列可编程自组装DNA纳米结构]: 精确控制尺寸、刚度、粘弹性和配体呈递","[微粒形成工艺]: 微流控包封两种正交DNA纳米结构"]},{"i":35170,"as":"蛋白质疗法具有极高的特异性和即时生物活性，但其结构脆弱性及细胞膜穿透屏障极大限制了应用。这篇综述探讨了纳米颗粒介导的蛋白质递送技术的变革，强调了先进的分子工程如何实现纳米-生物界面的精确调控和极高的时空分辨率。文章系统总结了多种前沿纳米平台，包括脂质纳米颗粒、聚合物组装体、多孔纳米材料和超分子结构，并重点阐述了这些平台的化学成分和结构特征在精准蛋白质递送中的关键作用。","scd":null,"kp":["蛋白质递送[纳米颗粒介导的纳米-生物界面分子工程]: 精确编排实现可编程和精准递送","[克服递送障碍]: 解决蛋白质内在结构脆弱性和细胞膜不可渗透性屏障"]},{"i":35171,"as":"","scd":null,"kp":[]},{"i":35172,"as":"","scd":null,"kp":[]},{"i":35173,"as":"","scd":null,"kp":[]},{"i":35174,"as":"","scd":null,"kp":[]},{"i":35175,"as":"","scd":null,"kp":[]},{"i":35176,"as":"在外周组织中，毛细血管内皮细胞的GPIHBP1负责捕获并结合脂蛋白脂肪酶（LPL）以水解甘油三酯释放脂肪酸。而在中枢神经系统中，LPL的结合位点此前一直未被发现。通过分析人类大脑的单核RNA测序数据库，研究发现少突胶质细胞表达GPIHBP1。这一结果证实，在人类大脑中，少突胶质细胞上的GPIHBP1是LPL的结合位点，揭示了中枢神经系统中脂质代谢与LPL转运的关键机制。","scd":null,"kp":["脂蛋白脂肪酶结合[人脑少突胶质细胞上的GPIHBP1]: 结合人脑内的脂蛋白脂肪酶"]},{"i":35177,"as":"放射性碳测年和树木年轮分析显示，意大利的常绿圣栎和落叶无梗花栎在15世纪初出现同步的种群建立脉冲。这一生态现象与1347年黑死病爆发及后续几个世纪的瘟疫导致人口急剧下降、从而减轻了人类对自然环境压力的过程高度吻合。从蒙特克里斯托岛到阿斯普罗蒙特山脉不同海拔梯度的样地均表现出相似的树龄分布，证实了 demographic collapse 后人类活动减少直接促进了地中海森林的自然野化与繁衍恢复。","scd":null,"kp":["森林重建历史信号[黑死病爆发后]: 15世纪初意大利圣栎和无梗花栎的同步定植脉冲","[古橡树测年结论]: 放射性碳测年证实人口崩溃后人类活动压力释放促进了地中海森林野化"]},{"i":35178,"as":"","scd":null,"kp":[]},{"i":35179,"as":"2023年加拿大野火季创下了过火面积和碳排放的历史纪录。研究估算，火灾后地表反照率的变化在70年内产生了-3.41 W m⁻²的时间累积气候冷却效应，曾部分抵消火灾排放的变暖影响。然而，由于积雪覆盖范围和持续时间的改变，自20世纪60年代以来，这种火灾后的气候冷却效应平均已减弱了29%。这意味着现代北方森林野火产生净气候变暖影响的可能性比过去增加了一倍。","scd":null,"kp":["气候冷却效应[2023年加拿大野火过火区域]: -3.41 W m⁻² (95% CI: -4.39至-2.43)","时间积分气候冷却评估周期[2023年加拿大野火]: 70年","[火灾后地表反照率变化]: 历史上部分抵消野火排放的变暖影响，但该气候冷却作用正在丧失"]},{"i":35180,"as":"","scd":null,"kp":[]},{"i":35181,"as":"","scd":null,"kp":[]},{"i":35182,"as":"","scd":null,"kp":[]},{"i":35183,"as":"","scd":null,"kp":[]},{"i":35184,"as":"","scd":null,"kp":[]},{"i":35185,"as":"","scd":null,"kp":[]},{"i":35186,"as":"","scd":null,"kp":[]},{"i":35187,"as":"","scd":null,"kp":[]},{"i":35188,"as":"","scd":null,"kp":[]},{"i":35189,"as":"","scd":null,"kp":[]},{"i":35190,"as":"","scd":null,"kp":[]},{"i":35191,"as":"植物细胞壁是由果胶、半纤维素和纤维素构成的动态超分子组装体。为探究赋予细胞壁力学性能的核心结构成分，研究人员构建了最小化的合成球形果胶-纤维素纳米纤维胶囊，并利用植物原生质体从零开始再生细胞壁的能力。平行板压缩测试表明，细胞壁硬度随时间推移和壁增厚而增加。研究证实，该合成果胶-纤维素纳米纤维胶囊能够在无细胞间连接干扰的情况下，精确再现再生植物细胞壁的力学性能。","scd":null,"kp":["[合成球形壳体结构]: 复现植物再生细胞壁的机械特性"]},{"i":35192,"as":"","scd":null,"kp":[]},{"i":35193,"as":"","scd":null,"kp":[]},{"i":35194,"as":"","scd":null,"kp":[]},{"i":35195,"as":"","scd":null,"kp":[]},{"i":35196,"as":"","scd":null,"kp":[]},{"i":35197,"as":"","scd":null,"kp":[]},{"i":35198,"as":"","scd":null,"kp":[]},{"i":35199,"as":"","scd":null,"kp":[]},{"i":35200,"as":"","scd":null,"kp":[]},{"i":35201,"as":"面对地缘政治紧张和能源进口中断导致的欧盟能源价格飙升及长期供应缺口，研究提出结合GAINS模型与WILIAM系统动态综合评估模型的新框架。研究发现，短期内弥合能源缺口的措施会加剧经济或公共健康负担。分析表明，致力于向可再生能源转型的长期战略不仅能有效填补能源供应缺口，还可以避免短期措施带来的负面效应，是实现可持续能源安全的根本途径。","scd":null,"kp":["[欧盟能源转型评估模型]: 结合GAINS模型与WILIAM系统动力学综合评估模型的综合框架"]},{"i":35202,"as":"","scd":null,"kp":[]},{"i":35203,"as":"","scd":null,"kp":[]},{"i":35204,"as":"研究揭示了多聚磷酸盐代谢在深海产甲烷古菌中的生理作用。针对深海冷泉沉积物中的产甲烷古菌，多聚磷酸盐代谢与细胞的生长及产甲烷过程相耦合。酶学分析表明，PPK1以依赖镁离子（Mg2+）的方式介导多聚磷酸盐的合成，而PPK2主要发挥水解酶功能。敲除ppk1基因会彻底消除该菌株的多聚磷酸盐积累，并显著损害细胞的生长及甲烷生成能力。","scd":null,"kp":["[深海产甲烷古菌]: 多聚磷酸盐代谢与生长和产甲烷过程相耦合","[代表性菌株]: Methanolobus sp. ZRKC1"]},{"i":35205,"as":"研究探讨了生态预测中记忆、非线性和随机噪声之间的交互作用。基于包含鸟类、哺乳动物等全球302个丰度时间序列数据库，采用经验动态建模评估记忆长度，并通过有效李雅普诺夫指数分类时间序列稳定性。研究发现，记忆长度在处于中性稳定的序列中最长，在混沌序列中则与李雅普诺夫时间范围成正比。同时引入记忆和非线性模型能够显著降低表观噪声并提高生态预测准确性。","scd":null,"kp":["[生态种群丰度时间序列分析]: 记忆长度和非线性动力学相互作用决定预测性","[全球数据库样本量]: 包含鸟类、哺乳动物、鱼类、昆虫和浮游生物的302条丰度时间序列"]},{"i":35206,"as":"系统综述了锂氧气电池（LOBs）正极催化剂的创新进展及人工智能驱动的设计范式。LOBs具备极高理论能量密度，但迟缓的氧还原/析出反应动力学、绝缘放电产物、大电压极化和差循环稳定性阻碍其实用化。正极催化剂在调节反应路径、加速界面动力学和提高反应可逆性方面发挥关键作用。文章总结了非水系LOBs的工作原理及挑战，并全面评述了碳基、贵金属基等先进催化剂材料的最新研究进展。","scd":null,"kp":["[锂氧电池(LOBs)实际应用瓶颈]: 氧化还原反应动力学缓慢、放电产物绝缘、电压极化大及循环稳定性差","[正极催化剂核心作用]: 调节反应路径并加速反应动力学"]},{"i":35207,"as":"提出一种在自然阳光下合成共轭微孔聚合物的绿色无金属策略，用于高效光催化回收真实塑料废弃物。该合成利用原位形成的电子供体-受体复合物在自然光照下驱动聚合，无需苛刻条件或贵金属。所得聚合物能够作为高效的非均相光催化剂，在室温下将十种真实聚苯乙烯基塑料升级回收为高附加值苯甲酸。该工艺具备高度可扩展性，为废弃塑料的常温可持续升级回收提供了新方案。","scd":null,"kp":["[聚合物合成驱动源]: 自然阳光","[共轭微孔聚合物(CMPs)合成策略]: 无金属绿色策略，原位形成电子 donor-acceptor (EDA) 络合物驱动聚合"]},{"i":35208,"as":"通过对CdSe/CdS量子点进行精巧的结构工程，研究实现了在可见光下的单一光氧化还原循环中，将光催化二氧化碳还原与邻二胺生产相耦合。光催化二氧化碳还原结合有机转化是高效利用太阳能的策略，但面临选择性低和氧化有机转化种类受限的挑战。实验表明，这种结构工程化的量子点能有效整合二氧化碳还原与胺类氧化的碳碳偶联反应，显著提升了光催化体系的光能转化效率与产物多样性。","scd":null,"kp":["[光催化体系]: 结构工程化量子点耦合CO2还原与邻二胺生产的单一光氧化还原循环"]},{"i":35209,"as":"研究深入解析了双链DNA中G-四链体与i-Motif结构共存的平衡机制。DNA可短暂折叠成具有调节功能的多种结构，富鸟嘌呤序列形成G4，其互补链形成iM。近期单分子分析已证实两者在双链DNA同一基因位点可同时存在并作为协同阻断剂阻碍复制叉推进。本研究采用广泛的分析方法，明确了双链DNA内部调控G4与iM折叠共存的物理化学因素与平衡条件。","scd":null,"kp":["[双链DNA瞬态折叠构象]: G-四链体和i-Motif构象可在双链基因组位点同步共存"]},{"i":35210,"as":"研究了Pd1Cu单原子合金催化剂中合金化位点密度变化对电催化一氧化碳还原产物产率的调控作用。对于具有解耦速率和选择性限制步骤的催化反应，合金化位点密度能显著操纵这些独立步骤。研究发现，根据Pd原子呈稀释或密集状态的不同，立方体Pd1Cu单原子合金催化剂在电催化CO还原中分别对乙烯或乙醇表现出截然不同的高反应活性，证明了单原子合金体系位点密度对产物选择性的关键决定作用。","scd":null,"kp":["[单原子合金(SAA)催化剂]: Pd1Cu合金催化剂的合金化位点密度可显著调控解耦的速率限制与选择性限制步骤"]},{"i":35211,"as":"开发出一种可扩展的光谱选择性日间辐射制冷涂层，解决了传统宽带发射器在密集城市环境中吸收环境热辐射的寄生问题。该涂层结合了由相分离衍生的聚氟乙烯微纳米多孔层与反射性银基底，实现了1.37的创纪录光谱选择性。涂层具备97.5%的太阳反射率，且94.4%的中红外发射率被严格限制在8-13微米的大气窗口内。在城市峡谷模拟测试中，该涂层展现出了优异的净制冷性能。","scd":null,"kp":["[日间辐射制冷涂层]: 具有可扩展性的光谱选择性涂层，通过相转化微结构克服城市环境寄生热吸收的宽带发射体缺陷"]},{"i":35212,"as":"开发了一种新型氢键有机框架材料HOF-BUT-1，实现了高容量丙烯/乙烯分离。针对气体分离吸附剂中孔体积与孔径限制之间的权衡难题，研究利用一种罕见的8连接 linker 构建了具有区室化多孔结构的HOF。该材料结合了0.95 cm3/g的高孔隙率和仅7.6埃的小腔径。得益于这种平衡的孔结构，HOF-BUT-1在298 K和1 bar条件下表现出8.83 mmol/g的创纪录高丙烯吸收量，从而实现了极高的分离潜力。","scd":null,"kp":["孔体积[HOF-BUT-1框架材料]: 0.95 cm³/g","孔道结构[HOF-BUT-1框架材料]: 分隔化多孔结构","应用性能[C3H6/C2H4分离]: 高容量气体分离"]},{"i":35213,"as":"探索出一种基于双钙钛矿Cs2NaBiCl6:Yb3+/Mn2+的新型光学测压材料，克服了传统紫外激发光学压力计灵敏度低、成本高及背景荧光光谱重叠的缺陷。该材料展现出由Yb3+-Mn2+二聚体引发的宽带压力敏感上转换发射。这种新型上转换发光测压技术在提升压力测量灵敏度的同时，有效避免了常规紫外激发带来的光致发光干扰，为先进光学测压技术提供了新方案。","scd":null,"kp":["光学测压材料[压力响应上转换发光器件]: Cs2NaBiCl6:Yb3+/Mn2+","发光激发机制[光学测压计]: 避免紫外激发及其背景荧光干扰"]},{"i":35214,"as":"提出了一种利用受控腐蚀实现动态钝化和骨免疫调节的“腐蚀引导功能化”新概念。在非对称且三维互锁的P(VDF-TrFE)/Mg网状复合材料中，部分聚合物封装构建了作为原位微型反应器的界面微裂缝。这些微反应器捕获初始腐蚀产物，触发自适应性氢氧化镁阻挡层的自主生长。与传统的牺牲性磷酸钙涂层相比，这种钝化机制提供了持久的腐蚀稳定性，同时保留了镁的有益生物活性以进行骨免疫调节。","scd":null,"kp":["防腐策略[P(VDF-TrFE)/Mg复合材料]: 腐蚀引导的功能化（利用受控降解）","微观结构设计[复合材料界面]: 部分聚合物封装工程化形成微裂纹作为原位微反应器"]},{"i":35215,"as":"设计并制备了一种由DNA编程的非晶态PtCu纳米混合结构，用于高效析氢反应。非晶态原子级薄金属材料具有极高的催化活性位点密度，但受限的电荷传输和质量交换限制了其宏观动力学性能。该集成结构将原子级薄的PtCu纳米片与互连的PtCu纳米管在空间上交织，构建了强烈耦合的反应域与传输域。非晶态纳米片充当高活性反应中心，而纳米管网络负责高效的电荷传输与质量交换，从根本上克服了非晶金属催化剂的动力学瓶颈。","scd":null,"kp":["催化剂形态[无定形原子级薄金属]: 非晶态原子层厚度","微观结构设计[PtCu纳米杂化材料]: 空间功能分隔化设计","应用场景[析氢反应]: 解决非晶催化剂电荷传输与质量交换的动力学限制"]},{"i":35216,"as":"生物组织在承载时表现出非线性应变硬化特性（具有不同的初始和后段弹性模量）。本研究开发了一种工程化应变硬化颗粒水凝胶，在保持高保真度3D打印能力的同时，为独立调节其初始和后段弹性模量提供了统一的策略与机制基础，成功实现了合成组织模拟材料的构建。","scd":null,"kp":["力学特性[仿生组织工程材料]: 具有独立的趾区和跟区模量的非线性应变硬化"]},{"i":35217,"as":"宽禁带钙钛矿太阳能电池的效率与稳定性常受自组装单分子层（SAM）和混合卤化物钙钛层不均匀性的限制。本研究提出一种埋底界面驱动的协同均质化策略，通过在FTO基板与MeO-2PACz SAM层之间插入氟化铜（CuF2），有效抑制了分子的聚集，促进了MeO-2PACz层的均匀覆盖，从而显著提升了器件的效率与稳定性。","scd":null,"kp":["界面工程[钙钛矿太阳能电池]: 埋底界面驱动的自组装单分子层与钙钛矿协同均质化","应用对象[宽带隙钙钛矿太阳能电池]: 提升作为叠层电池顶电池的光伏效率与稳定性"]},{"i":35218,"as":"金红石型IrO2与TiO2或SnO2体系中存在较宽的不混溶区，导致制备IrO2基固溶体在热力学上极具挑战。本研究使用超过20种外来金属阳离子，成功合成了单相金红石型(Ir, M)O2和(Sn, M)O2固溶体催化剂。该催化剂利用拉普拉斯压力实现稳定，展现出优异的酸性水氧化催化性能。","scd":null,"kp":["晶体结构[金红石固溶体催化剂]: 拉普拉斯压力稳定的固溶体相","应用场景[酸性水氧化]: 借鉴析氧电极(DSA)的成分设计突破热力学不互溶区"]},{"i":35219,"as":"聚合物固态电解质面临锂离子传输迟缓、阴离子迁移严重及界面不稳定等问题。本研究将含有铁电性铌酸钾钠（K0.5Na0.5NbO3）的静电纺丝纤维框架引入固态聚合物基体中，构建了铁电调制复合聚合物固态电解质。该设计有效加速了锂离子传输并稳定了电极-电解质界面，提升了固态锂金属电池性能。","scd":null,"kp":["电解质设计[固态锂电池]: 铁电调控的复合聚合物固态电解质","改性效果[固态锂电池内部环境]: 加速离子传输、抑制阴离子迁移并稳定电极-电解质界面"]},{"i":35220,"as":"为替代碱性介质中的铂基析氢反应催化剂，本研究通过不到10秒的超快微波准固态工艺，将Os团簇与FeP结合构建了Os/FeP异质结构。该异质结构引发的电子金属-载体相互作用和内置电场优化了电子配置，加速了电子转移，缓解了Os位点对H*的过度吸附，增强了FeP上的H*覆盖，实现了安培级海水电解。","scd":null,"kp":["制备工艺[Os/FeP异质结构]: 超快微波准固态处理（<10秒）","催化机制[析氢反应]: 内建电场调控电子传输通道（基于金属-载体电子相互作用）","应用性能[安培级海水分解]: 替代碱性介质中Pt基化合物的低成本高稳定性析氢"]},{"i":35221,"as":"为解决锌金属负极人工聚合物界面相中机械完整性与快速离子传输难以兼顾的问题，本研究开发了一种原位相分离策略，制备了由富含聚合物的强韧相（辛胺接枝PVA骨架）和弹性锌离子导电区组成的聚合物界面相。前者赋予界面坚固的机械性能，后者确保了快速的离子传输，从而实现了超稳定锌金属负极。","scd":null,"kp":["界面策略[锌金属负极]: 原位相分离制备的高度纠缠功能聚合物界面相(PN)","微结构特征[聚合物人工界面]: 解耦但协同的微区结构","改性效果[锌金属负极]: 兼顾机械完整性与快速离子传输，实现超稳定循环"]},{"i":35222,"as":"有机小分子正极在含水锌电池中易溶解导致寿命受限。本研究设计了非平面叔氮扩展硝基苯（TNB），利用超过水解离能的强分子内π-π相互作用，制备出不溶且低能垒的硝基芳烃正极。两个叔氮键合的旋转使得TNB在水中具有强排斥力，分子内最大负势能达-35.8 kcal/mol，从根本上解决了正极溶解问题。","scd":null,"kp":["正极材料[水系锌电池]: 非平面叔胺型扩展硝基苯小分子","分子内相互作用[硝基芳烃小分子]: 强π-π相互作用（超越水分子解离能）","[TNB正极]: 不溶且具有低能垒"]},{"i":35223,"as":"高熵氧化物可通过多元素协同提升析氧反应活性，但平衡活性与稳定性具有挑战。本研究通过超快热冲击法合成了尖晶石型FeCoNiCrRu高熵氧化物，实现了吸附物演化机制（AEM）和晶格氧机制（LOM）的协同双路径催化。其中，Cr和Ru在Co位点共同增强AEM动力学，而Ru在Fe-Cr桥氧位点引发局部LOM路径，优化了中间体吸附。","scd":null,"kp":["催化剂[OER反应]: 尖晶石型FeCoNiCrRu高熵氧化物","制备工艺[高熵氧化物]: 超快热冲击法","催化机制[高熵氧化物OER]: 吸附物演化机制(AEM)与晶格氧机制(LOM)双路径协同"]},{"i":35224,"as":"湿气发电机（MEG）能够从环境水蒸气中收集能量，为可穿戴电子设备和物联网系统提供自供电方案。然而，其输出功率有限，阻碍了实际应用。为解决这一问题，本研究提出了一种太阳能补充式湿气发电机，通过协同多种机制收集能量，实现了在所有地区的高效稳定产能。","scd":null,"kp":["技术瓶颈[水汽发电机输出功率]: 输出功率受限（文本原文截断缺失具体数值）","[MEG技术]: 能够收集环境水汽电能，但在实际应用中受限于输出功率"]},{"i":35225,"as":"核电厂在可再生能源高渗透率市场中面临灵活运行压力。研究表明，将核反应堆与高温电解制氢及辅助服务参与相结合，可显著提高核能系统的经济性和运行灵活性。通过小时级优化模型和全生命周期技术经济分析发现，为现有反应堆加装高温电解装置可大幅增加平均净现值，改善整体经济效益。","scd":null,"kp":["技术路径[核电制氢耦合]: 通过高温电解将核反应堆与产氢耦合","系统效益[核能灵活性]: 整合核能发电、产氢及辅助服务可提升系统灵活性与附加价值"]},{"i":35226,"as":"","scd":null,"kp":[]},{"i":35227,"as":"","scd":null,"kp":[]},{"i":35228,"as":"","scd":null,"kp":[]},{"i":35229,"as":"","scd":null,"kp":[]},{"i":35230,"as":"","scd":null,"kp":[]},{"i":35231,"as":"","scd":null,"kp":[]},{"i":35232,"as":"在分离科学中兼顾高分子选择性与机械稳健性是一大挑战。本研究在聚合物基质中共价嵌入多孔骨架构建扩散通道，将网络完整性作为连接桥连通性与分离性能的定量设计指标。通过密度探针法证实了小于3埃的孔隙存在。所制氢选择性膜超越了现有聚合物性能阈值，且长期稳定运行，兼顾了工程实用与分离效能。","scd":null,"kp":["结构特征[聚合物网络]: 含有共价嵌入扩散通道的聚合物网络","设计指标[聚合物分离膜]: 引入“网络完整性”作为连接桥连接性与分离性能的定量设计描述符"]},{"i":35233,"as":"","scd":null,"kp":[]},{"i":35234,"as":"","scd":null,"kp":[]},{"i":35235,"as":"","scd":null,"kp":[]},{"i":35236,"as":"","scd":null,"kp":[]},{"i":35237,"as":"","scd":null,"kp":[]},{"i":35238,"as":"","scd":null,"kp":[]},{"i":35239,"as":"","scd":null,"kp":[]},{"i":35240,"as":"","scd":null,"kp":[]},{"i":35241,"as":"","scd":null,"kp":[]},{"i":35242,"as":"","scd":null,"kp":[]},{"i":35243,"as":"","scd":null,"kp":[]},{"i":35244,"as":"","scd":null,"kp":[]},{"i":35245,"as":"","scd":null,"kp":[]},{"i":35246,"as":"","scd":null,"kp":[]},{"i":35247,"as":"","scd":null,"kp":[]},{"i":35248,"as":"","scd":null,"kp":[]},{"i":35249,"as":"","scd":null,"kp":[]},{"i":35250,"as":"","scd":null,"kp":[]},{"i":35251,"as":"","scd":null,"kp":[]},{"i":35252,"as":"","scd":null,"kp":[]},{"i":35253,"as":"Rras2缺失会导致小鼠骨量减少、骨强度降低和成骨作用受损，重现人类骨骼发育不良特征。机制上，Rras2通过阻断Smurf1依赖的BMPR2泛素化和降解来维持BMP信号传导，进而促进骨髓间充质干细胞的成骨分化；同时BMP信号增强Rras2转录。这形成了维持成骨的Rras2-BMPR2正反馈环路，骨质疏松小鼠中Rras2表达显著降低，成为治疗骨质疏松的潜在靶点。","scd":null,"kp":[]},{"i":35254,"as":"光体（PBs）是由光敏色素B（phyB）组织的核凝聚物。研究发现，phyB的输出模块（OPM）作为所有PB类型的通用成核剂，而光传感模块（PSM）通过削弱该活性实现环境控制。温度通过两种独立的机制调节PB数量。结论表明phyB通过分级成核状态和效能来设定凝聚物数量。","scd":null,"kp":[]},{"i":35255,"as":"利用细菌单细胞RNA测序和功能实验研究了肺炎克雷伯菌。研究发现，在同等基因群内，不同的转录反应可以被诱导并共同促进细菌在抗生素处理下的存活。结论表明，细菌处理前的细胞状态决定了抗生素诱导的转录重编程，从而影响其表型适应和生存结局。","scd":null,"kp":[]},{"i":35256,"as":"利用高温高能同步加速器X射线衍射和差示扫描量热法，系统研究了典型金属玻璃形成体（Cu46Zr42Al7Y5）在加热过程中的结构演变。通过探测宽加热速率下玻璃转变与结晶的动力学相互作用，识别出首个放热过程性质依赖于加热速率的交叉现象。结论定量揭示并证实了相互竞争的结构有序性会阻碍结晶并促进玻璃形成。","scd":null,"kp":["材料成分[典型金属玻璃形成体]: Cu46Zr42Al7Y5","物理机制[金属玻璃]: 结构阻挫在抑制结晶和促进玻璃形成中起关键作用","表征技术[金属玻璃结晶过程]: 结合高温高能同步辐射X射线衍射的原位表征"]},{"i":35257,"as":"开发了一系列合理设计的用于可见光驱动光氧化还原反应的本征微孔聚合物（PIMs）。通过多学科方法证实这些PIMs作为无金属光催化剂具有广泛适用性，能够有效驱动多种反应，并评估了多种回收和连续流反应-分离策略。结论表明该催化剂成功结合了均相反应的高效性与材料的可回收性。","scd":null,"kp":["光催化剂[连续流反应分离]: 固有微孔聚合物(PIMs)","催化特性[PIMs光催化剂]: 无金属、可见光驱动且结合了均相反应性与可回收性"]},{"i":35258,"as":"提出了一种双波长光图案化策略，在合成过程中直接在液晶弹性体（LCEs）中实现空间可编程的异质性。该方法利用两种波长的光和广泛使用的单体，克服了现有方法调节性受限、依赖热固化或特殊单体的缺点。结论表明该技术成功解锁了LCEs内部高分辨率的定制空间异质性。","scd":null,"kp":["加工技术[液晶弹性体光刻]: 双波长光刻技术","加工效果[液晶弹性体]: 实现空间可编程的异质性"]},{"i":35259,"as":"实验研究了利用137Ba+离子处理量子信息，成功实现了多达25个内部能级的高保真度态制备和读出，构建了一个25维的囚禁离子量子比特。通过探查多达24个态的叠加，研究了误差随维度缩放的规律。结论表明，在单个量子比特中可实现高维量子逻辑运算，成功演示了3量子比特Bernstein-Vazirani算法和4量子比特Toffoli门。","scd":null,"kp":["量子系统[囚禁离子量子信息处理]: 137Ba+离子","量子维数[制备的单原子系统]: 25维囚禁离子量子dicast (qudit，25个内部能级)","系统性能[25维qudit]: 实现了高保真度的态制备和读出"]},{"i":35260,"as":"开发了一种标准化的多尺度定量方法，用于精确测量和原位观察接触起电引起的机械-电转换（MEC）过程。系统研究了半结晶聚合物（如能带结构和聚集态）的关键特性如何决定MEC行为。结论成功建立了材料性质与电荷转移及体运输之间的内在联系。","scd":null,"kp":["研究方法[接触起电动态过程]: 标准化的多尺度定量表征方法","应用基础[半结晶聚合物]: 机械-电转换(MEC)与接触起电(CE)"]},{"i":35261,"as":"将离子液体[EMIM][TFSI]引入圆柱状聚环氧乙烷-聚丁二烯嵌段共聚物中，能够显著扩展复杂球形胶束堆积的相空间。研究发现该体系在广泛的组分和温度范围内形成σ、A15和Laves C15等Frank-Kasper相，并观察到热致和溶致相变序列。结论表明离子液体增强了有效Flory相互作用参数，作为结构导向剂发挥了双重作用。","scd":null,"kp":["结构导向剂[嵌段共聚物Frank-Kasper相]: 1-乙基-3-甲基咪唑双(三氟甲基磺酰)亚胺离子液体([EMIM][TFSI])","聚合物体系[嵌段共聚物]: 聚环氧乙烷-嵌段-聚1,2-丁二烯(PEO-b-PB)"]},{"i":35262,"as":"引入了深度分辨电子衍射成像（DREDI）技术，这是一种快速、无损绘制铁电薄膜极化的方法。研究发现极性纹理存在隐藏的深度演变：表面71°条纹演变为次表面的通闭合涡旋，并在底部界面附近分叉为三重顶点。应变非均匀性和电极中的铁弹性孪晶是导致这些掩埋构型的原因，证实了该方法在揭示三维拓扑极化结构方面的能力。","scd":null,"kp":["表征方法[铁电拓扑极化纹理]: 深度分辨电子衍射成像(DREDI)","技术特点[DREDI]: 快速、无损的三维极化映射方法","结构演变[铁电薄膜深度方向]: 表面71°条纹演化为亚表面磁通闭合涡旋并分岔为三重矢量"]},{"i":35263,"as":"研究提出一种结合α-FeOOH/NiFe层状双羟基化合物（NiFe-LDH）异质结催化剂与脉冲电解（PE）的集成电催化平台，用于绿色高效合成尼龙单体己二酸。该异质界面能通过电子桥接降低C-C键断裂的能垒，并为己二酸提供高选择性位点。该技术克服了传统KA油高温硝酸氧化工艺碳排放大、产二氧化氮多，以及常规电氧化方法中O2利用率低、催化剂易钝化等导致的活性-稳定性-选择性相互制约的问题。","scd":null,"kp":["电催化平台[KA油电化学氧化升级合成己二酸]: 整合式α-FeOOH/N催化剂体系","技术挑战[KA油电氧化]: O2利用率低、析氧反应和电位下催化剂迅速钝化导致的活性-稳定性-选择性权衡"]},{"i":35264,"as":"研究将近零指数（NZI）介质中的超耦合现象扩展至复杂网络结构中，揭示了电磁功率流遵循由边界条件和阻抗对比决定的被动、确定性及准静态分布规律。在完美导体（PEC）终端的分支中没有传播的功率流。研究人员借助压力驱动流体类比解释了这一现象，并在带有光子掺杂的波导模拟等离激元平台上进行了直观可视化。该准静态功率流分布遵循电磁理想流体的“欧姆定律”。","scd":null,"kp":["电磁传输特性[复杂近零指数网络]: 由边界条件和阻抗支配的被动、确定性、准静态功率流分布","超耦合特性[NZI介质]: 具有近零相位延迟的几何不敏感电磁传输"]},{"i":35265,"as":"研究人员开发了micDROP合成系统，以系统性地表征天然多价内在无序区（IDRs）的相互作用及其介导自特异性分配的能力。研究发现，能发生相分离的天然IDR在体内的饱和浓度与其序列的总“粘性”呈正相关。该研究揭示了IDR通过其序列编码的相互作用网络驱动生物分子凝聚物形成的机制，为解答无固定三维结构的无序蛋白如何控制细胞内无膜细胞器的空间特异性提供了关键实验依据。","scd":null,"kp":["[内在无序区(IDRs)生物分子凝聚体形成]: IDR-IDR相互作用呈现出驱动相分离的兼容性(Promiscuity)特征"]},{"i":35266,"as":"研究报道了一种由光激发驱动的吸附模式。在金属酞菁钾（KPc）与还原氧化石墨烯（RG）组成的复合材料中，紫外光照射促使复合材料内的激发电子从KPc高效转移至RG，在KPc上留下长寿命的激发态空穴，从而实现对一氧化碳（CO）分子的选择性吸附。在暗态下，该复合材料的CO吸附量仅为0.06 mmol/g；而在紫外光照射下，其CO吸附量大幅增加至1.20 mmol/g。","scd":null,"kp":["吸附模式[激发态驱动]: 紫外光辐照下激发态电子驱动的非常规吸附模式","吸附材料[激发态吸附]: 钾酞菁/还原氧化石墨烯(KPc/RG)复合材料"]},{"i":35267,"as":"针对水系锌电池中因缺乏专门的成核理论而难以抑制析氢反应和枝晶生长的问题，研究修正了传统基于锂的球形成核模型。传统模型忽略了锌的晶体学特征和控制成核的界面电阻。该研究重新推导了基于锌密排六方结构的经典成核理论，并建立了一个无量纲因子来量化和调节锌水界面的电化学行为，为解决水系锌电池界面问题提供了专门的理论描述符。","scd":null,"kp":["[水系锌电池界面电化学]: 引入无量纲因子以量化锌特异性成核理论，从而调节界面电化学并抑制析氢和枝晶"]},{"i":35268,"as":"研究结合地震观测与数值地幔流模型，探讨了南海作为西太平洋最大边缘海的大陆裂谷动力学机制。观测揭示了南海北缘从早古新世分布式伸展到晚古新世超伸展的系统性西向裂谷扩展。数值模型预测了东南亚下方存在西南向的太平洋地幔流，并在西部与特提斯/欧亚地幔流汇聚。这种地幔汇聚流动与裂谷向西迁移动力学一致，且西南方向沃顿洋脊的俯冲可能进一步增强了地幔流动。","scd":null,"kp":["[南海北部大陆边缘裂谷过程]: 从古新世早期分布式拉伸到古新世晚期超拉伸的系统性向西裂谷传播"]},{"i":35269,"as":"研究构建了一个将交通基础设施分段与气象网格相连接的地理空间框架，量化了中国道路和铁路沿线部署路边光伏（PV）的潜力。该框架映射了480,019公里的交通网络，避免了粗略的区域平均计算。分析表明，路边光伏系统可支持40.91至202.84 GW的装机容量，年发电量达56.6至239.2太瓦时。在基准情景下，其年发电量约占当前交通部门电力需求的50%，具有显著的交通脱碳和碳减排潜力。","scd":null,"kp":["交通基础设施规模[全国路边光伏潜力评估]: 480,019公里","气象网格映射[路边光伏部署]: 4,133个气象网格"]},{"i":35270,"as":"","scd":null,"kp":[]},{"i":35271,"as":"研究开发了名为GANBase的基因组引导生成对抗学习框架，旨在解决纳米孔自适应测序中现有深度学习方法高度依赖特定且昂贵的实验训练数据的问题。该框架完全基于参考序列进行训练，并集成了基于蒙特卡洛树搜索的Rollout策略。实验证明，GANBase在靶标富集和宿主核酸剔除中表现出色，且在发生严重孔损耗或流通池版本更新时依然有效，提供了一种独立于实验数据的实时靶向测序解决方案。","scd":null,"kp":["[纳米孔自适应测序]: 开发基于基因组指导的生成对抗学习框架(GANBase)，通过蒙特卡洛树搜索策略实现无需样本特异性训练数据的靶向富集"]},{"i":35272,"as":"研究介绍了一个名为MINTsC的框架，用于从单细胞高通量染色质构象捕获（scHi-C）数据中学习多向染色质相互作用。传统分析方法多局限于推断染色体结构或成对相互作用，忽视了基因组元件之间的复杂多向关联。MINTsC基于Dirichlet-多项式样条模型构建，通过聚合特定细胞背景下的成对相互作用，并利用成对检验统计量的次序统计量进行汇总，成功提取并计算得到多向染色质相互作用评分。","scd":null,"kp":["[分析模型]: MINTsC可从单细胞高吞吐量染色质构象数据中学习多向染色质相互作用"]},{"i":35273,"as":"","scd":null,"kp":[]},{"i":35274,"as":"","scd":null,"kp":[]},{"i":35275,"as":"研究发现在单链寡脱氧核苷酸上简单进行5'端花菁修饰，能够显著提升CRISPR-Cas9介导的同源定向修复（HDR）效率，并在多种人类干细胞模型中提供2到3倍的存活优势。在三维人类胚胎模型（胚状体）中，该化学修饰方法实现了高达30%的原位HDR效率，较未修饰的ssODNs提升了2.5至3倍，且不损害细胞生存力或发育潜力。机制上，这种HDR效率的提升与染色质调控和化学修饰诱导的上调有关。","scd":null,"kp":["存活优势[花青素修饰的ssODNs在人干细胞模型中]: 2-3倍","同源定向修复(HDR)效率[3D人类胚胎模型原位编辑]: 高达30%","[修饰策略]: 单链寡脱氧核苷酸(ssODNs)的5'端花青素修饰增强CRISPR-Cas9的HDR效率"]},{"i":35276,"as":"研究提出了一种名为ChargeDIFF的无机材料生成模型，通过显式结合电子结构来优化材料的逆向设计。不同于现有生成模型仅关注材料的几何结构，ChargeDIFF将直接反映材料电子结构的空间电荷密度作为额外模态引入生成过程中。这种设计弥补了电子行为对材料稳定性和功能性的基础性决定作用。在条件和非条件生成任务中，ChargeDIFF均展现出卓越的性能，有效提升了新晶体结构发现的准确性。","scd":null,"kp":["[生成模型特点]: ChargeDIFF模型通过引入显式电子结构来指导无机材料的生成式逆向设计"]},{"i":35277,"as":"","scd":null,"kp":[]},{"i":35278,"as":"研究成功制造出高性能的二维纳米带晶体管，其沟道宽度成功缩减至100纳米以下。这一突破有助于在极窄物理尺度下保持器件的高性能表现，推进了二维半导体材料在先进集成电路中的实际应用潜力。","scd":null,"kp":["沟道宽度[高性能2D纳米带晶体管]: 缩小至100 nm以下"]},{"i":35279,"as":"","scd":null,"kp":[]},{"i":35280,"as":"研究利用配位-重结晶策略结合氩气热解合成了Co1/C3N5单原子催化剂。在活化过一硫酸盐（PMS）的过程中，催化剂的Co–N2O1位点演变为Co–N1O2，这种反应诱导生成的位点促进了自旋选择匹配的PMS活化。该活化机制共生了硫酸根自由基（·SO4⁻）和单线态氧（1O2），表现出以单线态氧为主、自由基并行的氧化模式。在这一机制下，Co1/C3N5降解土霉素的伪一阶速率常数（kapp）提高了5.3倍。","scd":null,"kp":["催化剂[过氧单硫酸盐(PMS)活化]: Co1/C3N5单原子催化剂","配位环境演变[PMS活化诱导]: Co-N2O1位点演变为Co-N1O2位点","[催化机制]: 反应诱导的Co-N1O2位点实现自旋选择倾向的PMS活化与高效污染物降解"]},{"i":35281,"as":"研究提出了一种在排斥性电子-电子相互作用下，仅依赖三维立方晶格对称性即可实现外尔拓扑超导态（TSC）的普适且鲁棒的机制。通过群论和金兹堡-朗道分析表明，将由排斥相互作用驱动的二维方格子上d(x²-y²)波配对推广至三维立方晶格时，会自然产生手性d(3z²-r²)+id(x²-y²)态。这种状态不同于px+ipy等传统的破坏时间反演对称性的配对形式，为探索具有点节点能隙和Bogoliubov-Majorana费米弧的超导态提供了新途径。","scd":null,"kp":["[机制特点]: 提出一种无需复杂能带结构或精细调节自旋轨道耦合，仅依赖排斥性电子-电子相互作用与3D立方晶格对称性即可产生Weyl拓扑超导态的普适机制"]},{"i":35282,"as":"","scd":null,"kp":[]},{"i":35283,"as":"","scd":null,"kp":[]},{"i":35284,"as":"","scd":null,"kp":[]},{"i":35285,"as":"人工智能技术对社会科学领域的影响具有两面性。一方面，该技术可能生成虚假的研究结果并污染问卷等调查数据；另一方面，它也具备促进社会科学研究流程更加严谨的潜力，引发学界对其是否会颠覆社会科学的广泛探讨。","scd":null,"kp":[]},{"i":35286,"as":"","scd":null,"kp":[]},{"i":35287,"as":"","scd":null,"kp":[]},{"i":35288,"as":"","scd":null,"kp":[]},{"i":35289,"as":"","scd":null,"kp":[]},{"i":35290,"as":"","scd":null,"kp":[]},{"i":35291,"as":"","scd":null,"kp":[]},{"i":35292,"as":"","scd":null,"kp":[]},{"i":35293,"as":"大规模的大气测量结果显示，大气中氢氟烯烃（hydrofluoroolefins）的水平正在上升。这类化学物质原本被认为是环保的，但其在高空大气中积累上升所带来的具体影响和后果目前尚不明确。","scd":null,"kp":["[观测特征]: 大气中生态友好型氢氟烯烃的浓度水平呈上升趋势"]},{"i":35294,"as":"","scd":null,"kp":[]},{"i":35295,"as":"","scd":null,"kp":[]},{"i":35296,"as":"","scd":null,"kp":[]},{"i":35297,"as":"","scd":null,"kp":[]},{"i":35298,"as":"","scd":null,"kp":[]},{"i":35299,"as":"Smitakshi Goswami 解释了如何利用微光致发光光谱技术研究用于清洁能源技术的新兴半导体中的电荷复合现象。该技术能够有效照亮并分析局部光电景观，为半导体材料的微观光电特性研究提供支持。","scd":null,"kp":["[表征技术]: 显微光致发光光谱可用于研究清洁能源半导体技术中的电荷复合"]},{"i":35300,"as":"研究团队报告了一种采用自上而下多图案化工艺制造的 monolayer 2DS 纳米带晶体管，支持n型和p型操作。该工艺使用“锚定”触点限制纳米带剥离，实现了低至25-30纳米的沟道长度和宽度，并通过纳米级表征证实了最小的边缘退化。结合薄的高k栅极电介质，器件在特定漏源电压下分别实现了高达560、420和130 µA µm−1的导通电流。","scd":null,"kp":["半导体厚度[单层2DS纳米带晶体管]: 具备极限厚度","[制备工艺]: 采用包含“锚定”接触的自上而下多重图案化工艺限制纳米带剥离","[器件性能]: 实现了具有n型和p型操作的单层二维半导体纳米带晶体管"]},{"i":35301,"as":"研究利用天气监视雷达网络量化了西欧夜间和年度大规模鸟类运动的数量、时间和空间范围，并结合风力涡轮机特征及风力分布数据评估了潜在能源产量。通过整合鸟类移动模式、涡轮机特性和能源生产模型，研究估算了因在旋转叶片高度附近飞行而面临碰撞风险的鸟类数量，旨在为风力发电的生态影响提供数据支持。","scd":null,"kp":["[鸟类迁徙与风电影响评估]: 利用天气监视雷达网络量化并绘制西欧地区鸟类大规模夜间和年度运动的数量、时间及空间范围，并计算陆上风力涡轮机的潜在影响"]},{"i":35302,"as":"研究开发了一种名为NPCbots的生物混合微型机器人，通过将人类诱导多能干细胞衍生的神经祖细胞与磁电纳米粒子结合，实现了无线磁导航和无创神经元刺激。借助芯片实验室平台进行规模化制造，维持了细胞活力和分化能力。在斑马鱼脊髓损伤模型中，交变磁场刺激NPCbots诱导了体内快速的神经元和星形胶质细胞分化，克服了传统神经元再生能力受限的挑战。","scd":null,"kp":["[神经再生治疗微纳机器人]: 基于人类诱导多能干细胞衍生的神经祖细胞与磁电纳米颗粒集成的生物混合微型机器人(NPCbots)，实现无线磁导航"]},{"i":35303,"as":"研究设计了金属有机框架MUV-1001(Fe)作为自包含的光氧化还原催化剂，将所有关键功能集成在其金属簇中，成功在固体材料中实现光催化。该催化剂无需添加剂或贵金属即可实现光驱动的碳-碳键形成反应。这项工作确立了通过对金属簇成分的精确控制，将光氧化还原化学转化为可编程多孔架构的通用策略。","scd":null,"kp":["[固态光氧化还原催化]: 将所有关键催化功能整合至金属有机框架MUV-1001(Fe)的金属簇中，实现无添加剂或贵金属的光驱动碳-碳键形成反应"]},{"i":35304,"as":"研究发现GaSe单晶在沿倾斜于[0001]晶带轴的方向加载时，展现出优异的拉伸延展性，实现了超过40%的均匀拉伸伸长率和显著的应变硬化。原子级应力定量实验揭示了一种非局域层间剪切机制，相邻范德华层之间的交替滑移均化了拉伸应变并抑制了局部化。这种协同滑移过程驱动了ε到γ相变，并引入了受限的滑移路径。","scd":null,"kp":["均匀拉伸伸长率[沿倾斜于GaSe单晶[0001]晶带轴的加载方向]: 超过40%","[范德华半导体]: 具有显著的应变硬化能力"]},{"i":35305,"as":"针对耐甲氧西林金黄色葡萄球菌（MRSA）感染的糖尿病足溃疡难以愈合的问题，研究开发了一种自级联降糖免疫调节水凝胶。该水凝胶整合了Fe3O4纳米颗粒，不仅能够消除活细菌，还能中和细菌死亡后释放的病原体相关分子模式，从而抑制NF-κB/NLRP3通路的持续激活，重塑再生型创面微环境，解决现有抗菌策略忽略炎症中和的痛点。","scd":null,"kp":["[感染性糖尿病创口修复]: 开发自级联免疫调节水凝胶，通过消除细菌释放的病原体相关分子模式来抑制NF-κB/NLRP3的持续激活，重塑MRSA感染的糖尿病足溃疡微环境"]},{"i":35306,"as":"研究报道了一种通过螺噻喃（STP）与聚二硫化合物在白光（λ>400 nm）照射下发生加成反应，直接重构聚合物网络的新策略。光照使STP异构化暴露出活性烯烃部分，同时聚二硫化合物主链离解成硫中心自由基，两者快速发生硫醇-烯偶联建立动态C-S键。该技术避免了传统高能紫外线照射引发的材料降解问题，提供了一种非侵入式的聚合物再加工和回收方法。","scd":null,"kp":["[动态共价聚合物网络重构]: 利用白光激活螺硫代吡喃(STP)与聚二硫化物之间的加成反应，避免传统高能紫外线造成的材料降解"]},{"i":35307,"as":"研究通过在中心对称的范德华磁体中使用飞秒激光激发，成功展示了广泛的不同形态的偶极斯格明子袋（Skyrmion bags）。以往实验大多局限于基于Dzyaloshinskii-Moriya相互作用（DMI）的系统，且对特定斯格明子袋形态的实验获取十分稀缺。该成果突破了这一限制，为拓扑磁性材料及自旋电子学应用提供了新的实验途径。","scd":null,"kp":["[范德华磁性材料拓扑自旋电子学]: 在中心对称范德华磁体中观察到具有任意拓扑电荷和内部形态的偶极斯格明子袋"]},{"i":35308,"as":"研究开发了一种基于树枝状脂肽（DLPs）的自组装纳米疫苗平台。DLPs通过将结构优化的脂质尾部连接到富含赖氨酸或精氨酸的第二代树枝状支架上，构建出具有显著增强TLR2/4激动剂活性的分子。该结构能在时间和空间上精确控制抗原递送和免疫刺激，促进抗原呈递细胞对抗原的摄取和交叉呈递，从而有效协调多种模式识别受体的激活并增强抗肿瘤免疫反应。","scd":null,"kp":["[树突状脂肽纳米疫苗]: 将结构优化的脂质尾基共价连接至富含赖氨酸或精氨酸的第二代树突状支架构建自组装纳米疫苗，实现多模式识别受体激活以增强抗肿瘤免疫"]},{"i":35309,"as":"针对高温高功率密度电子设备对聚合物电介质的需求，研究将手性分子（如R5011及其手性对映体S5011）引入聚醚酰亚胺中。这种手性诱导的扭曲超分子组装策略解决了传统分子半导体掺杂存在的分散性差、界面不相容及形成导电通路导致介电性能退化的问题。该方法显著提升了聚合物电介质在高温环境下的能量密度。","scd":null,"kp":["[高温聚合物电介质]: 通过手性诱导的扭曲超分子组装结构，解决分子半导体掺杂分散性差的问题，在高温下实现超高能量密度"]},{"i":35310,"as":"文章综述了超薄锂金属（≤15 µm）负极的定量设计原则及其在液态和固态电池制造中的关键作用。针对锂金属在机械轧制过程中因粘性和脆性导致的减薄挑战，文章指出当前过度依赖厚锂箔造成的资源浪费，并阐述了超薄锂负极在实现高能量密度锂电池真正潜力方面的重要性，同时介绍了相关的制造策略。","scd":null,"kp":["[超薄锂金属负极]: 针对机械辊压过程中的粘性和脆性限制，提出跨越液态和固态电池的超薄锂金属负极定量设计原则以提高高能量密度锂电池的实用性"]},{"i":35311,"as":"飞行时间二次离子质谱法已成为表征电池材料复杂表面和界面化学的关键分析技术。该技术具备超高表面灵敏度、高空间分辨率（横向<50 nm，深度<1 nm）以及高质量分辨率。这些优势使其能够精确多维度地表征电极-电解质界面（EEIs），在纳米尺度上解析EEIs的组成和结构，并追踪界面演变。","scd":null,"kp":["表面灵敏度[飞行时间二次离子质谱分析]: ppm-ppb","横向空间分辨率[ToF-SIMS]: < 50 nm","深度分辨率[ToF-SIMS]: < 1 nm"]},{"i":35312,"as":"研究在双面单结钙钛矿光伏器件中引入了一种吸收-传输可重构的2D/3D/2D架构。该设计利用二维钙钛矿钝化层的寄生吸收，实现了高能蓝紫光子与低能绿光至近红外光子的光谱吸收分离。这种架构不仅能够实现高效的双面运行，还具备近全方位的光谱适应性，克服了传统多端子叠层配置复杂且实施要求高的问题。","scd":null,"kp":["[吸收-传输可重构架构]: 实现双面单结钙钛矿光伏器件的多光谱自适应"]},{"i":35313,"as":"电催化二氧化碳还原（CO2RR）可将二氧化碳转化为燃料和高附加值化学品。实现高活性和高稳定性的CO2RR仍面临挑战。除催化剂设计外，界面水的作用不可忽视。界面水作为主要质子供体，直接影响二氧化碳还原与析氢反应的竞争。界面水的动态氢键网络对反应过程也具有关键影响。","scd":null,"kp":["[电催化CO2还原界面水工程]: 通过分子级理解调控界面水分子结构以提升催化活性和稳定性"]},{"i":35314,"as":"研究提出一种在脂肪族聚酯中实现本征激发依赖性余辉发光的普适策略。通过与偏硼酸杂化，利用制造过程中形成的不同尺寸簇，将激发源从254纳米调节至405纳米时，余辉峰会发生从431纳米到540纳米的位移。此外，通过掺杂商业染料引发三重态至单重态的福斯特共振能量转移（TS-FRET），余辉发射颜色可从深蓝色调至红色。该技术在6D动态加密领域具有应用潜力。","scd":null,"kp":["余辉发射峰[脂肪族聚酯/偏硼酸杂化激发]: 431-540 nm"]},{"i":35315,"as":"研究证明二维电化学电池（硼烯/六方氮化硼/石墨烯）具有集体离子本征模式。当受到10 kHz的“临界频率”电脉冲共振激发时，离子传导从扩散漂移转变为相干弹道波。时间分辨泵浦-探测光谱直接观测到强烈的28 THz振荡，证实了亚皮秒级波状运动。整个嵌入的离子系综同相运动，在不到300飞秒的时间内以相干波包的形式穿过80纳米通道。","scd":null,"kp":["临界激发频率[二维电化学电池离子相干控制]: 10 kHz","[二维电化学电池]: 硼烯/六方氮化硼/石墨烯","[离子传导模式]: 在共振激发下从扩散漂移转变为相干弹道波"]},{"i":35316,"as":"","scd":null,"kp":[]},{"i":35317,"as":"","scd":null,"kp":[]},{"i":35318,"as":"","scd":null,"kp":[]},{"i":35319,"as":"","scd":null,"kp":[]},{"i":35320,"as":"塑料单体对苯二甲酸（TPA）对微生物具有内在毒性。研究结合全基因组化学基因组分析、转录组和生理学分析，界定了酿酒酵母中TPA毒性的细胞学基础。研究发现，参与苏氨酸生物合成和葡萄糖代谢的磷酸依赖性酶与酵母在TPA环境中的存活密切相关。数据证明，TPA会重编程酵母的磷酸盐代谢网络，揭示了塑料单体毒性的分子机制。","scd":null,"kp":["[酵母菌对对苯二甲酸的毒性响应]: 激发磷酸盐代谢重编程机制"]},{"i":35321,"as":"","scd":null,"kp":[]},{"i":35322,"as":"","scd":null,"kp":[]},{"i":35323,"as":"","scd":null,"kp":[]},{"i":35324,"as":"","scd":null,"kp":[]},{"i":35325,"as":"","scd":null,"kp":[]},{"i":35326,"as":"研究采用物理信息训练数据生成策略，开发了可跨层数和堆叠配置迁移的机器学习力场。应用于多层扭曲MoTe2（tMoTe2）时，发现了结构和电子分层现象：两个莫尔界面层在厚层中保留大量晶格重构，而外部的类体层畸变迅速衰减。令人意外的是，这种分层效应在超小扭转角（≤1°）下并非最强，其能带重排在中等扭转角下更为显著。","scd":null,"kp":["[多层扭曲MoTe2]: 呈现层状分层与能带重排效应"]},{"i":35327,"as":"","scd":null,"kp":[]},{"i":35328,"as":"研究构建了在碲纳米棒上生长的超薄二碲化铂（PtTe2）纳米壳结构，用作直接甲醇燃料电池的高效电催化剂。这种独特的核壳结构暴露了大量活性边缘位点，在铂负载量仅为5 wt.%的低水平下实现了极高的铂利用率。其峰值质量活性约为3.4 A mgPt⁻¹，分别是商业Pt/C和PtRu/C（20 wt.% Pt）的16倍和6倍以上。","scd":null,"kp":["催化剂[直接甲醇燃料电池高效转化]: Te@PtTe2核壳结构 (Te纳米棒上生长的超薄PtTe2纳米壳)"]},{"i":35329,"as":"研究开发了一种利用光热增强的热电化学电池（PTEC）以实现低品位废热（<100°C）的被动稳定收集。该器件结合了含胍增强铁/亚铁氰化物氧化还原对的高离子导电双网络水凝胶电解质，以及光热碳电极和准固态结构。无需主动冷却或液态电解质，PTEC在热和太阳能激发下即可建立稳定温度梯度，瞬时热电势达到4.5 mV K⁻¹。","scd":null,"kp":["工作温度范围[低品位废热热电化学电池]: <100°C","[光热增强热电化学电池]: 采用高离子导电双网络水凝胶电解质并结合胍促进的铁/铁氰化物氧化还原对"]},{"i":35330,"as":"在二维受限空间内，由于水分子与MXene表面氧末端形成强氢键导致质子被固定，从而阻碍电荷存储动力学。研究提出边缘配位策略，将羧基功能化碳量子点锚定在带正电的边缘，实现了对Ti3C2Tx MXene的电子离域精准调控。这种电子离域-限域耦合效应能够有效调节界面氢键网络，从而实现超快质子传输。","scd":null,"kp":["[MXene边缘配位策略]: 通过电子离域-限制耦合实现氢键网络调控，促进超快质子传输"]},{"i":35331,"as":"可逆质子陶瓷电池（RPCCs）空气电极的开发常受限于电催化活性与操作稳定性之间的固有权衡。研究采用双掺杂策略，将钛和铌共掺杂入PrBaCo2O5+δ中，开发出一种新型三重传导（H⁺/O²⁻/e⁻）钙钛矿空气电极（PrBaCo1.8Ti0.1Nb0.1O5+δ）。该设计平衡了电化学性能与耐久性，有效解决了传统电极材料活性与稳定性难以兼顾的挑战。","scd":null,"kp":["双掺杂策略[可逆质子陶瓷电池空气电极]: Ti和Nb掺杂PrBaCo2O5+δ形成新型三导体(H+/O2-/e-)"]},{"i":35332,"as":"绝缘的碱式硫酸锌的沉积阻碍了安时级水系锌锰 dioxide（MnO2）电池的实际应用。在放大系统中，由于添加剂消耗不均匀，传统的抑制ZHS策略效果有限。研究提出从抑制ZHS形成转向形态管理的范式转变。通过集成阴极设计实现开放结构的ZHS生成，使Ah级锌锰电池具备高度可逆性。完全消除ZHS既不切实际也无必要，形态控制成为关键。","scd":null,"kp":["集成阴极设计[安时级水系Zn-MnO2电池]: 形成开放结构的硫酸羟锌以抑制绝缘沉积并实现高可逆性"]},{"i":35333,"as":"研究人员利用CO气体介导合成了钯纳米片，并首次通过快速CO2激光照射（10分钟内）将NiMo双原子二聚体固定在钯纳米片上。该催化剂平台在乙二醇氧化反应中表现出增强的活性和依赖于电位的产物选择性。在1.0V（相对于RHE）下，通过选择性C─H键断裂生成乙醇酸（C2产物），其法拉第效率达到81%，产率为1.14 mmol h⁻¹ cm⁻²。","scd":null,"kp":["合成工艺[NiMo双原子二聚体催化剂制备]: CO2激光快速辐照法","辐照时间[NiMo-DA/PdNS制备]: 10分钟内","催化体系[乙二醇氧化反应(EGOR)]: NiMo双原子二聚体负载于钯纳米片(PdNS)"]},{"i":35334,"as":"水系锌碘电池面临多碘化物穿梭和锌负极不稳定的难题。研究提出一种全MXene协同策略，利用HF蒸汽刻蚀合成的富氟MXene（Nb2C-F和V2C-F）同时改造正负极。Nb2C-F作为碘宿主，其扩张的层间通道与氟化物纳米域可有效固定多碘化物，并催化碘的氧化还原反应，从而抑制穿梭效应并稳定锌沉积。","scd":null,"kp":["电极协同设计[水系Zn-I2电池]: 采用全MXene协同策略(富氟MXene)共工程化正负极以解决多碘化物穿梭和不稳定锌沉积"]},{"i":35335,"as":"为提升锂金属电池负极稳定性，研究提出将掺氟碳酸氧铋（F-BOC）与金属锂热熔合，构建具有亲锂性的非均相人工固体电解质界面（ASEI）。氟的引入增强了F-BOC对锂的吸附能力，并形成各向同性且致密的结构。该界面层作为整流器调控锂离子的沉积与剥离，有效阻挡TFSI⁻阴离子，实现了无枝晶的锂沉积，并应用于首个安时级氟化物转化软包电池。","scd":null,"kp":["热融合工艺[金属锂负极SEI构建]: 掺氟Bi2O2CO3(F-BOC)与锂金属热融合形成亲锂异质SEI","电池体系[无枝晶锂沉积]: 首个实现氟化转化的安时级软包电池"]},{"i":35336,"as":"研究发现了几何受挫的 spin glass （自旋玻璃）金属间化合物（Mn32Co5In15）具有巨大的交换偏置效应（约0.3 T）。通过工程化构建高密度相干界面实现了这一特性。该材料具有三维交错结构，克服了传统自旋玻璃系统交换偏置响应微弱的缺陷，为下一代自旋电子器件提供了潜在的候选材料。","scd":null,"kp":["材料特性[几何受挫自旋玻璃系统]: 通过高密度相干化学界面产生超大交换偏置效应"]},{"i":35337,"as":"二维纳米机电系统（NEMS）的谐振频率极易受温度变化引起的热膨胀影响。研究人员利用二维材料的层间自由度，设计了石墨烯与二硫化钼（MoS2）的范德华异质结构。这种人工设计的二维复合材料的熱膨胀系数可被精确调控，从而克服了材料固有的热频敏效应，为开发对温度稳定且高精度的纳米力学压力传感器奠定了基础。","scd":null,"kp":["材料设计[二维复合NEMS压力传感器]: 人工设计具有定制热膨胀系数的2D复合材料以实现温度稳定和精确的纳米机械传感"]},{"i":35338,"as":"研究证实了准二维钙钛矿太阳能电池在真实空间环境中的适用性。在近地轨道的实际太空条件下，刚性准二维钙钛矿太阳能电池稳定输出电力超过100天。在轨数据与地面热及质子辐照研究表明，该类电池具备高本征辐射耐受性，但也发现了基板引起的性能损耗。该成果揭示了钙钛矿空间光伏技术轻量化的关键挑战及潜力。","scd":null,"kp":["稳定运行时间[近地轨道实际太空环境下的准二维钙钛矿太阳能电池]: 超过100天","核心特性[准二维钙钛矿太阳能电池空间应用]: 具有高本征辐射耐受性"]},{"i":35339,"as":"为解决全聚合物水系准固态电池中电化学窗口窄和形变下界面不稳定的问题，研究人员开发了一种“网络中水”（WIN）电解质。通过调节聚合物网络的交联密度来精确控制水的活性和动力学，发现了水活度对交联密度呈非单调依赖的“水约束”效应。该界面互锁机制有效提升了电池在可穿戴电子设备中的结构稳定性与能量表现。","scd":null,"kp":["电解质设计[全聚合物纤维电池]: 界面互锁的网络中水型电解质(Water-In-Network Electrolytes)"]},{"i":35340,"as":"针对有机光伏电池（OPV）中有机给体和空穴传输层固有的稳定性问题，研究采用无机p型半导体硫氰酸亚铜（CuSCN）同时作为给体和空穴传输层。结合非富勒烯受体L8-BO，体异质结器件实现了7.21%的最高光电转换效率。更重要的是，该器件表现出卓越的热稳定性，在85°C下运行近400小时后仍能保持初始效率的80%。","scd":null,"kp":["光电器件[无共轭给体的有机光伏电池]: 采用无机p型半导体硫氰酸亚铜作为给体和空穴传输层","转换效率[传统有机光伏体系]: 超过20%"]},{"i":35341,"as":"插层过渡金属硫族化物Co1/3TaS2的三重Q非共面反铁磁态中存在电子向列相。研究在磁阻和磁转矩中观察到了旋转磁滞，揭示了三重Q相中存在强烈钉扎的面内弱铁磁矩。实验证明，共存的电子向列相是由磁性驱动的。该向列相具有场可调性和应变可调性，在自旋电子学应用中极具潜力。","scd":null,"kp":["磁性态[Co1/3TaS2的3Q非共面反铁磁相]: 具有弱面内铁磁性与电子向列序（打破三重旋转对称性）","电子向列序[外加磁场/应变]: 具备高度可调谐性"]},{"i":35342,"as":"两性离子聚合物是一类结构单元中带有等量正负电荷的高分子材料，通过离子溶剂化作用产生强烈的水合效应。这赋予了其抗蛋白质吸附、抗细胞粘附、有效界面润滑、增强药物稳定性和抗冻等独特性质。文章综述了两性离子聚合物的合成、结构和生物医学应用，强调其生物医学性能不仅取决于材料类型，还与分子结构息息相关。","scd":null,"kp":["两性离子聚合物[等量正负电荷基团]: 产生强水合效应，具备抗蛋白吸附、抗细胞黏附、界面润滑、药物稳定性增强及防冻等特性"]},{"i":35343,"as":"自组装单分子层（SAMs）是倒置钙钛矿太阳能电池的关键空穴接触材料，但在溶液加工中易发生脱附和聚集。研究提出一种基于挥发性丙胺氯化物的瞬态二维钙钛矿保护策略。该物质在沉积过程中暂时保护SAMs免受溶剂降解，并在热退火过程中解耦，保持了SAM界面的完整性，实现了大面积钙钛ite薄膜均匀结晶。最终器件在0.05 cm²面积上实现了26.14%的光电转换效率。","scd":null,"kp":["自组装单分子层[倒置钙钛矿电池空穴选择性接触]: 易在溶液法制备过程中发生脱附与聚集","[2D钙钛矿保护策略]: 使用挥发性丙胺盐酸盐暂时屏蔽溶剂降解并在后续解耦"]},{"i":35344,"as":"针对传统钙钛矿溶液法和气相法使用有毒溶剂且浪费材料的问题，研究开发了一种温度场驱动的定向空间限域熔融结晶策略。该技术避免了有毒溶剂，成功制备出高结晶度、纯取向的二维钙钛矿单晶薄膜。这种长程有序的薄膜具有优异的光电特性，有效推动了高性能光电器件及光传感技术的发展。","scd":null,"kp":["[钙钛矿材料制备工艺]: 现有溶液法与气相法面临有毒溶剂和材料浪费问题","[温度场驱动定向空间限域结晶]: 实现钙钛矿熔体结晶以制备高性能光电器件"]},{"i":35345,"as":"常规面心立方铜纳米线常用于电催化二氧化碳还原，而非常规晶相铜在热力学上极不稳定。研究通过分析铜纳米线内的应变，揭示了铜从面心立方到体心四方/面心立方异质相的相变过程。系统研究证明，这种非常规体心四方晶相的铜纳米线在二氧化碳电催化还原转化为多碳产物的反应中，表现出更高的催化效率。","scd":null,"kp":["铜晶相[常规铜纳米线]: 面心立方(fcc)相","铜晶相[应变调控铜纳米线]: 非常规体心四方(bct)相","[非常规bct相铜纳米线]: 用于高效电催化CO2还原为多碳产物"]},{"i":35346,"as":"有机光伏电池的进一步发展受限于非辐射电压损耗。研究通过聚二甲基硅氧烷（PDMS）薄膜转移法制备了精确控制的给体/受体双层系统，系统探究了界面分子取向对电压损耗的内在作用。采用面内分子平行取向构型的器件有效抑制了非辐射电压损耗，打破了电压损失瓶颈，有助于提升有机光伏器件的整体能量转换效率。","scd":null,"kp":[]},{"i":35347,"as":"为了提升胶原蛋白基传感器的高拉伸性与长期稳定性，研究引入霍夫迈斯特离子工程直接调控原胶原分子的聚集结构。这种方法引发了从长程有序到无序的结构转变，制备出可拉伸的胶原蛋白离子凝胶。该材料兼具优异的机械拉伸性与稳定的电学性能，克服了传统分子级改性策略的局限，为可穿戴和植入式柔性传感器提供了理想材料。","scd":null,"kp":["[胶原蛋白离子凝胶]: 通过有序-无序转变实现高拉伸性、稳定电学与长期耐久性"]},{"i":35348,"as":"为实现氯气的绿色合成与能量存储，研究开发了一种锌-氧还原/氯气析出（Zn-ORR/CER）电池。该电池在放电时发生氧还原反应，充电时发生氯气析出反应，采用铁基有机金属框架作为高效的双功能电催化剂。该系统在腐蚀性反应条件下表现出稳定的电池性能，实现了废料修复、高附加值氯气生产和能量存储转换的“一石三鸟”策略。","scd":null,"kp":["[Zn-ORR/CER电池]: 放电时发生氧还原反应(ORR)，充电时发生析氯反应(CER)","催化剂[Zn-ORR/CER电池]: 铁基金属有机框架(Fe-MOF)"]},{"i":35349,"as":"研究开发了冰相光热镊子（IOT）平台，利用冰-水界面实现对异质微型和纳米结构的快速可编程操控。通过光热效应在冰基质中产生移动的微熔融区，能够以10-100 μm/s的速度和纳米级分辨率定向搬运介电或金属纳米颗粒、蛋白质、DNA甚至微气泡。该技术克服了布朗运动干扰，实现了跨材料兼容的多材料组装。","scd":null,"kp":["操控速度[冰相光热镊(IOT)]: 10–100 μm/s","[冰-水界面操控平台]: 可编程操纵介电/金属纳米粒子、蛋白质、DNA等异质目标"]},{"i":35350,"as":"自由基SAM酶Elp3能够催化tRNA反密码子上的关键修饰。研究结合结构分析与同位素掺入实验证实，Elp3内部含有一条保守的分子隧道，能将游离醋酸分子从其乙酰辅酶A结合域跨越20埃的距离穿梭运输至自由基SAM活性位点。这一过程完成了醋酸的自由基介导反应，对于调节密码子-反密码子相互作用和保证蛋白质翻译效率至关重要。","scd":null,"kp":["[Elp3(自由基SAM酶)]: 利用保守分子隧道在远距离活性位点间转运乙酸盐","催化产物[tRNA反密码子修饰]: 5-羧甲基尿苷(cm5U)"]},{"i":35351,"as":"选择性激活碳氟键一直是化学界的重大挑战。最新研究提出了一种由吡啶-硼基自由基介导的策略，成功实现了多氟芳烃的迭代碳氟键官能化。该方法能够选择性地断裂并转化第二个、第三个甚至第四个碳氟键，生成了多种具有高附加值的氟化分子骨架，在药物化学领域具有重要的应用价值。","scd":null,"kp":["活化策略[多氟代芳烃C-F键]: 吡啶-硼基自由基介导的迭代C-F键官能化","[C-F键转化]: 可实现对多氟代芳烃中第二、第三甚至第四个C-F键的选择性转化"]},{"i":35352,"as":"","scd":null,"kp":[]},{"i":35353,"as":"","scd":null,"kp":[]},{"i":35354,"as":"","scd":null,"kp":[]},{"i":35355,"as":"","scd":null,"kp":[]},{"i":35356,"as":"","scd":null,"kp":[]},{"i":35357,"as":"","scd":null,"kp":[]},{"i":35358,"as":"","scd":null,"kp":[]},{"i":35359,"as":"人类胚胎中的DNA双链断裂（DSB）修复机制尚不明确。研究表明，DSB引起的染色体改变具有不对称性：无着丝粒染色体臂表现出互补的增减，而有着丝粒的染色体臂偏向于丢失。着丝粒附近会发生严重的二次断裂和磨损，这阻碍了姐妹染色单体的分离，表明DSB会导致人类胚胎发育过程中的染色体进一步失稳。","scd":null,"kp":[]},{"i":35360,"as":"分布式声学传感（DAS）技术通过将光纤电缆转化为密集应变计阵列，为地震预警提供了一种低成本方案。针对DAS在方位角覆盖和震级评估方面的挑战，研究人员开发了一种机器学习方法。该方法利用集成决策树模型，基于钻孔应变计数据（震级3.5至7.1）进行训练。技术要点在于，无需确定地震位置，即可在P波到达后4秒内的应变波形中，准确区分中大型地震（M≥5.4）与小型地震。","scd":null,"kp":["监测技术[地震预警]: 分布式声学传感 (DAS) 将光纤电缆转化为密集应变计阵列","[震级估算]: 利用机器学习方法解决由应变测量估算震级的挑战"]},{"i":35361,"as":"","scd":null,"kp":[]},{"i":35362,"as":"对于微纳结构材料而言，同步表征其结构演化与力学行为是一项极具挑战性的工作。这凸显了发展和推进原位表征技术的迫切需求，以便能够深入观察和理解微观及纳米结构材料在受力过程中的微观结构变化与机械响应之间的内在联系。","scd":null,"kp":["表征技术[微/纳米结构材料]: 需要发展原位表征技术以解析结构演变与力学行为的对应关系"]},{"i":35363,"as":"为提高塑料包装废弃物的回收率，除了源头分类外，混合废弃物后分拣被提出作为一种替代方案。研究基于单一物料回收设施的样本分析发现，源头分离和后分拣路径在包块纯度（即目标聚合物百分比）上表现相似。然而，后分拣得到的包块中含有更多的污染物。这表明尽管后分拣系统能够捕获大量废弃物，但在控制杂质污染方面仍面临挑战。","scd":null,"kp":["塑料回收[家庭废弃物管理]: 混合废弃物后分拣被提出作为一桶式替代方案以提高捕获率","[挑战]: 存在误投、不参与及污染等问题"]},{"i":35364,"as":"为解决痛风性关节炎难以治愈和反复发作的难题，研究人员开发了一种可植入的锰铂微型原电池（Mn@Pt micro-GC）。该系统利用铂的类尿酸酶活性降解沉积的单钠尿酸盐晶体，同时锰离子与氢气协同作用，有效逆转促炎微环境。此外，Mn@Pt微型原电池不仅能减少痛风相关的疼痛信号产生，还能有效抑制疼痛信号沿CXCL轴的传输，实现对骨-神经轴的双重沉默治疗。","scd":null,"kp":["植入式器件[痛风性关节炎治疗]: 锰铂微型原电池 (Mn@Pt micro-GC)","[作用机制]: 利用铂的类尿酸酶活性降解尿酸以沉默骨-神经轴"]},{"i":35365,"as":"研究团队利用兆电子伏特超快电子衍射技术，探究了典型过渡金属羰基化合物五羰基铁的光解离过程。通过分别追踪轴向和赤道方向的结构演化，研究提供了CO解离前核运动的原子级角分辨视图，并推断出激发态势能面的关键特征。研究还表明，在到达圆锥交叉点之前的振动耦合，通过Berry伪旋转机制促进了随机羰基配体的丢失。","scd":null,"kp":["表征技术[Fe(CO)5光解离]: 兆电子伏特超快电子衍射","[结构动力学]: 提供CO解离前核运动的原子级角分辨视角"]},{"i":35366,"as":"聚电解质弹性体作为固态单离子导体，具有无泄漏和机械弹性等优点，但现有材料的离子电导率较低（约10−3 mS cm−1），限制了其应用。为此，研究人员提出一种新的材料设计方法，通过引入结合了两个关键特征的固态添加剂来提升电导率：一是具有高介电常数，以增加解离离子密度；二是具有增塑效应，以提高离子迁移率，同时保持无泄漏运行。","scd":null,"kp":["离子电导率[现有聚电解质弹性体]: ~10⁻³ mS cm⁻¹","[材料设计[单离子导体]: 引入高介电增塑剂以提升离子电导率"]},{"i":35367,"as":"研究人员引入了一种用于评估通用人工智能（AGI）和超级人工智能（ASI）的全新度量标准——SuperARC。与依赖人类中心问题和模式匹配的测试不同，该测试基于算法信息理论（AIT）中的随机性和最优推断等基础数学领域。它利用独立于人类的通用原理，为模型抽象和预测提供了强大的计量框架。在应用于前沿模型时，领先的大型语言模型在多项任务中表现优异，但在复杂度增加时表现并不总是稳定。","scd":null,"kp":["评估测试[人工智能超级智能(ASI)]: SuperARC","[核心特征]: 基于随机性和最优推理的基础数学领域，不依赖以人类为中心的问题"]},{"i":35368,"as":"交流原生电池系统将电池从被动的直流能源重新定义为主动的能量处理平台。通过将可控的功率转换能力转移到电池模块或电池组内部，该系统能够实现内部交流波形合成、感知拓扑的电流路由、增强的状态可观测性、可控的应力重分布以及主动故障隔离。这一技术构建了一个融合电池、电力电子、嵌入式传感和实时控制的新架构设计空间，其实际应用受制于成本、可靠性及系统级的权衡。","scd":null,"kp":["电池架构[交流原生电池系统]: 将可控功率转换能力置于电池模块或电池组内部","[功能特征]: 实现内部交流波形合成、拓扑感知电流路由和主动故障隔离"]},{"i":35369,"as":"针对钙钛矿太阳能电池功能材料研发缓慢和依赖试错的问题，研究采用代理辅助多目标进化算法进行界面分子设计，以同时提升器件的效率和稳定性。该方法成功识别出新型分子，使钙钛矿太阳能电池达到了26.9%的光电转换效率，并展现出优异的热稳定性。该成果证实了人工智能在加速下一代能源技术功能材料发现方面的巨大潜力。","scd":null,"kp":["设计方法[钙钛矿太阳能电池空穴选择性接触层]: 代理辅助的多目标进化算法","光电转换效率[AI设计的新型分子界面]: 26.9%","稳定性[钙钛矿太阳能电池]: 具备极强的热稳定性"]},{"i":35370,"as":"研究报道了一种由机械力驱动的微生物自养生长机制，通过矿物的挠曲电效应将机械能转化为电能。在缺乏阳光和化学能源的条件下，机械力使挠曲性氧化锰纳米片弯曲产生自由电荷，沼泽红假单胞菌捕获并利用这些电荷维持生长。该过程通过构建基于氧化锰和电活性细菌的模型生物杂合系统得到验证，揭示了挠曲电效应作为微生物生命能源的潜力。","scd":null,"kp":["[微生物生长驱动机制]: 通过矿物的挠电效应将机械能转化为电能，支持无常规能源下的微生物自养生长"]},{"i":35371,"as":"研究提出了一种二维熔体生长方法，用于合成大面积、单晶有机-无机杂化钙钛矿薄膜。该方法结合了直拉法和布里奇曼法的特点，采用气-液-固工艺。具体而言，预沉积的无机NaxPbBry种子层与有机前驱体熔剂反应，生成二维熔体相。该熔体相随后铺展成二维液膜，实现了与基底无关的结晶过程，能够对超薄薄膜进行精确的厚度控制和均匀的大规模结晶。","scd":null,"kp":["合成工艺[混合有机-无机钙钛矿单晶薄膜]: 结合提拉法和布里奇曼法的二维熔体生长法，采用气-液-固过程","[薄膜结晶特性]: 与基底无关且厚度可精确控制"]},{"i":35372,"as":"量子随机存取存储器（QRAM）是许多量子算法高效运行的关键构建模块，但其极高的资源需求，尤其是在量子纠错方案中，阻碍了物理实现。研究将实现QRAM的挑战完全转化为状态准备问题：由于该资源态独立于存储器，可以对其进行离线准备。研究还引入了“QRAM工厂”的概念，能够实现 heralding 功能，从而显著提升查询保真度并降低容错开销。","scd":null,"kp":["[量子随机存取存储器(QRAM)]: 采用资源态机制，以实现快速且支持量子纠错的查询，克服庞大的资源开销"]},{"i":35373,"as":"针对中红外光谱区域对高分辨率、微型化光谱仪的需求，研究提出了一种基于微腔耦合光子晶体波导（MPCW）架构的光子光谱仪原型。该器件通过协同整合非均匀微腔共振和尖锐的光子晶体能带边缘，实现了独特的光谱响应。借助慢光效应，钛微加热器提供了有效的热光调谐。该计算光谱仪结合了硅光子学技术和计算重构算法，为化学传感等应用提供了紧凑轻便的解决方案。","scd":null,"kp":["[中红外计算光谱仪]: 基于微腔耦合光子晶体波导协同作用的片上原型，实现高分辨率、微型化和便携性"]},{"i":35374,"as":"利用单分子追踪技术，研究揭示了带电纳米颗粒在油水界面的扩散行为不仅表现出异常扩散，还呈现出与玻璃态无关的扩散老化现象。研究开发了定量复现这些实验观察的理论框架，分子动力学模拟进一步表明，要使这种扩散老化现象出现，颗粒间吸引和排斥作用的共存是必要条件。这些发现深化了对乳液稳定化和泡沫制备等底层技术的物理认识。","scd":null,"kp":["[带电纳米粒子在水油界面的扩散行为]: 表现出反常扩散并呈现扩散老化现象"]},{"i":35375,"as":"为解决类脑脉冲神经硬件在光强范围扩大时自适应灵敏度受限的挑战，研究人员构建了基于单晶体管-单忆阻器像素结构的神经形态视觉传感器。该传感器通过融合互补的超线性和亚线性编码，在宽强度范围内实现了高编码灵敏度。具体而言，超线性强度到脉冲的激发基于等离激元易失性Ag/hBN/Au忆阻器，在高亮度下具有高时间到首脉冲（TTFS）和速率编码灵敏度；而亚线性激发则基于二硫化钼突触器件。","scd":null,"kp":["像素结构[神经形态视觉传感器]: 单晶体管-单忆阻器结构","[宽光强范围]: 融合互补超线性机制实现高编码灵敏度"]},{"i":35376,"as":"针对刚性金属微球表面凹陷结构难以可控合成的难题，研究提出了一种在液滴蒸发过程中诱导和调节刚性微球表面凹陷的应力操纵策略。在机器学习的优化指导下，这种工程化的凹陷结构能够增强电磁系统中的磁性活性。其机制在于通过重编程磁畴来编排局部的能量重新分布和磁化，从而克服了传统热力学驱动机制中由各向异性表面能和晶体学限制带来的阻碍。","scd":null,"kp":["合成策略[刚性金属微球凹面结构]: 液滴蒸发过程中的应力操纵策略，摆脱传统热力学驱动机制的限制"]},{"i":35377,"as":"针对光子计算在多任务处理中面临的可扩展性瓶颈和高昂的重构成本，研究提出通过扩展网络宽度而非深度来规避限制的缩放范式。研究实现了一种可扩展的光子混合专家架构，其中并行的光子核心充当专家网络。PMoE通过将输入动态路由到这些专家，在不改变物理光学权重的情况下高效执行多任务工作负载。该团队还制造了集成PMoE芯片，展示了光子计算在人工智能应用中的高带宽和低能耗优势。","scd":null,"kp":["扩展范式[片上光子神经网络]: 通过增加网络宽度而非深度来规避光损耗和可扩展性瓶颈","[多任务架构]: 实现光子混合专家系统以解决多任务处理的高昂硬件和重构成本"]},{"i":35378,"as":"研究证明了在范德华铁电体CuInP2S6中，存在一种调节光铁电滞后的准粒子态。研究人员将“铁子”——一种携带偶极子的晶格振动的集体激发，确定为光学印记极化态的载体。在2.16 THz下的窄带共振铁子振荡表现出蝴蝶状的滞后现象，这与光电流滞后响应相对应，直接将铁子动力学与室温下依赖于极化的光电流保持联系起来。带隙以上光激发通过特定机制驱动了铁子的形成。","scd":null,"kp":["光铁电滞留机制[范德华CuInP2S6]: 由铁子（携带偶极子的晶格振动集体激发）作为光学印刻极化态的载体介导"]},{"i":35379,"as":"针对现有晶体材料性能预测方法难以捕捉其复杂几何与拓扑特征的挑战，研究提出了多视图几何图Transformer（MGT）模型。该模型联合建模了SE(3)不变的标量表示和SO(3)等变的方向表示，从而能够同时捕捉晶体结构中的旋转-平移不变性和旋转等变方向信息。此外，模型采用受混合专家机制启发的路由器作为关键集成机制，自适应地对这些互补嵌入进行加权，显著提升了大规模晶体材料性质预测的准确性。","scd":null,"kp":["[晶体材料性能预测]: 提出多视图几何图 transformer (MGT) 模型，联合建模 SE(3) 不变标量表示和 SO(3) 等变特征以捕捉复杂几何与拓扑特征"]},{"i":35380,"as":"提出了一种名为LG-Transformer的深度学习框架，旨在通过精确预测理化性质来加速绿色燃料设计。传统图神经网络仅处理原子-化学键分子图，而该框架采用对比学习技术构建分子间关系图，融合分子内外部信息，克服了现有模型泛化性和可解释性不足的问题，实现了多样化燃料理化性质的高效预测。","scd":null,"kp":["预测模型[燃料分子理化性质]: 基于内外与分子间信息交互的学习图变换器框架"]},{"i":35381,"as":"通过构建纳米金属界面并采用羟基亲和力调节策略，实现了普适pH条件下的高效二氧化碳电化学还原制乙醇。该策略使含羟基中间体远离界面水，从而促进乙醇生成。纳米钴/铜催化剂在碱性和酸性条件下的法拉第效率分别达到62.17%和45.32%，乙醇部分电流密度超过300 mA cm−2。","scd":null,"kp":["催化剂策略[电催化CO2还原至乙醇]: 构建纳米金属界面的羟基亲和力调节策略","[乙醇选择性核心机制]: 稳定含羟基中间体并使其远离界面水"]},{"i":35382,"as":"提出了一种基于磁控群集纳米探针的生物自适应表面增强拉曼光谱(SERS)平台。探针集成了磁性核心、金/银等离子体层和二氧化硅涂层，在磁场下可编程组装成链状结构，进而重组为动态群集。循环组装与拆卸过程生成了瞬态电磁热点，并通过对流流动主动富集目标分子，克服了活体检测中信号重现性差的问题。","scd":null,"kp":["SERS探针[活体检测]: 磁控自组装群集纳米探针","探针结构[活体动态检测]: 磁性核心、等离激元金银层与生物相容性二氧化硅涂层"]},{"i":35383,"as":"提出了一种正交接力催化机制，用于高效电化学合成乙醇。通过在铜催化剂中掺杂铅原子电子调谐，降低了关键中间体*CH2COH的加氢能垒；同时构建界面离聚物-催化剂异质结产生部分去溶剂化的铯阳离子，选择性稳定该中间体的碳氧键，抑制碳氧键断裂。该机制在降低加氢壁垒的同时抑制了副产物乙烯的生成。","scd":null,"kp":["催化剂调控[CO电合成乙醇]: 铅原子掺杂电子调节铜催化剂","[正交级联催化机制]: 降低氢化能垒并抑制碳氧键断裂"]},{"i":35384,"as":"开发了一种基于单腔双梳激光器的闭环双光子光刻平台，解决了三维纳米结构制造中可重复性差的问题。该系统利用双梳激光在加工时同时进行原位相位测量，频率达360赫兹。通过将实时相位数据输入动态模型，平台能够自动进行调制和纠错，有效预防了加工误差，取代了依赖电子显微镜的复杂事后检测。","scd":null,"kp":["制造分辨率[双光子光刻]: 100纳米","光刻系统[闭环高精度双光子光刻]: 单腔双梳激光器驱动"]},{"i":35385,"as":"研究发现超快激光脉冲可触发磁性材料磁矩的巨幅增加，颠覆了激光仅导致磁矩丧失的传统认知。利用紧束缚和时间依赖密度泛函理论证实，调节特定激光至二维磁性材料（如CrI3和CrSBr）的多数自旋导带，可引发高达33%（2 μB）的磁矩增幅。该机制源于自旋轨道诱导的价带自旋纹理与强场光脉冲相互作用导致的光学自旋翻转跃迁。","scd":null,"kp":["磁矩增幅[二维磁性材料CrI3]: 增加33%","磁矩绝对值[二维磁性材料CrI3]: 2 μB","[超大磁矩增加触发条件]: 超快激光调谐至多数自旋导带"]},{"i":35386,"as":"展示了一种基于单向纤维素纳米晶体(CNC)水凝胶的生物基可逆变色光学与传感器技术。将单向CNC水凝胶作为延迟层置于天然左旋手性向列相CNC薄膜上，可将其左旋反射转化为右旋反射。通过施加机械压力，这种右旋反射又能可逆地切换回左旋状态，实现了在可见光区域的机械响应手性光学反转。","scd":null,"kp":["光学特性[可见光波段手性调控]: 引入单向纤维素纳米晶体水凝胶实现天然左手性向右手性的可逆翻转"]},{"i":35387,"as":"探讨了微纳米尺度原位机械表征技术在新兴功能材料研究中的前沿应用。结合高时空分辨率的仪器（如电子显微镜、X射线成像和光声技术），研究人员能够深入分析低维材料、仿生材料及三维架构超材料的加工-结构-性能关系。此外，人工智能与机器学习技术的整合为材料原位机械性能分析提供了新方案。","scd":null,"kp":["表征技术[功能与架构材料]: 配备极高空間和时间分辨率的电子显微镜、X射线成像与光声技术"]},{"i":35388,"as":"揭示了海上风电场基础设施引发的湍流对海床沉积物的强烈动员作用。实验室数据表明，单桩尾流产生的近床湍流能在其17倍直径的下游处动员沙粒，且海床形态的形成与尾流的三维下洗结构空间重合。研究提出了一种预测方法，证明单桩尾流引起的三维尾流结构不仅塑造了海床，还显著增强了沉积物的流动性。","scd":null,"kp":["海底泥沙扰动机制[海上风电单桩尾流]: 单桩尾流引起的近床面湍流增强了海底沉积物的活动性"]},{"i":35389,"as":"","scd":null,"kp":[]},{"i":35390,"as":"","scd":null,"kp":[]},{"i":35391,"as":"","scd":null,"kp":[]},{"i":35392,"as":"微软宣布升级其量子计算芯片，致力于开发可扩展速度超越竞争技术的“拓扑”量子计算机。尽管微软宣称该技术将加速商业化进程，但科学界对此仍持谨慎和怀疑态度。","scd":null,"kp":["量子计算架构[拓扑量子计算机]: 扩展速度优于竞争技术的拓扑量子计算机"]},{"i":35393,"as":"探讨了人工智能系统在医疗诊断中的应用潜力及现状。医学专家就人们是否很快将由人工智能系统进行疾病诊断进行了深入探讨，评估了“AI医生”的实际能力及其在医疗领域的未来发展前景。","scd":null,"kp":[]},{"i":35394,"as":"心理学和认知科学领域正面临可重复性危机。各实验室通过联合开展大量针对婴儿和狗的超大规模研究项目，旨在为认知科学引入严谨性，通过新的研究范式解决该领域的可靠性问题。","scd":null,"kp":[]},{"i":35395,"as":"美国白宫提出对美国科学资助体系进行大规模改革。特朗普政府的提案旨在提高联邦科研资金的透明度，但批评人士担忧这些提议的规则会将科学研究政治化，影响科学资助的公正性。","scd":null,"kp":[]},{"i":35396,"as":"研究发现称为质体小球（plastoglobules）的微小细胞结构在优化玉米氮素利用中发挥关键作用。这些结构能够组织相关酶，将氮元素转化为植物生长所需的化合物，该机制为发展可持续农业提供了重要启示。","scd":null,"kp":[]},{"i":35397,"as":"研究通过分析牙釉质中矿物纳米晶体的排列结构，揭示了灵长类动物、古人类和现代人类的饮食演变。随着这些物种在进化过程中饮食习惯的改变，其牙釉质内部的纳米晶体排列方式也随之发生相应的结构性变化。","scd":null,"kp":[]},{"i":35398,"as":"","scd":null,"kp":[]},{"i":35399,"as":"利用创新的质谱技术，首次在非蛋白质生物分子上检测到泛素标签。研究发现，在小鼠肝脏中，储存能量的糖原分子在禁食期间发生大量泛素化（涉及肝脏1%的总泛素），表明肝糖原分解为葡萄糖的过程可能受到泛素化的直接调控。","scd":null,"kp":[]},{"i":35400,"as":"玉米叶肉细胞叶绿体中的质体小球（PGs）作为代谢枢纽调控氮利用。ZmNIR2和ZmGLN1两种关键酶通过叶绿体转运肽和疏水区特异性定位于PGs。冷冻电镜分析表明，重组ZmGLN1形成十聚体复合物，与ZmNIR2构成代谢子以提高效率。这两种酶是调控氮同化过程的主要PG定位成分。","scd":null,"kp":["代谢枢纽[玉米叶肉细胞叶绿体]: 质体小球（PGs）区室化协调氮同化","关键酶[玉米质体小球靶向]: ZmNIR2和ZmGLN1"]},{"i":35401,"as":"研究通过对421名个体（含125名炎症性肠病患者）的220万个单细胞进行cis-eQTL映射，发现细胞类型级别的eQTL比组织级别的eQTL在与全基因组关联分析发现的IBD位点的共定位概率高出3.5倍以上。研究在超过一半的已知IBD位点中提名了效应基因，包括髓样细胞中的MAML2、PSEN2和ZMIZ1，这些基因与Notch信号传导减少有关。","scd":null,"kp":[]},{"i":35402,"as":"玉米在驯化过程中种子蛋白含量急剧下降。大刍草拥有天冬酰胺合成酶4（ASN4）的优越单倍型。研究克隆了大刍草高蛋白3（THP3）基因，该基因编码参与氮同化和碳氮平衡的关键酶——谷氨酸草酰乙酸转氨酶1（GOT1）。THP3-T等位基因在驯化过程中受到负向选择，其自然变异能提升表达量和酶活性。过量表达该基因可以促进谷氨酰胺合成。","scd":null,"kp":["关键基因[大刍草高蛋白单倍型]: THP3基因（促进谷氨酰胺合成）","关键基因[大刍草高蛋白单倍型]: ASN4基因（编码天冬酰胺合成酶）"]},{"i":35403,"as":"寒冷诱导的花粉败育是农作物减产的主要原因。研究在番茄中鉴定出控制花粉耐寒性的冷响应小信号肽SlRGF9和SlRGF10。这两种肽功能丧失后，番茄在正常条件下无缺陷，但在冷胁迫下会出现花粉败育。研究还发现了与之相关的富含亮氨酸重复序列的受体激酶SlRGFR，揭示了花粉耐寒的分子信号通路。","scd":null,"kp":[]},{"i":35404,"as":"研究采用时空评估方法和双重差分框架，分析了2001至2020年间撒哈拉以南非洲16,627个矿山对茂密森林的砍伐影响。研究共发现187,000公顷的直接采矿驱动森林砍伐（由矿坑、尾矿池等直接引起）。此外评估表明，采矿活动在1公里范围内还额外引发了8.0个百分点的森林砍伐增长。","scd":null,"kp":["毁林面积[2001-2020年撒哈拉以南非洲矿业开发]: 187,000公顷"]},{"i":35405,"as":"","scd":null,"kp":[]},{"i":35406,"as":"细胞感知水分变化的机制一直不明确。研究发现，植物蛋白SAM8在水势较低时会经历一种依赖于其自身水合作用的相分离过程。这种相分离机制能够感知细胞内的水分可用性，从而将细胞水分状态的变化与基因表达的调控直接联系起来。","scd":null,"kp":["感知机制[植物细胞水分缺乏]: SAM8蛋白发生依赖于水合作用的相分离"]},{"i":35407,"as":"玉米雄花和雌花同步开花至关重要，干旱会破坏这种同步性并导致大幅减产。研究发现名为SAUR72的基因能够在干旱条件下维持开花的同步性。控制SAUR72基因表达的DNA序列中发生的插入变异会降低玉米的耐旱性，为培育耐旱玉米品种提供了潜在策略。","scd":null,"kp":["抗旱靶点[玉米花期耐旱基因]: SAUR72（维持雌雄花序同步开花）"]},{"i":35408,"as":"","scd":null,"kp":[]},{"i":35409,"as":"","scd":null,"kp":[]},{"i":35410,"as":"超荧光（SF）是量子发射体集合产生强烈且相干光的集体发射现象。研究首次在室温下的大面积手性钙钛矿超晶格的边缘态中观察到了手性超荧光。理论计算重现了从非极化非相干的自发发射向相干手性超荧光态的转变，定量验证了高达约14%的圆偏振光生成及其符号反转现象。","scd":null,"kp":["发光材料[大面积垂直排列手性钙钛矿超晶格]: 室温下产生源自边缘态的手性超荧光","面积参数[手性钙钛矿超晶格]: >100 µm × 100 µm"]},{"i":35411,"as":"传统交联虽能提高聚合物的热和化学稳定性，但在机械变形下常使材料变脆。为克服稳定性与韧性之间的矛盾，研究将少部分对力敏感的力敏基团作为交联剂嵌入普通聚合物中。这种设计从根本上逆转了上述权衡，使材料在高应变速率下的弹道能量耗散能力得到显著增强。","scd":null,"kp":["[高分子材料抗冲击性能]: 交联通常会导致材料脆化，限制抗冲击性能和功能寿命","[力学耗散机制设计]: 力致交联能够克服传统分子设计难以缓解高速变形下穿孔现象的局限"]},{"i":35412,"as":"","scd":null,"kp":[]},{"i":35413,"as":"核子（质子和中子）在极短距离内会形成高动量的短程相关对。研究利用高能电子在具有不同壳层结构的40Ca、48Ca和54Fe原子核上的散射来探测这些对的形成。出乎意料的是，研究发现短程相关配对现象主要取决于质子和中子占据的具体量子轨道，而非先前的其他假设。","scd":null,"kp":[]},{"i":35414,"as":"受损的溶酶体会释放钙离子，触发内质网出口位点驻留蛋白TFG易位至受损溶酶体。研究通过全基因组CRISPRi筛选发现，TFG是名为LASER的多组分蛋白质组装的核心。LASER复合物能够感知溶酶体膜损伤，并将这种损伤感应与ESCRT依赖性修复机制在时空上紧密耦合，从而维持细胞存活。","scd":null,"kp":[]},{"i":35415,"as":"","scd":null,"kp":[]},{"i":35416,"as":"牙釉质由平行捆绑成长杆的羟基磷灰石纳米晶组成。利用PELICAN方法，研究比较了跨越9个物种、1780万年进化和不同饮食的12颗灵长类动物牙齿。结果表明，随着食肉和农业的出现，相邻牙釉质纳米晶体之间的取向错误角度显著增加。这一发现揭示了饮食变化与微观晶体结构之间的直接关联。","scd":null,"kp":["纳米晶体宽度[牙釉质羟基磷灰石]: 50–70 nm","微柱宽度[牙釉质结构]: 约 5 µm","增韧机制[牙釉质微柱交叉排列模式]: 通过使裂纹偏转实现材料增韧"]},{"i":35417,"as":"","scd":null,"kp":[]},{"i":35418,"as":"端粒替代延长（ALT）是与5-10%癌症相关的端粒延伸机制。研究在ALT癌细胞系和原发性ALT儿童神经母细胞瘤中，特异性地发现了着丝粒α-卫星序列重复和CENP-B框插入到端粒位置。利用DiMeLo-seq分析揭示了在特定染色体端粒位置组装的CENP-A染色质离散足迹，表明表观遗传失调与ALT激活存在病理联系。","scd":null,"kp":[]},{"i":35419,"as":"","scd":null,"kp":[]},{"i":35420,"as":"文章探讨了在 ambitious 项目启动十年后，重新审视从零开始构建人类基因组的价值与原因。该项目致力于人工合成完整的人类基因组，旨在推动生物医学领域的技术创新与理论发展。作者强调，随着技术进步，重新评估该项目的科学意义与应用前景具有重要时代价值，为未来基因组学研究提供了新的战略视角。","scd":null,"kp":[]},{"i":35421,"as":"文章标题为“Cron Job之书”，正文简短提及了“行为准则”。","scd":null,"kp":[]},{"i":35422,"as":"木星附近的观测数据显示，超音速冲击波现象为太空粒子加速机制提供了新见解。研究指出，瞬态等离子体结构在控制穿越太空的粒子加速过程中起着决定性作用。这一发现基于木星周围环境的实际观测，为理解宇宙空间中粒子运动的动力学机制提供了关键的理论依据。","scd":null,"kp":["[木星附近超音速冲击波]: 瞬态等离子体结构可能控制穿越太空粒子的加速过程"]},{"i":35423,"as":"研究分析了2001年至2020年间撒哈拉以南非洲矿区附近因采矿活动导致森林砍伐的严重程度。该分析将采矿活动与热带地区森林退化直接关联，量化了矿产开采对生态环境的破坏。这些数据结论为制定针对性的保护策略和减缓生态破坏提供了科学依据。","scd":null,"kp":["[采矿导致森林砍伐的影响分析周期]: 2001年至2020年"]},{"i":35424,"as":"无碰撞冲击波普遍存在于宇宙空间等离子体中，被认为是宇宙射线加速的主要场所，其加速机制为扩散冲击加速。根据Hillas准则，加速器的物理尺度限制了粒子的最大能量。NASA朱诺号探测器提供了木星弓激波上游相对论性电子（能量≥1 MeV）加速的直接观测证据。该数据为理解天体物理系统中粒子加速极限提供了直接约束条件。","scd":null,"kp":["[无碰撞冲击波]: 被认为是宇宙射线加速的主要场所","[扩散激波加速机制]: 需要粒子反复穿越激波波前以获取能量","[最大可加速能量约束]: 受限于将加速器物理尺度与最大粒子能量相关联的Hillas准则"]},{"i":35425,"as":"MYO7A突变会导致Usher综合征和非综合征性耳聋。研究利用长读长测序发现了一种在听觉毛细胞中与典型MYO7A-C并列表达的新亚型MYO7A-N。小鼠模型表明，内毛细胞主要表达MYO7A-C，外毛细胞以反向的拓扑梯度表达这两种亚型。MYO7A-N缺失会导致外毛细胞退化及进行性听力丧失。冷冻电镜结果显示，两种亚型在肌动蛋白-肌球蛋白界面存在差异，这与它们不同的ATP酶活性直接相关。","scd":null,"kp":[]},{"i":35426,"as":"地球反照率是决定行星能量收支的关键因素。基于25年的卫星观测记录，研究证实地球除了南北半球反照率对称外，还存在一种独特的东-西向反照率对称现象。以东经27度子午线为界，东半球和西半球反射的太阳光量基本相同。这种东西半球反照率对称的发现，为深入研究反照率对称成因及其对地球行星能量收支的影响提供了新视角。","scd":null,"kp":[]},{"i":35427,"as":"","scd":null,"kp":[]},{"i":35428,"as":"链霉菌与植物的互作能通过组装抗病微生物组来增强对土传病害的抵抗力。研究构建了香蕉与永兴链霉菌的互作模型，发现该菌株分泌的倍半萜（紫罗兰烯和Ledene）作为关键信号分子，触发香蕉根部生物合成10-羟基癸酸（10-HCA）。10-HCA特异性富集了有益的芽孢杆菌，从而有效抑制香蕉枯萎病。这一机制通过合成群落实验得到了验证。","scd":null,"kp":["[香蕉枯萎病抗性机制]: 永兴链霉菌通过分泌倍半萜类物质诱导10-HCA分泌并招募抗病根际微生物群"]},{"i":35429,"as":"","scd":null,"kp":[]},{"i":35430,"as":"登革病毒（DENV）感染中，抗原特异性CD8+ T细胞同时发挥保护和致病作用。研究利用载有DENV NS3衍生表位的HLA四聚体，对血液中的DENV特异性CD8+ T细胞进行了单细胞RNA测序。根据当前和既往感染的主要血清型多肽结合情况，识别出与疾病严重程度相关的不同CD8+ T细胞亚群。无症状登革热患者富集了具有适度细胞毒性程序的细胞，而重症患者的细胞特征则存在显著差异。","scd":null,"kp":[]},{"i":35431,"as":"FOXG1转录因子是胚胎大脑发育的关键调节因子，其变异会导致FOXG1综合征。研究在具有类似综合征特征的个体中识别出两个非编码结构变异，界定出一段约124 kb的常见受累调控区域。通过表观基因组分析和体内增强子测定，验证了该区域及更宽FOXG1 TAD内的调控元件。研究发现前脑增强子存在强烈激活作用，并鉴定出一个增强子簇及祖细胞特异性增强子。","scd":null,"kp":[]},{"i":35432,"as":"Rubisco酶是几乎所有有机碳进入生物圈的入口，存在于所有生命领域。为探究其结构和功能多样性，研究人员利用宏基因组学技术，合成并系统采样了一个侧重于稀疏分支的多样化Rubisco序列库。更新后的系统发育分析表明，许多深层分支的Rubisco同源物在生化特性上展现出不同特征，填补了序列数据增长与生化表征之间的空白。","scd":null,"kp":["[Rubisco酶超家族生化特征]: 多样性驱动的生物化学研究表明二聚化现象在整个超家族中广泛存在"]},{"i":35433,"as":"","scd":null,"kp":[]},{"i":35434,"as":"研究提出了一种名为UDR-WM的深度学习框架，利用体素级的各向异性分数（FA）图像，在不依赖解剖学假设的情况下提取全脑深度影像表型（UDIP-FA）。与传统FA表型相比，UDIP-FA对衰老表现出更高的敏感性，且具有更高的基于SNP的遗传力。多变量GWAS分析识别出586个基因座上的939个主效SNP，映射到3480个基因，这些基因在神经胶质细胞中显著富集。","scd":null,"kp":["深度学习框架[白质微结构遗传架构分析]: 无监督深度表示模型（UDR-WM）","[体素级各向异性分数（FA）映射]: 可推导出覆盖全脑的无监督深度成像表型（UDIP-FA），克服传统基于纤维束或图谱平均值的局限性"]},{"i":35435,"as":"利用自然主义功能磁共振成像技术，研究分析了20名母语者在观看波兰手语叙事时的脑部活动。手语虽然具有使用手部、面部和空间位置等特定模态元素，但其叙事理解同样能够同步分层神经网络。研究结果揭示了手语叙事在皮层时间尺度层级上展现出模态不变的特征，证明了语言层级网络的核心特征在不同语言模态间具有普遍性。","scd":null,"kp":["[自然语境下的fMRI神经时间尺度层级]: 揭示了手语叙事在皮层时间尺度层级上兼具普遍性与特定模态特征"]},{"i":35436,"as":"","scd":null,"kp":[]},{"i":35437,"as":"","scd":null,"kp":[]},{"i":35438,"as":"转录因子对顺式调控元件的序列特异性识别实现了基因型向表型的传递。研究构建了一个基于拟南芥DNA结合数据训练的可解释多标签深度学习模型，用于分析CRE序列及其上下文对转录因子占据率的影响。该模型能够注释全基因组转录因子结合位点，预测不同条件下的调控语法，并结合GWAS数据成功识别了数量性状基因座内的调控基因变异，实验验证证实了其预测的有效性。","scd":null,"kp":["[转录因子结合预测]: 采用基于拟南芥DNA结合数据训练的可解释多标签深度学习模型","[基因型与表型传递机制]: 捕获顺式调控元件序列、上下文及句法对转录因子占据率的影响"]},{"i":35439,"as":"","scd":null,"kp":[]},{"i":35440,"as":"","scd":null,"kp":[]},{"i":35441,"as":"","scd":null,"kp":[]},{"i":35442,"as":"探讨在科学类求职申请中使用人工智能的优势、局限性与潜在风险。明确分析了AI工具在求职过程中的具体应用场景及其对招聘流程的影响，为科学领域的求职者提供参考。","scd":null,"kp":[]},{"i":35443,"as":"","scd":null,"kp":[]},{"i":35444,"as":"","scd":null,"kp":[]},{"i":35445,"as":"","scd":null,"kp":[]},{"i":35446,"as":"一项新研究提出了一种振动诱导发光策略，可实时可视化4D打印中的光固化过程和动态驱动。该技术利用多色发光反映聚合程度和网络刚性，实现了分子层面的材料设计到工程应用的跨度过渡。这种直观的化学平台能够支持可编程形状变化、多级防伪以及软体机器人应用，为合理设计智能刺激响应材料提供了创新工具。","scd":null,"kp":["可视化策略[4D打印光固化与动态驱动]: 振动诱导发射","多色发光机制[聚合物网络]: 反映聚合度与网络刚性"]},{"i":35447,"as":"为打破传统冯·诺依曼计算架构中内存与处理分离的局限，纳米流体记忆电阻器成为构建类脑神经形态计算的重要基础组件。该器件利用纳米尺度限制下的离子传输，产生依赖历史的电导率，从而实现模拟或数字开关。器件性能由表面化学、几何形状和电解质特性共同决定。探索新材料不仅能提升功能，还能深化对驱动记忆行为多样化物理机制的理解。","scd":null,"kp":["核心机制[纳米流体离子记忆体]: 纳米尺度限域下的离子传输产生依赖历史的电导率","应用方向[类脑计算]: 模拟或数字开关"]},{"i":35448,"as":"塑料废弃物处理与二氧化碳去除是两大全球性挑战。研究人员展示了一种催化转化策略，通过催化修饰将聚苯乙烯和橡胶转化为含胺吸附剂。这些新型吸附剂能够有效捕获烟道气甚至环境空气中的二氧化碳。该技术为同时解决塑料污染和温室气体排放这两个同等规模的全球性问题提供了创新桥梁。","scd":null,"kp":["胺类吸附剂[原料来源]: 聚苯乙烯和橡胶","应用目标[催化修饰转化]: 烟气及环境空气中的CO2捕集"]},{"i":35449,"as":"镁电池因金属镁具有高体积容量、无枝晶沉积和丰富的元素储量，成为后锂时代极具潜力的储能系统。然而，界面的缓慢脱溶剂化和固相扩散导致Mg2+跨尺度传输迟缓，限制了其实际应用。研究表明，芳香族化合物凭借其低电负性骨架、离域π电子系统和分子可编程性，能够有效缓解局部静电捕获并调节Mg2+传输，为镁电池系统性联合设计提供了重要平台。","scd":null,"kp":["金属负极优势[镁电池]: 高体积比容量、多种条件下无枝晶沉积及良好的元素丰度","传输瓶颈[Mg2+传输]: 跨尺度的界面离子去溶剂化和固态扩散缓慢"]},{"i":35450,"as":"阴离子交换膜水电解（AEMWE）是可再生能源制氢的可持续途径，但其阳极缓慢的四电子析氧反应（OER）动力学严重限制了系统的实际可行性。研究提出一种氢氧化物表面工程策略，构建了NiFe(OH)x/PrBa0.5Sr0.5Co1.5Fe0.5O5+δ (PBSCF) 层状双钙钛矿材料。该表面工程显著加速了OER动力学，有效提升了AEMWE系统的电催化性能。","scd":null,"kp":["催化剂[阴离子交换膜电解水析氧反应]: NiFe(OH)x/PrBa0.5双钙钛矿水滑石","表面工程[加速OER动力学]: 氢氧化物表面工程构建电子微环境"]},{"i":35451,"as":"共价有机框架（COFs）在锂离子电池中具有结构可设计和孔隙明确的优势，但其本征电子传导性差及高电流密度下离子扩散缓慢限制了其实际应用。研究提出通过化学结构演变来调控电子微环境，构建了具有局部偶极极化的新型全共轭BTTP-COF材料。这种分子设计增强了电子传输的驱动力，提高了电子传导率，有效促进了高倍率下活性位点的利用。","scd":null,"kp":["材料缺陷[共价有机框架锂电池应用]: 固有的电子传输不良及高电流密度下离子扩散动力学缓慢","技术方案[高速率离子存储]: 调节全共轭共价有机框架的电子微环境"]},{"i":35452,"as":"混合处理宽带隙钙钛矿在钙钛矿/硅叠层电池中极具应用前景，但其相比溶液处理法存在显著的开路电压不足问题。研究揭示了导致该电压 deficit 的两个耦合原因：扩散限制引起的结晶不完全和垂直不均匀，以及界面非辐射复合。通过引入氯化甲基铵（MACl），成功调节了扩散驱动的转化过程并改善了界面性质，有效克服了电压不足。","scd":null,"kp":["性能缺陷[混合工艺宽带隙钙钛矿电池]: 相较于溶液工艺存在明显的开路电压损失","应用导向[混合工艺钙钛矿]: 钙钛矿/硅叠层集成的可扩展且共形的光伏技术"]},{"i":35453,"as":"为实现离网原位制氢，研究人员开发了一种具有不对称润湿性的Janus结构凝胶。该器件底部为LiCl改性的纳米原纤化纤维素吸湿层，顶部为SrTiO3:Al光催化层，中间精心设计了聚偏氟乙烯隔层。这种独特结构能够协同促进大气水分中水的高效传输，克服了能量转换效率低和吸附剂降解的限制，实现了从大气水分中高效、清洁地光催化产氢。","scd":null,"kp":["凝胶结构[Janus凝胶光热制氢]: 由LiCl改性纳米原纤化纤维素吸湿底层与SrTiO3构成的不对称润湿性结构","应用优势[便携式太阳能制氢]: 摆脱对牺牲剂的依赖，实现离网原位产氢"]},{"i":35454,"as":"非共价相互作用因其可逆性和机械稳定性在力学响应材料设计中极具吸引力，但其构象能景难以通过传统系综技术探测。研究利用原子力显微镜力谱技术结合分子动力学模拟，探究了苝二酰亚胺二聚体中的单个π-相互作用。单分子拉伸实验揭示了具有平行和反平行苝核的两种不同长寿命构象异构体，展现了机械力在揭示隐藏解离路径方面的关键作用。","scd":null,"kp":["测试技术[单分子π相互作用二聚体]: 基于原子力显微镜的力谱技术","材料特性[力化学响应材料]: 利用机械力控制分子结构，非共价相互作用具有可逆性和可调机械稳定性"]},{"i":35455,"as":"由于缺乏同时构建非六元环和稳定手性的可行方法，手性非苯型纳米石墨烯一直是极具挑战性的合成目标。研究展示了一种分步氧化的新合成策略，成功构建了手性鞍形纳米石墨烯。该工艺首先通过Scholl型氧化构建含有sp3缺陷七元环的关键中间体，随后氧化脱氢生成包含两个七元环嵌入[4]螺烯的目标产物。该研究为复杂拓扑碳基材料的合成提供了新途径。","scd":null,"kp":["分子结构[手性鞍形纳米石墨烯]: 由蒽齐聚物前体逐步氧化并通过Scholl反应构建，嵌入双七环的[4]螺烯","合成策略[非苯型手性纳米石墨烯]: 分步氧化法"]},{"i":35456,"as":"高性能固态电解质的机械化学合成耗时耗能，是全固态电池规模化的关键瓶颈。研究以无定形氧卤化物NaTaOCl4为模型系统，仅通过数分钟级的球磨即可完成合成，相较于传统NaTaCl6需数天的合成时间取得显著突破。结合原位同步辐射X射线散射等技术，证实了结构中桥氧的引入是实现超快无定形化和提升离子传输性能的核心驱动力。","scd":null,"kp":["成键机制[超离子卤氧化物固体电解质]: 桥氧驱动的超快非晶化"]},{"i":35457,"as":"受地球光照周期性特征及生命系统适应明暗期的启发，研究人员探索了光/暗交替输入对光响应超分子系统结构演变的影响。实验表明，振荡的光能量供应能够促进自组装光开关多肽的结构选择，这与在连续光照下形成的无定形结构不同，证明了明暗周期可有效控制合成超分子系统的瞬态多晶型结构，实现更高级的功能和组织演化。","scd":null,"kp":["结构演化[光响应超分子系统]: 受明暗交替周期控制，黑暗阶段通过热弛豫过程提升功能和结构组织度"]},{"i":35458,"as":"","scd":null,"kp":[]},{"i":35459,"as":"","scd":null,"kp":[]},{"i":35460,"as":"研究提出陆海加热对比是东太平洋多年代际冷却现象的潜在驱动因素。通过在全球耦合气候模型中仅对陆地二氧化碳浓度进行加倍，研究发现陆地加剧变暖引发了赤道及东太平洋的显著瞬态降温。陆地CO2每年1%的增加量可产生年代际冷却。针对性模拟进一步证实，局地陆地加热效应能够引发太平洋的大气遥相关作用，导致其变冷。","scd":null,"kp":["模拟参数[全球耦合气候模型]: 仅在陆地上4倍增加二氧化碳浓度","气候效应[赤道和东太平洋]: 引起显著的瞬时变冷"]},{"i":35461,"as":"","scd":null,"kp":[]},{"i":35462,"as":"","scd":null,"kp":[]},{"i":35463,"as":"","scd":null,"kp":[]},{"i":35464,"as":"","scd":null,"kp":[]},{"i":35465,"as":"","scd":null,"kp":[]},{"i":35466,"as":"","scd":null,"kp":[]},{"i":35467,"as":"","scd":null,"kp":[]},{"i":35468,"as":"","scd":null,"kp":[]},{"i":35469,"as":"","scd":null,"kp":[]},{"i":35470,"as":"","scd":null,"kp":[]},{"i":35471,"as":"","scd":null,"kp":[]},{"i":35472,"as":"","scd":null,"kp":[]},{"i":35473,"as":"研究将基于底物的蛋白激酶C（PKC）活性确定为非小细胞肺癌的预后生物标志物，并作为抗PD-1难治性肿瘤的治疗靶点。泛PKC抑制能够诱导依赖于Caspase-3/GSDME的免疫原性细胞焦亡，通过激活GSK3β促进肿瘤内源性PD-L1降解，并借助CCL4-CCR5信号增强CD8+ T细胞的招募和功能。机制上，PKC阻断会破坏XIAP的稳定性，从而解除对半胱天冬酶的抑制，使难治性肿瘤重新对免疫治疗敏感。","scd":null,"kp":[]},{"i":35474,"as":"植物激素生长素的核心途径依赖于生长素响应因子（ARFs）的蛋白水平调控。研究以拟南芥为模型，探究了ARF2和ARF3中高度保守的不稳定性（INS）结构域的作用。结果表明，T298N、T298D和T298E等INS结构域突变会导致明显的生长素相关表型（如雄性不育和根毛发育缺陷）。其中，T298D和T298E突变显著增加了ARF2蛋白的稳定性，揭示了INS结构域在调控B类ARF水平中的保守作用。","scd":null,"kp":[]},{"i":35475,"as":"轮状病毒非结构蛋白1（NSP1）通过抑制干扰素调节因子3（IRF3）来阻断干扰素信号通路。研究发现，NSP1含有一个BC box基序，负责介导其与Elongin BC复合体的结合。通过siRNA或CRISPR敲除编码Elongin B的TCEB2基因，可显著阻止NSP1对IRF3的降解。携带BC box突变的重组轮状病毒无法降解IRF3，会引发强烈的干扰素反应，并在体内和体外表现出毒力减弱。","scd":null,"kp":[]},{"i":35476,"as":"巨噬细胞产生的活性醛类物质——甲基乙二醛（MGO）是抗微生物天然免疫的重要武器。单核细胞增生李斯特菌利用乙二醛酶A（GloA）和细菌谷胱甘肽对MGO进行解毒。缺失GloA会导致细菌毒力严重受损，突变频率增加100至1000倍。谷胱甘肽不仅参与MGO解毒，还激活主要毒力调控因子PrfA。锁定PrfA于活性构象的突变能够挽救gloA缺失菌株的毒力缺陷。","scd":null,"kp":[]},{"i":35477,"as":"无机多聚磷酸盐广泛存在于各生物体中。研究以新月柄杆菌为模型，通过转座子测序技术证明，多聚磷酸盐合成在细胞从缺磷恢复到富磷环境的“营养上调”过程中具有必不可少的生理作用。在此恢复期间，编码多聚磷酸盐激酶的ppk1基因对于维持细胞内磷酸盐稳态和ATP（三磷酸腺苷）平衡至关重要。","scd":null,"kp":[]},{"i":35478,"as":"研究利用无线神经记录、动作捕捉和眼动追踪技术，探究了自由探索开阔场地的猕猴大脑顶叶-压后皮层-海马通路中的视觉与空间编码机制。研究识别出了自我中心空间和他我中心空间编码的相反梯度。压后皮层作为关键中间枢纽，通过增益调制联合编码自我中心位置和他我中心注视方向；而海马体则表现出二者的整合编码特征。","scd":null,"kp":[]},{"i":35479,"as":"","scd":null,"kp":[]},{"i":35480,"as":"大气集水技术（AWH）是应对全球水危机的有效方案，其中基于吸附的大气集水技术（SAWH）因对不同气候的强适应性备受关注。综述系统探讨了吸附剂材料的动力学基础、材料设计进展和规模化加工策略，并重点分析了热传递与质传递过程的系统工程优化。文章还梳理了能源管理、操作策略等挑战，为实用化AWH技术的部署规划了路线图。","scd":null,"kp":["技术特点[吸附式大气取水]: 适应广泛的气候条件，通过热质传递优化实现系统放大"]},{"i":35481,"as":"研究测定了跨越六个数量级浓度（1 pM至100 nM）的17β-雌二醇（E2）对乳腺癌细胞的分子影响。发现低生理剂量（1-100 pM）和高药理剂量（10-100 nM）形成的雌激素受体α（ERα）增强子在机制上截然不同。低剂量增强子形成于FOXA1结合的开放染色质，并簇集于拓扑相关结构域内，产生具有调控基序的增强子RNA，驱动具启动子近端暂停RNA聚合酶II的增殖基因表达。","scd":null,"kp":[]},{"i":35482,"as":"非经典光源是量子技术的重要资源。为解决超冷原子和固态系统在可扩展性上面临的复杂性及光谱漂移挑战，研究展示了一种将芯片级铷原子束与高精细度腔量子电动力学（QED）系统相结合的混合方案。该方案在少光子水平下产生了非经典光并观察到光学非线性，且未导致腔QED系统性能退化。该技术为分布式非经典光源及提升芯片级磁力计性能开辟了新途径。","scd":null,"kp":["系统架构[芯片级原子束非经典光源]: 芯片级铷原子束与高精细度腔量子电动力学系统耦合"]},{"i":35483,"as":"研究提出了一种结合荧光寿命和强度信息的定量电生理成像新范式，用于在体外高保真捕捉心肌细胞的动态电信号。利用门控单光子雪崩二极管相机，能以高达200帧/秒的速度获取荧光寿命图像。该方法的荧光寿命测量本质上不受收缩运动伪影的影响，能在宽广的视野内提供校准的钙离子浓度和膜电位估算，实现对心肌细胞兴奋-收缩偶联的无接触、高通量直接测量。","scd":null,"kp":["检测特征[收缩心肌细胞电生理检测]: 结合荧光寿命和强度信息进行定量电生理成像，且寿命测量在本质上不受收缩伪影干扰"]},{"i":35484,"as":"研究通过结合阴离子配位与酰胺-π相互作用，构建了一种由62个组分构成的离散型十二面体超分子笼。这种合成结构类似于登革热病毒，由三种不同分子通过60个氢键和30组酰胺-π相互作用结合而成。该超分子笼在溶液中表现出优异的稳定性，并展现出多种固态结构多晶型现象。该结构突破了以往弱非共价力超分子组装体最多仅含20个组分的极限。","scd":null,"kp":["组装成分[阴离子配位超分子笼]: 62组分的十二面体","驱动力[超分子十二面体组装]: 酰胺-π相互作用辅助的阴离子配位"]},{"i":35485,"as":"原钙黏蛋白7（PCDH7）在肺腺癌中经常过度表达，与不良临床结果相关，并具有促癌作用。在KrasLSL-G12D;Tp53fl/fl小鼠模型中，消耗Pcdh7可减少肿瘤负荷并延长生存期。研究开发了高亲和力的抗PCDH7单克隆抗体。实验结果证实，靶向抑制PCDH7能够抑制肿瘤生长并增强抗肿瘤免疫反应，是治疗KRAS突变型非小细胞肺癌的潜在有效靶点。","scd":null,"kp":[]},{"i":35486,"as":"研究记录了大鼠在不平坦地形上觅食时的海马体位置细胞活动。结果表明，位置细胞活动反映地形形状，支持基于表面的认知地图，而非体积地图。位置野平行于地形轮廓延伸，这与大鼠的运动偏好和预测编码模型不一致。三分之一的位置细胞在每个山脊上表现出重复的位置野。边界向量细胞模型有效解释了地形特征对空间映射的影响。","scd":null,"kp":[]},{"i":35487,"as":"针对层状热电材料中声子和电子传输相互交织的挑战，研究提出一种范德华间隙工程策略。通过对n型碲化铋（Bi2Te3）进行选择性层间掺杂，引发局部电荷不平衡并驱动波纹状晶格褶皱。这些结构起伏重新归一化了声子色散并显著降低声子速度，从而抑制晶格热导率。由于褶皱幅度远小于电子平均自由程，该结构形变对电子传输的负面影响可忽略不计。","scd":null,"kp":["工程策略[层状热电材料Bi2Te3范德华间隙工程]: 引入面外应力并进行选择性层间掺杂以产生局部电荷不平衡，驱动波纹状晶格起伏","物理效应[层状热电材料]: 晶格起伏实现热传输与电荷传输的解耦"]},{"i":35488,"as":"针对大面积钙钛矿发光二极管制造中成膜不均匀的瓶颈，研究提出一种多模态溶剂工程策略。该方法结合环境刮涂与真空辅助溶剂蒸发，将N-甲基-2-吡咯烷酮（NMP）和乙腈（ACN）引入二甲基甲酰胺（DMF）溶剂体系。该体系协同调节蒸发动力学，通过马兰戈尼流抑制宏观溶质偏析，同时调节前驱体配位以控制成核和相变，从而促进形成均匀且具有高辐射效率的钙钛矿薄膜。","scd":null,"kp":[]},{"i":35489,"as":"为了突破多共振（MR）发光体发射半峰宽的瓶颈，研究提出一种通过构建分子内氢键来打破吲哚咔唑（ICz）发光体光谱极限的策略，并开发了旋转手性ICz稠合对映异构体。该手性改性ICz发光体实现了466纳米的发射峰，半峰宽仅为56毫电子伏特，并在甲苯溶液中有效抑制了肩峰，实现了已知红色发光材料中最窄的发射光谱。","scd":null,"kp":["发光特性[多共振发光系统]: 超窄带发射且具有理想高斯发射轮廓","修饰策略[吲哚咔唑发射体]: 分子内氢键构建打破发射光谱极限"]},{"i":35490,"as":"通过多组学和全基因组关联分析，研究鉴定出毛果杨中的PtoCPK3基因是控制耐旱性的关键。该基因的变异与松柏醇和阿魏酸两种相关代谢物有关。在转基因杨树中过表达PtoCPK3能够通过协同调节木质部重塑和木质素代谢（特别是改变愈创木基木质素单体的生物合成），增强植物的耐旱性。这表明PtoCPK3是通过木质部重构驱动干旱适应性。","scd":null,"kp":[]},{"i":35491,"as":"使用数学模型评估了美国实施 hypothetical HSV-1疫苗的潜在公共卫生收益。若2030年引入有效率为70%且提供终身保护的婴儿疫苗接种计划，到2075年，口腔和生殖器疱疹的发病率将分别降低47.3%和58.3%，年度新发感染率分别下降41.2%和53.5%，累计可避免2850万例感染。预防一例感染所需接种人数将从2040年的35.8降至2070年的7.2。","scd":null,"kp":[]},{"i":35492,"as":"研究利用人工智能模型框架整合多卫星和现场数据，重建了巴西过去二十年的地下水行为数据。研究量化了在气候和人为压力源下约850万平方公里陆地范围内的地下水变化、补给和趋势。结果显示，2002至2023年期间，巴西含水层露头区的平均地下水补给率为每年223 ± 16毫米。该研究填补了巴西地下水监测数据的空白。","scd":null,"kp":["[地下水储量监测]: 结合多卫星与原位数据集成的人工智能建模框架进行时空重建"]},{"i":35493,"as":"为了探究早期地球生命必需元素（LEE）的来源，研究重建了在太阳系形成不到100万年内吸积的铁陨石母体（IMPBs）的磷-氮（P-N）预算。结合高压高温合金分配实验和地球化学模型，研究发现外太阳系IMPBs的P/N比值高于内太阳系IMPBs，这一趋势与球粒陨石中的情况完全相反。该研究证实了第一代行星体在向地球输送生命必需元素方面的重要作用。","scd":null,"kp":[]},{"i":35494,"as":"研究探讨了脂质成分和机械力如何调控Piezo1离子通道的门控机制。实验表明，在细胞衍生膜的囊泡中，Piezo1通道在机械力作用下能够保持开启并传导离子，同时呈现出与配体门控通道相似的完全扁平的圆盘形状。相反，在人造脂质体中，由于膜曲率介导，通道形状仅略微变平且离子孔保持关闭。研究证实了脂质组成和机械力在Piezo1形态和功能多模态调节中的核心作用。","scd":null,"kp":[]},{"i":35495,"as":"提出一个全球内潮建模框架，以改善对海洋中尺度涡流和丝流等精细海洋环流特征的卫星观测精度。利用数据同化海洋预报模型解析中尺度环境，并从更广泛的环流中分离出潮汐信号。该模型成功捕捉到了非相位锁定内潮波的混沌变率。通过校正总内潮信号，显著降低了地表水和海洋地形（SWOT）任务的测量误差，提高了细尺度海洋垂直热交换观测的准确性。","scd":null,"kp":[]},{"i":35496,"as":"利用新开发的Arl13b-TurboID小鼠模型实现了针对纤毛的稳健特异性生物素化和蛋白质组学分析。比较蛋白质组学揭示，神经元纤毛高度富集了突触蛋白、粘附分子和神经递质受体，具有明显的组织特异性。扩展显微镜观察显示，包括NMDA受体亚基GluN1在内的几种信号分子在皮质神经元纤毛上被组织成离散的纳米结构域。这些纳米结构域由主动回收机制维持，构成了突触外信号传导的特化区域。","scd":null,"kp":[]},{"i":35497,"as":"研究构建了一个用于超图相似性比较的通用信息论框架。该方法克服了传统网络比较仅限于成对相互作用的局限性，能够捕捉高阶相互作用之间的有意义的对应关系，同时校正虚假相关性。该框架将超图之间的结构重叠转化为标准化的互信息度量，从而推导出在相互作用的不同层级和多个尺度上日益精细的超图相似性层级结构，提升了聚类和异常检测等下游任务的准确性。","scd":null,"kp":[]},{"i":35498,"as":"研究在莫桑比克罗非鱼中发现了一种跨途径招募机制，即雌性分化级联反应中的基因被重新作为雄性主决定基因（MSD）。该MSD基因figlaY是雌性相关基因figla的Y连锁截短副本，起源于祖先丽鱼科的重复和易位，并随后通过基因渗入到多个谱系中。转座元件促进了figlaY的上游调控序列的演化，使其获得了雄性特异性表达模式，从而驱动了雄性性别决定机制的演化。","scd":null,"kp":[]},{"i":35499,"as":"国际海洋发现计划（IODP）402航次在意大利近海第勒尼安海的初生海洋盆地进行了钻探。岩心由与橄榄岩交错的花岗岩侵入体和高度变形的蛇纹石化橄榄岩组成。地质年代学和地球化学数据表明，这些花岗岩在400万年前于地下7至9公里深处结晶，随后沿剥离断层迅速隆升。研究证实，花岗岩侵入体的存在显著增强了局部应变，从而促进了地幔岩的快速剥露。","scd":null,"kp":[]},{"i":35500,"as":"在埃及发现了一个早古新世（丹麦阶）的特提斯洋热带化石库（Qreiya 3 Lagerstätte，约6220万年前）。该遗址揭示了包含9个目至少21种辐鳍鱼类的海洋生态系统，其多样性超过了所有其他丹麦阶骨骼组合的总和。化石中大部分属于棘鳍类，包括至少六个生态高度分化的现存类群最古老的骨骼记录。这一发现证实了K-Pg灭绝事件对海洋鱼类的强烈影响，并表明随后迅速建立了具有现代结构的鱼类群落。","scd":null,"kp":[]},{"i":35501,"as":"研究报道了一种结合能量过滤和扩展局域轨道叠层成像术（eLOP）的电子叠层成像重建方法。该方法能够校正电子束扫描期间不断变化的像差，成功对厚度高达85纳米的硅样本实现了深亚埃分辨率的结构重建。该样本厚度约为传统多层电子叠层成像厚度极限的三倍。通过消除像差变化，该技术在深亚皮米级精度下实现了对块体材料内在物理和机械性质的高分辨率结构分析。","scd":null,"kp":["分辨率[厚样品透射电子显微镜]: 深亚埃级","精度[厚样品透射电子显微镜]: 深亚皮米级","成像技术[厚样品]: 结合能量过滤与扩展局部轨道叠层成像"]},{"i":35502,"as":"研究利用滑动铁电体的非简并转变路径作为对称性工程旋钮，在交错磁体中建立了一个六态高维磁电耦合平台，超越了传统滑动铁电性的二进制上下范式。基于双层三硫化锰磷（MnPS3）的第一性原理计算表明，自旋极化的对称性锁定机制使得沿三条非简并路径的极化翻转不仅能够反转自旋分裂，还能在六种状态之间实现精确调控。该研究为低功耗自旋电子学提供了确定性电控途径。","scd":null,"kp":["[交变磁性多铁态控制]: 通过滑移铁电性实现六态对称性锁定控制"]},{"i":35503,"as":"研究开发了一种基于图像的筛选和分选工作流程，用于在非克隆群体中探索基因表达囊泡（合成细胞）的表型并选择目标变异体。利用自动化共聚焦显微镜和实时神经网络辅助的图像分析技术，该系统能够根据脂质体的荧光强度、蛋白质定位、膜形态及动态行为进行精确筛选，并将表型特征与其遗传物质相关联。这一方法大幅加速了在极简合成系统中细胞功能的定向进化。","scd":null,"kp":["[合成细胞表型分选]: 自动化共聚焦显微镜结合神经网络辅助图像分析"]},{"i":35504,"as":"哺乳动物骨骼肌中的肌球蛋白重链在代谢调节中起关键作用。研究利用骨骼肌特异性敲除小鼠模型证明，编码MyHC-slow蛋白的Myh7基因缺失会导致氧化型慢肌纤维退化、纤维类型比例改变、肌力下降及肌肉功能障碍，同时引发葡萄糖代谢受损。这证实了Myh7在维持骨骼肌功能和代谢稳态中具有不可或缺的调节作用。","scd":null,"kp":["[哺乳动物代谢平衡调节]: 骨骼肌慢肌球蛋白重链通过NRF2 pathway调节"]},{"i":35505,"as":"为解决自主水下航行器在尺寸、成本和环境限制下的感知难题，研究人员开发了一款小型轻量化的软磁毛状流速传感器。该传感器基于机械偏转原理，能够测量流体速度、方向和振荡。水下机器人测试证实，该仿生传感器可有效估算机器人前进、侧向运动及水流结构，为复杂运动测量与环境水流探测提供了紧凑型解决方案。","scd":null,"kp":["[水下机器人流场传感]: 仿生流量传感器估计运动并检测流场结构"]},{"i":35506,"as":"","scd":null,"kp":[]},{"i":35507,"as":"全聚合物有机太阳能电池（APSCs）兼具高效率和机械稳健性，但其功率转换效率（PCE）常落后于小分子受体器件。本研究通过精确调控聚合物受体（PAs）的化学结构，设计了两种双轴共轭延伸的PAs。通过调控侧链和端基取代基控制分子间非共价相互作用，优化了分子聚集行为并实现了理想形貌。这种形貌有序化使APSCs实现了20.29%的光电转换效率及极高的机械韧性。","scd":null,"kp":["能量转换效率[全聚合物太阳能电池]: 20.29%"]},{"i":35508,"as":"自由基转化中的立体控制是一项重大挑战，尤其是高活性乙烯基自由基的不对称操纵。研究开发了一种结合手性铬催化与有机光氧化还原催化的双催化系统。该平台实现了炔烃的对映选择性三组分1,2-二烷基化反应，将简单的烷基自由基前体、炔烃和醛直接转化为轴向手性烯丙醇类化合物。反应具有高非对映选择性（最高超20:1 dr）和对映选择性（最高99% ee），机理涉及光氧化还原介导的自由基级联过程。","scd":null,"kp":["[乙烯基自由基对醛加成反应]: 手性铬催化与有机光氧化还原催化协同的双催化系统"]},{"i":35509,"as":"非活化烷基硼酸频哪醇酯（APEs）的不对称官能化因对常规双电子转金属化固有的惰性而极具挑战性。本研究开发了一种铜催化、由氨基自由基转移（ART）介导的不对称脱硼自由基偶联反应。使用氨基苯甲酸酯作为双功能试剂，既作为氨自由基前体触发C(sp3)-B键均裂，又作为氧亲核试剂，成功实现了APEs与共轭二烯的对映选择性偶联，合成了手性酯类化合物。","scd":null,"kp":["[非活化烷基硼酸频哪醇酯不对称官能化]: 铜催化结合氨基自由基转移介导的去硼化"]},{"i":35510,"as":"中温电化学技术需要高性能的无水质子交换膜。研究通过将磷鎓、咪唑鎓和锍鎓基离子液体限域在经聚乙烯亚胺功能化的氮化硼与石墨烯纳米片堆叠通道中，构建了 robust 且高效的质子传导膜。带正电的纳米片诱导离子发生空间有序排列，将阴离子锚定在通道壁附近，使质子和阳离子集中在通道中央，从而形成平行连续的快速质子传导路径，同时抑制离子液体的体相扩散，实现在最高240°C下的快速无水质子传导。","scd":null,"kp":["温度[无水质子传导]: 高达240℃","质子传导机制[无水条件]: 限制在由氮化硼、石墨烯纳米片和聚乙烯亚胺形成的通道内的有序离子液体"]},{"i":35511,"as":"电催化硝酸盐还原反应（NO3RR）可同时实现环境修复和氨的可持续合成，但现有的共价有机框架（COFs）催化体系多依赖金属活性位点。为克服这一局限，研究引入了一种高活性的无金属COF电催化剂。该催化剂利用COF固有的孔隙率和结构可调性进行活性位点工程，摆脱了对金属的依赖，不仅提升了系统的可持续性，还清晰展示了框架本身在NO3RR中的催化活性。","scd":null,"kp":["[无金属电催化硝酸盐还原制氨]: 以酮腙键连接的共价有机框架作为催化剂平台"]},{"i":35512,"as":"光催化一氧化氮还原制氨（NORR）是替代高耗能哈伯法合成氨的有效途径。针对传统多质子耦合电子转移（PCET）缓慢和活性位点价态难以调控的问题，研究提出了一种以乙二醇（EG）为氢供体、由氢自由基（•H）驱动的新型氢化路径。该机制有效规避了传统PCET过程的限制。通过精确构建并调控Pd0/Pd2+双活性位点协同作用，显著提升了NORR的反应效率。","scd":null,"kp":["光催化一氧化氮还原制氨[NORR]: Pd0/Pd2+双位点协同催化机制","[迟缓的多质子耦合电子转移及价态调控]: 氢自由基介导的反应路径"]},{"i":35513,"as":"热塑性弹性体（TPEs）兼具热塑性可再加工性和橡胶弹性，而传统共价交联含氟弹性体难以回收。本研究开发了一种光氧化还原介导的可逆失活自由基共聚技术，实现了四氟乙烯（TFE）与功能单体共聚。通过设计具有热活化延迟荧光特性的氟苯腈基光催化剂（E1/2(PC/PC•−)），成功合成了基于氢键相互作用的硬-软-硬三嵌段共聚物，为制备可再加工的热塑性含氟弹性体提供了便捷途径。","scd":null,"kp":["[热塑性含氟弹性体合成]: 光氧化还原介导的可逆失活聚合","[硬-软-硬三嵌段共聚物合成]: 以四氟乙烯为原料"]},{"i":35514,"as":"De Mayo反应是合成1,5-二羰基或环丁醇的传统化学方法。本研究利用烯基硼酸酯作为1,3-二羰基化合物的替代物，提出了一种基于硼元素的新型环加成方法。该工艺实现了对传统De Mayo产物的延迟受控合成，并成功进行了产物中C-B键的衍生化转化。机理研究证实，刚性氧-硼杂环关键中间体的形成是实现双分子环加成反应的核心要素。","scd":null,"kp":["[De Mayo反应的硼赋能环加成方法]: 使用烯基硼酸酯作为1,3-二羰基的替代物"]},{"i":35515,"as":"实现快速、可控且具立构选择性的链增长是合成高性能可回收聚合物的难点。本研究引入了一种基于非经典C-H⋯X（X=O, S）氢键相互作用的催化系统。大体积季铵阳离子构建了一个受限环境，通过微弱但具方向性的相互作用精准定向单体和增长链末端，从而促进高立体选择性的开环反应。该系统在二氯甲烷中实现了化学可回收外消旋二硫代内酯的超快立构选择性开环聚合。","scd":null,"kp":["[外消旋二硫代内酯的立构选择性开环聚合]: 非经典C─H⋯X (X = O, S) 氢键相互作用催化体系","[大体积季铵阳离子]: 创造限制性空间以定向单体和增长链"]},{"i":35516,"as":"针对双原子催化剂（DACs）在光电化学（PEC）水分解中的机制不明确问题，研究构建了锚定在TiOx包覆BiVO4光电阳极上的NiFe双原子结构（NiFe DAs/TiOx/BiVO4）。该光阳极在1.23 V vs RHE下实现了6.13 mA cm-2的光电流密度，稳定性超150小时。研究证实，该体系通过*O-O*耦合机制路径改变水氧化路径，成功突破了传统吸附物演化机制的局限性。","scd":null,"kp":["光阳极材料[PEC水氧化]: TiOx涂层BiVO4上锚定NiFe双原子","[水氧化路径转换]: 以*O─O*耦合机制绕过吸附物演化机制(AEM)的限制"]},{"i":35517,"as":"扭曲分子纳米碳因具有持久手性和潜在的空间电子相互作用而备受关注。研究利用定量的四重区域选择性Scholl反应，高效合成了一种具有显著π-重叠的8字形扭曲纳米碳。通过制备型TLC板成功分离了其对映异构体，展现出持久的光学手性特性，其不对称因子适中。该研究为探索分子纳米碳的空间电子耦合效应提供了有效途径。","scd":null,"kp":["[双扭曲分子纳米碳合成]: 定量的四重区域选择性Scholl反应","分子纳米碳[构效关系]: 具有显著的π重叠及空间电子耦合/贯穿空间电子耦合"]},{"i":35518,"as":"针对二硫化钼（MoS2）负极在快充电池中电荷转移动力学迟缓的瓶颈，研究开发了原子级钴（Co）掺杂的开口空心MoS2纳米球。在结构上，开口空心设计缩短了离子扩散距离并适应体积膨胀；在电子性质上，Co掺杂增强了S 3p-Mo 4d-Co 3d轨道杂化，触发了显著的电子自旋极化，降低了嵌入和转化反应的动力学势垒。这种协同作用大幅提升了MoS2的超快锂存储性能。","scd":null,"kp":["电极材料结构[超快充电MoS2负极]: 原子级Co掺杂的开口空心纳米球结构","[电荷转移动力学加速]: 通过触发电子自旋极化实现"]},{"i":35519,"as":"半个多世纪以来，硒代半胱氨酸亚磺酸（Sec-SeOH）作为中心催化中间体一直未被成功分离。本研究通过仿生设计，将硒肽序列包裹在保护性支架内，并采用从对应硒化碘（Sec-SeI）出发的无氧化剂合成路线，首次在室温下成功分离出可结晶且热稳定的Sec-SeOH。X射线结构分析和表征表明，该分子对β-消除形成脱氢丙氨酸表现出意外的抗性。","scd":null,"kp":["[硒代半胱氨酸硒代次磺酸]: 首个在室温下可分离的形式","[提升稳定性]: 依赖于受保护空间内的仿生硒肽序列设计"]},{"i":35520,"as":"针对生物膜顽固的胞外聚合物（EPS）基质导致的根除难题，研究人员设计了聚合碳点（CDs）。为克服生成活性氧（ROS）的热力学和动力学悖论，提出了一种长路径电子受体策略。通过将碳化核心与聚萘二酰亚胺（PNDI）网络结合，实现了绝对的空间电荷解耦。这种长程空间电荷解耦机制显著促进了超氧阴离子（·O2-）等双重ROS的生成，从而实现对生物膜的高效根除。","scd":null,"kp":["[聚合物碳点驱动的生物膜根除]: 促进长程空间电荷解耦以增强双活性氧(ROS)的生成"]},{"i":35521,"as":"光催化甲烷转化为高附加值化学品提供了一条打破传统高耗能热催化的低温反应新途径。本综述系统总结了甲烷增值化反应中半导体光催化剂的理性设计进展。文章概述了光驱动CH4活化的基本原理和标准评估协议，并重点归纳了包括金属氧化物和氮化碳等在内的材料工程策略，以解决甲烷转化效率低和产物选择性差的基础性挑战。","scd":null,"kp":["[光催化甲烷转化]: 提供低温路径，规避传统热催化的高能耗问题","[半导体材料]: 合理设计用于提高转化效率和产物选择性"]},{"i":35522,"as":"针对获取C-N或N-N轴手性分子的有机催化立体收敛策略有限的现状，研究开发了一种N-杂环卡宾（NHC）催化的动态动力学拆解（DKR）方法。在氧化条件下，受阻转的环状酰亚胺与烯醛发生(3+3)环化反应，合成了C-N或N-N轴手性吡啶酮。机理表明，酮-烯醇互变异构是对映体转化的机制基础。该反应产率高、非对映选择性好，对映选择性高达99:1 er，并带有远程立体中心。","scd":null,"kp":["[C─N或N─N轴手性吡啶酮合成]: N-杂环卡宾(NHC)催化阻转环状酰亚胺的动态动力学拆分(DKR)","[催化反应机理]: 烯醛在氧化条件下通过(3+3)环化进行"]},{"i":35523,"as":"理解催化活性位点在工作条件下的演化对合理设计非均相催化剂至关重要。研究利用原位低压像差校正电子显微镜，直接成像并可视化了析氢反应过程中合金态PtNi纳米团簇与相分离态Pt-NiO纳米团簇之间的转变。电子束同时作为刺激源和探针，揭示了在低水汽条件下，具有特定构型熵状态的双金属纳米团簇从熵稳定状态转变为相分离状态，从而暴露出催化活性位点的原子机制。","scd":null,"kp":["[析氢反应催化剂活性位点形成]: 合金化PtNi与相分离Pt-NiO纳米团簇之间的直接转化机制","[原位表征技术]: 低压像差校正电子显微镜(电子束同时作为刺激源和探针)"]},{"i":35524,"as":"研究提出一种利用氧化还原储库（RRs）将苄胺氧化反应（BOR）与析氢反应（HER）解耦的独立运行策略，以实现可持续的苄腈合成与氢气联产。碱性电解质虽能降低BOR过电位，但会促进苄基亚胺中间体和苄腈产物的水解分解，导致严重的碳损失，且在工业相关浓度下副反应加剧。采用氧化还原储库技术有效解决了这一问题。","scd":null,"kp":["[苄胺氧化反应(BOR)]: 电化学方法实现苯甲腈(BN)合成与析氢反应(HER)产氢的耦合","[碱性电解液]: 可降低BOR过电位，但会促进苄基亚胺的水解分解"]},{"i":35525,"as":"为提升全小分子有机太阳能电池的光电转换效率，研究通过将两种结构相似且功能互补的异构体（BTP-Br-γ和BTP-Br-δ）引入高性能主客体系统中，构建了四元共混器件。该策略有效提升了体系的形态稳定性、电荷传输效率，并抑制了能量损失，克服了全小分子太阳能电池在电荷管理和形态控制上的劣势。","scd":null,"kp":["[全小分子有机太阳能电池]: 相比聚合物太阳能电池存在电荷管理和形貌控制不佳导致功率转换效率(PCE)较低的问题","[性能提升策略]: 引入两种结构相似的异构体(混合异构体策略)以实现热稳定和高性能厚膜器件"]},{"i":35526,"as":"研究开发了一种铂催化1,3-烯炔不对称氢硅化反应，成功实现无环1,3-二烯阻转异构体的对映选择性合成。该反应使用单膦配体L1，在克服传统C-C键低旋转壁垒难题的同时，表现出良好的产率、优异的对映选择性、区域选择性和E-型立体选择性，为功能材料、药物发现和不对称催化领域提供了有效方法。","scd":null,"kp":["[阻转异构1,3-二烯合成]: 铂催化1,3-烯炔的氢硅烷化实现对映选择性合成","[非环状1,3-二烯催化挑战]: C-C键固有旋转能垒低导致催化对映选择性合成困难"]},{"i":35527,"as":"研究展示了一种可设计的范德华（vdW）晶体，用于在器件尺度模拟人工神经元细胞。该技术利用纳米结晶工艺，实现了生物膜离子通道与层状范德华晶格之间的结构相似性。通过调控系统从载流子传输主导向离子传输主导的渐进式转变，成功模拟了生物神经元的信息处理过程。","scd":null,"kp":["[光遗传学]: 采用光调节神经元活动，具备极高时空精度","[仿生信息处理人工神经元细胞模拟]: 可设计的范德华(vdW)晶体用于外部光刺激控制神经元信号"]},{"i":35528,"as":"化疗药物通过破坏线粒体膜电位（ΔΨm）诱导线粒体损伤，是药物开发评估的核心挑战。现有商用荧光探针常干扰、掩盖或人为放大药物诱导的线粒体功能障碍，导致评估结果失真和转化失败。为此，研究开发了一类具有线粒体损伤自报告功能的阳离子化学治疗探针，以提供更可靠的药物评估手段。","scd":null,"kp":["[化疗药物评价核心挑战]: 药物通过破坏线粒体膜电位(ΔΨm)诱导线粒体损伤","[癌细胞治疗探针]: 破坏线粒体并具有自我报告功能的探针用于评估ΔΨm靶向药物"]},{"i":35529,"as":"研究利用纳米柱上的WS2/WSe2异质双层结构，通过亚衍射极限探测技术，成功观察到了莫尔超晶格中的俘激子。研究发现，在莫尔势阱内，当两个层间激子的作用距离缩小至特定尺度时，它们之间的库仑力会从排斥力转变为吸引力。这一发现揭示了纳米尺度下复杂的激子相互作用物理机制。","scd":null,"kp":["[莫尔超晶格相互作用]: 层间激子被周期性势阱捕获，展现包含吸引和排斥组分的丰富相互作用物理","[纳米柱异质双层观测技术]: 亚衍射极限探针观测莫尔捕获的双激子"]},{"i":35530,"as":"这篇综述探讨了外场响应型生物材料（EFRBs）在组织修复与再生中的应用。EFRBs能够响应光、磁、电、超声和热等外部刺激，实现按需激活及免疫相关通路的调控。文章概述了组织修复的动态生物学需求及免疫微环境的作用，详细介绍了EFRBs的结构特征，及其在精确时空控制组织修复中的核心优势。","scd":null,"kp":["[组织缺损修复过程]: 涉及炎症调节、血管生成、细胞外基质组装和免疫微环境稳态的时空控制","[外部场响应生物材料(EFRBs)]: 响应光、磁、电、超声和热刺激，在再生医学中实现按需激活"]},{"i":35531,"as":"针对手性π共轭有机小分子在圆偏振光（CPL）探测中因吸收不对称因子（gabs）较低而受限的问题，研究报道了一种利用手性记忆效应的无模板制备方法，构建了具有高gabs值的螺旋超分子。该策略有效平衡了电偶极矩和磁偶极矩，提升了圆偏振光探测性能。","scd":null,"kp":["分子结构[手性π共轭有机小分子]: 具有本征手性、明确的分子结构和易于修饰的特点","应用瓶颈[圆偏振光探测]: 吸收不对称因子较低，受限于不平衡的电偶极和磁偶极跃迁矩"]},{"i":35532,"as":"钙钛矿太阳能电池在运行初期会产生严重的老化损失，其根源在于光热条件下掩埋的自组装单分子层（SAM）与钙钛ite界面发生配位松弛或解离，导致最初数十小时内离子快速迁移。为解决此问题，研究开发了一种多齿膦酸聚合物网络，有效抑制了界面的离子迁移和光热老化损失，提升了组件的长期稳定性。","scd":null,"kp":["衰减机制[钙钛矿太阳能电池组件]: 初始运行阶段的烧损损失会导致异质功率输出，加剧子电池间的串并联失配","技术痛点[单体自组装单层]: 在严苛的光热应力下会发生严重的早期性能衰减"]},{"i":35533,"as":"研究利用DNA进行胶体晶体工程，成功组装了具有极高晶格应变耐受力的多相胶体晶体。DNA的结构灵活性能够容纳高达18%的晶格失配。基于此，研究首次在具有(110)面的体心立方晶体上，成功外延生长出具有(111)面的面心立方晶格，克服了晶格失配导致的晶体稳定性下降问题。","scd":null,"kp":["组装方法[多相胶体晶体]: 利用DNA进行胶体晶体工程组装","晶体稳定性[胶体晶体的异质外延生长]: 对晶格应变具有极高的容忍度"]},{"i":35534,"as":"为治疗急性肾损伤（AKI）并保护肾脏免受细胞组织损伤，研究提出了一种基于超声-电流转换驱动的无线定位和跟踪纳米机器。该纳米机器（Au@PASP-PArg/BaTiO3）具有高介电常数和压电特性，能够获取内源性超声电流，并在外加电流引导下进行精准导航，为高效抑制肾脏损伤提供了一种新技术。","scd":null,"kp":["纳米机器结构[无线定位追踪治疗设备]: 单侧覆盖金的PASP-PArg/BaTiO3底盘 (Au@PASP-PArg/BaTiO3, ASPB)","驱动机制[超声波驱动纳米机器]: 基于内部超声多重散射的电流-超声转换驱动"]},{"i":35535,"as":"研究揭示了钨或钼亚烷基络合物催化烯烃复分解反应中催化活性中心的形成机制。结果表明，在环烯烃存在下，W(NR)(OR')2Cl2络合物发生双电子还原反应，生成W(NR)(OR')2(环烯烃)和/或W(NR)(OR')2(环亚烷基)络合物。这一过程由环烯烃催化生成亚烷基络合物，但过量的环烯烃又会对该过程产生抑制作用。","scd":null,"kp":["催化机制[钨亚烷基络合物生成]: 烯烃复分解反应中催化活性的环亚烷基络合物可由环烯烃自身催化生成，亦可被其抑制","前驱体[双电子还原反应]: W(NR)(OR')2Cl2络合物"]},{"i":35536,"as":"研究开发了一种铜催化的不对称硼氢化反应，将炔烃与N-芳基氮硼杂苯在温和条件下反应，高效合成C-N轴手性氮硼杂苯。该反应具有高收率、优异的区域选择性、Z型立体选择性和对映选择性，通过动态动力学拆分机制克服了相关分子骨架难以直接合成的挑战。","scd":null,"kp":["催化合成[碳-氮轴手性氮硼杂环]: 铜催化不对称硼氢化反应，通过动态动力学拆分直接构建"]},{"i":35537,"as":"研究采用密度泛函理论（DFT）计算，深入探究了反向ZrO2/Cu催化剂上二氧化碳加氢制甲醇的反应机理。通过分析反应条件下可及的83种甲酸盐构象，发现该反应表现出显著的结构敏感性：在所有催化剂构象中，仅有10种构象在反应中表现出显著的催化活性，揭示了催化位点的反应性与失活机制。","scd":null,"kp":["催化性能[二氧化碳加氢制甲醇]: 具有高催化性能","催化剂模型[高度分散的Zr氧化物团簇]: 负载于Cu(111)上的反相ZrO2/Cu催化剂"]},{"i":35538,"as":"研究开发了一系列超窄半峰宽（FWHM）有机发光体。通过将反芳香性环丁二烯结构引入含氮多环芳烃中，利用非苯环π电子微扰效应重构了前沿轨道的对称性。这种重构有效抑制了内在的成键-反键跃迁特性，实现了超窄的光谱发射，为高清显示技术提供了突破传统分子设计限制的新策略。","scd":null,"kp":["发射特性[超窄带有机发光体]: 具有超窄的半峰宽（FWHM）","分子设计[非苯类π电子微扰]: 将反芳香性环丁二烯基序引入含氮多环芳烃中，实现前线轨道对称性重构"]},{"i":35539,"as":"研究通过还原铂(II)前体，获得了两种由庞大卡唑基PNP配体支撑的阴离子T型d10铂(0)络合物，分别以Na+和[MgCl(thf)2]+为反离子。在与有机溴化物的反应中，根据产生自由基的稳定性，生成了均偶联碳氢化合物以及铂(II)溴化物和烷基物种。原位EPR光谱学研究揭示了铂(I)中间体在自由基反应中的存在。","scd":null,"kp":["络合物结构[阴离子T型铂配合物]: 还原铂(II)氯化物前驱体获得d10构型的铂(0)配合物","存在形态[接触离子聚集体]: 与Na+和[MgCl(thf)2]+结合形成"]},{"i":35540,"as":"研究通过添加剂工程，在采用A-D-A'-D-A型受体的有机太阳能电池中实现了超过30毫伏的光电压损失（Vloss）缓解，同时保持了高电荷产生与传输效率。实验与分子动力学模拟分析表明，添加剂处理能够有效调节共混薄膜的形态，抑制了电荷转移态能级的降低，从而提升整体光伏效率。","scd":null,"kp":["技术瓶颈[添加剂工程处理的有机太阳能电池]: 电荷转移激子离域化增加导致CT态能量降低，损害光电压并限制效率提升","改性目标[有机太阳能电池]: 实现光电压损失的有效缓解"]},{"i":35541,"as":"研究开发了一种基于环加成-环消除反应（CACR）策略的骨架编辑方法，实现了吡啶氮原子的易位转化。该方法将易于合成的4-芳基或烷基吡啶转化为难以通过传统途径获取的间位功能化（3-烷基化）异构体。此外，该环加成反应引入的多功能砜基团还可用于后续的C-X和C-C键构建。","scd":null,"kp":["[4-aryl and alkyl pyridines transposition]: 采用环加成/环逆转策略 (CACR) 实现4-芳基和烷基吡啶向3-烷基化吡啶的转化","[氮原子位移技术]: 骨架编辑方法"]},{"i":35542,"as":"研究开发了一种在镁介导下，将丙炔基和烯丙基双氯化物与氯硅烷进行双交叉亲电偶联的新策略，用于合成二硅基取代的丙二烯和双(硅基)丙烯。该方法无需过渡金属催化剂或配体，具有优异的产率。机理研究表明，二氯化物与镁反应生成碳亲核试剂，随后对氯硅烷发生SN2取代反应生成最终产物。","scd":null,"kp":["[二硅基取代的丙二烯和双(硅基)丙烯合成]: 丙炔基和烯丙基同碳二氯化物与氯硅烷在镁介导下发生双交叉亲电体偶联","[催化体系特点]: 无需过渡金属催化剂或配体","[反应收率]: 良好至极佳"]},{"i":35543,"as":"研究报道了一种铑催化的含炔醚三炔底物[2+2+2]环加成反应，实现了轴手性二芳基醚的高对映选择性合成。该方法通过芳构化反应一步构建芳香环、限制Ar-O键的旋转并引入多样化的取代基，成功克服了传统去对称化策略中存在的局限性，为生物活性分子和手性材料提供了一种有效的合成途径。","scd":null,"kp":["[轴向手性二芳基醚合成]: 铑催化对映选择性 [2+2+2] 环加成反应","[Ar–O键旋转能垒]: 相对较低"]},{"i":35544,"as":"研究团队开发了一种集成CRISPR/Cas13a的纳米探针系统（InCasRD），用于组织切片中RNA的快速检测。与传统依赖探针杂交的“始终开启”型探针不同，InCasRD利用Cas13a的反式切割活性，实现了空间受限的信号放大和极高的信噪比（SBR），成功应用于组织切片中突变mRNA的原位扩增成像。","scd":null,"kp":["[突变mRNA原位成像技术]: 基于集成CRISPR/Cas13a的纳米探针系统","[RNA组织切片检测速度]: 快速"]},{"i":35545,"as":"研究人员提出了一种人工酶组装工程，将光热模块与仿生催化框架相结合。该集成催化剂（Cux/Cu1-NC）在氮掺杂碳基底上锚定了共存的铜团簇和单原子。在光电系统中，该催化剂实现了近100%的氨选择性，将硝酸盐高效转化为氨，超越了自然酶的固有功能和局限性。","scd":null,"kp":["[硝酸盐电催化还原制氨 (NO3- to NH3)]: 接近100%的法拉第效率","[人工酶组装工程]: 集成光热模块与仿生催化框架","[集成催化剂体系]: Cux/Cu"]},{"i":35546,"as":"这是关于科研人员Xiaoran Hu的个人简介。他表示化学的乐趣在于赋予人类合理设计并创造自然界原本不存在分子和材料的能力。他建议学生分析并理解失败的实验以培养化学直觉，而不是轻易放弃意外或不想要的结果。","scd":null,"kp":[]},{"i":35547,"as":"研究提出了一种用于工业级析氧反应（OER）的高密度Fe-N-C催化剂。理论计算表明，Fe位点密度对关键中间体的吸附能具有持续调节作用。实验证实，逐步增加Fe位点密度能够精细调节表面*OH覆盖率，从而定制O-O自由基耦合路径，解决高电流密度下运行稳定性不足的问题，满足阴离子交换膜大规模制氢需求。","scd":null,"kp":["[OER催化剂阴离子交换膜水电解]: 需要低成本、高效且在 高电流密度 下具备充足操作稳定性的催化剂","[高密度Fe─N─C催化剂反应路径]: 理论计算揭示了连续的定制化 O─O 自由基耦合路径"]},{"i":35548,"as":"为解决水系锌碘电池中“死碘”导致的利用率低和面积容量受限问题，研究设计了一种由卤键交换驱动的界面接力氧化还原策略。利用在集流体上由硫化碘电化学产生的多碘化物作为氧化还原锚点，实现了电解质-电极界面的碘接力转化。该方法形成疏水有机阳离子-多碘化物对以抑制穿梭效应，同时促进多碘化物的均匀沉积与溶解。","scd":null,"kp":["[水系Zn||碘电池]: 界面继电器氧化还原策略由卤素键交换驱动，解决高倍率下死碘问题并提升碘利用率和面容量","[多碘化物中间体]: 电化学产生的多碘化物 (如 I3−)"]},{"i":35549,"as":"这是关于科研人员Jerry Alfred Fereiro的个人简介。他将尼古拉·特斯拉、迈克尔·法拉第和理查德·费曼视为科学英雄，因为他们完美结合了创新、实验才华和基础理解能力。他的座右铭是：享受生活，享受所做的事情，把工作变成自己热爱的事物。","scd":null,"kp":[]},{"i":35550,"as":"研究将光纤布拉格光栅传感器嵌入锂金属电极中，实现了充放电循环过程中内部应力的实时监测。测量揭示了与活性锂迁移行为一致的动态应力演化过程，该过程表现出非均匀性特征。这一方法为直接洞察锂金属电池中由电化学机械效应驱动的枝晶生长和不稳定界面问题提供了内部应力演变特征的直接数据。","scd":null,"kp":["[锂金属电池理论容量]: 最高","[锂金属电极电化学-力学效应]: 枝晶生长和不稳定界面由电化学-力学效应驱动","[内部应力演化特征监测]: 使用光纤传感器监测"]},{"i":35551,"as":"这是一篇更正声明，针对的是由JinHa Shim等人撰写、发表于《Energy & Environmental Science》期刊的论文《前驱体驱动的姜-泰勒效应：富镍锰稳定正极材料表面不稳定性的隐匿根源》（DOI: 10.1039/D6EE00713A）。声明未提供具体的技术细节。","scd":null,"kp":["[Mn稳定富Ni正极表面不稳定性]: 前驱体驱动的 Jahn-Teller 畸变是其隐藏根源"]},{"i":35552,"as":"为解决钠离子电池P2型正极材料的不可逆相变和湿气敏感性问题，研究通过相工程和位点选择性取代设计了层状氧化物P2/O3-Na8M（Na0.80Mn0.60Mg0.07Ni0.23Cu0.07Zn0.03O2）。在Na位点的Zn选择性取代起到了支柱作用，防止了相变并利用更强的Zn-O键阻隔水分子插入；过渡金属位点的Cu/Mg取代则通过增强Cu-O共价性抑制了氧流失，显著提升了结构稳定性和空气稳定性。","scd":null,"kp":["[P2-Na0.67Ni0.33Mn0.67O2正极相变]: 充电至4.0V以上时发生不可逆 P2-O2 相变","[P2-Na0.67Ni0.33Mn0.67O2正极降解]: 放电至2.0V时发生 Mn3+ 降解","[高熵层状氧化物正极设计 (P2/O3-Na8M)]: 相工程与位点选择性取代的协同","[P2/O3-Na8M材料化学式]: Na0.80Mn0.60Mg0.07Ni0.23Cu0.07Zn0.03O2","[改性钠离子电池正极性能]: 具备空气稳定性和长循环寿命"]},{"i":35553,"as":"该综述阐述了电催化合成聚合物单体的策略演变框架，涵盖从基础转化到集成系统的三个阶段：一是由原位生成的活性物种驱动的水相电化学转化，用于生产己二酸等单体；二是电生亲核或亲电中间体发生C-N或C-C偶联的耦合电催化转化，用于合成环己酮肟等复杂单体；三是更高级的集成催化系统。","scd":null,"kp":["[聚合物单体电合成策略]: 涵盖从基本水相电化学转化到集成催化系统的递进演化框架"]},{"i":35554,"as":"该综述系统总结了锌金属电池中的晶面工程。晶体学晶面工程能有效调节锌沉积的热力学，但其实际应用受限于枝晶生长、析氢和腐蚀等问题。文章理清了主导锌晶面的结构与性能关系，对比了热处理、机械加工、电沉积和激光/化学刻蚀等关键制备方法，并指出当前缺乏规模化合成、苛刻条件下晶面退化以及活性与稳定性权衡等应用挑战。","scd":null,"kp":["[锌金属电池晶面工程]: 有效调节锌沉积热力学，但在规模化合成、恶劣条件下的晶面退化及机制不明确方面面临挑战"]},{"i":35555,"as":"研究探明了钌（Ru）团簇在碱性析氢反应（HER）条件下的尺寸依赖性动态表面行为。通过探测从原子级分散的单原子到纳米颗粒范围内催化剂的氧化态，阐明了亚纳米团簇在电化学条件下丰富的低配位金属原子导致的独特表面行为。该研究强调了动态表面状态在调节界面水结构并增强催化性能中的关键作用。","scd":null,"kp":["[亚纳米Ru簇催化剂]: 桥接单原子与纳米颗粒，提供独特的电子结构和高效的金属利用率"]},{"i":35556,"as":"研究披露了一种基于组成改变和可逆质子转移的光驱动分子马达运转机制。与传统的光致键旋转机制不同，该机制在运转周期中伴随结构重组。该分子马达能够保留极高的入射光能量，这一特性被成功应用于低温分子太阳能热能存储系统，实现了太阳能的存储与受控释放。","scd":null,"kp":["[光驱动分子马达运转机制]: 涉及组成结构改变和可逆质子转移的高效机制"]},{"i":35557,"as":"研究开发了包含两个结构不同的转子的人工双分子马达，首次在单个分子内实现了两个主动驱动的旋转。每个转子在独特的频率下运作，形成分子转向系统。转子的激活偏好源于光化学（而非热学）行为的差异，并且可以通过改变转子结构、溶剂和光源来进行调控。","scd":null,"kp":["[双分子马达系统]: 在单一分子内实现具有两个不同旋转频率的主动驱动旋转"]},{"i":35558,"as":"该综述重点介绍了自2019年以来细胞表面糖工程及其生物应用的重大进展。细胞表面聚糖在生理和病理过程中发挥核心作用。文章总结了修饰细胞表面聚糖的多种方法，包括代谢糖工程、遗传修饰、酶介导重塑和合成糖脂整合。这些技术进步推动了基础研究和治疗应用中对糖萼的精准操控。","scd":null,"kp":["[细胞表面糖萼工程]: 通过多种方法对细胞表面密集的糖聚合物层进行操控以用于基础研究和治疗"]},{"i":35559,"as":"","scd":null,"kp":[]},{"i":35560,"as":"类脑光计算技术突破了传统基于矩阵的光学计算限制。该技术结合了光子记忆、学习能力和事件驱动处理机制，在边缘计算和具身智能系统中实现了超低延迟感知、高带宽数据交互以及高能效的自主控制，为智能系统提供了一条新的技术路径。","scd":null,"kp":["[仿脑光计算技术]: 结合光子记忆、学习和事件驱动处理，实现超低延迟感知和节能自主控制"]},{"i":35561,"as":"结构可编程技术使固态电解质能够构建成具有应力调节、定向离子传输调节和界面稳定功能的架构框架。这种结构编程策略使全固态微电池能够在无堆叠压力的条件下运行，从而实现了其与微系统的无缝集成。","scd":null,"kp":["[全固态微型电池固态电解质]: 结构化编程构建的架构框架可实现应力调节、定向离子传输和界面稳定，从而支持无堆叠压力运行"]},{"i":35562,"as":"","scd":null,"kp":[]},{"i":35563,"as":"过去十年中，聚合物科学已从精密合成转向循环经济设计。在可回收、解聚和数据驱动方法等领域的突破，对于在地球生态承载极限内设计具有可持续性的聚合物材料起到关键作用。","scd":null,"kp":["[聚合物科学发展]: 从精确合成向循环经济设计转变，依赖回收、解聚和数据驱动方法"]},{"i":35564,"as":"研究设计了一种无铜的Ag/Cr2O3电催化剂，在过氯酸盐的辅助下，实现了选择性电还原二氧化碳为乙醇。该催化剂在约160 mA/cm²的电流密度下，法拉第效率超过50%。过氯酸盐能够破坏连续的氢键网络，从而抑制竞争性的析氢反应。此外，银-铬不对称位点进一步稳定了碳-碳（C-C）耦合中间体，降低了生成乙醇的反应能垒，使其优于生成乙烯的途径，从而实现了高选择性的乙醇生成。","scd":null,"kp":["法拉第效率[无铜Ag/Cr2O3电催化CO2还原为乙醇]: >50%","电流密度[无铜Ag/Cr2O3电催化CO2还原为乙醇]: ~160 mA/cm2","[界面氢键网络调控]: 高氯酸盐的加入破坏了连续的氢键网络，从而抑制了竞争性析氢反应","[Ag-Cr不对称位点]: 稳定C-C偶联中间体并降低乙醇生成路径能垒"]},{"i":35565,"as":"本文介绍了离子热电技术作为一种柔性能量转换技术。作者包括Weishu Liu、Xiaogang Zhang和Nicholas X. Fang，文章发表于《National Science Review》。该技术主要探讨利用离子系统进行热能向电能的转化，为柔性电子设备等领域的能源收集与转换提供了新的技术途径。","scd":null,"kp":[]},{"i":35566,"as":"","scd":null,"kp":[]},{"i":35567,"as":"","scd":null,"kp":[]},{"i":35568,"as":"","scd":null,"kp":[]},{"i":35569,"as":"","scd":null,"kp":[]},{"i":35570,"as":"","scd":null,"kp":[]},{"i":35571,"as":"研究提出了一种双相界面原子刻蚀策略（BIAES），将原子级缺陷引入黑磷纳米片中，为可控负载金属单原子和纳米晶体微区提供了高密度锚定位点和空间限域。强烈的金属-载体相互作用以及纳米晶体对相邻单原子位点的调节，显著提升了催化剂的催化性能。","scd":null,"kp":["缺陷引入策略[黑磷纳米片]: 双相界面原子刻蚀","活性位点[金属单原子/纳米晶微区]: 高密度锚定位点与空间限域","催化增强机制[相邻单原子位点]: 纳米晶诱导调制与强金属-载体相互作用"]},{"i":35572,"as":"","scd":null,"kp":[]},{"i":35573,"as":"研究开发了一种名为Dexime的、可被酶选择性降解的水凝胶，用于蛋白质治疗药物的释放。这种水凝胶通过改性糊精（酮或醛基团）与聚乙二醇-四氧胺发生点击交联形成。其流变学和力学性能可通过总糊精重量百分比和pH值等参数进行调节。该水凝胶能够通过30G注射器针头注射，并具有选择性降解的特性，避免了传统给药系统中常见的蛋白质变性剪切力或有机溶剂。","scd":null,"kp":[]},{"i":35574,"as":"研究整合了空间生物物理与经济数据及优化方法，开发了可持续景观效率前沿，展示了生物多样性保护、基于土地的气候缓解以及农业和林业生产净经济价值的最大可行组合。对146个国家的应用结果显示，改善土地的利用和管理能够在生物多样性、气候和经济方面带来巨大收益。各国结果汇总表明，气候缓解潜力可增加超过2000亿吨二氧化碳当量。","scd":null,"kp":[]},{"i":35575,"as":"","scd":null,"kp":[]},{"i":35576,"as":"","scd":null,"kp":[]},{"i":35577,"as":"","scd":null,"kp":[]},{"i":35578,"as":"","scd":null,"kp":[]},{"i":35579,"as":"指出美国地表臭氧暴露水平在过去数十年取得的改善成果，目前正面临被野火逆转的风险。野火产生的烟羽会增加臭氧的生成，从而对环境造成负面后果。","scd":null,"kp":[]},{"i":35580,"as":"","scd":null,"kp":[]},{"i":35581,"as":"","scd":null,"kp":[]},{"i":35582,"as":"研究开发了一种可扩展的、具有立体保留性的自由基-自由基交叉偶联方法，用于构建C(sp3)–C(sp3)键。该反应基于对映体富集的磺酰肼和无手性卤代烷，在无需手性配体、导向基团或外加氧化还原剂的条件下进行。该底物控制的策略利用了镍催化的氧化还原中性机制，实现了重氮介导的自由基生成与卤素原子转移的精确动力学匹配。","scd":null,"kp":["合成方法[立体保持型烷基-烷基交叉偶联]: 两种不同瞬态烷基自由基的可规模化交叉偶联","反应物来源[手性烷基自由基]: 对映体富集的磺酰肼"]},{"i":35583,"as":"","scd":null,"kp":[]},{"i":35584,"as":"","scd":null,"kp":[]},{"i":35585,"as":"","scd":null,"kp":[]},{"i":35586,"as":"文章提出了一种轨道“安全气囊”的概念，旨在通过卫星释放气体来阻挡太阳风暴，从而大幅降低极端空间天气带来的威胁。","scd":null,"kp":[]},{"i":35587,"as":"研究通过在氮化硼（BN）纳米管内部进行空间限域反应，成功合成了直径接近1纳米的单壁二硫化钼纳米管。限域几何结构稳定了常规方法难以达到的高应变纳米管，生成了结构明确的扶手椅型构型。研究发现，随着直径的减小，这些纳米管的带隙发生系统性收缩。这一技术突破了传统合成方法只能生产大直径且手性不受控多壁管的限制。","scd":null,"kp":["直径[单壁二硫化钼纳米管]: 接近1纳米","手性控制[扶手椅型单壁二硫化钼纳米管]: 空间限域生长实现严格控制"]},{"i":35588,"as":"研究利用深度学习开发了1公里分辨率的日地表臭氧数据集，发现美国全国臭氧趋势从2003-2015年的每年下降0.65 ppb，转变为2015-2024年的每年上升0.13 ppb。这一趋势逆转主要由野火排放增加引起，抵消了3.9年的减排进展。自2013年以来，火灾引发的臭氧导致的过早死亡人数每年增加318人，死亡率比2013年前高出46%。","scd":null,"kp":["空间分辨率[每日地表臭氧数据集]: 1公里","趋势变化[美国地表臭氧浓度]: 从-0.65 ppb/年(2003-2015)逆转为+0.13 ppb/年(2015-2024)"]},{"i":35589,"as":"","scd":null,"kp":[]},{"i":35590,"as":"","scd":null,"kp":[]},{"i":35591,"as":"研究发现植物免疫受体NLR MLA3通过分子模拟病原体效应器的毒性靶标来识别病原体，从而触发免疫反应。通过将这种模拟结合界面引入小麦秆锈病抗性蛋白SR50中，研究人员生物工程改造出一种嵌合受体，该受体具备双重识别活性。在转基因大麦品系中，这种嵌合受体赋予了对两种主要谷物病原体的抗性，为植物抗病性改造提供了新思路。","scd":null,"kp":[]},{"i":35592,"as":"","scd":null,"kp":[]},{"i":35593,"as":"","scd":null,"kp":[]},{"i":35594,"as":"","scd":null,"kp":[]},{"i":35595,"as":"艾伦研究所发起了一项大脑映射计划，旨在寻找神经退行性疾病的根源。该项目致力于捕捉引发这些疾病的最早期的细胞损伤，并期望通过这些微观层面的生理机制研究，识别并确定全新的药物靶点，从而为相关疾病的干预和治疗提供明确的方向。","scd":null,"kp":[]},{"i":35596,"as":"美国正逐步加强对“双重用途研究”的监管力度。然而，这种强化的监管措施正面临日益严重的管辖权限制问题。同时，这些更为严格的审查与合规要求给美国本土的科学研究带来了额外的成本负担，影响了国内科研活动的效率与资源分配。","scd":null,"kp":[]},{"i":35597,"as":"随着人工智能（AI）技术的飞速发展与大量应用，天体物理学界开始对这一领域的核心精神与本质进行反思。在AI自动化处理海量天文数据并得出结果的背景下，天体物理学家们正在重新审视人类在天文学研究中的角色，以及AI泛滥对传统天体物理学方法论带来的挑战。","scd":null,"kp":[]},{"i":35598,"as":"DNA研究揭示了巴西沿海“滚石礁”生态系统中隐藏的生物多样性，证实该区域具有极高的物种丰富度。与此同时，这项研究结果也针对当前在该区域进行的石油勘探活动发出了严厉警告，指出石油开采等人类活动可能对这些脆弱且极具生态价值的礁石系统构成严重威胁。","scd":null,"kp":[]},{"i":35599,"as":"随着人工智能（AI）能力的快速提升，人类对这些系统的理解正日益落后于其发展速度。多种趋势的交织导致AI系统变得更加难以理解，而其产生的影响却愈发深远。如果不采取刻意的应对措施，人类能够有效理解和引导AI系统的机会之窗可能会永久关闭，导致技术失控。","scd":null,"kp":["[AI系统可解释性与可引导性]: 多种趋势交汇使得人类理解AI系统日益困难，构建能够被有意义理解和引导的AI系统的窗口期可能正在不可逆转地关闭"]},{"i":35600,"as":"","scd":null,"kp":[]},{"i":35601,"as":"","scd":null,"kp":[]},{"i":35602,"as":"研究利用单核苷酸精度的紫外交联免疫沉淀结合RNA测序技术，揭示了拟南芥剪接因子1（AtSF1）的分子功能。研究鉴定了AtSF1在体内结合的分支点序列并描绘了其RNA结合图谱，发现其突变会导致广泛的剪接缺陷，主要表现为3'剪接位点选择的异常。这证实AtSF1通过改变3'剪接位点选择来调节植物的昼夜节律和免疫反应。","scd":null,"kp":[]},{"i":35603,"as":"研究使用极简的DNA纳米传感器，在细胞环境下精确量化了双链DNA之间的同源识别现象（即具有相同序列的DNA双链能相互识别）。研究发现，同源性增强了由生理二价阳离子诱导的双链间亲和力，并精确测量出由同源序列驱动的识别自由能约为-0.01 kcal。这一结果为DNA重组和修复机制中的纯粹物理相互作用假说提供了直接证据。","scd":null,"kp":["[同源识别机制评估]: 使用最小DNA纳米传感器精确量化同源双链DNA之间的相互作用","[DNA双链同源识别]: 同源性增强了由生理二价阳离子诱导的双链-双链亲和力"]},{"i":35604,"as":"研究开发了一种在室温和大气压下，利用二氧化碳（CO2）作为氧供体的光催化烯烃氧化断裂新方法，可生成酮或羧酸。该反应采用坚固的铁基多相光催化剂，通过氧转移形成环氧化物中间体，进而开环并断裂碳碳键，实现高选择性产物转化。结合时间分辨光谱、同位素标记和量子力学模拟的机理研究，揭示了这一温和条件下的基础催化机制。","scd":null,"kp":["反应条件[烯烃光催化氧化裂解]: 常压、室温","氧供体[烯烃光催化氧化裂解]: 二氧化碳(CO2)","催化剂[烯烃光催化氧化裂解]: 稳健的铁基多相光催化剂","[烯烃光催化氧化裂解机理]: 发生氧转移形成环氧化物中间体，随后进行开环"]},{"i":35605,"as":"","scd":null,"kp":[]},{"i":35606,"as":"研究探讨了手性自旋液体中具有相反手性的畴界面的物理性质。通过建立畴壁的Ginzburg-Landau理论，证明了畴壁附近自旋子的自洽平均场描述依然成立。手性自旋液体体相包含有能隙的自旋子激发和规范涨落（由有限自旋子质量和非零自旋子陈数设定），此外还存在一类具有等效vielbein场几何解释的自旋子跳跃幅度涨落。","scd":null,"kp":["[手性自旋液体畴壁结构]: 使用自旋子的自洽平均场描述构建了畴壁的金兹堡-朗道理论"]},{"i":35607,"as":"研究开发了一种基于烟草脆裂病毒（TRV）的系统，递送紧凑型ISYmu1 TnpB核酸酶并结合植物体内枝条再生技术，成功在多种番茄品种中实现了无需组织培养且无转基因的遗传基因编辑。通过靶向SlPDS基因，研究在单代繁育中成功培育出无病毒感染的纯合突变体后代，并验证了该系统在未特征化基因功能分析中的有效性。","scd":null,"kp":["递送系统[番茄可遗传基因组编辑]: 基于烟草脆裂病毒(TRV)的系统","核酸内切酶[番茄可遗传基因组编辑]: 紧凑型ISYmu1 TnpB","[番茄可遗传基因组编辑工艺]: 结合植株内芽再生，无需组织培养和转基因材料，且不受基因型限制"]},{"i":35608,"as":"","scd":null,"kp":[]},{"i":35609,"as":"","scd":null,"kp":[]},{"i":35610,"as":"","scd":null,"kp":[]},{"i":35611,"as":"","scd":null,"kp":[]},{"i":35612,"as":"研究表明，患有严重肥胖症的射血分数保留型心力衰竭（HFpEF）患者的心肌细胞表现出显著受抑的收缩储备，包括钙刺激张力、功率和肌球蛋白激活降低，其功能衰竭程度与晚期心衰患者相似。这些心肌缺陷与HFpEF患者的体重指数及运动血流动力学直接相关。此外，减重有望逆转这些缺陷，且伴随肌钙蛋白I磷酸化水平的增加。","scd":null,"kp":["[重度肥胖HFpEF患者心肌细胞]: 收缩储备严重受抑，钙和长度刺激引起的张力、功率和肌球蛋白激活降低"]},{"i":35613,"as":"","scd":null,"kp":[]},{"i":35614,"as":"","scd":null,"kp":[]},{"i":35615,"as":"研究提出了一种新型的双离子共调节策略，通过配位介导的凝胶化相变方法，成功制备了过渡金属硫化物/硫氮共掺杂碳气凝胶。第一性原理计算证实，硫和氮的共掺杂有效调节了碳基体的电子结构，增强了局部电荷不平衡。这种局部电荷工程策略克服了传统电磁波吸收材料可控性有限的缺陷，实现了多功能、可编程的复杂电磁波衰减效果。","scd":null,"kp":["[电磁波吸收材料制备]: 采用配位介导的凝胶化相变方法，通过双离子共调制策略设计过渡金属硫化物/硫氮共掺杂碳材料"]},{"i":35616,"as":"本文综述了有机室温磷光（RTP）纳米材料的制备方法及其在生物领域的应用进展。有机RTP材料凭借高三重态激子利用率、大斯托克斯位移和长寿命发射，在OLED、生物成像等领域备受关注。传统块状RTP材料存在机械脆性和水相分散性差等缺点，难以应用于复杂的生物环境。综述重点总结了维持高强度三重态发射的高效纳米级有机磷光颗粒的制备策略，以克服传统块体材料的局限性。","scd":null,"kp":["应用领域[有机室温磷光材料]: OLEDs、安全数据加密、化学传感、生物成像和闪烁体","传统室温磷光材料[本体状态合成]: 具有固有的机械脆性和水相分散性差"]},{"i":35617,"as":"本文报道了一类新型手性碘化亚铜簇闪烁体材料，用于圆偏振辐射发光成像，通过抑制光学串扰提升X射线成像分辨率。研究合成了对映体纯的R-/S-3-MLCuI和外消旋的Rac-3-MLCuI，通过选择对映体精确控制晶体对称性（手性P42212与中心对称C2/c），从而决定手性光学活性。结合TD-DFT、原位XAS和超快光谱技术，研究阐明了材料发光的内在机制与结构起源。","scd":null,"kp":["材料结构[圆偏振闪烁体]: 手性卤化亚铜簇合物（包含对映体纯的R-/S-3-MLCuI和外消旋的Rac-3-MLCuI）","技术优势[圆偏振发光X射线成像]: 通过抑制光学串扰提升成像分辨率"]},{"i":35618,"as":"本文提出一种在钙钛矿结晶前沉积三碱金属夹层（LiOH/KCl/CsI）的策略，以解耦钙钛矿太阳能电池中的体相均质化与界面重构。该设计实现了空间上的结晶调控与组分调制分离：局部Li+和K+离子重构隐藏接触并钝化缺陷，界面Cs+离子则作为动态来源实现原位向上扩散。该机制有效克服了传统体相掺杂导致的垂直偏析和晶格应变问题，大幅提升了器件性能。","scd":null,"kp":["界面工程[钙钛矿薄膜结晶前调控]: 引入三碱金属阳离子中间层（LiOH/KCl/CsI）","技术机理[沉积于电子传输层]: 空间解耦结晶调控与界面重组，解决传统体相掺杂导致的垂直偏析和晶格应变问题"]},{"i":35619,"as":"本文提出了一种飞秒激光界面工程策略，用于制备具有分级微纳结构和富氧空位特征的自支撑镍基阳极。该电极设计同时具备超亲水性和超疏气性，能够实现大电流密度下的快速气液传输。此外，氧空位的引入有效调控了表面电子性质，显著增强了析氧反应（OER）的本征催化活性。在工业级水电解条件下，该激光结构化电极展现出优异的OER活性和运行稳定性。","scd":null,"kp":["制备工艺[工业水电解析氧电极]: 单步飞秒激光界面工程技术","材料特征[自支撑镍基阳极]: 具有分级微/纳米结构、富氧空位表面以及超疏水特性","催化机制[高效传质与高电流密度]: 氧空位激活晶格氧驱动析氧反应，满足大电流下高本征活性与传质需求"]},{"i":35620,"as":"本文利用非富勒烯受体（NFAs）的体相光生电荷特性，有效提升了可拉伸有机太阳能电池在形变下的性能稳定性。该机制对共混形貌依赖性弱，显著减少了弹性体稀释光敏层中的激子利用损失。研究基于π-π四极矩分子描述符，从130种NFAs中筛选出具有优异体相光生电荷能力的AQx-2F，并结合SEPS弹性体进行器件制备，使器件在90%拉伸应变及30%应变循环下仍保持稳健的光伏性能。","scd":null,"kp":["拉伸应变耐受[可拉伸有机太阳能电池]: 可承受90%的极限拉伸应变及30%的应变循环","工作机制[非富勒烯受体]: 利用非富勒烯受体的体相光生电荷特性，降低对共混形貌的依赖以缓解激子利用损失"]},{"i":35621,"as":"本文利用机器学习原子间势构建了大规模分子动力学轨迹，深入研究了非晶态氧卤化物固体电解质的碱金属离子传输机制。研究发现非晶态结构由不同长度的金属-阴离子四面体链状片段组成，其离子电导率高达1 mS，且几乎不依赖于底层化学组成。通过分析碱金属阳离子迁移的停留时间，揭示了这些材料具有优异化学稳定性、机械柔软性及与晶体导体截然不同的传输特性。","scd":null,"kp":[]},{"i":35622,"as":"本文综述了由不对称金属1-氧-金属2（M1-O-M2）组成的不对称氧桥（AOB）在多相催化领域的设计框架与应用进展。不对称配位特性诱发了独特且可控的界面电荷极化，为改善催化剂的构效关系提供了全新的设计理念。文章系统总结了AOB的电子与几何不对称特征，提出为了充分发挥其催化潜力，需要建立统一的设计原则体系来指导高效催化剂的开发。","scd":null,"kp":["催化结构设计[非对称氧桥(AOBs)]: 由非对称的金属1-氧-金属2(M1-O-M2)构成，具有本征的电子与几何不对称性","技术效果[多相催化]: 不对称配位诱导独特且可控的界面特性，增强催化性能"]},{"i":35623,"as":"本文系统综述了镁基热电材料的最新研究进展。因具备元素储量丰富、材料成本低、环境友好及优异的中低温热电性能，镁基热电材料成为大规模应用的重点研究方向。文章详细考察了三大类代表性材料：Mg3X2（X=Sb, Bi）、MgAgSb和Mg2X（X=Si, Ge, Sn）。重点强调了这些材料的晶体结构、电子能带特征以及声子传输机制，为开发高性能、低成本热电材料提供了理论和技术参考。","scd":null,"kp":["核心优势[镁基热电材料]: 元素储量丰富、材料成本低、环境友好性好且具有竞争性","适用温区[镁基热电材料]: 中低温范围"]},{"i":35624,"as":"研究人员提出一种无需螯合剂的放射性金属标记工程亲和蛋白新方法。通过在亲和蛋白的三个螺旋中各引入一个半胱氨酸构建三半胱氨酸基序，将金属直接掩埋结合在蛋白核心内。该方法能稳定结合Bi(III)、Pb(II)、In(III)和Ga(III)等成像与放疗常用金属，实现快速定量的金属摄取，为癌症诊疗提供新途径。","scd":null,"kp":["放射金属标记策略[工程化亲和体]: 无螯合剂策略，将放射性金属直接隐藏于工程化亲和体内部","技术优势[成像与癌症治疗]: 消除了对传统双功能连接体和大分子螯合剂的依赖"]},{"i":35625,"as":"本文提出了一种利用空间位阻刷调控DNA折纸表面图案化的可调谐策略。通过在DNA折纸表面生长均匀的单链多核苷酸刷，引入长程熵排斥作用，有效调节了DNA折纸的有效几何形状。这一方法克服了传统方法中折纸间距难以控制的局限，实现了自组装过程中折纸之间横向间距的精确调控，成功构建了宏观尺度的二维晶格图案，为定制二维材料的局部排列和长程有序性提供了可行路线。","scd":null,"kp":["图案化调控策略[DNA折纸表面组装]: 利用空间位阻刷进行可调且可复制的规则化调控","技术突破[二维材料表面组装]: 打破传统紧密堆积阵列限制，实现对折纸纳米结构间间距的精确控制"]},{"i":35626,"as":"本文针对高压无钴全固态锂电池（ASSLBs）的界面失效机制，提出一种协同调控策略以解耦空间电荷层动力学瓶颈与界面晶格氧的电化学不稳定性。在5V级LiNi0.5Mn1.5O4（LNMO）体系中，研究揭示了LNMO与电解质界面处巨大的锂化学势不匹配会导致界面失效。通过协同调控界面电位和阴离子共价性，有效抑制了锂缺乏引发的负面效应，显著提升了高能量密度全固态电池的实用性。","scd":null,"kp":["界面失效机制[高压无钴全固态锂电池]: 涉及空间电荷层的动力学瓶颈与界面晶格氧的电化学不稳定性","协同调控策略[解耦界面失效]: 协同调控界面电势与阴离子共价性以克服界面动力学与晶格氧失稳问题"]},{"i":35627,"as":"本文深入研究了钒液流电池（VFB）负极电解液中二价钒V(II)在低温下的沉淀机制。通过单晶X射线衍射确定低温沉淀物的晶体结构为VSO4·6H2O。结合原位变温拉曼光谱和密度泛函理论（DFT）计算，阐明了该沉淀的微观结构与形成机制。该发现解决了钒液流电池在低温环境下运行的阻碍，为实现宽温域钒液流电池的大规模储能应用提供了关键理论依据。","scd":null,"kp":["[二价钒V(II)沉淀物]: 低温下显微结构及形成机制尚不明确","[沉淀物晶体结构]: 通过单晶X射线衍射(SCXRD)进行揭示"]},{"i":35628,"as":"本文报道了首例包含较重第14族元素锡和铅的零价镍络合物——[R2E2·Ni]。这些 heavier alkyne-Ni0络合物展现出典型的σ-络合物特性。研究利用特定配体成功合成并表征了该类新型过渡金属有机配合物。这一突破填补了重元素与过渡金属形成类似炔烃络合物的研究空白，对丰富络合物化学体系和探索新的催化合成反应具有重要的基础理论意义。","scd":null,"kp":["[重第14族元素炔烃-镍(0)络合物]: 首次成功合成了锡和铅的同类物种并展现σ-络合物特性"]},{"i":35629,"as":"本文报道了一种利用适配体构建结构明确的蛋白-DNA界面，以组装蛋白-DNA框架（PDF）纳米结构的稳健方法。通过将DNA和蛋白质整合，PDF结合了两者优势并克服了单一组分的局限。利用特定且高亲和力的蛋白质-适配体结合特性，成功解决了PDF组装中蛋白-DNA界面工程结构难以精确控制的难题，实现了在结构、功能、组装多样性和刺激响应性方面高度可控的纳米结构自组装。","scd":null,"kp":["[蛋白质-DNA框架]: 整合两者以克服单一组分局限性并实现结构、功能及响应性的高度多样性"]},{"i":35630,"as":"本文提出了一种用于液晶弹性体（LCEs）的硫醇-异氰酸酯光打印策略。传统完全依赖丙烯酸酯聚合的LCEs光打印方法因光反应基团的限制，断裂韧性差（低于10 MJ m−3），且永久光固化位点阻碍了材料的重复打印和回收。该新策略在保持液晶特性的同时，显著提高了材料的韧性，并赋予LCEs可重复打印性，为制造具有复杂几何形状、可逆大变形的软致动器提供了全新化学设计方案。","scd":null,"kp":["韧性[传统液晶弹性体光打印]: < 10 MJ m−3","[液晶弹性体光打印]: 传统方法因完全依赖丙烯酸酯基聚合而存在韧性差的问题"]},{"i":35631,"as":"本文报道了一种刚性铝基金属有机框架材料HIAM-344，实现了全氟丙烯（C3F6）的高效吸附及其与全氟丙烷（C3F8）的分子筛分分离。该MOF具有由硝酸根调控的窄孔窗和较大空腔结构，结合形状识别机制，能够精准捕捉微量C3F6。这一方法克服了C3F6和C3F8物理化学性质极其相似导致的分离难题，实现了全氟丙烷的高效纯化。","scd":null,"kp":["吸附与分离材料[全氟丙烯(C3F6)的去除及C3F6/C3F8分离]: 具有硝酸根调控的窄孔窗口及形状识别特性的刚性铝基MOF (HIAM-344)"]},{"i":35632,"as":"本文合成了一种5-氨基四唑功能化金纳米复合物（ATZ-Au），通过在关键节点分流电子来消灭细菌，且不产生诱导耐药性的活性氧（ROS）。传统杀菌剂破坏电子传递链会导致电子积累并产生ROS，亚致死浓度的ROS会引发DNA损伤并增加抗生素耐药性风险。ATZ-Au能够直接拦截电子，破坏细菌的能量代谢网络，实现无ROS生成的抗菌效果，为控制感染和规避细菌耐药性提供了全新途径。","scd":null,"kp":["[氨基四唑-金纳米复合物]: 通过分流电子以消除细菌，从而避免由亚致死浓度活性氧(ROS)诱导的DNA损伤和耐药性风险"]},{"i":35633,"as":"本文报道了一种光诱导钯催化策略，利用商业化的烷基溴化物，通过氧化还原中性去芳构化途径实现了吡啶的区域选择性间位烷基化。该方法克服了吡啶固有电子偏置的限制，解决了传统Minisci型烷基化反应优先功能化缺电子位置的问题。在可见光激发下，该体系成功实现了无偏向吡啶的间位C-H键烷基化修饰，为有机合成提供了新的区域选择性官能团化手段。","scd":null,"kp":["[吡啶间位-C-H烷基化反应]: 克服固有的电子偏置，利用烷基溴化物实现光诱导钯催化的高区域选择性间位烷基化"]},{"i":35634,"as":"","scd":null,"kp":[]},{"i":35635,"as":"本文报道了一种通过铑催化β-硼化烯胺与醛的不对称加成反应，实现了具有优异立体控制的（Z）-羟基烯酰胺的合成。传统方法主要生成热力学稳定的（E）-异构体，而富含对映异构体的（Z）-构型对应物的合成极具挑战。研究通过后期配体修饰策略，从混合烯烃原料出发立体汇聚地制备了所需底物，成功合成了同时含有羟基手性中心和明确烯烃几何构型的烯丙醇类化合物。","scd":null,"kp":["[β-硼基烯酰胺对醛的不对称加成反应]: 借助后期配体修饰，实现对映体富集的(Z)-构型烯丙醇的高立体选择性合成"]},{"i":35636,"as":"本文设计了一种能够特异性响应肿瘤内异常高表达的碱性磷酸酶（ALP）的蛋白质复合淬灭探针，用于癌症免疫治疗。与单磷酸类似物相比，双磷酸探针展现出更快的ALP响应速度和更强的荧光输出，信噪比提升了四倍。该探针在肿瘤细胞内被ALP原位激活，引发分子聚集，从而有效诱导细胞焦亡和免疫激活。这种原位合成治疗药物并激活免疫的策略，为精准肿瘤诊疗提供了新方法。","scd":null,"kp":[]},{"i":35637,"as":"研究报道了一种嵌入四对五边形-八边形单元的非苯环马鞍形纳米石墨烯（HN1）。该合成通过3-溴苊烯酮的四聚化，随后与二乙炔衍生物进行三重钯催化环化两步关键反应完成。将非六边形环引入纳米石墨烯能够改变其几何与电子结构，克服了高应变和设计策略的限制。单晶X射线分析证实了其结构的成功构建。","scd":null,"kp":["[非苯环类纳米石墨烯]: 成功实现连续五元环-八元环对的精准整合，合成了 unprecedented (前所未有的) 马鞍型结构"]},{"i":35638,"as":"为解决低温无负极钠金属电池中钠剥离/沉积的可逆性问题，研究设计了一种不对称链状醚溶剂。该溶剂通过分子侧链调节，平衡了弱的Na+偶极和强的阴离子偶极相互作用，形成富含阴离子的Na+配位环境。这显著降低了去溶剂化能垒，并促使形成坚固的阴离子衍生的固态电解质界面，实现了200 Wh/kg的能量密度及优异的低温性能。","scd":null,"kp":["能量密度[低温无负极钠金属软包电池]: 200 Wh/Kg","电解液溶剂[低温无负极钠金属电池]: 具有平衡相互作用的不对称链状醚溶剂","[无负极钠金属电池]: 实现高可逆的Na沉积/剥离、超高库仑效率和长期耐久性"]},{"i":35639,"as":"Prasenjit Mondal在个人介绍中表示，如果不做科学家，他会选择成为一名学校教师。此外，他分享过的最好建议是“永不放弃”。","scd":null,"kp":[]},{"i":35640,"as":"研究报道了一类由离散共价有机纳米管构建的人工跨膜通道，可介导抗坏血酸（AA）的选择性跨膜运输。X射线结构分析和囊泡荧光实验证实，这些分子形成具有近纳米级孔径的刚性管状结构，能稳定插入脂质双分子层并高效运输AA。该分子介导的AA运输能触发生物正交反应，实现细胞内信号转导。","scd":null,"kp":["人工跨膜通道[抗坏血酸传输]: 由离散共价有机纳米管构建，介导抗坏血酸选择性跨膜传输"]},{"i":35641,"as":"为提高癌症免疫疗法的响应率并降低脱靶毒性，研究开发了一种化学掩蔽的抗PD-L1纳米抗体-唾液酸酶偶联物（CAPS）。通过基因编码非经典氨基酸结合定点PEG化安装化学掩蔽，该掩蔽在肿瘤微环境中被MMP2选择性去除，从而恢复蛋白质功能。该设计实现了对纳米抗体亲和力、去唾液酸化活性和肿瘤组织渗透的同步精确控制。","scd":null,"kp":[]},{"i":35642,"as":"该综述探讨了电催化加氢（ECH）反应中杂原子中间体（如水衍生的活性氢物种与各种受氢体）间的复杂相互作用对反应路径和选择性的影响。文章引入了耦合、竞争和促进三种代表性模型，以捕捉反应关键步骤中中间体之间的主要相互作用模式。该框架为解释复杂的ECH系统提供了机理上的清晰度，有助于性能调控。","scd":null,"kp":["电催化加氢效率与选择性限制因素[多相中间体复杂相互作用]: 水源衍生氢物种与多种氢受体间的复杂相互作用"]},{"i":35643,"as":"为解决催化剂在强酸中易浸出导致不稳定的问题，研究提出了一种在强酸中动态吸引浸出金属物种以稳定催化剂的策略。在二氧化铅（PbO2）催化葡萄糖电氧化为甲酸的过程中，将电解液替换为硫酸可减少高达30倍的Pb2+浸出。实验证明SO42-离子能动态吸引因葡萄糖还原PbO2产生的Pb2+，从而在1 A cm-2下实现了275小时的稳定运行。","scd":null,"kp":["催化剂[强酸下葡萄糖电氧化]: PbO2","催化剂稳定化策略[强酸电解液环境]: 利用H2SO4替代HClO4动态吸引浸出的金属物种","目标产物[葡萄糖电氧化]: 甲酸"]},{"i":35644,"as":"现有技术可用于探测在生产武器级钚过程中伴随产生的反中微子。这种探测设备的研发有望用于监测和识别秘密生产核弹材料的聚变反应堆。","scd":null,"kp":["探测物质[武器级钚生产监测]: 反中微子","探测技术成熟度[武器级钚生产监测]: 现有技术可实现探测"]},{"i":35645,"as":"","scd":null,"kp":[]},{"i":35646,"as":"湍流是经典物理学中尚未解决的问题，且是限制气候、航空航天和能源系统精确流动预测的瓶颈。研究提出了一种统一的数据驱动湍流建模框架，通过多目标集成学习策略，在稀疏和间接观察数据中稳健学习，以平衡不同流动状态下的竞争目标。该框架将物理一致性嵌入闭包模型中，基于流动特征相似性自动选择训练案例，生成了单一的统一模型。","scd":null,"kp":["湍流模型框架[多机制控制流动预测]: 基于多目标学习的统一数据驱动框架，能够从稀疏和间接观测中稳健学习"]},{"i":35647,"as":"研究人员分析了美国专利记录和文献计量数据库中的双用途（军民两用）研究数据，评估了具有军事应用潜力的科学研究在学术界的影响力。分析表明，双用途研究的被引频次高于纯民用研究。","scd":null,"kp":[]},{"i":35648,"as":"数据分析显示，在2016年至2020年期间，中国作者发表的论文中有近三分之一拥有多位通讯作者。相关研究和分析指出，近期的科研评价政策改革预计将缓解并改变这一多位通讯作者的历史高频趋势。","scd":null,"kp":[]},{"i":35649,"as":"板片撕裂是俯冲大洋板片与大陆岩石圈的侧向分离，但其地表信号在地质记录中常存在矛盾。研究通过大地构造模型解决了这一悖论，表明被动大陆边缘强度的横向变化控制了板片撕裂的传播速度及其地表信号。这解释了前陆盆地沉积中心的侧向迁移和加厚等地质观察现象。","scd":null,"kp":["板块撕裂传播速度[现有地球动力学模型预测]: 异常高（导致其瞬时特征极难在地表或地层记录中保留）"]},{"i":35650,"as":"","scd":null,"kp":[]},{"i":35651,"as":"","scd":null,"kp":[]},{"i":35652,"as":"为解决水系电池硫基电极中硫簇不可逆溶解和界面退化问题，研究在二硫化铁（FeS2）中耦合外源硫簇构建了可逆动态共价系绳。在首次放电时，Cu2+自发还原并在界面重构形成Cu2S/FeS2异质结构，构筑了分子级桥梁并建立了稳定的活性位点，实现了二硫化铁/硫基水系电池正极的快速离子迁移和优异性能。","scd":null,"kp":["异质界面重构[水系电池二硫化铁/硫基正极]: 转化驱动的可逆动态重构实现快速离子迁移并抑制不可逆硫簇溶解"]},{"i":35653,"as":"","scd":null,"kp":[]},{"i":35654,"as":"研究通过高温高压实验揭示了克拉通边缘稀土矿碳酸岩岩浆的成因。在俯冲过程中，钙质碳酸盐逐渐富集轻稀土元素（LREE）。当这些碳酸盐在高压下熔化并穿过克拉通岩石圈地幔上升时，极贫LREE的菱镁矿沉淀促使残余熔体进一步富集，使其LREE浓度最高可达沉积碳酸盐的156倍，从而形成天然的成矿碳酸岩熔体。","scd":null,"kp":["LREE富集与载体[俯冲带富碳酸盐沉积物循环过程]: 钙质碳酸盐逐渐富集轻稀土元素并成为主要载体","成矿碳酸岩岩浆成因[高压熔融条件]: 高压下富集轻稀土元素的钙质碳酸盐熔融形成"]},{"i":35655,"as":"","scd":null,"kp":[]},{"i":35656,"as":"研究综合了残留物监测、群落分析和大规模培养分离等技术，调查了农业土壤和河流沉积物中真菌的抗药性。结果表明，杀菌剂在环境中广泛存在，尤其是多菌灵和戊唑醇具有很高的生态风险。在超过3900个耐药分离株中，发现了358个对多种农用杀菌剂具有交叉耐药性的多重耐药（MDR）真菌菌株。转录组分析揭示了环境真菌具有严重的多重耐药性特征。","scd":null,"kp":["耐药真菌库塑造因素[农业土壤与相邻河流沉积物环境]: 农业杀菌剂的广泛检出与残留"]},{"i":35657,"as":"为解决低铂质子交换膜燃料电池中离聚物吸附引起的铂中毒和高局部氧传质阻力问题，研究设计了一种介孔碳载体。该设计以小介孔为主结构，并将孔深合理控制在中等水平。这种碳介孔深度工程在介孔内部为铂纳米颗粒创造了理想的局部反应环境，既保护了铂免受离聚物毒害，又降低了传质阻力，从而大幅提升了电池性能。","scd":null,"kp":["低铂燃料电池核心挑战[质子交换膜燃料电池]: 离聚物吸附引起的Pt中毒与高局部氧传质阻力","性能提升策略[低铂燃料电池]: 碳介孔深度工程"]},{"i":35658,"as":"全无机手性发光体在热稳定性和器件兼容性上优于有机或杂化材料，但受限于制备困难和低发光不对称因子。研究提出以手性二氧化钛纳米螺旋为模板，在其表面共形涂敷非手性的溴化铅铯钙钛矿发光体，构建出全无机手性核壳纳米发光体。该方法实现了从二氧化钛纳米螺旋到钙钛矿的手性传递，为开发先进光子显示器、量子通信和生物成像提供了新技术途径。","scd":null,"kp":["发光不对称因子[全无机手性发光体]: 受限于较低值","发光体[热稳定/环境鲁棒/器件兼容性]: 全无机钙钛矿涂层TiO2纳米螺旋"]},{"i":35659,"as":"二维光调制器常因缺陷引起损耗导致效率低下。研究发现在液相处理的二硒化钨（WSe2）纳米片中，边缘金属1T相和内部半导体2H相产生的边缘缺陷可通过载流子陷阱填充被动态饱和。通过调节纳米片横向尺寸并施加光电或电学激发，缺陷态逐渐饱和，降低了非辐射复合。该过程增强了本征激子响应，使光电和全光光致发光峰值调制效率分别提升至0.025 eV·V−1和0.1 eV·mW−1。","scd":null,"kp":["WSe2纳米片边缘缺陷[动态饱和]: 通过载流子陷阱填充实现，降低非辐射复合"]},{"i":35660,"as":"针对发声器官受损者的交流障碍，研究开发了一种传感器内通信电子围巾界面，能够隐蔽捕获多肌肉活动并超强稳健地解码无声语音。该技术融合了由欺瞒表面等离子激元驱动的传感器内电磁生理通信与超材料拓扑刺绣。此生理传感模式通过捕捉多肌肉活动，克服了传统麦克风和压电薄膜易受外部干扰以及传感与通信分离的局限，实现了可靠的无声语音解码。","scd":null,"kp":["传感模态[静默语音解码]: 捕捉并解码多肌肉微小生理活动"]},{"i":35661,"as":"光固化3D打印高性能树脂的开发受限于粘度、固化动力学和机械性能之间的权衡，且传统打印筛选无法评估高粘度或慢固化配方。本研究引入了包含小体积配方筛选、机器学习优化和功能验证的数据高效工作流。通过建立涵盖可打印和不可打印区域的配方库，利用小体积模具固化将材料表征与打印限制解耦以扩大训练域。基于粘度、固化时间和伸长率训练的回归模型实现了具有约束感知的弹性体配方设计。","scd":null,"kp":["配方设计[光固化3D打印弹性体]: 突破粘度-拉伸性制约的机器学习引导数据高效工作流"]},{"i":35662,"as":"海水电解水制取绿氢面临电极腐蚀和高电流密度下氯析出竞争的挑战。研究提出原位生长策略，将铁泡沫转化为硼掺杂钴铁氧羟基氧化物（B-FeCoOOH）纳米片。硼的掺入和无序晶格产生了大量氧空位，降低了水氧化的动力学势垒。该催化剂在1.0 A cm−2电流密度下仅需325 mV过电位，且在碱性海水中运行600小时后性能衰减不到2%。机理表明氧空位激活了晶格氧氧化机制，表现出极高的耐久性。","scd":null,"kp":["电极催化剂[工业级海水分解]: 硼掺杂钴铁羟基氧化物(B-FeCoOOH)纳米片","制备策略[铁泡沫原位生长]: 硼掺杂与无序晶格诱导晶格氧活化"]},{"i":35663,"as":"电荷密度波凝聚体是具有强电子-晶格相互作用的关联电子相。研究在准一维正交晶系三硫化钽（o-TaS3）中观察到了凝聚体密度的巨大栅极响应效应。栅极诱导的凝聚体电荷密度变化超过了基于几何栅极电容的预测值一至两个数量级。这种增强效应源于电场与电子-晶格凝聚体之间的耦合，通过集体电子行为放大了栅极响应。研究通过确定量子电容对该效应进行了定量分析。","scd":null,"kp":["栅极响应[准一维正交硫化钽(o-TaS3)电荷密度波凝聚体]: 巨大的凝聚体电荷密度变化，超越几何电容预测"]},{"i":35664,"as":"","scd":null,"kp":[]},{"i":35665,"as":"","scd":null,"kp":[]},{"i":35666,"as":"通过将一维量子玻色-哈伯德模型映射到二维宏观声子晶体中，研究人员观察到了一种完全由均匀非局域双体相互作用诱导的新型连续域中多体束缚态。该研究证实了在声学系统中可以实现这种独特的多体束缚态。","scd":null,"kp":["连续域束缚态[非局域双体相互作用]: 均匀非局域两体相互作用诱导的新型多体束缚态"]},{"i":35667,"as":"研究人员提出了一种仅需单次猝灭即可产生具有最小控制的幺正k-设计的方案。系统首先在随机哈密顿量H1下演化，在达到或超过Thouless时间的切换时刻ts时，系统被猝灭到从同一系综中独立抽取的哈密顿量H2并继续演化，从而生成幺正k-设计。","scd":null,"kp":["幺正k-设计[单淬火协议]: 在最小控制下通过随机哈密顿量演化切换生成"]},{"i":35668,"as":"研究聚焦于三维超导交替磁体中由零能表面交叉平带表征的高维拓扑相。这些零能表面交叉平带的出现，揭示了交替磁性对称性与超导对称性之间的相互作用机制。","scd":null,"kp":["拓扑物相[三维超导交变磁体]: 零能表面交叉平带"]},{"i":35669,"as":"以往自旋磁化的产生仅依赖于电场下的线性或非线性埃德尔斯坦效应。研究提出了一种全新的物理机制——非线性磁电埃德尔斯坦效应（NMEE）。该机制表明，电场和磁场可以协同作用产生自旋磁化，打破了传统单一电场调控的限制。","scd":null,"kp":["自旋磁化[非线性磁电Edelstein效应(NMEE)]: 电场与磁场协同产生"]},{"i":35670,"as":"","scd":null,"kp":[]},{"i":35671,"as":"","scd":null,"kp":[]},{"i":35672,"as":"","scd":null,"kp":[]},{"i":35673,"as":"","scd":null,"kp":[]},{"i":35674,"as":"","scd":null,"kp":[]},{"i":35675,"as":"","scd":null,"kp":[]},{"i":35676,"as":"","scd":null,"kp":[]},{"i":35677,"as":"研究报道了在大型螺旋装置（LHD）中中心电子温度约4 keV等离子体条件下，高电荷态钨杂质离子的X射线晶体光谱学（XCS）测量。结合Flexible Atomic Code计算与碰撞辐射模型，成功识别了3.7–4.0 Å波段内W43+至W47+的电荷态发射谱线。其中在3.7691 Å处观察到的W47+谱线，刷新了LHD中观察到的最高电荷态记录，为聚变等离子体诊断提供了重要数据。","scd":null,"kp":["中心电子温度[LHD等离子体条件]: 约4 keV","发射光谱波段[W43+-W47+高电荷态钨杂质离子]: 3.7-4.0 Å"]},{"i":35678,"as":"TCV托卡马克研究计划针对ITER和未来聚变电站的关键问题。近两年的实验活动在多个领域取得重大进展：包括ITER基准场景、低碰撞性条件下的台基特性、高非感应机制、准连续偏滤器排气、X点辐射等离子体和负三角形配置。在缓解失控电子束、阐明快离子损失机制和改善排气行为方面也取得了实质性成就。","scd":null,"kp":["高约束运行模式[TCV托卡马克]: 替代高约束模式场景","等离子体模式[ITER与未来聚变电厂]: 高参数非感应驱动模式"]},{"i":35679,"as":"聚变反应堆环境中的诊断设备在生存性、可维护性和端口空间上受到严格限制。这项研究旨在从有限的诊断子集中提取用于控制聚变先导工厂（FPP）的等离子体状态信息。研究采用基于机器学习的工具，利用已知的FPP相关诊断数据来监测和分析不同的重大等离子体状态参数，解决反应堆等离子体控制的工程挑战。","scd":null,"kp":["诊断系统可用性[聚变先导电厂(FPP)反应堆环境]: 数量受限","[FPP等离子体状态控制]: 需从有限诊断子集中提取状态信息"]},{"i":35680,"as":"","scd":null,"kp":[]},{"i":35681,"as":"","scd":null,"kp":[]},{"i":35682,"as":"","scd":null,"kp":[]},{"i":35683,"as":"通过对20名受试者长达一周的无约束自发行为进行颅内多电极和视频同步记录，研究发现大脑神经动力学与昼夜节律、心率及多种行为密切相关。行为转换伴随着快速、混沌的神经探索爆发，随后稳定进入新状态。尽管存在混沌现象，大规模脑动力学锚定在与神经生理和意识状态相关的稳定中心流形上，呈现中心吸引子特征。","scd":null,"kp":["脑电信号记录周期[自然环境中的人脑]: 一周","神经认知动态检测[大脑实时状态转换]: 动态深度学习算法"]},{"i":35684,"as":"研究开发了SONAR平台，用于在人类细胞中检测目标DNA和RNA序列并触发可控的基因表达。该平台利用可环化的单链DNA（ssDNA）传感器，与目标核酸互补结合后，通过细胞连接酶进行靶向依赖性连接，驱动下游遗传基因表达。在检测RNA时，利用反义寡核苷酸引导靶向逆转录生成互补DNA，从而促进ssDNA的环化。","scd":null,"kp":["靶标检测[人活体细胞]: DNA和RNA序列","[SONAR单链DNA传感器]: 可环化单链DNA与互补DNA或逆转录RNA杂交后触发可控基因表达"]},{"i":35685,"as":"结合蛋白质组学和脂质代谢组学分析，研究发现脂滴在宿主抗病毒反应中发挥双重作用。RNA病毒感染会导致脂滴的蛋白质组和脂质组重塑，将RIG-I、MDA5等抗病毒蛋白招募至病毒诱导的脂滴上。同时，脂质组转向富含长链多不饱和脂肪酸和生物活性磷脂，以增强膜动力学和蛋白招募，揭示了脂质与蛋白质间的广泛相关性。","scd":null,"kp":["脂滴功能[宿主细胞抗病毒反应]: 动态重塑蛋白质组和脂质组并招募抗病毒蛋白"]},{"i":35686,"as":"","scd":null,"kp":[]},{"i":35687,"as":"对Heusler型Co-Ni-Ga形状记忆合金单晶超弹性变形行为的研究发现，在卸载应力诱导马氏体期间会伴随声发射。中子衍射提供了清晰的证据，表明在卸载马氏体区域内，马氏体畴变体的体积分数发生改变，即一种马氏体畴变体的生长以另一种变体的消耗为代价，从而实现了马氏体的重新取向。","scd":null,"kp":["声发射机制[应力诱发生成马氏体卸载阶段]: 伴随声发射现象","变形行为[Heusler型Co-Ni-Ga形状记忆合金单晶]: 超弹性变形"]},{"i":35688,"as":"通过测量单分子蛋白电导，研究监测了细胞色素P450 1A1在代谢过程中的催化动力学。结果显示，催化引起的α螺旋结构重排和血红素中心的氧化还原转变共同调节了电荷传输效率。BaP浓度与电导呈负相关，构建的动力学模型得出表观米氏常数为24.2-43.2 μM。实时电导测量成功分辨出四种与蛋白质构象和氧化还原状态相关的独立电导状态。","scd":null,"kp":["结构动力学监测[单分子酶催化]: 微秒至毫秒级时间尺度","[细胞色素P450 1A1催化机制]: 测量单分子蛋白电导以揭示α-螺旋结构重排与氧化还原转变"]},{"i":35689,"as":"研究提出了SECS框架，将对比学习与进化算法相结合，实现直接从原始多模态光谱数据中自动化解析分子结构。该框架通过跨核磁共振、红外和质谱对齐嵌入向量，克服了现有方法仅限于单一光谱模态且需大量手动预处理的局限。SECS提供了解决结构解析中简并解问题的新途径，并具备实用的置信度估计能力。","scd":null,"kp":["分子结构解析[原始光谱数据]: 结合对比学习与进化算法的端到端多模态解析"]},{"i":35690,"as":"研究开发了一种不对称合金化方法，通过向高对称性碳中心六金簇中添加三氟乙酸银，成功合成了碳中心手性金甲烷合金簇CAuI4AgI6。该金属簇呈现双帽四方反棱柱结构，理论计算揭示了C-AuI键和C-AgI相互作用的特性。使用同手性羧酸盐配体，实现了不对称诱导，获得了具有红光到近红外光致发光特性的手性金属簇。","scd":null,"kp":["光致发光特性[碳中心手性Au4Ag6多面体]: 红光至近红外光致发光","不对称合金化方法[高对称C中心六金(I)原子团簇]: 加入三氟乙酸银"]},{"i":35691,"as":"为解决玻尔兹曼生成器在大规模系统平衡采样中的扩展性限制，研究提出了一种结合增强耦合流和图神经网络的新型架构。该模型利用局部环境进行能量训练和快速推理，相比以往设计，训练速度更快且资源消耗更少，实现了卓越的采样效率。该架构能够直接迁移至大得多的系统尺寸中，高效生成大规模材料的平衡系综结构。","scd":null,"kp":["采样技术[大规模材料平衡采样]: 结合增强技术的可扩展Boltzmann生成器架构"]},{"i":35692,"as":"利用1纳米厚粘土通道中受限水的独特电化学特性，研究人员构建了一种全水基超级电容器。该器件通过组装层状粘土和导电石墨烯制成，受限水作为唯一电解质。器件在1.6 ± 0.1 V的电压下稳定运行，比电容达到40 F/g，库仑效率为97 ± 2%，具备优异的长期循环稳定性能，实现了全天然丰富材料构筑的电化学储能系统。","scd":null,"kp":["通道尺寸[超级电容器黏土通道]: 1纳米","电解质[1纳米受限水通道]: 纯水作为唯一电解质","器件构成[全水超级电容器]: 黏土与石墨烯"]},{"i":35693,"as":"研究开发了一种微液滴封装阵列（EDA）技术，用于高通量微摩尔规模的化学反应筛选。该技术将微升级反应液滴限制在由铝制底盘增强的聚丙烯化学惰性袋中，使得化学反应能够在高温（105°C）和高压（7 atm）条件下大规模并行运行（每板48个反应）。该技术克服了传统微孔板和微流控在严苛条件和组合筛选上的局限。","scd":null,"kp":["[高通量反应筛选]: 封装液滴阵列(EDA)技术克服苛刻反应条件与高度平行组合筛选限制"]},{"i":35694,"as":"在透射电子显微镜（TEM）技术中，研究引入了交叉激光相位板（XLPP），通过两条交叉的激光驻波在衍射面相互作用以实现电子束相移。理论模型和实验表明，与单束激光相位板相比，XLPP显著提高了低空间频率下的信息传递能力，并有效抑制了卡皮查-狄拉克衍射产生的重影图像，进一步优化了相位衬度成像方案。","scd":null,"kp":["相位板技术[透射电子显微镜]: 交叉激光相位板(XLPP)由两束相交激光驻波构成"]},{"i":35695,"as":"为解决硫化物全固态锂电池界面不稳定和寿命短的问题，研究提出一种由Li2S、LixIn和LiInS2组成的Li-In-S复合箔。该复合箔利用Li2S与LixIn之间的功函数差异在异质界面构建内建电场，捕获并限制电子向Li6PS5Cl转移，抑制了界面副反应。同时，内建电场促进Li+吸附与扩散，抑制锂枝晶生长，实现了长寿命全固态电池。","scd":null,"kp":["复合箔成分[全固态电池界面稳定]: Li2S、LixIn和LiInS2","界面稳定机制[Li/Li6PS5Cl界面]: Li2S与LixIn的功函数差异产生内置电场"]},{"i":35696,"as":"设计了一种钾和铯共修饰的聚合氮化碳（CN-KCs）光催化剂，构建了作为受阻路易斯酸碱对的双端吸附位点。该设计大幅降低了O-O键断裂能，通过*O2解离途径（*O2→2*O）实现了高效的H2O2光催化合成。在有生物质衍生物存在下，该系统H2O2产率高达1806.6 μmol/h，420 nm处量子效率达72.3%，太阳能到H2O2的转化效率为6.1%。","scd":null,"kp":["催化剂[光催化合成H2O2]: K和Cs共修饰的聚碳氮化物(CN-KCs)","反应路径[光催化合成H2O2]: O-O键断裂显著降低能量的*O2解离途径"]},{"i":35697,"as":"研究提出利用非润湿微结构在流动条件下自发诱导近壁面霜形成（界面霜）的策略，以提升热融冰效率。较厚的界面霜在融化过程中将常规的固-液-冰相互作用转变为直接的固-冰接触，从而显著增强融冰性能。此外，满足特定数学标准的预冻结液滴被微结构破碎，直接调控固冰界面的破坏行为，打破了冰型仅由流动条件决定的传统观念。","scd":null,"kp":["除冰策略[流动条件下热融冰]: 利用非润湿微结构在流动条件下诱导近壁面霜冰自发形成以提升热除冰效率"]},{"i":35698,"as":"研究发现了选择性HDAC6抑制剂BAS-2，其核心结构为异硫脲，且不含明显的锌结合基团。机制研究表明，BAS-2能强效抑制人类HDAC6，但不抑制斑马鱼HDAC6。通过计算建模与突变分析证实，人类HDAC6中的Asp567氨基酸残基对BAS-2的识别至关重要，而斑马鱼对应的残基为Asn530。","scd":null,"kp":["抑制剂核心[HDAC6选择性抑制]: 异硫脲鎓核心且无明显的锌结合基团"]},{"i":35699,"as":"浓度电池是一种利用相同氧化还原电对、依靠电解质成分差异产生电压的电池。由于十倍的浓度差通常只能产生微小的电压，其实际应用受到了限制。该研究通过调控电解质溶剂化结构，成功构建了高压浓度电池，为高效储能提供了新的解决方案。","scd":null,"kp":[]},{"i":35700,"as":"在n型碲烯薄膜中观察到了巨大的负磁阻效应，其数值达到了零场电阻的-90%。该效应在低温下最高可持续至35特斯拉，且当化学势远离导带外尔节点时受到抑制，证实了其量子几何起源。该现象由扩散的量子几何增强以及磁电自旋相互作用机制共同驱动。","scd":null,"kp":["磁阻效应[n型碲烯薄膜]: 巨负磁阻效应达到零场电阻(R0)的-90%","磁场上限[巨负磁阻效应]: 高达35 T"]},{"i":35701,"as":"通过将发展基础扩展至异步网络，证明了图灵完备的神经网络不需要全局时钟。该异步模型每步仅随机更新单个神经元，消除了全局更新需求，显著降低了系统能耗。通过引入特定的设计约束，研究成功构建了具备图灵完备性的异步神经网络架构。","scd":null,"kp":["[图灵通用神经网络]: 无需全局时钟的异步网络即可实现图灵通用计算"]},{"i":35702,"as":"将量子霍尔绝缘体的手性边缘态与s波超导体耦合的混合结构是研究非阿贝尔准粒子的平台。该结构中会发生交叉安德烈夫反射（CAR）。实验将砷化镉薄膜的量子霍尔边缘模式与超导铌氮条接触，观察到下游电阻和热电响应的磁场振荡，且热电响应特征证实了CAR的存在。","scd":null,"kp":["[量子霍尔/超导体混合结构]: 利用热电检测技术实现了交叉安德烈夫反射(CAR)，将上游手性边缘态电子转化为下游空穴"]},{"i":35703,"as":"精准计时支撑着全球导航卫星系统（GNSS）、高频金融交易等现代关键技术。文章回顾了原子钟的演进及其应用，描述了网络时间协议（NTP）、精密时间协议（PTP）等关键时间传递方法，并探讨了其在量子通信与量子计算等新兴领域的应用趋势。","scd":null,"kp":[]},{"i":35704,"as":"间质型结直肠癌对免疫治疗产生抗性，主要归因于癌症相关成纤维细胞介导的纤维化屏障。研究发现，成纤维细胞中上调的TXNDC5蛋白通过稳定TGFBR1受体增强TGFβ信号传导，从而驱动免疫抑制。特异性敲除成纤维细胞中的Txndc5能减轻肿瘤纤维化，缓解缺氧，并增强细胞毒性T细胞的招募。","scd":null,"kp":[]},{"i":35705,"as":"通过分析美国门多塔湖20年间的471个宏基因组，重构了1512个巨型病毒基因组。Imitervirales目病毒在该病毒组中占主导地位。研究揭示，基因重复（占23%）和水平基因转移（占29%）是病毒基因组创新的关键驱动力。2009年入侵性浮游动物引入后，病毒与宿主的相互作用明显增加。","scd":null,"kp":[]},{"i":35706,"as":"利用机器学习辅助的组合文库方法，开发了能与癌症相关成纤维细胞表面的LRRC15蛋白结合的二硫键约束肽（DCPs），如ML-YSD-07和ML-PD-03。这些多肽对鼠源LRRC15具有亚纳摩尔级的亲和力。经18F放射性标记的ML-YSD-07在PET成像中表现出对富含LRRC15肿瘤的特异性积累。","scd":null,"kp":[]},{"i":35707,"as":"利用超分辨活细胞显微镜，揭示了在线粒体氧化磷酸化（OXPHOS）条件下RNA颗粒与线粒间的接触位点。OXPHOS产生的活性氧（ROS）通过氧化TDP-43的Cys173/Cys175，促进其定位于RNA颗粒。TDP-43结合线粒体上的GADD34形成接触束缚，而GADD34与PP1调节该位点的功能。","scd":null,"kp":[]},{"i":35708,"as":"利用全基因组CRISPR干扰技术，鉴定了结核分枝杆菌不同耐药基因型的附带效应。耐药性在多个重叠的功能通路中产生了共同的脆弱性，绝大多数耐药菌株对tRNA合成酶敲除的敏感度显著增加。此外，特定的利福平耐药突变体（RpoB S450L）表现出对特定靶点敏感度增加的特性。","scd":null,"kp":[]},{"i":35709,"as":"一种与红脚石鸡脑炎暴发相关的禽类佩吉病毒（ParPgV）被鉴定。新一代测序在脑组织中发现该病毒。组织病理学显示存在脑炎病变及神经元变性。实验接种证实该病毒具有跨物种的嗜神经性和全身分布特性，并在多个石鸡群中表现出广泛的垂直传播。","scd":null,"kp":[]},{"i":35710,"as":"提出了一种结合增强采样技术和机器学习变量的计算工作流程，以识别雄激素受体无序N端结构域（AR-NTD）的可成药构象。该研究表征了Tau-5区域的九种亚稳态，揭示配体识别由π-π堆积和结构水介导的氢键驱动，并阐明了调节剂EPI-002的结合机制。","scd":null,"kp":[]},{"i":35711,"as":"为客观量化灵长类动物磨牙解剖亚区，开发了结合计算机视觉与机器学习的Hecate算法。该算法量化了代表主要灵长类分支及化石的500个下颌第二磨牙亚区。结合系统发育比较方法分析发现，臼齿前部区域的进化改变表明在灵长类起源期间，植食性取食行为有所增加。","scd":null,"kp":[]},{"i":35712,"as":"衔接蛋白TNS1在细胞内形成缩合物，以调节粘附组分的可用性。在灶性粘附分解或整合素与细胞外基质结合受限时，内源性TNS1缩合物充当未磷酸化粘附蛋白的可逆库。TNS1的内在无序区控制其缩合物形成，进而调控细胞粘附的动态变化。","scd":null,"kp":[]},{"i":35713,"as":"证明了利用全局非手性材料的局部手性（手性位点），可以放宽手性光子发射的对称性限制。光子纳米结构通过线偏振光增强左旋和右旋手性场。被这种场包围的无手性发光体发出了高度椭圆的光，纳米颗粒和染料的发光不对称因子在1.65到-1.58之间，接近理论极限。","scd":null,"kp":["手性发光[纳米结构]: 利用全局非手性材料的局部手性(手性倾向)来放宽对称性限制并实现左/右手手性的增强与定位"]},{"i":35714,"as":"一种配备环形碳纳米管传感器阵列的导管，能够实时、原位地对癌症生物标志物进行三维化学成像。该纳米传感器涂层设备能够精准映射早期膀胱癌肿瘤的物理位置。","scd":null,"kp":["[碳纳米管传感器阵列导尿管]: 实现实时、原位三维化学成像及早期肿瘤定位"]},{"i":35715,"as":"将锂电池正极材料磷酸铁锂纳入生物电子设备中，实现对神经元的可控和局部锂离子递送。这种利用电池矿物的策略为精准抑制神经活动确立了新的途径。","scd":null,"kp":["[神经抑制生物电子器件]: 结合磷酸铁锂(LiFePO4)实现向神经元的受控和局部化锂离子递送"]},{"i":35716,"as":"设计了一种具有热稳定三维异质结构的高熵合金(FeCoNi)86Al7Ti7。该合金由双峰核壳结构、纳米析出物和纳米氧化物组成，在高达1000°C下保持稳定。在5×10³ s⁻¹的应变率下，该合金实现了2.2 GPa的屈服强度和1100 MJ m⁻³的能量吸收密度，其极高的冲击韧性源于马氏体相变。","scd":null,"kp":["耐高温高熵合金[三维异质结构]: (FeCoNi)86Al7Ti7，具有热稳定的双峰核壳架构、均匀分布的纳米析出物和纳米氧化物颗粒"]},{"i":35717,"as":"","scd":null,"kp":[]},{"i":35718,"as":"","scd":null,"kp":[]},{"i":35719,"as":"","scd":null,"kp":[]},{"i":35720,"as":"","scd":null,"kp":[]},{"i":35721,"as":"道路上的化石燃料汽车减少正在降低中国部分污染物的排放水平。数据显示，电动车辆的普及有效减少了污染，并成功预防了26万例过早死亡事件，但并非所有污染物的浓度都得到了同等降低。","scd":null,"kp":["避免过早死亡[中国电动汽车减排]: 260,000人"]},{"i":35722,"as":"提出一种基于倾斜Su-Schrieffer-Heeger模型的二维拓扑声学超构材料方法，能够在整个布里渊区内平移传统Dirac锥，改变其位置。实验展示了非平凡的边缘态可以向任意方向辐射，且通过该方法实现了在任意入射角下的克莱因隧穿效应。","scd":null,"kp":["[二维拓扑声学超材料]: 基于倾斜Su-Schrieffer-Heeger模型，通过工程跳跃幅度实现狄拉克锥在整个布里渊区的平移"]},{"i":35723,"as":"受鱼类侧线系统启发，研究人员开发出一种基于光通量原理的柔性人工侧线（ALL）传感器单元，用于测量流速矢量。该传感器采用双层倒置杯状摇杆设计，通过水流冲击摇杆压缩柔性硅胶弹簧，将流速变化转化为多方向光敏单元接收到的光通量变化，从而实现局部流速矢量感知，克服了大变形和非线性力学造成的建模挑战。","scd":null,"kp":["[柔性人造侧线传感器]: 采用双层倒置杯状摇杆设计，基于光通量原理测量水流速度矢量"]},{"i":35724,"as":"探讨了聚四氟乙烯（PTFE）的核心矛盾。正是让这种材料成为工业奇迹的分子设计，导致其及其相关化学物质成为一种持久的环境危机。","scd":null,"kp":[]},{"i":35725,"as":"提出一种以霍夫曼消除产生的可分离平台为中心的发散性生物碱重塑策略。通过哌啶的C-N键断裂和第二个烯烃基团的生成，结合Stevens或Meisenheimer重排以及闭环复分解反应，实现了结构的扩环和缩环。利用少量催化剂和试剂，仅用48步便制备了26种骨架重塑结构，加速了药物发现。","scd":null,"kp":["[生物碱重塑策略]: 通过霍夫曼消除产生可分离平台，进行C-N σ键的选择性断裂以实现哌啶解构，结合Stevens和/或Meisenheimer重排"]},{"i":35726,"as":"报告了一种镍(0)催化的降冰片二烯（NBD）与未活化内炔烃的内型立体选择性[2+2]环加成反应。通过配体介导的NBD面部分化和镍控制的关键中间体构型，克服了传统NBD主要在更具电子密度的外型面发生反应的限制，为合成内型-三环壬二烯等重要构象限制性骨架提供了捷径。","scd":null,"kp":["催化剂[降冰片二烯与内炔的[2+2]环加成反应]: 零价镍(Nickel(0))","[双环化合物的面选择性转化]: 实现了通常难以发生的内型面选择性反应"]},{"i":35727,"as":"提出一种基于环芳烃的屏蔽策略，在空间上保护石墨烯纳米带（GNR）骨架并施加内部应变，实现了单分散的GNRs并调控其光电性能。通过合成和研究不同环链长度的环芳烃屏蔽GNRs，发现随着链长增加，短程电荷载流子迁移率从190显著提升至330 cm2 V−1 s−1。","scd":null,"kp":["[超分子屏蔽策略]: 引入基于环芳烷的屏蔽策略以提供空间位阻保护并引入内应变","[单分散石墨烯纳米带]: 成功实现单根分散并调制其光电特性，克服了强聚集瓶颈"]},{"i":35728,"as":"结合氢交换质谱、生物信息学、X射线晶体学和分子动力学，研究对比了细菌转录因子家族及其同源周质结合蛋白的能量景观。发现两类蛋白尽管结合相同的糖类，却演化出独特的“能量蓝图”以满足各自不同的功能需求，揭示了高保守蛋白质折叠产生差异生化功能的机制。","scd":null,"kp":[]},{"i":35729,"as":"通过系统发育分析指出，真兽类H3f4直系同源基因起源于1亿多年前真兽类与有袋类分化前的一个祖先H3.2基因。研究阐明了H3f4基因（编码组蛋白变体H3.4）的进化起源，及其序列变异在小鼠雄性生殖细胞发育和精子发生中的分子生理作用，证实该基因对生殖适应性至关重要。","scd":null,"kp":[]},{"i":35730,"as":"采用流延成型和共烧结技术制造多层堆叠架构的全陶瓷微电池。该策略不仅降低了厚度、增强了结构完整性，还形成了确保电极与电解质紧密接触并促进锂离子快速传输的原位界面层。最终电池在0°C至150°C的宽温度范围内实现了稳定的免压力运行。","scd":null,"kp":["[全陶瓷微电池多层架构]: 采用流延和共烧结工艺构建多层堆叠","[电极/电解质界面]: 原位形成紧密接触的界面层以促进锂离子快速传输","[全陶瓷微电池运行状态]: 实现宽温域内稳定且无压力的操作"]},{"i":35731,"as":"定义了一个与主要脑部疾病发展阶段相匹配的框架，概述了微纳米机器人在跨越血管、血脑屏障和组织传输屏障以实现大脑主动递送中的应用潜力。此外，还提出了区分区室的暴露和安全基准，以推动大脑纳米机器人技术向临床可信平台迈进。","scd":null,"kp":["[微纳机器人跨屏障递送]: 通过将驱动力与血管、血脑屏障和组织传输屏障相匹配实现主动控制","[脑部微纳机器人临床转化]: 提出了阶段匹配框架以及按室划分的暴露与安全性基准"]},{"i":35732,"as":"开发了一种利用固定电位介导剂进行快速、精确预锂化的技术，解决了有机框架正极无锂属性难以集成到全电池中的问题。该预锂化过程保留了框架完整性及快速反应动力学，为制造与商用碳负极相匹配的耐用、高电流全电池开辟了实用途径。","scd":null,"kp":["预锂化方法[有机框架正极用于超高电流锂电池]: 电势 controlled（固定电势介体）实现快速精确预锂化","[有机框架正极预锂化效果]: 保持了骨架结构完整性并维持了快速反应动力学","[全电池组装]: 成功与商用碳负极匹配构建耐用的高电流全电池"]},{"i":35733,"as":"确认AMC-F1（原名TRIM44）是线粒体生物能量学和自噬的核心整合因子。通过小鼠模型证实，AMC-F1缺失会降低线粒体呼吸和自噬通量，过表达则独立于营养胁迫促进线粒体拉长和增加自噬。转录组学显示，AMC-F1通过调控线粒体生物发生程序来协调基础和饥饿状态下的自噬作用。","scd":null,"kp":[]},{"i":35734,"as":"受生物肌肉滑动肌丝机制启发，构建了一种机械自适应的超薄人工固体电解质界面（SEI）。该纳米级增强结构由刚性氧化石墨烯（GO）骨架和Triton诱导的牺牲性氢键交联组成，通过动态氢键介导的应力耗散实现可控的层间滑动，在抑制锌枝晶生长的同时适应体积波动，实现高可逆的锌金属负极。","scd":null,"kp":["[水系锌金属电池枝晶与界面问题]: 受生物肌肉滑动丝机制启发构建了机械自适应的超薄界面层(SEI)","人工SEI层[水系锌金属电池]: 兼具抑制枝晶的刚性与适应体积波动的柔韧性"]},{"i":35735,"as":"通过在铅基催化剂上锚定巯基咪唑配体，在催化剂表面创建了局部碱性微环境并建立了质子屏蔽效应。这一分子层面的工程策略有效平衡了抑制析氢反应与防止盐沉淀的矛盾，成功在零间隙质子交换膜（PEM）电解槽中实现了持久高效的二氧化碳电还原。","scd":null,"kp":["催化剂[零间隙PEM电解槽CO2电还原]: 锚定巯基咪唑配体的铅基催化剂","[零间隙PEM电解槽CO2还原机制]: 分子级工程调控微环境，解决了抑制析氢反应与防止盐沉淀之间的矛盾"]},{"i":35736,"as":"开发了一种无损的比率型光学纳米传感器，将聚集诱导发光碳点嵌入沸石咪唑酯框架（CD@ZIF-8）中，用于活体植物中镰刀菌素（FA）的选择性检测。通过调节碳点在框架内的分散和聚集平衡产生双发射，实现对早期真菌感染关键生物标志物的实时原位监测。","scd":null,"kp":["检测方法[活体植物内毒素检测]: 研发出非破坏性的比率型双发射纳米传感器","检测目标[农作物真菌感染早期诊断]: 镰刀菌产生的藤曲酸(FA)生物标志物"]},{"i":35737,"as":"采用配体工程方法设计了一对手性金属卤化物共晶。该设计克服了诱发手性与多面体畸变驱动的非辐射能量损失之间的矛盾，成功实现了接近1的光致发光量子产率（98%）以及7.4×10^-3的发光不对称因子绝对值，为高效圆偏振发光提供了新途径。","scd":null,"kp":["材料体系[圆偏振发光(CPL)材料]: 手性锰卤化物共晶","[圆偏振发光性能突破]: 克服了引入手性与最小化非辐射跃迁之间的内在矛盾，同时实现高发光不对称因子和光致发光量子产率"]},{"i":35738,"as":"","scd":null,"kp":[]},{"i":35739,"as":"","scd":null,"kp":[]},{"i":35740,"as":"研究揭示了马铃薯晚疫病菌的效应蛋白AVRcap1b通过结合宿主蛋白NbTOL9a和辅助型NLR受体来抑制植物免疫。解析的晶体结构显示，AVRcap1b具有独特的L型折叠结构，界定了疫霉属中一个独特的效应蛋白结构家族。研究明确了AVRcap1b与NbTOL9a的ENTH结构域的结合界面，阐明了病原体劫持辅助NLR通路抑制免疫的机制。","scd":null,"kp":["蛋白结构[致病效应子AVRcap1b与宿主相互作用]: 解析了RXLR-LWY效应子AVRcap1b与NbTOL9a的ENTH结构域的复合物晶体结构","[病原体免疫抑制机制]: 效应子与宿主蛋白NbTOL9a及辅助NLR相互作用，以劫持辅助NLR途径并抑制宿主免疫"]},{"i":35741,"as":"为解决传统载药涂层药物浓度下降和细菌耐药性问题，研究开发了一种利用植物乳杆菌作为代谢工厂的活性涂层。该涂层通过持续的消耗和产生效应，发挥长达10周的持续抗炎和抗菌作用。其消耗效应能有效消除炎症期间的活性氧，防止细胞凋亡，在感染性角膜炎治疗中展现出潜力。","scd":null,"kp":["活体涂层[感染性角膜炎治疗]: 以植物乳杆菌作为代谢工厂","[传统载药涂层]: 面临药物浓度递减和细菌耐药性发展的问题"]},{"i":35742,"as":"","scd":null,"kp":[]},{"i":35743,"as":"针对人工智能多模态学习中静态融合方案缺乏动态性的问题，研究受生物系统逆有效性原则（即较弱的单模态信号对多模态融合贡献更大）的启发，引入了逆有效性驱动的多模态融合（IEMF）策略。将IEMF集成到神经网络中，能够产生更具适应性的融合行为，从而有效提升多模态学习系统的感知能力。","scd":null,"kp":["多模态学习模型[类脑机制引入]: 融合反向有效性原则实现动态多感官整合","[传统人工智能方法]: 依赖静态融合方案"]},{"i":35744,"as":"","scd":null,"kp":[]},{"i":35745,"as":"","scd":null,"kp":[]},{"i":35746,"as":"研究利用“电极组学”技术揭示了醚类局部超高浓度电解液（LSCEs）缓解硅负极退化的电化学演变过程。硅负极复合物在初期由醚类溶剂和阴离子氧化形成；在低电位出现首次演变，富集了醇锂和氧化锂并消耗了硫氧化物；随着电池循环，发生第二次演变。这些发现阐明了硅负极在电化学反应各阶段的演化机制，支撑了其电化学力学稳定性。","scd":null,"kp":["电极组学分析[硅负极演化]: 揭示醚类局部超高浓度电解质(LSCEs)缓解硅负极降解的机制","[初始高电位阶段]: 阴极复合材料由醚类溶剂和阴离子(FSI−)氧化还原形成","[较低电位首次演化爆发]: 富集烷氧锂和锂化产物"]},{"i":35747,"as":"","scd":null,"kp":[]},{"i":35748,"as":"","scd":null,"kp":[]},{"i":35749,"as":"研究提出了一种光基3D打印策略，用于制造含有甲藻的生物相容性水凝胶复杂形状的机械发光物体。结合光学显微镜、发射光谱和力学测试，证实包裹在细胞负载凝胶中的甲藻能够生长并保持机械发光特性。当这种含甲藻的凝胶在足够高的应变下被压缩时，能够表现出强烈的生物发光现象。","scd":null,"kp":["3D打印策略[机械发光活体凝胶]: 制造嵌入甲藻的复杂形状机械发光物体"]},{"i":35750,"as":"","scd":null,"kp":[]},{"i":35751,"as":"","scd":null,"kp":[]},{"i":35752,"as":"","scd":null,"kp":[]},{"i":35753,"as":"在凝聚态物理系统中，电子的有效质量通常被认为是影响光学响应的关键因素。本研究挑战了这一传统观念，在二次能带接触型半金属中发现了一种纯粹由量子几何推导出的质量不变普适光学导电率。该光学导电率简化为一个不依赖于质量的基本常数表达式，揭示了材料量子几何特性的独特作用。","scd":null,"kp":[]},{"i":35754,"as":"为实现更高频段、更宽频带和更快响应速率的无线传感与通信一体化系统，研究提出一种垂直传输狄拉克源（DS）探测器。该探测器利用狄拉克半金属作为热电子源，有效抑制金属诱导间隙态的形成；结合范德华异质结构的固有层间垂直电子传输优势，展现出在宽带、高速太赫兹无线传感领域的巨大应用潜力。","scd":null,"kp":["垂直传输Dirac源探测器[太赫兹无线传感]: 利用狄拉克半金属作为热电子源实现宽带和高速探测"]},{"i":35755,"as":"针对钙钛矿太阳能电池异质界面在运行应力下的降解问题，研究合成了吡啶-3-甲酸铯作为钝化剂。该材料能引发反应性表面重构，抑制离子迁移并增强界面电荷转移。基于该策略的器件实现了27.28%的认证光电转换效率，未封装器件在ISOS条件下运行4092小时后仍保留了87%的初始效率，展现出卓越的运行稳定性。","scd":null,"kp":["[异质界面的传统钝化剂]: 体积型阴离子和阳离子钝化剂表现出不同的老化行为（阴离子在热应力下引发晶格膨胀）","异质界面钝化材料[钙钛矿光伏电池]: 合成吡啶-3-甲酸铯引发反应性表面重建并抑制离子迁移"]},{"i":35756,"as":"嵌合抗原受体（CAR）T细胞疗法在实体瘤中易出现T细胞耗竭。研究表明，利用溶瘤病毒（VSV）激活CAR-T细胞的内源性T细胞受体（TCR），可增强其功能与持久性。联合治疗生成了一群具有增强效应功能的抗病毒TCR启动型CAR-T细胞，单细胞RNA测序证实了其克隆扩增和效应基因的增强，其中CD4 T细胞发挥了关键作用。","scd":null,"kp":[]},{"i":35757,"as":"针对肠道病毒A71（EV-A71），研究解析了12种强效中和性人类单克隆抗体Fab片段及其与病毒复合物的结构。这些抗体表位覆盖了85%的衣壳表面，大部分结合于“峡谷”区域。阻断SCARB2受体结合是其共同的中和机制。研究指出，较长的CDR-H3环在结合中起关键作用，基于短CDR3抗体的抗原性数据可能具有误导性。","scd":null,"kp":[]},{"i":35758,"as":"研究提出了一种名为FOLIC的中央凹光场复合成像系统。该系统将复眼启发的广角覆盖和室眼启发的空间敏锐度统一在多孔凹面架构中。FOLIC能够通过单次拍摄自然生成外围、融合和中央凹区域，实现从广角视野背景到单细胞横向分辨率的无缝、深度延伸的多尺度可视化，突破了空间分辨率、视场和深度感知之间的固有权衡。","scd":null,"kp":["FOLIC成像系统[视觉成像]: 结合复眼启发的宽角度覆盖实现中央凹光场复合成像","[传统紧凑型人工视觉系统]: 在空间分辨率、视场和深度感知之间存在固有权衡"]},{"i":35759,"as":"为解决抗癌药物紫杉醇天然丰度低的问题，研究在培养的红豆杉形成层分生细胞（CMC）中分析了其生物合成的转录因子网络。结果表明，联合表达两种成髓细胞血症（MYB）转录因子，能够协同激活一系列紫杉醇生物合成基因。在稳定的转基因CMC中，紫杉醇产量提高了121倍，其前体巴卡亭III产量提高了364倍。","scd":null,"kp":["转录因子网络[紫杉醇生物合成驱动]: 最小化的双MYB转录因子组合表达足以驱动合成","红豆杉形成层分生细胞系统[紫杉醇产量提升]: 茉莉酸甲酯可增强紫杉醇生产"]},{"i":35760,"as":"肌肉因子Irisin被证实能够改善实验性和人类2型糖尿病中胰腺β细胞的分泌功能障碍。在糖尿病小鼠和人类胰岛中，Irisin增加了胰岛素含量和葡萄糖刺激的胰岛素分泌，并显著刺激β细胞增殖。机制研究表明，Irisin逆转了慢性高糖暴露造成的β细胞功能损伤，有效维持了2型糖尿病中的β细胞功能质量。","scd":null,"kp":[]},{"i":35761,"as":"研究利用太平洋深海海山的观测和再分析数据，揭示了近惯性内波（NIWs）如何通过与海山相互作用影响底层沉积物的变化。海山上方的反气旋涡度“泰勒帽”充当烟囱，将NIW能量聚焦。NIWs在海山顶部发生反射并产生强烈的底层水流，导致沉积物受到侵蚀。随着纬度升高，风能向NIWs的输入增加，该过程促进了海山顶部沉积物的清除。","scd":null,"kp":[]},{"i":35762,"as":"受攀缘植物卷须动态成圈的启发，研究团队提出了一种微型螺旋结构形成与驱动的时空控制材料系统。该系统利用聚丙烯酸共聚物水凝胶差异膨胀产生的内在弯曲来控制螺旋形成的空间位置和动态变化，并以电场作为电渗流诱导膨胀/解胀相变的主要控制手段。通过操纵电场，实现了对微观螺旋形成和驱动的精确时空控制，解决了微尺度下的技术挑战。","scd":null,"kp":["微螺旋形成与驱动[仿生时空控制]: 实现对微观尺度螺旋形成和驱动的精确时空控制"]},{"i":35763,"as":"研究使用转录组学衰老时钟，测量了感染四种肠道RNA病毒的果蝇的生物年龄，证实致病性肠道病毒感染会加速机体衰老。衰老加速的程度与病毒的致病性直接相关。这一规律在不同感染途径中均成立，且在秀丽隐杆线虫中同样保守（非致病性病毒几乎不产生加速）。通路分析显示衰老加速具有系统性的跨组织影响，且在雌雄中加速程度相当。","scd":null,"kp":[]},{"i":35764,"as":"研究提出了一种基于硫醇-烯化学的聚合物半导体（PSCs）直接生物功能化策略，用于制造软体可拉伸的晶体管生物传感器。该策略将硫醇化生物分子选择性地接枝到半导体/弹性体网络的弹性体结构域中。此方法在保持PSCs电子性能的同时，实现了分辨率高达10微米的图案化。利用该平台，成功设计并制造了类皮肤的电解质门控有机场效应晶体管等生物传感器。","scd":null,"kp":["直接生物功能化策略[聚合物半导体]: 基于硫醇-烯化学将生物分子选择性接枝到半导体上","[传统聚合物半导体]: 有限的生物功能化能力限制了其在生物传感中的应用"]},{"i":35765,"as":"研究证明，结合携带轨道角动量（OAM）的扭曲飞秒激光束、自旋角动量（SAM）与质谱技术，可将手性选择的灵敏度提高至四倍。实验使用樟脑对映体作为样品，利用能量为数百微焦的数百飞秒激光脉冲，观察到了强烈的对映体选择性电离和碎裂现象。SAM与OAM的相互作用显著提升了质谱在区分分子镜像对映体时的敏感度和选择性。","scd":null,"kp":["[手性分子鉴别]: 利用携带轨道角动量(OAM)的扭曲飞秒激光束结合自旋角动量(SAM)与质谱技术增强手性区分能力"]},{"i":35766,"as":"为追踪古代欧洲人是否食用昆虫，研究采用宏基因组学筛选了745份古代人类牙结石样本，发现昆虫DNA丰度极低，远低于尼安德特人、黑猩猩和大猩猩。此外，编码胃表达几丁质酶的基因在全球范围内表现出显著的纬度分化特征。这种基因渐变群与进化带来的利益相一致，基因组双重证据表明古代欧洲人食用昆虫的现象十分有限。","scd":null,"kp":[]},{"i":35767,"as":"研究打破传统多环耦合策略中的几何对称性约束，创建了一个广义的弹出式剪纸平台，实现了具有可编程多稳态的三维可重构物质。该平台允许进行可控的、非对称的弹出和扭转运动。其特性将简单的二维制造状态与复杂的三维操作状态解耦，大幅简化了制造过程。利用该平台，研究团队成功演示了先进制造和可部署设备的相关应用。","scd":null,"kp":["[多稳态弹出式剪纸系统]: 采用多环耦合策略设计，实现了二维制造状态与复杂三维操作状态的特性解耦","[三维可重构物质]: 通过可编程多稳态弹出式剪纸技术构建"]},{"i":35768,"as":"研究通过综合卫星浮游植物生理指数、水文观测、组学生物标志物与营养盐添加实验，揭示了海洋大规模营养盐压力的驱动因素。研究得出了清晰的生物地理学规律：营养盐压力与营养跃层深度密切相关，在氮限制水域中表现强于磷限制水域，并在细胞利用稀缺替代营养物时达到峰值。季节性变化占主导地位，同时过去二十年的表面变暖也放大了营养盐压力。","scd":null,"kp":[]},{"i":35769,"as":"模拟表明，南大洋对热带气候的遥相关作用受平均态热带辐合带（ITCZ）的稳健调节。拥有更真实ITCZ的模型，能通过更强的风-蒸发-SST反馈模拟出热带海表温度（SST）对南大洋强迫的更强响应。当引入逼真的南极融水强迫时，纠正模型的热带平均态偏差会使热带对南大洋变冷的降温响应更强，有效改善了模拟与观测的SST趋势之间的一致性。","scd":null,"kp":[]},{"i":35770,"as":"研究提出了一种无 beads（微珠）的单分子力谱平台——系链力谱（TFS）。该平台使用单一DNA系链同时作为施力器和内部校准器，避免了传统微珠技术的尺寸和表面化学变异、校准需求及多重系链伪影等问题。在TFS中，剪切流对相同的DNA系链施加皮牛顿级的力，直接作用于表面锚定的分子，并通过单分子荧光同步监测其构象动力学。","scd":null,"kp":["[单分子力谱]: 提出一种无珠、长柄脱离的系链力谱(TFS)高通量平台，消除尺寸/表面化学变异及多系链伪影"]},{"i":35771,"as":"研究提出了一种电场引导的DNA数据存储系统，通过电场驱动的分子数据控制克服了传统PCR工作流的局限。该DNA存储芯片集成了编码固定化功能与可重复使用的合成访问能力。通过位置特异性引物杂交结合室温下的延伸，评估了电场驱动的引物访问与DNA合成能力，在保持高保真度的同时大幅缩短了访问时间，并表现出线性的降解特性。","scd":null,"kp":[]},{"i":35772,"as":"研究测量了在1至700 MeV能量中子诱导下的铀-235裂变反应的平均瞬发裂变中子多重性。第四代核反应堆的开发需要利用快中子，这要求在1 MeV以上的宽中子能量范围内具备低不确定性的核数据。该研究针对铀-235提供了当前平均瞬发中子多重性实验数据的测量结果，以满足核工程及第四代核反应堆开发的精确核数据需求。","scd":null,"kp":["入射中子能量[$^{235}\\mathrm{U}(n,f)$反应]: 1至700 MeV","[平均瞬发裂变中子多重性]: 覆盖广泛中子能区(特别是1 MeV以上)以满足GenIV核反应堆低不确定度核数据需求"]},{"i":35773,"as":"研究提出了一种具有抗噪能力的创新方法，用于测试多体量子系统的真实多体非局域性。该方法基于一个量子网络假设，即该网络通过多份真实多体纠缠态的副本进行“膨胀”。此方法能够有效揭示多部分量子系统的非局域性行为，为深入理解多体量子系统的特性及其在量子网络中的潜在应用提供了重要见解。","scd":null,"kp":["[多体量子非定域性测试]: 提出一种基于多拷贝真正多体纠缠态膨胀网络的抗噪新方法"]},{"i":35774,"as":"研究提出了一种利用n2EDM装置、通过磁诱导自旋退极化测量来提取超冷中子能谱的新颖方法。该方法还被用于探究材料捕获超冷中子的储存特性，特别是对用于约束和储存超冷中子的陷阱材料的表面相互作用和物理特性具有高度敏感性，为超冷中子物理实验及中子电偶极矩的精确测量提供了关键的技术分析手段。","scd":null,"kp":["[超冷中子能谱提取]: 提出利用n2EDM装置从磁诱导自旋退极化测量中提取能谱的新方法","[超冷中子存储属性]: 利用磁诱导自旋退极化测量方法探究材料陷阱的存储特性"]},{"i":35775,"as":"研究在8×8的光学镊子阵列中，实现了费米子锂-6原子的任意两组分乘积态的确定性制备，其运动基态保真度超过98.5%。该实验利用锂-6原子在自旋分辨率上较大的微分磁矩，结合并行化操作技术，成功演示了基态费米子镊子阵列的可编程组装，为量子模拟和量子计算的高精度控制奠定了基础。","scd":null,"kp":["运动基态保真度[费米子光镊阵列$8\\times8$网格]: 高于98.5%","[费米子$6\\mathrm{Li}$原子制备]: 实现任意双组分乘积态的确定性制备及并行化自旋分辨操作"]},{"i":35776,"as":"研究探讨了横向动量微分径向流，并提出可观测量v0(pT)是重离子碰撞中径向流的直接且敏感的探针。该观测量可用于量化微分横向动量谱的事件逐次涨落。近期在欧洲核子研究中心（CERN）大型强子对撞机上的测量结果显示出明显的质量依赖性规律，研究将爆炸波解析模型与夸克结块机制结合，对这些实验测量数据进行了深入理论分析。","scd":null,"kp":[]},{"i":35777,"as":"研究分析了在长程代数衰减耦合作用下，XY模型中Berezinskii-Kosterlitz-Thouless（BKT）相变的持续性。BKT相变是由涡旋激增驱动的拓扑相变的典型代表。研究结果阐明了在引入长程相互作用机制后，这种典型的拓扑相变特征是否依然保持，为理解复杂量子体系中的拓扑相变和长程耦合物理机制提供了理论依据。","scd":null,"kp":[]},{"i":35778,"as":"研究在美因茨电子加速器（MAMI）的A2标记光子设施上，对γp→π0p反应中的达利兹衰变（π0→e+e−γ）进行了迄今统计精度最高的测量。研究精确提取了π0电磁跃迁形状因子的斜率参数。该高统计量实验结果为粒子物理标准模型的精确检验以及轻子-强子相互作用的基础理论模型计算提供了至关重要的实验数据支撑。","scd":null,"kp":[]},{"i":35779,"as":"研究发现了声波散射的因果散射规律，提出了量子物理中巴尔丁求和规则的声学类比。实验证明，在一个频率范围内增加声波散射，必须以减少另一频率范围内的散射为代价。这一基于因果关系的散射约束机制发现，为声学工程领域的超材料设计、声学隐身以及声波定向操控等应用提供了全新的理论指导。","scd":null,"kp":[]},{"i":35780,"as":"研究开发了一种柔性、无线且完全无源的双模态传感平台，用于解耦检测汗液电解质和皮肤温度，以评估热应激状态。该系统将汗液响应型电化学模块和热敏导电复合材料集成在单一LC谐振架构上。两者均通过电磁感应耦合到柔性蛇形线圈中，无需电池即可实现近场通信与数据传输，确保了剧烈运动下对生理信号可靠、独立的实时监测。","scd":null,"kp":["[柔性无源传感平台]: 实现对电解质和温度的解耦双模态无线监测以评估热应激状态"]},{"i":35781,"as":"本综述探讨了人工智能与热拉制多材料纤维技术在智能纺织品领域的交叉融合。热拉制纤维能够将聚合物、金属、半导体及压电材料集成到连续的高精度多材料结构中，具备高可扩展性。这种纤维可实现分布式传感、能量调节和信号转导，并产生适合AI分析的高维数据流。文章总结了两项技术结合的最新进展，包括以数据为中心的优化等应用。","scd":null,"kp":["[热拉拔多材料纤维]: 将聚合物、金属、半导体及压电/离子电子相集成，实现高几何保真度和制造可扩展性","[智能纺织品]: 赋予机械柔顺性与嵌入式自适应计算能力的分布式架构"]},{"i":35782,"as":"研究开发了一种噻吩-联吡啶共价有机框架（BT-Bpy-COF），用于高效光催化合成过氧化氢（H2O2）。传统光催化过程常因光生电子在到达氧激活位点前复合而受限。该技术通过将光激发电子直接限制在催化中心，解决了这一瓶颈。超快瞬态吸收光谱和Operando X射线光电子能谱证实，这些被限制的电子被快速转移并利用，从而显著提升了太阳能驱动合成H2O2的效率。","scd":null,"kp":["[光催化合成H2O2]: 通过在共价有机框架催化位点空间限域光生电子，抑制复合并提升O2活化效率"]},{"i":35783,"as":"受头足类动物皮肤适应性变色的启发，研究通过4D打印技术开发了一种具有可编程开关的微波吸收器。该设计利用热对流温度梯度控制液晶弹性体的亚稳态形貌，促使R6M基体与羰基铁进行定向排列。这种策略打破了传统吸收器结构与频率固定的限制，实现了对吸收器形态的精确宏观控制。该动态器件具备自主且可逆的控制能力，满足了智能隐身系统日益增长的需求。","scd":null,"kp":["[微波吸收器]: 4D打印、可变形渗滤网络与谐振模型、具备自适应可编程开关","[隐身机制]: 模仿头足类动物皮肤变色原理实现电磁隐身状态的动态可逆重构"]},{"i":35784,"as":"研究通过优化电化学循环协议（恒流协议），显著提升了基于二氧化锰（MnO2）的水相质子插层系统在电化学二氧化碳（CO2）捕集中的性能和能效。传统方法受限于低电流密度和电极快速降解。研究发现，未优化的循环协议会导致MnO2材料退化，而采用特定的电化学循环协议能够有效改善质子插层材料在CO2捕集应用中的表现，为低能耗CO2分离提供了新途径。","scd":null,"kp":["[电化学CO2捕集]: 基于水系质子插层的MnO2系统","[循环性能优化]: 采用恒电流协议优化策略改善低电流密度运行与电极快速降解问题"]},{"i":35785,"as":"研究合成了一系列含铱的双钙钛矿氧化物（A=Sr, Ba；B'=Fe, Co, In, Y, La, Ce, Pr, Nd, Tb），探究其在酸性析氧反应（OER）中的结构与长期性能关系。表面敏感光谱和电化学测试表明，尽管成分不同，所有材料在结构重排后都会收敛至相似的内在OER活性，但速率不同。其中，B'位阳离子决定了材料的溶解动力学，亲氧性更强的阳离子表现出更慢的重排速率。","scd":null,"kp":["[OER催化剂]: 含Ir双钙钛矿（A=Sr,Ba; B'=Fe,Co,In,Y,La,Ce,Pr,Nd,Tb）","[OER催化机制]: 酸性析氧反应过程中催化剂结构重组动态及稳态活性呈现趋同特征"]},{"i":35786,"as":"研究提出了一种光热消融印迹（PAB）策略，用于在凝胶基质中构建可灌注、稳健且具有层级分支的毛细血管网络。该方法利用生物可吸收的光热纤维（PTF）作为雕刻模板，通过近红外（NIR）和紫外线激活形成多种直径的微通道，同时通过纤维增强提高了水凝胶的机械韧性。生成的光热微通道水凝胶（PMH）能够支持高效灌注和细胞活动，解决了工程组织微血管网络构建的瓶颈。","scd":null,"kp":["[微血管网络工程]: 光热消融印迹（PAB）策略","[工程模板]: 生物可吸收光热纤维（PTF）","[水凝胶基质]: 构建可灌注、坚固且具有分级分支的毛细血管尺度微血管网络"]},{"i":35787,"as":"研究设计了碘极化的单原子铁位点（Fe-NI-C），实现普适性的非自由基催化。该材料能够分子吸附过氧单硫酸盐（PMS）并降低其活化能垒，从而在2分钟内完全去除酚类物质，速率常数达4.098 min⁻¹，且具有71.2%的总有机碳去除率。该系统在pH 3-11及自来水、河水、海水中均保持接近定量的活性。电化学和EPR测试证实了其高效的电子转移机制。","scd":null,"kp":["[催化剂]: 碘极化的氮掺杂碳负载Fe-N4单原子位点","[苯酚降解]: 2分钟内完全去除","[PMS活化机制]: 分子吸附过硫酸盐（PMS）降低活化能垒，实现超快非自由基氧化"]},{"i":35788,"as":"研究使用国际未来模型（International Futures），将188个国家的188项社会经济指标预测推演至2150年，扩展了共享社会经济路径（SSPs）的量化范围。该模型整合了人口、冲突、经济、教育、健康、基础设施和治理数据，解决了预测与叙事不匹配、模型不连贯及缺乏22世纪预测的问题。结果表明，由于冲突、治理等因素的影响，预测的全球经济增长率低于现有预期。","scd":null,"kp":[]},{"i":35789,"as":"基于物理引导的机器学习模型和综合水库清单，研究对全球超过55万个水库（约95%为小型水库）的泥沙淤积进行了高分辨率评估。结果显示，仅考虑大型水库会严重低估超过75%区域的泥沙淤积率。这种低估掩盖了全球水库蓄水量平均每十年下降7.3%±2.8%的事实，且目前近五分之一的水库面临高风险状态。研究强调了小型水库在全球水安全中被忽视的风险。","scd":null,"kp":["[评估规模]: 超过550,000个水库","[小型水库占比]: ~95%","[沉积风险评估模型]: 基于物理引导的机器学习模型"]},{"i":35790,"as":"研究通过反应蒸馏技术原位去除挥发性副产物9-十八碳烯，打破了生物源油酸酯自交叉复分解反应长达40年的50%热力学平衡转化率限制，实现了100%的完全转化。在80-90°C条件下，使用大蒸发面积和短蒸汽路径的装置（如三通接头或分子蒸馏设备），优化后的油酸乙酯反应生成了近乎定量产率（80-90%）的高价值二乙基( E/Z )-9-十八碳烯二酸酯，使生产率翻倍。","scd":null,"kp":["[交叉复分解反应]: 生物基油酸酯","[传统转化率限制]: 50%（受热力学平衡限制）","[转化率突破]: 通过原位蒸馏挥发副产物迫使反应超越热力学平衡，实现100%完全转化"]},{"i":35791,"as":"向可再生碳转型以生产日常化学品的关键在于创新利用可持续原料。科学家通过协同催化和反应工程技术，成功将可再生脂肪酸整合到高附加值的最终产品中，从而提升了循环生物经济的潜力，为绿色碳化学品的生产提供了兼顾可再生性与成本效益的解决方案。","scd":null,"kp":["[绿色碳化学品合成]: 协同催化与反应工程将可再生脂肪酸整合为高附加值终端产品"]},{"i":35792,"as":"低温阴离子交换膜零间隙二氧化碳（CO2）电解槽难以在大于200 mA cm⁻²的工业相关电流密度下实现长期稳定（>1000小时）。电池失效主要由盐沉淀或水浸导致CO2运输受阻引起。文章审查了限制这些电池长期运行的离子和水传输过程，指出优化系统内的水和离子平衡可缓解上述失效机制，并为阳极液供给系统未来的盐和水管理策略指明了方向。","scd":null,"kp":["[CO2电解槽]: 阴离子交换膜零间隙","[电流密度]: >200 mA cm−2（工业相关）","[长期稳定运行时间]: >1,000小时","[失效机制]: 盐沉淀和/或液泛限制了CO2向催化剂层的传输"]},{"i":35793,"as":"研究证明了核协方差嵌入能够实现不同连续概率分布的信息论完美分离。在统计学上，这等价于在再生核希尔伯特空间中测试两个中心高斯测度之间的奇异性。这些高斯分布是通过概率测度的核协方差嵌入定义的。从信息论角度来看，区分奇异高斯分布比非参数双样本测试在结构上更为简单，特别是在复杂或高维空间中。","scd":null,"kp":[]},{"i":35794,"as":"APOBEC2是AID/APOBEC胞苷脱氨酶家族中缺乏催化活性的成员，其功能类似转录因子，能在骨骼肌中维持肌肉身份。研究发现，造血谱系中也表达APOBEC2。APOBEC2缺失会破坏正常的淋巴细胞谱系分化，导致在小鼠和人类中出现同时表达TCR和其他谱系标记的双向身份淋巴细胞，揭示了其在造血谱系定向中的关键作用。","scd":null,"kp":[]},{"i":35795,"as":"研究揭示了芝麻发芽过程中木脂素代谢的分子机制。在发芽期间，脂溶性木脂素完全转化为糖苷。研究鉴定出一组底物范围更广的细胞色素P450酶（SiCYP706V12–V14）。这些酶在发芽时氧化(+)-芝麻素和(+)-芝麻林：SiCYP706V12将(+)-芝麻素转化为(+)-芝麻醇，而SiCYP706V13和V14则进一步催化该过程，弥补了以往对发芽期代谢转变机制认知的空白。","scd":null,"kp":["[代谢转化机制]: 芝麻发芽过程中亲脂性木脂素向糖苷的完全转化","[关键酶]: SiCYP92B14（特异性氧化酶）及一组协同的氧合酶与糖基转移酶"]},{"i":35796,"as":"高危型人乳头瘤病毒（HPV-16）通过表达E6癌蛋白降解p53肿瘤抑制因子促进肿瘤恶性进展。研究通过共价靶向E6蛋白上邻近E6AP结合界面的半胱氨酸，实现了对E6蛋白的选择性和不可逆失活。药理抑制E6恢复了HPV-16阳性癌细胞中p53蛋白的稳定性和转录活性，诱导细胞凋亡和衰老。CRISPR工程化突变证实了其靶向机制，并在体内抑制了HPV驱动的肿瘤生长。","scd":null,"kp":[]},{"i":35797,"as":"为了提高作物产量和韧性，研究开发了一个数据驱动的框架，用于系统比较物种和模型，以确定限制植物叶片CO2同化速率的步骤。传统的串联电阻模型忽略了组织几何结构，而详细的解剖模型计算繁重且参数难以测量。该框架将CO2固定机制映射到两个有效参数上，克服了上述限制，为评估和优化植物光合作用提供了实用方法。","scd":null,"kp":["限制因素识别[提升作物产量与抗逆性]: CO2同化速率的关键步骤"]},{"i":35798,"as":"","scd":null,"kp":[]},{"i":35799,"as":"一项国际AI谈判大赛收集了海量谈判智能体，并在多场景下进行了超过18万次AI-AI谈判。结果显示，人类谈判理论在AI环境中依然适用。出人意料的是，作为人际交往特质的“热情”在各项关键绩效指标中均能带来更优结果；而“主导型”智能体则在价值获取上表现突出。此外，分析还揭示了如思维链推理等AI专属技术策略在谈判中的独特动态作用。","scd":null,"kp":["谈判交互规模[AI自主谈判智能体]: 超过180,000次","关键交互特征[AI-AI谈判]: 人类谈判理论原则依然至关重要","优势结果特征[AI谈判智能体]: 与传统人类建立关系的“温暖”特质紧密相关"]},{"i":35800,"as":"研究利用冷冻电镜解析了近期发现的蝙蝠携带病毒——勐腊病毒（MLAV）表面糖蛋白（GP）的结构。MLAV GP在翼状和HR1D区域具有独特特征，且保留了Cap结构，并含有类似马尔堡病毒（MARV）的α2螺旋。尽管广谱中和抗体MR191靶向了MLAV GP中保守的NPC1受体结合口袋，但其对MLAV的中和能力严重受损。这表明MLAV结合了埃博拉和马尔堡病毒的表位掩蔽策略以逃避免疫。","scd":null,"kp":[]},{"i":35801,"as":"通过对国际大洋发现计划U1532站点沉积物中的碎屑磁性矿物分析，研究揭示了南极西部冰盖（WAIS）自上新世以来的演化。约410-380万年前磁铁矿浓度最低，反映了当时阿蒙森海扇区WAIS面积处于最小状态。自410万年前起，WAIS扩张与全球长期变冷密切相关。约320万年前，来自思韦茨冰川盆地的细粒磁铁矿持续增加，标志着冰盖的急剧扩张及气候阈值的跨越。","scd":null,"kp":[]},{"i":35802,"as":"","scd":null,"kp":[]},{"i":35803,"as":"","scd":null,"kp":[]},{"i":35804,"as":"","scd":null,"kp":[]},{"i":35805,"as":"","scd":null,"kp":[]},{"i":35806,"as":"","scd":null,"kp":[]},{"i":35807,"as":"","scd":null,"kp":[]},{"i":35808,"as":"为解决高压锂金属电池醚基电解质的局限性，提出了一种基于双氢键相互作用的策略。通过在常规醚基电解质中引入0.05 M的LiBH₄构建双氢键电解质。BH₄−中的氢化氢与1,2-二甲氧基乙烷的活性Hδ⁺相互作用形成双氢键，从而减弱Li⁺-溶剂相互作用，加速Li⁺去溶剂化，提升电池性能。","scd":null,"kp":["电压上限[常规醚基电解液]: 4.0 V以下","氧化稳定性策略[高压锂金属电池]: 基于双氢键相互作用"]},{"i":35809,"as":"针对无负极钠金属电池中“死”钠积累和固体电解质界面不稳定的问题，提出利用晶界富含镓的多晶铝集流体。该集流体触发铝离子受控溶解，改变电解质的局部配位环境，干扰钠离子的溶剂化平衡，促进钠离子向正极迁移进行电荷补偿，有效提升电池的可逆性。","scd":null,"kp":["集流体设计[无负极钠金属电池]: 晶界富镓多晶铝集流体","核心机制[无负极钠金属电池]: 触发铝的可控溶解"]},{"i":35810,"as":"研究了点接触中边缘磁等离激元诱导的粘性电子流体的超弹道流动。在微波辐射下，超高迁移率二维电子气点接触中的边缘磁等离激元被激发。通过分析光电导信号证实了超弹道流的存在：在低磁场下，弱微波产生正光电导，而强辐射则因能量耗散引起负光电导。","scd":null,"kp":["导电状态[窄导体电子-电子碰撞]: 粘性流体态","导电机制[点接触边缘磁等离激元]: 超弹道输运","激发条件[超高迁移率二维电子气点接触]: 微波辐照"]},{"i":35811,"as":"受樱桃树皮螺旋纳米结构启发，通过可扩展的微流控纺丝技术制造出具有双轴取向结构的再生纤维素纤维。这种仿生双轴纳米结构能有效重新分布应力并抑制裂纹扩展。该纤维断裂应变达41%，拉伸强度为553 MPa，韧性高达184 MJ m−3，兼具高强度与高韧性。","scd":null,"kp":["韧性极限[再生纤维素纤维]: 50 MJ/m³以下","增韧策略[仿生纤维素纤维]: 引入仿生纳米取向策略构建双向取向结构","制造工艺[再生纤维素纤维]: 可扩展微流控纺丝技术"]},{"i":35812,"as":"针对动量编码超表面通常缺乏全局周期性的问题，引入了一种通用几何框架。该框架将动量编码超表面解释为通过在二维布拉伐晶格上施加一维周期性扰动而形成的方向莫尔晶格。推导出的显式公度条件揭示了非周期结构中隐藏的周期性，为分析和表征此类超表面提供了新方法。","scd":null,"kp":["几何分析方法[动量编码超表面]: 引入解释隐藏周期性的通用几何框架"]},{"i":35813,"as":"报道了在三维铁磁拓扑半金属CoS2表面二维五边形晶格上首次实验观察到带有能带交叉的奇异平带。突破了平带仅限于二维笼目和三维烧绿石晶格的实验局限，证明了材料表面自然形成的二维晶格可作为探索新晶格几何结构中奇特平带的新平台。","scd":null,"kp":["平带实验实现[传统几何阻挫晶格]: 仅限二维Kagome晶格和三维烧绿石晶格","新型研究平台[3D块材CoS2表面五角晶格]: 表面定域电子实现相关奇异性平带"]},{"i":35814,"as":"设计了一种基于羧甲基纤维素和磺化二氧化硅纳米颗粒的多功能剪切增稠非牛顿流体电解质。羧甲基纤维素将自由水转化为弱结合水，抑制由水引起的寄生反应和腐蚀；同时磺化SiO2纳米颗粒形成剪切增稠网络，有效抑制锌负极的无序枝晶生长，提升水系锌电池性能。","scd":null,"kp":["电解液类型[水系锌金属电池]: 剪切增稠非牛顿流体电解液","电解液组分[剪切增稠非牛顿流体电解液]: 羧甲基纤维素和磺化二氧化硅纳米颗粒","解决机制[锌负极]: 调节水状态以同时抑制枝晶生长和腐蚀反应"]},{"i":35815,"as":"揭示了钙钛矿α相到δ相自发相变的物理机制，指出拉伸应变下α相(011)和δ相(110)之间的共格界面是该相变的活性位点。通过在钙钛矿基质中引入二维钙钛矿材料，与δ相(110)面强相互作用形成2D/δ界面，利用巨大界面应变扰乱δ相取向，成功抑制相变发生。","scd":null,"kp":["相变活性位点[钙钛矿α到δ相变]: 钙钛矿α相(011)和δ相(110)面之间具有拉伸应变的相干界面","相稳定策略[甲脒基钙钛石(FAPbI3)]: 调节δ相取向以稳定α相"]},{"i":35816,"as":"利用DNA折纸技术构建了纳米级Jitterbug变形器。该结构响应化学和光学信号重构构象，泊松比保持为-1。结合机械设计与分子动力学模拟，紧凑的八面体通过释放弹性能量自发转变为扩张的立方八面体。这种DNA变形器能像病毒一样在脂质双分子层上制造纳米孔。","scd":null,"kp":["泊松比[DNA折纸纳米级Jitterbug可重构结构]: -1"]},{"i":35817,"as":"强调了原子级精确活性位点设计在废塑料加氢裂解转化为燃料、轻质烯烃和芳烃过程中的关键作用。指出传统催化剂的活性和稳定性源自原子尺度的基元步骤。文章重点介绍了原子活性中心和关键机理因素，并强调了技术经济与生命周期分析对设计高效加氢裂解系统的重要性。","scd":null,"kp":["[废弃塑料加氢裂解制燃料及化学品]: 催化剂设计正由传统的均相、纳米颗粒和体相催化剂向原子级精确催化剂转变"]},{"i":35818,"as":"","scd":null,"kp":[]},{"i":35819,"as":"设计以(PMA)4InCl7和(PMA)4NaInCl8为代表的铟基八面体基元，作为坚固的配位剂结合钙钛矿表面的Pb-I端基。其中PNIC形成有序的八面体骨架，通过In(Na)-Cl与Pb-I单元的八面体耦合，实现与3D钙钛矿的相干界面耦合。这种刚性耦合固定了表面界面的甲脒阳离子和Pb-I八面体，抑制结构自由度，提升稳定性。","scd":null,"kp":["表面/界面配位剂[卤化物钙钛矿降解防治]: (PMA)4InCl7 (PIC)和(PMA)4NaInCl8 (PNIC)等铟基八面体基序","[PNIC相界面结合]: 形成连贯的无机框架"]},{"i":35820,"as":"提出利用阳离子丝素蛋白(SF)对mRNA-脂质纳米颗粒进行定制化蛋白晕后修饰工程。SF包覆的LNP增强了细胞摄取和内体逃逸能力，使淋巴结递送效率提升3.6倍，体内蛋白质表达延长2.5倍。在癌症疫苗模型中，该策略显著促进树突状细胞成熟、抗原交叉呈递和细胞毒性T细胞激活，有效防止肿瘤复发。","scd":null,"kp":["载体工程[mRNA-LNP靶向递送]: 使用阳离子丝素蛋白(SF)进行后加工定制蛋白质冠修饰","[阳离子丝素蛋白包覆LNP]: 增强细胞摄取和内体逃逸能力"]},{"i":35821,"as":"提出了一种基于深度学习的逆向设计框架，用于创建动态可重构的太赫兹超器件。通过训练残差神经网络，将目标电磁响应直接映射到器件几何结构，克服了传统迭代设计的瓶颈。该方法实现了在连续材料相变过程中的自适应多维加密，满足了6G网络物理层安全通信的需求。","scd":null,"kp":["[6G网络多维安全通信]: 利用深度学习逆向设计框架创建动态可重构的太赫兹超器件"]},{"i":35822,"as":"通过将双(4-氨基环己基)甲烷引入硬段，结合低分子量聚四亚甲基醚二醇软段，合成了无定形脂环族聚(醚-酰胺)共聚物。这种分子设计产生了具有扩散边界的弱微相分离结构，即“界面擦除”策略。其形成的热压薄膜具有50至100纳米的相区，显著提升了材料的光学透明度及机械稳定性。","scd":null,"kp":["硬段成分[脂环族聚(醚-酰胺)共聚物]: 引入双(4-氨基环己基)甲烷(PACM)以抑制结晶","软段成分[脂环族聚(醚-酰胺)共聚物]: 采用低分子量聚四氢呋喃二醇(PTMEG)增强链段兼容性"]},{"i":35823,"as":"提出在单片混合离子-电子催化剂阴极中构建耦合离子-电子传输路径的策略。以LiCoO2为模型系统，通过超快热集成工艺与固态电解质建立无缝界面，形成连续的渗滤网络。该设计成功解决了固态锂氧电池空气正极中氧化还原动力学迟缓的问题，实现了快速的离子和电子传输及高催化活性。","scd":null,"kp":["[固态锂氧电池固态空气正极]: 构建耦合的离子-电子传导路径以突破迟缓的氧化还原动力学"]},{"i":35824,"as":"综述了可充电锌空气电池在储能、电动汽车等领域的应用潜力及其循环寿命短、过电位高等商业化瓶颈。文章系统分析并评估了克服传统锌空气电池限制的八种非传统创新策略，重点强调了具有成本效益和高性能驱动的电池设计，为下一代能源技术发展提供了全面指导。","scd":null,"kp":[]},{"i":35825,"as":"提出了一种手性微针阵列的制备路径。该微针具有亚毫米级尺寸和周期性，在太赫兹光谱窗口展现出强烈且可预测的光学手性共振。通过实现手性等离子体-手性声子共振，这项技术在药物递送和生物传感等生物医学设备中赋予了新的功能和潜力，填补了手性微针制造方法的空白。","scd":null,"kp":["[微针阵列(MNAs)太赫兹波段应用]: 实现手性-等离激元-手性-声子共振的手性光学活性"]},{"i":35826,"as":"针对钙钛矿太阳能电池中传统小分子表面钝化易失效的问题，报道了一种可聚合表面钝化材料乙烯基膦酸(VPA)。其乙烯基实现原位聚合，磷酸基团钝化未配位的金属缺陷。聚合后的PVPA形成比有机铵小分子更坚固稳定的钝化层，有效解决了光照和热应力下的去质子化问题，提升了器件效率与稳定性。","scd":null,"kp":["[倒置钙钛矿太阳能电池表面钝化]: 采用乙烯基膦酸(VPA)作为可聚合表面钝化材料","[传统小分子钝化剂缺陷]: 在光照和热应力下极易发生去质子化导致器件稳定性受损"]},{"i":35827,"as":"开发了一种基于聚合物纳米气泡的声学标记策略，实现了超声定位显微镜对移植细胞的单细胞级超分辨率追踪。研制出可被细胞高效内化并产生强超声信号的聚氰基丙烯酸丁酯纳米气泡。该技术实现了流动模型和小鼠乳腺癌中单个细胞位置及轨迹的实时可视化，为细胞疗法监测提供了新手段。","scd":null,"kp":["[移植细胞体内超声追踪]: 采用聚氰基丙烯酸正丁酯纳米泡的声学标记策略","[聚氰基丙烯酸正丁酯纳米泡]: 具备单细胞尺度的敏感度和超高分辨率空间精度"]},{"i":35828,"as":"探讨了太阳能驱动界面蒸发技术面临的非凝结气体(NCGs)积聚问题。NCGs来源于溶解空气、有机物分解和生物活动，它们在液-汽界面汇聚形成传质屏障，严重阻碍了该技术的实际部署。文章强调了在提升产水率之外，必须解决NCGs对光热转换和水汽传输带来的负面影响。","scd":null,"kp":["产水率[太阳能驱动界面蒸发]: >5.0 L·m⁻²·h⁻¹"]},{"i":35829,"as":"提出一种结合量子化学计算与27种机器学习模型的集成计算框架，用于预测金属-配体络合物在氮还原反应中的实验催化指标。该框架在大规模实验数据库上进行训练和验证。在分类任务中，两类催化剂的测试准确率最高达到1.0，回归模型在多个任务中也展现出高预测准确性，有效推动了高效固氮催化剂的设计。","scd":null,"kp":["计算框架[仿生氮还原反应催化剂设计]: 量子化学计算与27种机器学习模型结合"]},{"i":35830,"as":"","scd":null,"kp":[]},{"i":35831,"as":"","scd":null,"kp":[]},{"i":35832,"as":"","scd":null,"kp":[]},{"i":35833,"as":"","scd":null,"kp":[]},{"i":35834,"as":"","scd":null,"kp":[]},{"i":35835,"as":"","scd":null,"kp":[]},{"i":35836,"as":"","scd":null,"kp":[]},{"i":35837,"as":"","scd":null,"kp":[]},{"i":35838,"as":"针对层状CuCrTi2Se6材料因层间电子耦合弱导致载流子迁移率低的问题，采用电荷平衡的“一个铬替换三个铜”策略调控层间键合异质性，合成(Cu1-3xCrx)CrTi2Se6。该方法实现了电子-声子解耦，在保持该过渡金属二硫化物衍生物本征低晶格热导率的同时，有效提升了载流子迁移率，从而解锁了其高热电性能。","scd":null,"kp":["[层状CuCrTi2Se6热电性能调控]: 采用“一个Cr替换三个Cu”的电荷平衡策略调节层间键合异质性以实现电声子解耦"]},{"i":35839,"as":"针对钙钛矿太阳能电池中SnO2纳米粒子作为电子传输层易发生不可控团聚及界面质量差的问题，提出一种磷酸盐缓冲合成策略。该策略在合成过程及钙钛矿/SnO2界面处均实现了有效的质子缓冲，通过调节质子积累，有效抑制了团聚现象并改善了界面质量，从而提升了器件的光伏性能与稳定性。","scd":null,"kp":["[钙钛矿太阳能电池SnO2电子传输层]: 采用磷酸盐缓冲合成策略抑制纳米颗粒团聚并改善界面质量"]},{"i":35840,"as":"为提升锂金属负极的安全性与电化学性能，通过将氧化锌修饰的金刚石颗粒与锂箔进行机械轧制，制备了超薄复合负极。在热滥用条件下，锂-金刚石界面形成的惰性产物能迅速将金属锂与空气隔离，抑制锂液滴形成并实现接触火焰时的迅速自熄。将其与不可燃电解液组装成软包电池后，在加热条件下表现出优异的安全性。","scd":null,"kp":["[高安全锂金属电池复合负极]: 将ZnO修饰的金刚石颗粒与锂箔通过机械辊轧制成超薄复合负极，热滥用下生成惰性产物提供非易燃安全性"]},{"i":35841,"as":"开发了一种钆（Gd）掺杂的Cu2O电催化剂，用于高效选择性电还原二氧化碳为乙醇。利用镧系元素的高亲氧特性，构建了富含自由水的界面微环境以调控界面水动力学，有效抑制了竞争性乙烯路径并加速了质子耦合电子转移过程，从而实现了高选择性的二氧化碳到液体燃料的转化。","scd":null,"kp":["[CO2电还原高选择性制乙醇]: 通过Gd掺杂Cu2O调控界面水动力学，抑制竞争性乙烯路径并促进质子耦合电子转移"]},{"i":35842,"as":"为解决传统离子交换膜微相分离带来的选择性与电导率之间的权衡问题，提出利用刚性侧链在亚纳米通道中间引入电荷的策略。该策略避免了通道壁电荷过剩导致的过强氢键网络形成，提高了水分子和离子的自扩散系数，成功开发了QPAEPi-3膜并形成了连续的氢键网络，实现了离子的高效传输。","scd":null,"kp":["[阴离子交换膜亚纳米通道离子输运]: 调控受限通道内电荷分布以避免形成过强氢键网络，打破选择性与电导率的相互制约"]},{"i":35843,"as":"报道了一种双功能亚氨基膦（BIMP）催化的不对称分子内氮杂迈克尔加成反应，实现了磺酰胺与α,β-不饱和酯的偶联。该反应条件简单，以高达99%的产率和97.5:2.5的对映体比例合成了富对映体的吡咯烷、哌啶和吲哚啉衍生物。反应具有广泛的底物适用性，并在降低催化剂载量的克级规模反应中展现了合成实用性。","scd":null,"kp":["反应收率[分子内氮杂迈克尔加成反应]: 高达99%","对映体比例[分子内氮杂迈克尔加成反应]: 高达97.5:2.5","催化剂[酯类迈克尔受体不对称加成]: 双功能亚氨基膦(BIMP)"]},{"i":35844,"as":"针对质子交换膜燃料电池阴极氧还原反应动力学缓慢的问题，构建了核壳结构的L10-Pt2CoFe/Pt2FeNi金属间化合物。利用铁磁核的剩余磁化强度产生的自旋钉扎效应，使Pt壳层形成稳定的高自旋态Pt位点。这种对顺磁性Pt自旋状态的有效调控，显著提升了催化剂的氧还原催化性能。","scd":null,"kp":["[质子交换膜燃料电池阴极ORR催化剂]: 利用钉扎效应构建核壳L10-Pt基金属间化合物以调节Pt位点自旋态为高自旋构型"]},{"i":35845,"as":"通过一步煅烧法合成了具有不对称高自旋N-FeN4位点的轴向配位铁单原子催化剂，用于中性条件下的选择性化学发光传感。X射线吸收精细结构和密度泛函理论分析表明，轴向N配位稳定了高自旋态，降低了轨道分裂能，增强了与过氧单硫酸盐的d-p轨道杂化，从而生成了选择性的活性铁物种，解决了水相环境中自由基路径特异性差的问题。","scd":null,"kp":["[中性环境选择性化学发光传感]: 通过轴向配位合成不对称高自旋N-FeN4位点的单原子铁催化剂以调控反键态费米能级邻近度与氧亲和力"]},{"i":35846,"as":"提出了一种构建高质量过渡金属硫族化合物@二维π-共轭共价有机框架范德华异质结的通用策略。通过液-固界面反应在二氧化硅基底上生长大面积、原子级平整的含偶氮苯的二维共价有机框架薄膜，并采用湿法转移技术将其转移至单层二硫化钼上，克服了粉体材料难以集成的限制，为光开关电子器件应用提供了新途径。","scd":null,"kp":["[二维共轭共价有机框架薄膜]: 湿法转移原位生长策略用于光控电子器件集成"]},{"i":35847,"as":"在两步沉积法制备钙钛矿薄膜的过程中，通过掺入2-苯氧基乙脒盐酸盐（PhOAaCl），成功制备出具有完全（001）择优取向的高结晶度碘化铅模板。PhOAaCl的加入有效降低了晶体晶面能，实现了对钙钛矿晶体取向和相纯度的精确调控，从而显著提升了钙钛矿太阳能电池的光电转换效率和长期稳定性。","scd":null,"kp":["[钙钛矿晶体生长]: 碘化铅(PbI2)模板调控晶面优先生长实现高效稳定光伏电池"]},{"i":35848,"as":"开发了一种吡啶催化的界面聚合（PCIP）策略，以解决传统“酰基~胺”合成的聚酰胺膜耐酸稳定性差的问题。通过设计带有三个吡啶基团的单体，在三聚氰酰氯（CC）的界面聚合过程中转化为带正电荷的吡啶鎓，显著提高了CC在室温下的反应活性，成功合成了结合稳定C─N键的高性能耐酸纳滤膜。","scd":null,"kp":["[耐酸纳滤膜]: 吡啶催化三聚氯氰与胺类界面聚合构建耐酸C-N键"]},{"i":35849,"as":"构建了无掺杂的Ru/RuO2异质结构作为酸性水氧化的无铱催化剂。该结构通过界面电荷重分布和晶格氧的协同参与，显著提升了催化活性与耐久性。在0.5 M硫酸溶液中，该催化剂在10 mA·cm-2下的过电位仅为182 mV，并在100 mA·cm-2的电流密度下稳定运行超过270小时。","scd":null,"kp":["[酸性水氧化催化剂]: 无铱Ru/RuO2异质结构通过界面电荷重排与晶格氧参与促进催化增强"]},{"i":35850,"as":"提出一种由界面电场驱动的离子-电子耦合（IEC）策略，用于废旧磷酸铁锂（LFP）的直接再生。通过在LFP表面构建局部硼-碳（B-C）偶极子层建立功函数梯度，产生界面电场，实现锂离子和电子的协同流动，有效克服了同时传输锂离子和电子的高能垒限制，成功制备出高性能的再生LFP材料。","scd":null,"kp":["[废旧磷酸铁锂直接再生]: 界面电场诱导离子-电子耦合(IEC)策略降低Li+与电子传输能垒"]},{"i":35851,"as":"开发了一种高效简便的方法，制备了高收率的无异构体多加成富勒烯衍生物C60(NHR)4O，作为钙钛矿太阳能电池的电子传输层材料。其中，四[甲基2-氨基-3-(噻吩-2-基)丙酸酯]C60衍生物全面满足了电池对电子传输层的多功能要求，成功使钙钛矿太阳能电池的光电转换效率达到26.66%。","scd":null,"kp":["转换效率[钙钛矿太阳能电池]: 26.66%","[电子传输层材料]: 无异构体多加成富勒烯衍生物"]},{"i":35852,"as":"报道了一种基于金属有机框架的非均相双氢键/光氧化还原协同催化体系。研究合成了六种具有光催化和双氢键供体中心的MOF，发现催化中心的柔性和空间取向在催化性能中起主导作用，而非单纯的催化剂活性。其中具有相对柔性的硫脲中心的MOF-F-TU在促进脱卤和还原偶联反应中表现出最优异的催化效果。","scd":null,"kp":["[多相双氢键/光氧化还原协同催化]: 金属有机框架中催化中心的柔性与空间取向主导催化性能"]},{"i":35853,"as":"报道了两种基于芘的氢键有机框架多晶型物H4PTBA-AA和H4PTBA-ABC。两种材料在光吸收、亲水性和粒径分布上相似，但激发态行为截然不同。光谱研究表明，H4PTBA-AA具有更小的激子结合能，优先形成电荷转移态。这揭示了多晶型控制对有机光催化剂中激子解离过程及性能的决定性作用。","scd":null,"kp":["[光催化剂激子解离]: 氢键有机框架多晶型性控制光催化活性"]},{"i":35854,"as":"通过对配位环境和电子结构的精确调控，构建了具有打破对称性的Fe-S-Fe双原子中心催化剂（Fe2-S@NHCS）。相邻铁原子与桥连硫原子的相互作用优化了活性位点的电子结构，克服了传统对称金属-氮4位点催化剂的电子结构限制，使其展现出0.912 V的高半波电位和1.45 s-1的转换频率，实现了高性能的氧还原反应。","scd":null,"kp":["[氧还原反应双原子催化剂]: 构建硫桥连破对称Fe-S-Fe双铁位点优化电子结构与吸附"]},{"i":35855,"as":"开发了一种镍催化、氧化还原中立的N-芳基丙烯酰胺与膦氧化物的分子间不对称HECK-磷酰化串联反应。该反应同时构建C─C和C─P键，高收率、高对映选择性合成具有全碳季碳中心的3,3-二取代氧化吲哚。反应表现出独特的底物控制对映发散性，在相同手性催化剂下，仅通过改变烯烃离去基团即可反转产物构型。","scd":null,"kp":["[氧化吲哚啉-2-酮衍生物合成]: 镍催化氧化还原中性级联反应构筑C-C与C-P键及季铵立体中心"]},{"i":35856,"as":"提出一种可回收的绿色湿化学协议，整合废铜的自上而下氧化溶解与自下而上的结晶过程，制备八面体Cu2O亚微米晶体。在强碱介质中，瞬态铜-氨配位促进废铜的配位驱动氧化溶解生成亚稳态前驱体，而醛官能化配体诱导表面重建，赋予其特定表面态。该材料在葡萄糖电氧化反应中表现出优异的催化性能。","scd":null,"kp":["[绿色合成技术]: 自上而下的铜氧化溶解与自下而上的结晶相整合，实现可回收的湿化学合成","晶体形态[配位诱导表面重构]: 氧化亚铜(Cu2O)亚微米八面体晶体","催化反应[强碱性介质]: 葡萄糖电氧化"]},{"i":35857,"as":"报道了一种铁催化、羧酸盐导向的不对称邻位C(sp3)-H键双胺化反应。该技术以廉价易得的羧酸为底物，使用手性四齿N4配体Fe(II)催化剂和BocNHOMs作为胺化试剂，在温和条件下一锅法高效合成手性α,β-二氨基 acids。该反应具有高区域选择性、非对映选择性和对映选择性，非对映异构体比例最高超过20:1，对映体过量最高达99%以上，适用于广泛的芳香族和脂肪族底物。","scd":null,"kp":["[不对称催化工艺]: 铁催化、羧酸盐定向的相邻C(sp3)─H键双胺化反应","[合成挑战突破]: 直接立体选择性官能化构建手性1,2-二胺","[工艺特点]: 一锅法高效合成手性α,β-双氨基酸"]},{"i":35858,"as":"开发了一种数据与理论双重指导的新型V掺杂RuO2（RV）酸性析氧反应（OER）电催化剂。通过挖掘718种催化剂数据集并进行微动力学建模筛选，确定钒为最佳掺杂元素。在10 mA cm-2的电流密度下，RV表现出193 ± 1 mV的超低过电位，并稳定运行3000小时。在实际质子交换膜水电解槽（PEMWE）装置中，RV成功实现了1 A cm-2的工业级电流密度。","scd":null,"kp":["过电位[文献统计的多金属Ru基氧化物vs单金属 counterpart]: 210 mV vs 283 mV","[催化体系设计]: 数据与微观动力学建模联合筛选，鉴定钒为高性能酸性析氧(OER)催化剂的有效掺杂剂","应用场景[高效酸性析氧]: 质子交换膜水电解槽(PEMWE)"]},{"i":35859,"as":"开发了一种含有成对Ce(III)单原子位点和芘基团的三维共价有机框架（BPDA-AmCOF-Ce）。该催化剂具备优异的可见光吸收能力和匹配的能带结构，同时包含水氧化反应（WOR）和二氧化碳还原反应（CO2RR）的双重活性位点。这种结构设计克服了缺乏高效光催化剂的难题，成功实现了模拟植物全光合作用，将二氧化碳和水直接转化为C2+化学品。","scd":null,"kp":["[人工光合作用催化剂]: 将成对的Ce(III)单原子位点 incorporated 进入共价有机框架(COF)","[光催化功能突破]: 集成水氧化反应(WOR)与CO2还原反应，实现模拟全光合作用","产物[CO2与H2O光催化转化]: C2+化学品"]},{"i":35860,"as":"针对KRAS驱动型癌症治疗，发现脱氢吴茱萸碱（DEE）作为新型G-四联体（G4）稳定剂，并基于其与KRAS-G4的结合模式结构分析，合理设计并合成了15种DEE衍生物。筛选天然产物库克服了目前G4靶向配体效力不足和结构单一的临床阻碍。结构导向设计策略成功提升了G4稳定剂的抗癌活性，为靶向致癌基因启动子G4的恶性肿瘤治疗提供了新方案。","scd":null,"kp":["[抗癌靶点机制]: 靶向KRAS癌基因启动子的平行G-四链体(G4)","[药物筛选与设计]: 基于结构信息设计结构多样的特异性G4稳定剂用于KRAS驱动的癌症治疗"]},{"i":35861,"as":"报道了一种利用亚胺取代氧化膦与环氧化物发生类似Horner-Wadsworth-Emmons反应的新方法。该策略实现了从环氧化物到环丙胺的立体定向转化，具有极高的对映特异性（≥98%），成功将环氧化物的手性转移至环丙胺中。反应兼容多种单取代和双取代环氧化物，被高效应用于替格瑞洛和反苯环丙胺等生物活性分子核心骨架的可规模化合成。DFT计算阐明了亚氨基团在促进反应中的关键作用。","scd":null,"kp":["对映体过量值[立体保留的环丙胺化转化]: ≥ 98%","[反应类型与特征]: 亚胺取代膦氧化物与环氧化物发生同系Horner-Wadsworth-Emmons型反应，实现从O到C(NH2)的正式原子交换","[底物适应性]: 广泛兼容单取代、2,2-及其他多种取代基的环氧化物"]},{"i":35862,"as":"开发了能量转移催化技术，实现了2-吡啶酮的Birch型还原反应。部分饱和杂环是药物研发中的关键中间体，传统Birch还原条件在安全性和化学选择性上存在局限。利用三线态敏化策略，该技术高选择性地实现了单环杂环芳烃的部分还原。这一方法突破了能量转移催化在还原反应中主要局限于双环芳烃的现状，为药物先导结构优化提供了一种安全、高效的新途径。","scd":null,"kp":["[催化工艺特点]: 能量转移催化克服安全与化学选择性挑战，实现2-吡啶酮的Birch型还原"]},{"i":35863,"as":"揭示了水分子对TiO2催化醇脱水反应的晶面依赖性影响。研究表明，异丙醇在TiO2(001)表面的脱水抑制程度是(101)表面的四倍。结合原位固态核磁共振、原位红外光谱、动力学研究与理论计算证实，这种差异源于不同晶面上形成了截然不同的水-醇复合物。该发现深入阐明了生物质衍生原料中水分子在氧消除反应中的分子层面影响机制。","scd":null,"kp":["[水抑制机制]: 揭示异丙醇(IPA)脱水过程中显著依赖于TiO2晶面的水分子抑制效应","催化影响[不同暴露晶面络合物]: TiO2(101)与(001)晶面形成截然不同的水-烷醇络合物"]},{"i":35864,"as":"为解决室温电沉积过渡金属过程中严重的界面钝化问题，以多价钛为例揭示了其内在机制。Ti-Cl键与电极的结合使电极的d带中心下移了0.15 eV，显著抑制了界面的离子吸附与电荷转移。原位研究表明，通过阴阳极协同工程，阳极溶解产生的[Ti(Al2Cl7)]-配合物有效抑制了界面钝化。该策略显著提升了过渡金属电沉积的电流效率。","scd":null,"kp":["[界面钝化机制]: 过渡金属(如多价态Ti)与物种间强烈的化学键合导致严重的界面钝化","[工艺改进策略]: 阳极-阴极协同工程有效抑制界面钝化","[应用效果]: 显著提升过渡金属及其合金室温电沉积的电流效率"]},{"i":35865,"as":"开发了一种原子级工程策略，构建了由RuOx团簇修饰的Cu基纳米线阵列电极。该电极具备丰富的界面结构，作为高效串联催化剂，实现了安培级电流密度下的亚硝酸盐-乙醇配对电解。原位光谱分析与理论计算表明，原子级精准修饰的RuOx-Cu双活性位点在多步电化学转化中实现了高效的协同调节，解决了串联催化双活性位点难以原子级调控的挑战。","scd":null,"kp":["[催化剂微观结构]: 原子级精准构建的RuOx团簇修饰的Cu基纳米材料界面","[串联催化特点]: 实现双活性位点的协同调控以促进多步电化学转化","[电化学性能]: 实现安培级亚硝酸盐-乙醇共电解"]},{"i":35866,"as":"报道了一种基于天然(-)-α-蒎烯合成的手性四氢芴基铑(III)络合物，并将其成功用于催化不对称有机反应。该催化剂制备过程简单，无需手性HPLC或非对映异构体分离等耗时技术。利用双甲基取代的络合物，首次实现了Rh(III)催化的重氮化合物与氢硅烷及富电子烯烃的不对称反应，高效合成了手性硅烷和环丙烷类化合物，为制药和天然产物合成提供了实用工具。","scd":null,"kp":["催化剂[不对称合成硅烷和环丙烷]: 手性α-蒎烯衍生茚基配体 Rh(III) 络合物","合成工艺[手性四氢芴基Rh(III)络合物]: 起始于简单原料的四步法"]},{"i":35867,"as":"提出了一种准聚合诱导自组装策略，实现了聚合物纳米圆柱体的高浓度、规模化精确合成。该技术结合原位成核-生长动力学，利用浓度高达10 wt.%的液晶嵌段共olymer制造均匀的圆柱状胶束。研究证实，PISA过程中较宽的分子量分布可被用作精确组装的关键变量。通过调节聚合条件，实现了纤维状结构的精准控制，打破了纳米结构生产效率与形貌控制之间的固有权衡。","scd":null,"kp":["合成策略[纳米圆柱体可扩展精确合成]: 准聚合诱导自组装（quasi-PISA）","合成工艺[准聚合诱导自组装]: 结合原位成核-生长动力学制备均匀圆柱形胶束"]},{"i":35868,"as":"提出了一种消除无负极钠电池在高电流密度下软短路故障的界面设计策略。通过无溶剂气相聚合工艺，在铝集流体上保形沉积了20 nm厚的聚(1H,1H,7H-十二氟庚基丙烯酸酯)超薄涂层。该涂层极薄的厚度及固有的离子电导率优化了钠的沉积行为。该机制导向的界面修饰有效抑制了软短路，解决了钠库存有限导致的高易损性问题，实现了大容量钠金属电沉积。","scd":null,"kp":["界面设计[无负极钠电池高电流密度]: 抑制软短路机制","制备工艺[负极界面修饰]: 引发式化学气相沉积（iCVD）"]},{"i":35869,"as":"总结了硼氟二吡咯（BODIPY）衍生物在抗菌光疗领域的进展。面对抗生素耐药性及生物膜感染威胁，光动力疗法（PDT）和光热疗法（PTT）因其时空可控性、广谱抗菌性和低耐药性受到广泛关注。BODIPY染料凭借出色的结构可调性和优异的光物理性质，成为构建光疗系统的理想平台。通过阳离子化、引入重原子和延长π共轭等分子工程策略，可显著提升其抗菌性能。","scd":null,"kp":["治疗机制[BODIPY衍生物抗菌光疗]: 具备时空可控性、广谱抗菌活性和低诱导耐药性"]},{"i":35870,"as":"开发了一种具有可光控交联双分子层的盘状聚合物囊泡，用于胞内药物递送。通过调节亲疏水嵌段比例及共溶剂自组装过程中的加水速率，含有光不稳定硫代香豆素单元的嵌段共聚物自组装形成包括盘状细胞样囊泡在内的五种不同纳米结构。该盘状结构展现出优异的细胞摄取能力。可见光照射可触发双分子层交联并实现药物释放，突破了非球形聚合物囊泡热力学限制的合成瓶颈。","scd":null,"kp":["聚合物囊泡形貌[细胞内药物递送]: 盘状结构（类似红细胞）","组装基元[光响应双亲嵌段共聚物]: 疏水侧链带有光不稳定硫代香豆素单元"]},{"i":35871,"as":"构建了一种由两亲性跨膜通道与亲水性胞外通道静电共组装而成的人工间隙连接通道系统。两亲性通道的高效离子传输能力结合亲水模块在细胞间隙中的聚集，形成了稳定的细胞间连接。这种人工通道具有与天然间隙连接相似的生理功能，不仅介导了基本的细胞间通讯，还能有效抑制肝细胞癌细胞的增殖，拓展了人工间隙连接系统在病理调控中的应用。","scd":null,"kp":["人工间隙连接通道[抑制肝癌细胞增殖]: 两亲性跨膜通道与亲水性胞外通道的静电共组装体系"]},{"i":35872,"as":"报道了首个钚酰笼状簇合物——{Pu60}。该簇合物具有独特的扭曲截角十二面体拓扑结构。这一重大发现不仅极大扩展了水溶液中锕系元素的已知物种库，还通过可调节的笼状结构、反荷阳离子及配体取代，实现了对钚元素纳米尺度的精准控制，标志着钚化学领域的重要进展。","scd":null,"kp":["笼状团簇[水溶液钚化学]: 首个钶酰笼状团簇 {Pu60}","拓扑结构[{Pu60}团簇]: 独特的扭曲截角十二面体"]},{"i":35873,"as":"提出了一种混合异质成核与生长模板策略，解决了窄带隙Sn-Pb钙钛矿中Sn2+与Pb2+路易斯酸度差异导致的异步成核和结晶失控问题。该策略通过接枝的聚(4-乙烯基吡啶)将CsPbBr3量子点与多孔UiO-66金属有机框架结合，成功制备出均匀致密的Sn-Pb钙钛矿薄膜。该结晶调控技术显著提升了全钙钛矿叠层太阳能电池的光电转换效率。","scd":null,"kp":["结晶控制[窄带隙Sn-Pb钙钛矿]: 杂化异质晶种与模板调制策略","结晶问题[窄带隙Sn-Pb钙钛矿]: Sn2+和Pb2+路易斯酸性差异导致异步成核和不可控结晶"]},{"i":35874,"as":"开发了一种通过非共价构象锁定实现聚集诱导掺杂增强的共轭聚电解质，用于有机太阳能电池的高效空穴收集。通过引入非共价S-O和S-F相互作用作为构象锁，形成共平面的共轭主链。聚集态结构表征显示，CPE薄膜致密有序的分子聚集能诱导显著的p掺杂效应，解决了传统阳极界面层材料掺杂密度低、导电性差的问题，显著提升了器件的光伏性能。","scd":null,"kp":["掺杂机制[共轭聚电解质阳极中间层]: 非共价构象锁定诱导的聚集掺杂增强"]},{"i":35875,"as":"设计了一种总能量低于1兆焦耳的高增益热波驱动快点火激光核聚变方案。该方案放弃传统中心点火使用的脆弱壳体靶，采用抗流体动力学不稳定性的实心球靶。在精密激光脉冲内爆后，利用拍瓦级激光在10皮秒内将高密度燃料核心瞬间加热至点火温度。研究重点攻克了高密度燃料压缩、加热激光穿透冕区等离子体、能量高效耦合及高增益实现等核心技术挑战。","scd":null,"kp":["总激光能量[热波驱动快点火激光聚变]: < 1 MJ","点火时间[高密度燃料芯]: 10 ps","驱动激光[快点火]: 皮瓦级激光","靶材设计[抑制流体力学不稳定性]: 实心球靶"]},{"i":35876,"as":"在DIII-D高极向比压等离子体中，成功实现了高压力、剥离限制的等离子体台柱。实验中台柱顶部的归一化比压（βN,ped）大于2，且密度达到或超过格林沃尔德密度极限，同时全局βN超过3，能量约束因子H98达到1.2-1.7。高βN允许在低注入扭矩下实现更高的台柱密度和压力。MHD建模证实，强沙夫拉诺夫位移、高边缘电流密度与弱/负磁剪切等特征共同改善了台柱稳定性。","scd":null,"kp":["归一化β[DIII-D高极向比压等离子体台座]: > 2","台座顶部密度[DIII-D高极向比压等离子体]: 达到或超过Greenwald密度nG","全局归一化β[DIII-D高极向比压等离子体]: > 3","能量约束因子[DIII-D高极向比压等离子体]: ~1.2–1.7"]},{"i":35877,"as":"研究采用分子动力学模拟方法，深入分析了钨等离子体面向材料表面释放分子的特性。该工作重点探究了分子的转动和振动状态，并通过对比JET托卡马克铍限制器的光谱数据，验证了预测发射铍分子振动状态方法的准确性。","scd":null,"kp":["研究方法[等离子体-分子相互作用分析]: 分子动力学模拟","[等离子体边缘粒子与能量流]: 受到杂质/中性粒子输运及等离子体-分子相互作用的共同影响"]},{"i":35878,"as":"ST40球形托卡马克的合并/压缩等离子体启动实验中，利用二维离子多普勒断层扫描和汤姆逊散射诊断技术观测到离子的加热与约束过程。研究证实磁重联在下游区域实现了离子加热，在磁轴处实现电子加热并形成峰化分布，实现了启动等离子体电流和离子温度的准稳态维持。","scd":null,"kp":["诊断系统[ST40球形托卡马克M/C等离子体启动]: 96通道二维离子多普勒断层扫描","诊断系统[ST40球形托卡马克M/C等离子体启动]: 30通道汤姆逊散射诊断","[磁重联下游]: 观察到明显的离子加热及其约束/输运过程"]},{"i":35879,"as":"针对水系锌碘电池在高碘负载下的不稳定性，研究开发了一种分子工程双网络共晶凝胶电解质。该材料由PHEAA和PDMAPS在氯化胆碱/甘油低共熔溶剂中原位聚合而成，能同时调节锌沉积和多碘化物化学反应，维持结构完整性并提供空间电荷分布。","scd":null,"kp":["电解质[水系锌碘电池]: 分子工程化双网络低共熔凝胶电解质","[锌碘电池双网络低共熔凝胶电解质]: 通过原位聚合聚(N-羟乙基)构建，实现锌沉积和多碘化物化学的同步调节"]},{"i":35880,"as":"为了解决聚合物电介质在高温下介电常数与绝缘性之间的矛盾，研究部署了深度学习框架，在1200个候选材料中筛选聚酰亚胺复合材料中的氢键分子指纹。基于对氢键数量和带隙的预测，合成并掺入了O-PU，利用引入的氢键显著提升了材料在250°C下运行的储能性能。","scd":null,"kp":["[高温聚合物电介质]: 深度学习框架筛选聚酰亚胺复合材料中的氢键分子指纹","[深度学习虚拟筛选模型]: 破译了1200个候选者的静电势和供体/受体分布"]},{"i":35881,"as":"提出了一种针对废旧钴酸锂（LCO）的集成再生策略，通过乙二醇-醋酸锂溶剂体系实现界面清洗与钴的重新分布。这一过程均化了材料缺陷并激活了阳离子快速传输路径，在热激活下使钴发生梯度迁移，将材料衰退转化为具有功能稳定性的梯度结构，实现了电池的高效回收。","scd":null,"kp":["[废钴酸锂直接再生策略]: 乙二醇-醋酸锂溶剂系统实现缺陷均匀化并转化为梯度稳定功能架构"]},{"i":35882,"as":"倒置（p-i-n结构）钙钛矿太阳能电池凭借运行稳定性和大规模溶液可加工性获得了商业关注。尽管目前器件效率仍面临挑战，研究总结了其能量损失的来源，并突出了提升其高性能和高效率的有效策略，以期进一步推动其规模化商业应用。","scd":null,"kp":["[反式(p-i-n)钙钛矿太阳能电池]: 具有高操作稳定性、可溶液加工性及与叠层架构的兼容性","[反式钙钛矿太阳能电池商业化]: 仍受限于光电效率瓶颈"]},{"i":35883,"as":"","scd":null,"kp":[]},{"i":35884,"as":"研究开发了一种卤素离子调控结晶策略，通过调整熔盐离子成分，成功合成出具有高结晶度和局部离子耗尽特征的三嗪亚胺聚合物（PTI）。该结构能够有效调控缺陷态与电荷载流子动力学，抑制复合反应途径，促进电荷的传输与分离，从而显著提升了太阳能到氢气的转化效率。","scd":null,"kp":["结晶策略[聚三嗪酰亚胺(PTI)]: 卤素离子调制熔融盐离子成分","[卤素离子调制结晶PTI结构]: 具有高结晶度和局部离子耗尽，有效调节缺陷态并抑制多条复合路径","[光催化全分解水]: 显著提高了太阳能到氢气的转化效率"]},{"i":35885,"as":"","scd":null,"kp":[]},{"i":35886,"as":"","scd":null,"kp":[]},{"i":35887,"as":"","scd":null,"kp":[]},{"i":35888,"as":"","scd":null,"kp":[]},{"i":35889,"as":"","scd":null,"kp":[]},{"i":35890,"as":"","scd":null,"kp":[]},{"i":35891,"as":"","scd":null,"kp":[]},{"i":35892,"as":"","scd":null,"kp":[]},{"i":35893,"as":"综述分析了水凝胶作为界面材料在水-能纽带中的关键作用。水凝胶凭借其化学与结构特性，能够调节化学/电化学势梯度和传输动力学，广泛应用于太阳能水处理、大气取水、水伏发电和水系电池等领域，为可扩展的可持续水处理与能源技术设计提供了指导。","scd":null,"kp":["[水凝胶界面材料]: 通过调节化学/电化学电势梯度和输运动力学，实现太阳能水蒸发、大气取水、水伏发电和水系电池功能"]},{"i":35894,"as":"聚变公司Commonwealth Fusion Systems发布了一系列论文，详细阐述了其ARC聚变电站的具体设计方案，并声称该聚变电站未来将向电网输送电力。","scd":null,"kp":["[ARC聚变电站设计]: Commonwealth Fusion Systems发表了详细其设计的多篇论文"]},{"i":35895,"as":"提出了一种192维度的波长、模式和偏振多路复用光子计算架构。该架构在单一集成平台上同时利用了32个波长、3个空间模式和双偏振，实现了高度并行且完全可重构的光学计算。通过动态选择多路复用通道，展示了灵活的卷积核重构能力。","scd":null,"kp":["计算架构维度[光子矩阵-向量乘法]: 192维（波长/模式/偏振复用）"]},{"i":35896,"as":"研究揭示了控制金属有机无机复合物（MOIC）玻璃形成的结构因素，发现其依赖于氢键结构网络的建立。通过合理选择金属中心、阴离子和有机配体构建超分子网络，并对混合配体系统进行熔体淬火，成功制备出玻璃态MOIC，且其玻璃化转变温度（Tg）能够实现线性调节。","scd":null,"kp":["玻璃形成机制[金属有机-无机复合物]: 依赖于氢键结构网络的构建"]},{"i":35897,"as":"一本新书将环境临界点的原理应用于过去的社会变革中，通过分析历史发展模式，试图总结经验教训，探讨当今社会未来的发展趋势是走向可持续发展还是反乌托邦。","scd":null,"kp":[]},{"i":35898,"as":"一系列人工智能工具正在被应用于加速新型抗生素的发现和研发过程，以帮助应对日益严重的细菌抗生素耐药性问题。","scd":null,"kp":["研发效能[抗生素发现]: 加速新抗生素发现过程"]},{"i":35899,"as":"","scd":null,"kp":[]},{"i":35900,"as":"","scd":null,"kp":[]},{"i":35901,"as":"","scd":null,"kp":[]},{"i":35902,"as":"","scd":null,"kp":[]},{"i":35903,"as":"研究利用CRISPR-Cas12a2核酸酶的RNA引导特性，靶向癌症特异性转录本，诱导癌细胞染色质发生广泛降解，引发DNA损伤反应和细胞死亡。该方法能够精准识别细胞RNA，克服了传统疗法无法靶向肿瘤抑制蛋白（如p53）隐性突变的局限性。","scd":null,"kp":[]},{"i":35904,"as":"研究发布了首个完整重构的成年果蝇全脑与腹神经索连接体，揭示神经元控制回路原理。研究显示，运动神经元等效应神经元主要受特定感觉神经元影响，为探索大脑与脊髓协调的复杂神经控制机制提供了重要资源。","scd":null,"kp":["突触连接规模[果蝇完整连接组]: 10^8","突触连接规模[已知低等生物完整连接组]: 10^3–10^4"]},{"i":35905,"as":"研究证实GPR15是黏膜内GPR15导向的调节性CD8+ T淋巴细胞（CD8+ TIGR）的归巢受体和标志物。GPR15的有害基因变异会导致CD8+ TIGR归巢缺陷，进而引发严重的早发性炎症性肠病（IBD）。调节性CD8+ T细胞在控制肠道炎症中发挥关键作用。","scd":null,"kp":[]},{"i":35906,"as":"研究开发了一种超低压电化学有机发光晶体管。传统器件面临载流子注入效率低、工作电压高及复合区窄等问题。该新型单有源层器件实现了宽且固定的横向复合区，大幅降低了工作电压，在3.5V下电流超过10^-2，并支持两节1.5V电池供电，推动了有机电子系统直观可视化功能的应用。","scd":null,"kp":[]},{"i":35907,"as":"","scd":null,"kp":[]},{"i":35908,"as":"","scd":null,"kp":[]},{"i":35909,"as":"开发了一种阶段性演化的钯催化剂，用于木质素衍生醛的高效选择性加氢。催化剂从均相Pd2+逐步转变为约3.26纳米的石墨烯限域Pd纳米颗粒。在30°C香草醛加氢反应中，30分钟内转化率达99.4%，目标产物产率95.0%，转化频率达673.9 h−1。性能显著优于传统静态钯催化剂。","scd":null,"kp":["催化剂颗粒尺寸[石墨烯限域Pd纳米颗粒]: ~3.26 nm","反应温度[香草醛加氢]: 30 °C","催化机制[阶段演化Pd催化]: 均相Pd2+到石墨烯限域Pd纳米颗粒的序贯转化"]},{"i":35910,"as":"","scd":null,"kp":[]},{"i":35911,"as":"综述了聚合物柔性无线传感器在健康监测领域的应用。现有研究集中于材料设计、能量收集和无线通信，但缺乏对无线链路中信号衰减、噪声积累和数据失真的处理。生理信号在传输中易受多源干扰，为满足临床精度要求，本文构建了涵盖信号感知、链路传输和智能处理的综合框架。","scd":null,"kp":["应用瓶颈[聚合物柔性无线传感器健康监测]: 信号衰减、噪声累积及数据失真问题解决能力有限"]},{"i":35912,"as":"发现氧化胺脂质（AOL）能通过增强氢键和静电相互作用，将环二核苷酸（CDNs）稳定封装在脂质纳米颗粒中，封装效率高达86.8%。该体系解决了CDNs小分子量、两性离子和高亲水性导致难以递送的难题。与阳离子脂质体相比，含AOL的LNP具有更优的肿瘤穿透和胞质递送能力，引发广泛且强效的瘤内STING激活。","scd":null,"kp":["递送载体[环二核苷酸脂质纳米颗粒]: 氧化胺脂质（AOL）通过增强氢键和静电相互作用促进稳定包封"]},{"i":35913,"as":"提出了一种用于电池故障诊断的知识增强大型语言模型框架BattFailScholar。现有方法严重依赖训练数据且泛化和可解释性差。该框架构建了包含材料特性、多源信号和故障路径的电池故障知识图谱，并利用故障特征感知检索与优化算法生成知识增强内容，提升大语言模型的诊断推理能力。","scd":null,"kp":["技术特点[电池失效诊断]: 知识增强型大语言模型框架（BattFailScholar）"]},{"i":35914,"as":"系统研究了供体比例在1%至45%的PM6:Y12体异质结太阳能电池。发现供体含量低于5%时仍能形成渗透性PM6网络，有效电导率遵循三维渗透模型，电荷传输受网络拓扑控制。当供体含量低于5%时，复合机制由非双生朗道复合转变为分散的斯莫卢霍夫斯基型损失。","scd":null,"kp":["给体含量[PM6:Y12共混物形成渗滤网络阈值]: <5%"]},{"i":35915,"as":"通过一锅原位接枝共聚策略，直接利用工业牛皮纸木质素制备了全生物基高性能可回收弹性体。使用草酸和1,6-己二醇组成的低共熔溶剂在110°C下实现木质素溶解和无催化剂酯化，构建了含50-75wt.%木质素的互穿刚柔网络。最优弹性体抗拉强度达12.0 MPa，断裂能达85.1 MJ m−3，性能媲美石油基丁腈橡胶。","scd":null,"kp":["木质素含量[全生物基弹性体]: 超高含量","反应温度[一锅法原位接枝共聚]: 110°C","催化条件[深共熔溶剂酯化反应]: 无催化剂"]},{"i":35916,"as":"针对倒置钙钛矿电池界面损耗问题，提出了一种自组装单分子层（SAM）调控策略。将羟基化V2CTx MXene与氧化镍混合，提供丰富的羟基位点用于SAM锚定，形成均匀致密的SAM层。第一性原理计算表明，V2C-OH上的羟基与SAM之间具有更强的结合能，有效提升器件效率和稳定性。","scd":null,"kp":["[倒置钙钛矿太阳能电池界面调控]: 采用羟基化V2CTx MXene (V2C-OH)与NiOx混合的自组装单分子层(SAM)调控策略，解决覆盖不足和附着力弱的问题"]},{"i":35917,"as":"针对电磁波响应和动态调控需求，提出一种基于质子诱导电子-界面协同调控的异构薄膜设计策略。有别于传统由电导率主导的单一响应机制，通过构建超薄乙炔黑/H组成的异质结构，利用电化学介导界面电荷极化，实现了在有效动态电磁环境下的动态电磁调节。","scd":null,"kp":["[异质结构柔性薄膜电磁响应]: 突破导电主导的单一响应机制，实现电化学介导的界面电荷极化以进行动态电磁波调控"]},{"i":35918,"as":"提出一种三模态有机主动适应晶体管（TM-OAAT），用于机器视觉仿生适应。通过在栅极电介质内嵌入两个体异质结，实现了光电容增强和界面电荷捕获抑制的协同调制。该器件无需外部栅极偏压，即可在暗视觉、中间视觉和明视觉模式间自主切换，覆盖从月光到阳光（10^-2）的宽亮度范围。","scd":null,"kp":["[三模态有源自适应晶体管(TM-OAAT)]: 在栅极介电层内集成两个体异质结，实现无需外部偏压和光强联合调控的三模态协同视觉自适应"]},{"i":35919,"as":"针对无负极锂金属电池中锂金属阳极膨胀及内应力积累（SA）问题，提出定义应变缓冲技术边界参数的原理性准则。以典型的空间自适应缓冲（SAB）层为例，验证了该准则的科学性。该策略有效降低了内应力积累并缓解了局部应变，成功打破高能量密度与应力之间的权衡限制。","scd":null,"kp":["[无负极锂金属软包电池]: 提出打破能量密度-应力折中机制的原则性判据，以抑制负极膨胀并降低内应力积累(SA)"]},{"i":35920,"as":"","scd":null,"kp":[]},{"i":35921,"as":"","scd":null,"kp":[]},{"i":35922,"as":"提出了一种受量子动力学启发的量子启发式贝叶斯概率（QIBP）算法，用于改进理论模型对原子核质量的预测。在QIBP框架内，将理论与实验质量值之间的残差映射为波的形式，从而优化原子核质量预测的准确性。","scd":null,"kp":["[核质量预测]: 提出基于量子动力学的量子启发式贝叶斯概率(QIBP)算法，通过波函数映射理论与实验质量残差来提升预测精度"]},{"i":35923,"as":"在一维Floquet系统中实验观察到了五种不同的局域化相。扩展态、局域态和临界态是安德森局域化的基本特征。该研究实现了临界相的实验观测，特别是揭示了临界态与其他状态共存的复杂相变过程。","scd":null,"kp":["[一维Floquet系统]: 实验观测到了包含扩展态、局域态及临界态等五种不同的局域化相"]},{"i":35924,"as":"实现了具有宽带频率可调谐的纳米尺度相干声子探针。该技术能够以纳米级分辨率探测功能材料的多种光学、电子、热力学和机械特性，为材料科学的基础研究提供了先进的表征手段。","scd":null,"kp":["[纳米尺度相干声子]: 实现了具有宽带频率可调性的纳米尺度相干声子探针，用于探测材料的光学、电子、热力学和力学特性"]},{"i":35925,"as":"利用反常磁近邻效应实现了对亚皮秒相干自旋和谷动力学的控制。自旋与谷电子学致力于探索自旋和谷自由度以实现低功耗、高速信息处理。该研究通过相干控制自旋和谷动力学，推动了自旋谷电子器件向量子操作迈进的进程。","scd":null,"kp":["[自旋与谷动力学相干控制]: 利用反常磁近邻效应实现对亚皮秒级相干自旋和谷动力学的调控"]},{"i":35926,"as":"研究了包含Stone-Walles型局部晶格缺陷的自旋1/2 Kitaev蜂窝模型。纯Kitaev模型不存在有限温度相变，但研究发现，引入有限密度（约10^-4到10^-2）的奇数边缺陷会诱发手性自旋液体不稳定性，导致有限温度相变。","scd":null,"kp":["[Kitaev蜂窝模型]: 引入有限缺陷密度(nd≈10^-4–10^-2)的局部晶格缺陷会引发手性自旋液体不稳定性"]},{"i":35927,"as":"提出了一种神经网络实时等离子体成像策略及逆向设计微纳加工方法。利用条件生成对抗网络（cGAN）从等离子体强度分布生成高保真特征结构图像，实时成像延迟为1691毫秒；结合多层感知器（MLP）实现逆向设计，解决了超快激光加工中等离子体羽流阻挡表面无法直接成像的难题。","scd":null,"kp":["[超快激光微纳加工]: 提出基于神经网络的实时等离子体成像策略及逆向设计制备方法，利用条件生成对抗网络解决激光等离子体羽流阻挡表面成像的问题"]},{"i":35928,"as":"通过在初始充电过程中引入电化学弛豫路径，调节富锂阴极的阴离子氧化还原化学。4.6V氧活化平台上的电化学弛豫有助于形成晶格扭曲较小的框架结构。在Mn和O-O二聚体之间形成反馈π键，增强了相互作用，有效缓解了结构退化和局部扭曲，实现接近零的电压衰减。","scd":null,"kp":["电压衰减抑制方法[富锂正极材料]: 通过初充电过程中的电化学弛豫实现","氧激活电位[富锂正极材料]: 4.6 V"]},{"i":35929,"as":"聚对苯二甲酸乙二醇酯（PET）废弃物的电化学升级回收面临催化剂活性瓶颈。由于Pt催化剂上电子密度均匀且有限，关键中间体乙二醇（EG）和羟基（OH）的吸附受限于线性比例的“跷跷板”关系。为此，研究提出构建不对称的亲核-亲电Pt-M活性位点。该设计利用亲核Pt位点适度吸附EG，亲电M位点吸附OH，从而打破线性比例关系的限制，通过耦合电子和几何效应成功克服了这一基础活性瓶颈。","scd":null,"kp":["催化剂设计策略[PET电化学升级回收]: 构建不对称Pt-M双金属位点打破线性标度吸附关系"]},{"i":35930,"as":"","scd":null,"kp":[]},{"i":35931,"as":"环面等离子体合并技术通过磁重联提供大功率离子加热，可扩展球形托卡马克（ST）聚变反应堆的运行场景。当两个电流方向相同的环面等离子体合并时，会感应出反向片电流。为实现合并后的ST平衡，必须快速反转该反向电流。UTST等离子体合并实验研究了合并期间及之后的等离子体电流重排机制，发现下游区域形成了大于稳态预期值的静电场，并反转了沿磁力线的平行电场。","scd":null,"kp":["等离子体电流重排机制[球形托卡马克等离子体合并启动]: 极快反转等离子体合并时诱发的反向电流以建立平衡"]},{"i":35932,"as":"钨是聚变装置中等离子体面对部件的候选材料，但在意外空气进入时极易快速氧化，带来安全风险。现有第一性原理氧化模型由于依赖单一参数，无法准确解释实验速率趋势。本研究采用改进的多层界面跟踪模型，将氧化皮视为由WO、WO2、WO3等层组成的动态系统。研究利用差分进化遗传算法，针对综合实验数据库对13维参数空间进行了优化，以解决层特有参数未知的问题。","scd":null,"kp":["氧化行为评估模型[聚变环境钨材料]: 采用改进的多层界面追踪方法进行进化优化，克服单一参数依赖"]},{"i":35933,"as":"本研究使用动能-磁流体动力学混合代码MEGA，首次对离子回旋共振加热（ICRH）驱动的托卡马克等离子体进行了综合模拟。模拟包含了剪切阿尔芬波诱导的少数离子输运。结果显示，在磁场较低且共振层位于磁轴或内侧的等离子体中，多n和单n模拟均观察到爆发性环向阿尔芬本征模（TAEs）；而外侧加热则总是导致非爆发性TAEs。爆发期间，每个环向谐波都会出现一系列频率不同的离散TAEs。","scd":null,"kp":["环向阿尔芬本征模现象[ICRF加热托卡马克等离子体]: 观察到爆发式TAEs"]},{"i":35934,"as":"Wendelstein 7-X（W7-X）仿星器实验在误差场补偿方面取得显著进展。数值模拟表明，偏滤器热负荷分布对误差场高度敏感。实验中，利用修剪线圈和控制线圈分别补偿固有的1/1和2/2误差场，使得偏滤器热足迹的对称性得到显著改善。测得的固有1/1误差场振幅与七年前的结果一致。此外，实验首次成功确定了固有2/2误差场的振幅。","scd":null,"kp":["误差场补偿效果[Wendelstein 7-X偏滤器]: 利用偏滤器热负载对称化实现1/1和2/2误差场的大幅改善"]},{"i":35935,"as":"传统水分发电设备（MEGs）面临功率输出低、不稳定和可扩展性有限等问题。水凝胶凭借其优异的吸湿和保水性能、高效的离子传输通道以及出色的柔韧性，成为构建高性能、高稳定性和可扩展MEGs的理想平台。文章系统综述了水凝胶基水分发电设备（HMEGs）的最新进展，详细阐述了其内在机制、材料设计及可持续设备构建方案。","scd":null,"kp":["核心材料属性[水凝胶基湿气发电机]: 具备高吸湿/保水性、高效离子传输通道和极佳柔性适配性"]},{"i":35936,"as":"现有的锂电池回收工艺通常会破坏电极完整性。研究提出了一种直接电极到电极再生（DEER）技术，通过溶解钝化的电极-电解质界面（EEI），在完整状态下对寿命终止电池中的NMC和石墨电极进行电化学再生。DEER采用高供体数溶剂1,3-二甲基-2-咪唑烷酮（DMI），创造了有利于溶解无氧化还原活性EEI组分的热力学环境，在溶解厚EEI的同时保持了电极的结构完整性。","scd":null,"kp":["回收技术特征[废旧锂离子电池]: 直接电极到电极再生(DEER)，保持电极完整并通过溶解钝化界面实现同步电化学再生"]},{"i":35937,"as":"二氧化碳直接空气捕集（DAC）受限于吸附剂热再生能耗高的问题。研究展示了一种热响应型CO2吸附剂——PEI浸渍的PNIPAM接枝纤维素网络（TRCNF/PEI）。该材料在25°C下CO2吸收量为2.82 mmol/g，5°C下为4.33 mmol/g，且再生温度低于65°C。其核心机制是利用低临界溶解温度（LCST）相变实现“膨胀吸附/塌缩解吸”，室温下亲水膨胀暴露胺基位点捕获CO2，高于LCST时发生相变释放CO2。","scd":null,"kp":["CO2吸收量[直接空气捕集(25°C)]: 2.82 mmol g-1","CO2吸收量[直接空气捕集(5°C)]: 4.33 mmol g-1","再生温度[热响应CO2吸附剂]: 低于65°C","吸附剂材料[低临界溶解温度介导]: PEI浸渍的PNIPAM接枝纤维素网络"]},{"i":35938,"as":"湍流驱动的反常输运是降低等离子体约束性能的主要因素。在大型螺旋装置（LHD）中，主导湍流模式（离子温度梯度或电阻互换）决定了约束特性。当湍流模式发生切换时，湍流和反常输运均降至最低。本研究结合穷举搜索与支持向量机，成功确定了湍流转变发生时作为外部可控参数函数的条件，从而实现了对等离子体约束性能的优化。","scd":null,"kp":["约束优化策略[LHD等离子体湍流控制]: 实时追踪湍流最小状态以优化等离子体约束"]},{"i":35939,"as":"","scd":null,"kp":[]},{"i":35940,"as":"针对中国钢铁行业脱碳面临的技术和区域差异挑战，研究开发了一个基于主体的模型，将政策信号（碳配额、污染标准和资源限制）与企业层面的投资决策联系起来。评估了四种结合当前与强化气候目标及不同技术进步速度的情景。结果显示，所有情景到2060年均能实现90%至95%的深度碳减排，但只有“政策+技术”综合途径能在本世纪中叶前消除高炉，实现最陡峭的减排。","scd":null,"kp":["模型机制[钢铁脱碳基于主体建模]: 关联自上而下的政策信号（碳配额、污染标准、资源限制）与自下而上的企业级投资决策","评估场景[钢铁脱碳路径]: 结合当前与强化的气候和空气目标的四种情景组合"]},{"i":35941,"as":"农业扩张导致全球森林流失，进而减少蒸发并降低降水和作物产量。研究使用拉格朗日水分跟踪模型，量化了1982-2018年巴西亚马逊森林砍伐对降水和大豆产量的遥相关影响。树木蒸发贡献了三分之一的生长季降水，但近期森林砍伐导致巴西大豆种植区的季节性降水减少6%至30%。受降水下降影响，巴西南部地区的大豆产量出现最大幅度的减产。","scd":null,"kp":[]},{"i":35942,"as":"海洋生物通过内吞海水在细胞内进行修饰，产生非晶态矿物前体以形成矿化壳。在此过程中，水必须被排出以浓缩钙化底物并生成无水矿物。研究发现，海胆幼虫中的一种水甘油通道蛋白（spAQP9）参与了细胞钙化过程。spAQP9仅存在于钙化的初级间充质细胞中，且在矿化过程中表达量增加。其在异源系统中的表达证实了它控制着细胞内水和CO2的传导，对囊泡矿物形成至关重要。","scd":null,"kp":[]},{"i":35943,"as":"","scd":null,"kp":[]},{"i":35944,"as":"","scd":null,"kp":[]},{"i":35945,"as":"","scd":null,"kp":[]},{"i":35946,"as":"","scd":null,"kp":[]},{"i":35947,"as":"","scd":null,"kp":[]},{"i":35948,"as":"","scd":null,"kp":[]},{"i":35949,"as":"","scd":null,"kp":[]},{"i":35950,"as":"","scd":null,"kp":[]},{"i":35951,"as":"","scd":null,"kp":[]},{"i":35952,"as":"","scd":null,"kp":[]},{"i":35953,"as":"细菌利用表面附着的IV型菌毛（T4P）进行动态伸展和回缩。某些T4P系统依赖两种不同的运动ATP酶（PilT和PilU）共同提供回缩动力，但其协调机制一直未被阐明。本研究以霍乱弧菌为模型，利用AlphaFold 3和分子动力学模拟对PilT和PilU之间的相互作用进行了结构建模。研究结果揭示了在T4P回缩过程中，PilT与PilU协同作用驱动菌毛回缩的分子基础。","scd":null,"kp":["马达ATP酶[IV型菌毛回缩]: 依赖PilT和PilU两种不同ATPase的联合活动提供动力","研究方法[IV型菌毛回缩机制]: 结构建模揭示马达ATP酶在回缩过程中的协调机制"]},{"i":35954,"as":"豆科植物的根瘤形成受宿主机制严格限制，以平衡共生固氮的益处与植物生长代谢需求。研究揭示了一种大豆促进根瘤菌感染的系统性调节机制。大豆根部接种根瘤菌会抑制茎中microRNA miR4416-5p的生物合成，这种可移动的microRNA随后从茎运输到根。miR4416-5p水平的降低促进了根瘤菌感染，从而对抗限制机制，维持最佳结瘤水平并提高大豆产量。","scd":null,"kp":["调控机制[大豆结瘤促进]: 通过长距离信号传导环路系统性地促进结瘤起始，以对抗限制机制并维持最佳结瘤水平"]},{"i":35955,"as":"","scd":null,"kp":[]},{"i":35956,"as":"研究整合了304头泌乳奶牛的多组学数据，揭示了宿主遗传学对瘤胃甲烷排放的主导作用。数据显示，单位干物质摄入的甲烷排放量具有0.42的遗传力，高于0.19的微生物群影响力。孟德尔随机化分析确定了三种可遗传的普雷沃特氏菌物种（包括Prevotella_bryantii），它们能因果性地减少甲烷排放。这为降低奶牛甲烷排放提供了遗传学靶点。","scd":null,"kp":["样本规模[奶牛甲烷排放多组学研究]: 304头泌乳牛","遗传力[甲烷排放/干物质摄入量(M/D)]: 0.42","微生物能力[甲烷排放/干物质摄入量(M/D)]: 0.19","关键机制[奶牛瘤胃甲烷减排]: 宿主遗传对瘤胃6-羟褪黑素的调节可减少甲烷排放"]},{"i":35957,"as":"视杆细胞磷酸二酯酶-6（PDE6）包含一个α/β催化异二聚体核心，为了解各亚基的独特功能，研究构建了四种转基因小鼠模型。这些模型分别用于检测体内N端Pt基序缺失（PDE6αΔ2-48AA和PDE6βΔ2-46AA）以及选择性消除催化活性的活性位点突变（PDE6αH599A和PDE6βH597A）对PDE6功能的影响，揭示了各催化亚基在维持光感受器完整性中的不对称功能与关键结构作用。","scd":null,"kp":["蛋白结构[视杆细胞PDE6]: 由α/β异二聚体催化核心和两个抑制性γ亚基组成的四聚体","蛋白结构[视锥细胞PDE6]: α'/α'同源二聚体","研究模型[PDE6亚基功能与结构研究]: 生成了四种转基因小鼠模型以检测各亚基N端等功能贡献"]},{"i":35958,"as":"大肠杆菌K12的IE型CRISPR-Cas系统是其核心基因组的一部分，但其转录沉默状态使生物学功能受到质疑。为阐明该系统的作用，研究人员在肠杆菌目中进行了抗CRISPR（Acr）蛋白普查，并鉴定出AcrIE9是大肠杆菌K12 IE型CRISPR-Cas系统的强效抑制剂。该发现为IE型CRISPR-Cas系统的防御机制及功能提供了重要见解。","scd":null,"kp":["抗CRISPR蛋白[大肠杆菌K12 IE型CRISPR-Cas系统]: AcrIE9和AcrIE13作为该系统的抑制剂","系统特征[大肠杆菌K12 IE型CRISPR-Cas]: 属于核心基因组的一部分，但在转录水平上呈沉默状态"]},{"i":35959,"as":"针对肿瘤免疫治疗中程序性死亡配体1（PD-L1）抑制不足的问题，研究开发了一种可编程且响应肿瘤的DNA水凝胶平台。该平台通过滚环扩增合成，实现双模式调节：既递送基于多价适体的溶酶体靶向嵌合体以诱导细胞外PD-L1降解，又通过siSMARCAL1沉默染色质重塑因子以实现转录抑制，从而全面抑制PD-L1表达。","scd":null,"kp":["技术平台[PD-L1双重模式抑制]: 可编程的、响应肿瘤的DNA水凝胶","作用机制[PD-L1双重模式抑制]: 通过多价LYTAC模拟物和转录沉默实现双重抑制"]},{"i":35960,"as":"黏膜相关恒定T（MAIT）细胞能识别微生物衍生的核黄素前体并引发抗菌反应。食源性病原体单核细胞增生李斯特菌由于缺乏核黄素合成途径，被假设以此作为病理适应机制来逃避MAIT细胞。研究表明，经过基因工程改造能够产生核黄素的李斯特菌菌株会改变这一逃逸机制。这证实了避开MAIT细胞是李斯特菌致病机制的重要决定因素。","scd":null,"kp":["致病决定因素[单核细胞增生李斯特菌]: 避免被MAIT细胞识别（因缺乏核黄素生物合成途径）"]},{"i":35961,"as":"α-突触核蛋白（α-syn）聚集是帕金森病等突触核蛋白病的标志。利用电子显微镜对暴露于α-syn原纤维的SH-SY5Y细胞进行高分辨率成像，结果发现α-syn原纤维不仅导致线粒体嵴结构受损，还促进了线粒体来源囊泡（MDVs）的出芽生成。这表明MDV的形成反映了一种类似于细菌外膜囊泡生物发生的进化保守机制。","scd":null,"kp":["病理机制[突触核蛋白病/帕金森病]: α-突触核蛋白原纤维诱导线粒体衍生囊泡的出芽","研究方法[α-突触核蛋白聚集与线粒体毒性]: 使用电子显微镜的高分辨率成像对比暴露于原纤维的细胞与对照细胞"]},{"i":35962,"as":"","scd":null,"kp":[]},{"i":35963,"as":"双层石墨烯腔（电子被限制在有限石墨烯薄片内）具有可调能隙和三角翘曲费米面，是研究量子混沌的理想平台。研究表明，旋转相对于底层晶格结构的腔边界，能够驱动系统从近可积动力学向混沌区域的量子相变，这具体表现为特征值统计和特征态分布的交叉。半经典射线动力学分析证实了这一量子混沌发生的经典机制。","scd":null,"kp":["量子跃迁[双层石墨烯腔]: 旋转腔边界相对于底层晶格结构，驱动从近可积动力学向混沌状态的转变"]},{"i":35964,"as":"","scd":null,"kp":[]},{"i":35965,"as":"","scd":null,"kp":[]},{"i":35966,"as":"为解决当前直接空气捕获（DAC）吸附剂能耗高且不符合循环经济的问题，研究将乳制品和豆腐废水中回收的蛋白质升级改造为功能性淀粉样原纤维微球，用于常温下的二氧化碳捕集。通过原子级设计和模板成型，原纤维内的赖氨酸和谷氨酰胺残基被有效利用，实现了基于食物废料的环保、无热（非耗热）且可循环的大气二氧化碳捕获。","scd":null,"kp":["[生物基直接空气捕集CO2吸附剂]: 传统生物基替代品通常面临CO2吸附容量较低的问题","[废弃物衍生淀粉样蛋白吸附剂]: 具有符合循环经济原则的无热(低能耗)大气CO2捕集潜力"]},{"i":35967,"as":"cGAS-STING通路是驱动先天免疫激活的关键胞质DNA传感通路。在Q175DN敲入亨廷顿病（HD）小鼠模型中，基因消除cGAS后显著改善了HD相关的运动缺陷（包括转棒表现和平衡木协调能力），并减轻了进行性体重下降。组织学分析显示，cGAS缺失减少了侧脑室扩大，降低了纹状体星形胶质细胞增生。这证实了靶向cGAS-STING通路可减轻HD发病机制。","scd":null,"kp":[]},{"i":35968,"as":"生物矿化结构不仅具有优异的力学性能，还具备光学潜力。研究发现，在海星的多孔方解石骨骼中，被称为末端板的特定骨片包含径向排列的导光结构（LGSs）。这些LGSs呈细长锥形几何形状（长度约250微米），嵌入在由含镁单晶方解石组成的网状结构中，发挥了光引导的作用。","scd":null,"kp":["[海星多孔方解石骨架的生物矿化结构]: 末端骨板包含径向排列的光导阵列结构"]},{"i":35969,"as":"为应对新冠病毒变异及未来动物源性sarbecovirus外溢威胁，研究从一名早期大流行期间感染并接种疫苗的患者体内分离出20种针对受体结合域（RBD）的广谱中和抗体谱系。其中13种靶向高度保守的隐蔽1/4类或4类RBD表位，并具有18至26个氨基酸的特长重链互补决定区3环。实验表明，其中5种广谱中和抗体强效中和了测试组中的所有18种病毒。利用mRNA递送该抗体可在致死性小鼠模型中提供保护。","scd":null,"kp":[]},{"i":35970,"as":"氢键在酶活性位点中普遍存在，但其对催化作用的定量贡献长期未解。研究指出，传统方法在分配氢键催化贡献时存在局限性。为克服这一问题，研究人员利用线性自由能关系（LFERs）来评估活性位点氢键的能量，成功解决了如何精确量化氢键对酶催化反应中每种催化相互作用和分子机制的具体能量贡献这一长期基础难题。","scd":null,"kp":["[酶催化作用中的氢键贡献]: 长期缺乏对每种催化相互作用和分子机制贡献的准确定量分析"]},{"i":35971,"as":"文章将Fisher-Rao度量应用于Denicol-Niemi-Molnár-Rischke (DNMR) 14-矩流形，探讨了相对论动力学理论中矩流形的黎曼几何。传统上，夸克-胶子等离子体中的动力学到流体动力学交叉通常通过克努森数和倒数雷诺数等尺度比值来诊断，但这些比值在分布空间上并非度量。该研究为流体动力学逼近过程提供了新的几何视角。","scd":null,"kp":[]},{"i":35972,"as":"弱r过程或α过程的核合成建模需要庞大的核反应网络计算。为了约束弱r过程研究中α诱导的反应截面，研究人员在锶-88（88Sr）上进行了弹性α散射实验。该实验数据旨在改善对大质量恒星坍缩后发射的中微子驱动风中产生的富中子低质量同位素（铁到银之间）核合成的模型预测精度。","scd":null,"kp":[]},{"i":35973,"as":"环保型锌硫族化合物半导体纳米晶（包括ZnS、ZnSe、ZnTe及其合金，涵盖0D量子点、1D纳米线/棒和2D纳米片）具有无毒、优异的光学性能和从紫光到红光的宽禁带可调性，是先进照明和显示的理想材料。文章系统回顾了该类纳米晶的受控合成方法，并总结了其在发光二极管（LEDs）及其他光电器件中的应用进展。","scd":null,"kp":["[锌硫族化合物半导体纳米晶发光范围]: 能够实现从紫光到红光的发光","[锌硫族化合物半导体纳米晶核心优势]: 无重金属且具备优异的光学性能和宽带隙可调性"]},{"i":35974,"as":"","scd":null,"kp":[]},{"i":35975,"as":"通过构建反铁磁/铁磁异质结构，可在界面处产生内置磁场以对齐电子自旋。这种内置磁场通过快速的量子自旋交换相互作用，实现了在无外加磁场条件下对自旋依赖性氧电催化反应的高效控制。该策略不仅显著增强了析氧反应（OER）活性，还揭示了自旋极化在控制反应过程中的关键作用，为高效能量转换材料提供了通用的设计原则。","scd":null,"kp":["[反铁磁/铁磁异质结构析氧电催化]: 异质界面诱导的内置磁场通过增强自旋交换相互作用，实现了无外部磁场条件下的高效自旋依赖性氧电催化"]},{"i":35976,"as":"","scd":null,"kp":[]},{"i":35977,"as":"","scd":null,"kp":[]},{"i":35978,"as":"","scd":null,"kp":[]},{"i":35979,"as":"动物如何从单细胞祖先进化出复杂的多细胞性一直悬而未决。目前已知动物的 unicellular 亲属通过克隆分裂、多核体或聚集现象表现出简单的多细胞性。研究指出，聚集现象广泛存在于现存动物细胞以及三种动物的密切单细胞亲属（如领鞭毛虫和丝足虫）中。文章探讨了这种聚集行为在动物演化起源中的潜力及其衍生或祖代属性。","scd":null,"kp":[]},{"i":35980,"as":"","scd":null,"kp":[]},{"i":35981,"as":"","scd":null,"kp":[]},{"i":35982,"as":"关于冷却液体中冰晶如何生长的传统理论与实验数据之间存在巨大差异。目前，科学研究正在逐步揭开液体结冰最初时刻的物理面纱。新的实验研究正在不断提供关键数据，以期纠正现有不准确的理论模型，揭示冰形成初期的核心机制。","scd":null,"kp":["[冷却液体中冰晶生长的经典理论]: 与实验数据相比存在极大偏差"]},{"i":35983,"as":"","scd":null,"kp":[]},{"i":35984,"as":"","scd":null,"kp":[]},{"i":35985,"as":"","scd":null,"kp":[]},{"i":35986,"as":"","scd":null,"kp":[]},{"i":35987,"as":"","scd":null,"kp":[]},{"i":35988,"as":"一种可应用于单晶体管-单电阻二硫化钼阵列的硬件信号折叠方案，能够同时实现高权重精度和高能效，为精确高效的计算提供了解决途径。","scd":null,"kp":["[一晶体管-一电阻二硫化钼阵列的信号折叠方案]: 能够同时实现高权重精度和高能效"]},{"i":35989,"as":"","scd":null,"kp":[]},{"i":35990,"as":"","scd":null,"kp":[]},{"i":35991,"as":"","scd":null,"kp":[]},{"i":35992,"as":"","scd":null,"kp":[]},{"i":35993,"as":"","scd":null,"kp":[]},{"i":35994,"as":"新研究证实了家庭层面垃圾分类的价值。为了最大化收集材料的质量，政策制定必须谨慎考量消费者的行为习惯。","scd":null,"kp":["[家庭层面的废物分离策略]: 能够有效提升所收集材料的质量"]},{"i":35995,"as":"","scd":null,"kp":[]},{"i":35996,"as":"《自然》杂志的民意调查揭示了科学界对人工智能（AI）的“错失恐惧症”（FOMO）。近半数的受访科学家表示对AI持负面态度，但他们也认为部分AI工具的表现优于其他工具。","scd":null,"kp":["[科研人员对AI的态度]: 接近半数受访科学家对人工智能持普遍负面态度，但认为部分工具相对有效"]},{"i":35997,"as":"","scd":null,"kp":[]},{"i":35998,"as":"针对3D砂型打印铸造模具中变量组合和目标冲突带来的非线性高维优化挑战，开发了名为Ex3DSP的自进化实验平台。该平台结合了机器人的操作能力与AI的认知能力，建立了“边做边想”的实验范式。在处理三目标三变量优化问题时，该平台发现了帕累托前沿，并将实验工作量缩减了1148倍。","scd":null,"kp":["[3D沙模打印实验平台Ex3DSP优化问题]: 成功解决了包含3个变量和3个目标的高维优化冲突问题","[3D沙模打印实验平台Ex3DSP系统特点]: 结合了机器人的操作能力与AI的认知能力，确立了边做边思考的自我演进实验范式"]},{"i":35999,"as":"为解决通用灵巧操作中复杂扭转任务的挑战，提出DexAnyTwist框架。由于异构数据集中固有的混合动力学空间会导致优化冲突，传统学习方法失效。该框架将通用扭转任务重新构建为混合动力系统内的识别与控制问题，采用迭代策略将混合操作任务逐步划分为动力学一致的子系统。","scd":null,"kp":["[异构数据集的灵巧扭转操作]: 存在由异构动力学空间引发的优化冲突，导致标准学习范式无法跨不同物理定律合成连贯的控制策略"]}]);